-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00168_actions_soft_delete.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Deleting an Action Center action from its row menu.
--
-- A delete hides the action rather than removing the row: it is set to
-- 'dismissed' and stamped deleted_at. Kept as a dismissed row, it still
-- gives the nightly generator its rest window (generate.js reads completed
-- and dismissed actions to see when a definition last closed), so a
-- condition that is still firing doesn't come back as a fresh action the
-- next night. Removed outright, it would.
--
-- Everyone else stops seeing it:
--   * members read actions through "actions: member select", which now
--     leaves deleted rows out. The task, event and signal-link policies look
--     actions up through it, so a deleted action's tasks and trail go too.
--   * the server's admin reads (MCP, API, exports) filter deleted_at
--     themselves.
--   * sync_opportunity_status, a security-definer trigger, counts an
--     opportunity's actions to set its status; a deleted one no longer
--     counts, as if it had never been sent.

alter table public.actions add column if not exists deleted_at timestamptz;

drop policy if exists "actions: member select" on public.actions;

create policy "actions: member select" on public.actions
  for select using (
    deleted_at is null
    and brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

create or replace function public.sync_opportunity_status()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  opp uuid := nullif(new.payload->>'opportunityId', '')::uuid;
  since timestamptz;
  next_status text;
begin
  if opp is null then
    return new;
  end if;

  select nullif(source_data->'reopened'->>'at', '')::timestamptz
    into since
    from content_opportunities
   where id = opp;

  select case
           when count(*) = 0 then null
           when count(*) filter (where a.status <> 'dismissed') = 0 then 'reviewed'
           when count(*) filter (where a.status not in ('completed', 'dismissed')) = 0 then 'done'
           when count(*) filter (where a.status in ('in_progress', 'on_hold', 'completed')) > 0
             then 'in_progress'
           else 'sent'
         end
    into next_status
    from actions a
   where a.kind = 'content_opportunity'
     and a.brand_id = new.brand_id
     and a.payload->>'opportunityId' = opp::text
     and a.deleted_at is null
     and (since is null or a.created_at >= since);

  -- Only earlier work changed, or the only action was deleted: the
  -- opportunity stays as it is.
  if next_status is null then
    return new;
  end if;

  update content_opportunities
     set status = next_status, updated_at = now()
   where id = opp
     and brand_id = new.brand_id
     and status in ('new', 'reviewed', 'sent', 'in_progress', 'done')
     and status <> next_status;

  return new;
end;
$$;

revoke all on function public.sync_opportunity_status() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00169_head_to_head_daily.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Head-to-head on the Competitors page, from the daily rollups (#923).
--
-- getHeadToHeadComparison read the brand's raw prompt_results in one
-- request, which PostgREST caps at 1,000 rows, and summed them in the app:
-- a brand past 1,000 answers was compared on its newest 1,000 only, with no
-- sign of it. The largest brand has ~220k answers.
--
-- Every number the page shows is a sum the rollups already keep (00164):
--   * groups, one per (prompt, platform, model, region): runs and the
--     brand's visibility from insights_prompt_daily; the competitor's from
--     its sightings in insights_competitor_prompt_daily. An answer that is
--     not a sighting has the competitor at 0, which is what the page counted
--     for a group's runs without it.
--   * the averages per engine and overall: the brand's over every answer
--     (insights_brand_daily, answers with no prompt included), the
--     competitor's over the answers that list it (insights_competitor_daily
--     has one row per answer listing the competitor). The app folds engines
--     into display providers.
-- All time, as the page always read. The prompts' text comes along, once per
-- prompt, so the app needn't send hundreds of prompt ids back in a query
-- string. On the largest brand: 5,724 groups over 720 prompts, 1.1 s as a
-- member, every answer counted.
--
-- plpgsql with force_custom_plan, security definer with the organization
-- check made explicit, as the other Insights reads (00147): a caller
-- outside the brand's organization gets null.

create or replace function public.head_to_head_daily(
  p_brand_id uuid,
  p_competitor_id text
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  with brand_groups as (
    select d.prompt_id, d.platform, d.model_used, d.region,
           sum(d.answer_count)   as runs,
           sum(d.sum_visibility) as brand_total,
           max(d.max_created_at) as latest_at
    from public.insights_prompt_daily d
    where d.brand_id = p_brand_id
    group by d.prompt_id, d.platform, d.model_used, d.region
  ),
  comp_groups as (
    select cd.prompt_id, cd.platform, cd.model_used, cd.region,
           sum(cd.sum_visibility) as comp_total
    from public.insights_competitor_prompt_daily cd
    where cd.brand_id = p_brand_id
      and cd.competitor_id = p_competitor_id
    group by cd.prompt_id, cd.platform, cd.model_used, cd.region
  ),
  brand_engines as (
    select d.platform, d.model_used,
           sum(d.answer_count)   as brand_count,
           sum(d.sum_visibility) as brand_total
    from public.insights_brand_daily d
    where d.brand_id = p_brand_id
    group by d.platform, d.model_used
  ),
  comp_engines as (
    select cd.platform, cd.model_used,
           sum(cd.answer_count)   as comp_count,
           sum(cd.sum_visibility) as comp_total
    from public.insights_competitor_daily cd
    where cd.brand_id = p_brand_id
      and cd.competitor_id = p_competitor_id
    group by cd.platform, cd.model_used
  )
  select jsonb_build_object(
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object(
               'prompt_id',       g.prompt_id,
               'platform',        g.platform,
               'model_used',      g.model_used,
               'region',          g.region,
               'runs',            g.runs,
               'brand_total',     coalesce(g.brand_total, 0),
               'comp_total',      coalesce(c.comp_total, 0),
               'latest_at',       g.latest_at))
      from brand_groups g
      left join comp_groups c
        on c.prompt_id = g.prompt_id
       and c.platform is not distinct from g.platform
       and c.model_used is not distinct from g.model_used
       and c.region is not distinct from g.region
    ), '[]'::jsonb),
    -- Each prompt's text once, rather than on each of its groups.
    'prompts', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'text', p.text, 'category', p.category))
      from public.prompts p
      where p.id in (select g.prompt_id from brand_groups g)
    ), '[]'::jsonb),
    'engines', coalesce((
      select jsonb_agg(jsonb_build_object(
               'platform',    e.platform,
               'model_used',  e.model_used,
               'brand_count', e.brand_count,
               'brand_total', coalesce(e.brand_total, 0),
               'comp_count',  coalesce(c.comp_count, 0),
               'comp_total',  coalesce(c.comp_total, 0)))
      from brand_engines e
      left join comp_engines c
        on c.platform is not distinct from e.platform
       and c.model_used is not distinct from e.model_used
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke execute on function public.head_to_head_daily(uuid, text) from public, anon;
grant execute on function public.head_to_head_daily(uuid, text) to authenticated, service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00170_topics_overview_rollup_reads.sql
-- ─────────────────────────────────────────────────────────────────────────
-- The Topics overview's longer windows read the rollups alone (#1000).
--
-- topics_overview_window (00156) read a window of two days or more from the
-- prompt-grain rollups, but two things kept it slow when cold:
--
--   * It joined insights_prompt_daily and insights_competitor_prompt_daily
--     to the brand's prompts first. Since 00164 added (brand_id, prompt_id,
--     day), the planner walks that index once per prompt and fetches every
--     row's page on its own: 199k buffers for 180 days of the largest brand
--     (720 prompts), against 55k read by (brand_id, day), where a day's rows
--     sit together. Cold, the 90-day view took 23 s and the 30-day one 7 s,
--     against the authenticated role's 8 s statement timeout. Each table is
--     now read by brand and days first (materialized) and only then joined
--     to the topics' prompts.
--   * Each topic's last answer time came from prompt_results. It is now the
--     rollups' max_created_at (00164), over the window's whole days, as the
--     row's other figures are.
--
-- So a window of two days or more reads no prompt_results. The 24-hour view
-- still reads the answers, as 00156 explains. Output is 00156's otherwise:
-- on production, both brands checked returned the same rows for 7, 30 and
-- 90 days, last run times included, in 1.1 s instead of 5.3 s for the
-- largest brand's 30 days and 0.14 s instead of 2.7 s for another's 90.

create or replace function public.topics_overview_window(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null
)
returns table (
  topic_id              uuid,
  answers               bigint,
  mention_answers       bigint,
  citation_answers      bigint,
  pos_sum               double precision,
  pos_n                 bigint,
  prev_answers          bigint,
  prev_mention_answers  bigint,
  prev_citation_answers bigint,
  prev_pos_sum          double precision,
  prev_pos_n            bigint,
  total_mentions        bigint,
  total_citations       bigint,
  comp_mentions         bigint,
  active_prompts        bigint,
  visible_prompts       bigint,
  last_run_at           timestamptz,
  competitors           jsonb,
  daily                 jsonb
)
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
#variable_conflict use_column
declare
  v_to        timestamptz := coalesce(p_date_to, now());
  v_from      timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  -- Whole days the window spans, at least one, with an hour of slack: a
  -- rolling 7 days starts where the browser put it and ends at now(), a
  -- moment later, which must not make it 8 (lib/topicTrend.ts counts alike).
  v_days      integer;
  -- The rollup days of a longer window, and of the window before it.
  v_day_to    date;
  v_day_from  date;
  v_prev_from date;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return;
  end if;

  v_days := greatest(1, ceil(extract(epoch from (v_to - v_from)) / 86400.0 - 1.0 / 24)::integer);

  if v_days < 2 then
    return query
    with
    rows as (
      select p.topic_id,
             pr.prompt_id,
             pr.created_at,
             pr.competitor_mentions,
             (pr.created_at >= v_from)                        as in_window,
             coalesce(pr.mention_count, 0)                    as mentions,
             coalesce(pr.citation_count, 0)                   as citations,
             pr.mention_position,
             (coalesce(pr.mention_count, 0) > 0
               or coalesce(pr.citation_count, 0) > 0)         as visible
      from public.prompt_results pr
      join public.prompts p      on p.id = pr.prompt_id
      join public.prompt_sets ps on ps.id = p.prompt_set_id
      where pr.brand_id = p_brand_id
        and ps.brand_id = p_brand_id
        and p.topic_id is not null
        and pr.platform <> 'chatgpt-shopping'
        and pr.created_at >= v_from - (v_to - v_from)
        and pr.created_at <= v_to
    ),
    comps as (
      select r.topic_id,
             cm.value->>'competitor_id'                              as competitor_id,
             min(c.name)                                             as name,
             sum(coalesce((cm.value->>'mention_count')::int, 0))::bigint as mentions
      from rows r
      cross join lateral jsonb_array_elements(coalesce(r.competitor_mentions, '[]'::jsonb)) cm
      join public.competitors c on c.id::text = cm.value->>'competitor_id' and c.brand_id = p_brand_id
      where r.in_window
      group by r.topic_id, cm.value->>'competitor_id'
      having sum(coalesce((cm.value->>'mention_count')::int, 0)) > 0
    ),
    comp_totals as (
      select topic_id,
             sum(mentions)::bigint as comp_mentions,
             jsonb_object_agg(competitor_id, jsonb_build_object('name', name, 'sov', mentions))
               as competitors
      from comps
      group by topic_id
    ),
    main as (
      select r.topic_id,
             count(*) filter (where r.in_window)::bigint                          as answers,
             count(*) filter (where r.in_window and r.mentions > 0)::bigint       as mention_answers,
             count(*) filter (where r.in_window and r.citations > 0)::bigint      as citation_answers,
             coalesce(sum(1.0 / r.mention_position)
               filter (where r.in_window and r.mention_position > 0), 0)::double precision
                                                                                   as pos_sum,
             count(*) filter (where r.in_window and r.mention_position > 0)::bigint
                                                                                   as pos_n,
             count(*) filter (where not r.in_window)::bigint                      as prev_answers,
             count(*) filter (where not r.in_window and r.mentions > 0)::bigint   as prev_mention_answers,
             count(*) filter (where not r.in_window and r.citations > 0)::bigint  as prev_citation_answers,
             coalesce(sum(1.0 / r.mention_position)
               filter (where not r.in_window and r.mention_position > 0), 0)::double precision
                                                                                   as prev_pos_sum,
             count(*) filter (where not r.in_window and r.mention_position > 0)::bigint
                                                                                   as prev_pos_n,
             coalesce(sum(r.mentions) filter (where r.in_window), 0)::bigint      as total_mentions,
             coalesce(sum(r.citations) filter (where r.in_window), 0)::bigint     as total_citations,
             count(distinct r.prompt_id) filter (where r.in_window)::bigint       as active_prompts,
             count(distinct r.prompt_id) filter (where r.in_window and r.visible)::bigint
                                                                                   as visible_prompts,
             max(r.created_at) filter (where r.in_window)                         as last_run_at
      from rows r
      group by r.topic_id
    )
    select m.topic_id,
           m.answers, m.mention_answers, m.citation_answers, m.pos_sum, m.pos_n,
           m.prev_answers, m.prev_mention_answers, m.prev_citation_answers, m.prev_pos_sum, m.prev_pos_n,
           m.total_mentions, m.total_citations,
           coalesce(ct.comp_mentions, 0)::bigint,
           m.active_prompts, m.visible_prompts, m.last_run_at,
           coalesce(ct.competitors, '{}'::jsonb),
           '{}'::jsonb
    from main m
    left join comp_totals ct on ct.topic_id = m.topic_id
    where m.answers > 0;
    return;
  end if;

  v_day_to := (v_to at time zone 'UTC')::date;
  v_day_from := v_day_to - (v_days - 1);
  v_prev_from := v_day_from - v_days;

  return query
  with
  topic_prompts as (
    select p.id as prompt_id, p.topic_id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and p.topic_id is not null
  ),
  -- The brand's rows of both windows, read by (brand_id, day) and only then
  -- matched to the topics' prompts (see the header).
  prompt_rows as materialized (
    select d.prompt_id,
           d.day,
           d.answer_count,
           d.mention_answers,
           d.citation_answers,
           d.mentioning_answers,
           d.total_mentions,
           d.total_citations,
           d.sum_inv_position,
           d.position_count,
           d.max_created_at
    from public.insights_prompt_daily d
    where d.brand_id = p_brand_id
      and d.day between v_prev_from and v_day_to
  ),
  days as (
    select tp.topic_id,
           r.prompt_id,
           r.day,
           (r.day >= v_day_from) as in_window,
           r.answer_count,
           r.mention_answers,
           r.citation_answers,
           r.mentioning_answers,
           r.total_mentions,
           r.total_citations,
           r.sum_inv_position,
           r.position_count,
           r.max_created_at
    from prompt_rows r
    join topic_prompts tp on tp.prompt_id = r.prompt_id
  ),
  sightings as materialized (
    select cpd.prompt_id, cpd.competitor_id, cpd.mention_count
    from public.insights_competitor_prompt_daily cpd
    where cpd.brand_id = p_brand_id
      and cpd.day between v_day_from and v_day_to
  ),
  comps as (
    select tp.topic_id,
           s.competitor_id,
           min(c.name)                   as name,
           sum(s.mention_count)::bigint  as mentions
    from sightings s
    join topic_prompts tp     on tp.prompt_id = s.prompt_id
    join public.competitors c on c.id::text = s.competitor_id and c.brand_id = p_brand_id
    group by tp.topic_id, s.competitor_id
    having sum(s.mention_count) > 0
  ),
  comp_totals as (
    select topic_id,
           sum(mentions)::bigint as comp_mentions,
           jsonb_object_agg(competitor_id, jsonb_build_object('name', name, 'sov', mentions))
             as competitors
    from comps
    group by topic_id
  ),
  -- A point per UTC day, keyed as the client builds its keys
  -- (Date.toISOString()).
  daily as (
    select x.topic_id,
           jsonb_object_agg(x.day, jsonb_build_object('visible', x.visible, 'count', x.count))
             as daily
    from (
      select topic_id,
             to_char(day, 'YYYY-MM-DD')     as day,
             sum(mentioning_answers)::bigint as visible,
             sum(answer_count)::bigint       as count
      from days
      where in_window
      group by topic_id, day
    ) x
    group by x.topic_id
  ),
  -- Each topic's last answer in the window, from the rollups (00164).
  last_runs as (
    select topic_id, max(max_created_at) as last_run_at
    from days
    where in_window
    group by topic_id
  ),
  main as (
    select topic_id,
           coalesce(sum(answer_count) filter (where in_window), 0)::bigint         as answers,
           coalesce(sum(mention_answers) filter (where in_window), 0)::bigint      as mention_answers,
           coalesce(sum(citation_answers) filter (where in_window), 0)::bigint     as citation_answers,
           coalesce(sum(sum_inv_position) filter (where in_window), 0)::double precision
                                                                                   as pos_sum,
           coalesce(sum(position_count) filter (where in_window), 0)::bigint       as pos_n,
           coalesce(sum(answer_count) filter (where not in_window), 0)::bigint     as prev_answers,
           coalesce(sum(mention_answers) filter (where not in_window), 0)::bigint  as prev_mention_answers,
           coalesce(sum(citation_answers) filter (where not in_window), 0)::bigint as prev_citation_answers,
           coalesce(sum(sum_inv_position) filter (where not in_window), 0)::double precision
                                                                                   as prev_pos_sum,
           coalesce(sum(position_count) filter (where not in_window), 0)::bigint   as prev_pos_n,
           coalesce(sum(total_mentions) filter (where in_window), 0)::bigint       as total_mentions,
           coalesce(sum(total_citations) filter (where in_window), 0)::bigint      as total_citations,
           count(distinct prompt_id) filter (where in_window and answer_count > 0)::bigint
                                                                                   as active_prompts,
           count(distinct prompt_id) filter (where in_window and mentioning_answers > 0)::bigint
                                                                                   as visible_prompts
    from days
    group by topic_id
  )
  select m.topic_id,
         m.answers, m.mention_answers, m.citation_answers, m.pos_sum, m.pos_n,
         m.prev_answers, m.prev_mention_answers, m.prev_citation_answers, m.prev_pos_sum, m.prev_pos_n,
         m.total_mentions, m.total_citations,
         coalesce(ct.comp_mentions, 0)::bigint,
         m.active_prompts, m.visible_prompts, lr.last_run_at,
         coalesce(ct.competitors, '{}'::jsonb),
         coalesce(dl.daily, '{}'::jsonb)
  from main m
  left join comp_totals ct on ct.topic_id = m.topic_id
  left join daily dl       on dl.topic_id = m.topic_id
  left join last_runs lr   on lr.topic_id = m.topic_id
  where m.answers > 0;
end;
$$;

revoke execute on function public.topics_overview_window(uuid, timestamptz, timestamptz)
  from public, anon;
grant execute on function public.topics_overview_window(uuid, timestamptz, timestamptz)
  to authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00171_page_visibility_window.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00171: one window for "Pages AI engines aren't sending traffic to" (AT-002)
-- ============================================================================
-- The AI Traffic page's card listed the nightly findings, always the last 28
-- days whatever range the page showed, and judged "no AI traffic" from
-- Google Analytics' AI channel alone. A page the tracking snippet had seen
-- Gemini visitors land on that week could sit in the card, under the visits
-- that contradicted it.
--
-- ga_page_ai_visibility (00075) now takes the window's last day as well as
-- its first, so the server can rank a page's own range on request, and
-- reports each page's snippet visits in that window. The snippet's URLs go
-- through the same normalize_page_path the Analytics pages do, so the two
-- name a page the same way; ai_traffic_logs only keeps visits attributed to
-- an AI platform, so every row counts. The snippet window runs over whole
-- days, at least the timestamps the page itself counts, so a page with a
-- visit in the page's range is never missed.
--
--   * p_since and p_until are both optional and inclusive: no p_since reads
--     from the start, no p_until up to today. Nightly detection still passes
--     only p_since.
--   * The return type gains snippet_visits, so the function is dropped and
--     recreated: CREATE OR REPLACE can't change a return type, and adding a
--     parameter beside the old signature would leave PostgREST two overloads
--     to choose between (00164). The body is otherwise 00075's.

drop function if exists public.ga_page_ai_visibility(uuid, date);

create function public.ga_page_ai_visibility(
  p_brand_id uuid,
  p_since date default null,
  p_until date default null
)
returns table (
  landing_page text,
  sessions bigint,
  engaged_sessions bigint,
  key_events bigint,
  transactions bigint,
  revenue double precision,
  engagement_seconds bigint,
  ai_sessions bigint,
  ai_platforms text[],
  citations bigint,
  citing_prompts bigint,
  targeting_prompts bigint,
  snippet_visits bigint
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as (
    -- citation_urls.domain is already stored lowercased and without www, so
    -- this is an index probe rather than a scan.
    select cu.id, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  cited as (
    select
      ou.page_key,
      count(*)::bigint as citations,
      count(distinct pr.prompt_id)::bigint as citing_prompts
    from own_urls ou
    join public.prompt_result_citations prc
      on prc.url_id = ou.id
     and prc.brand_id = p_brand_id
     and prc.created_at >= coalesce(p_since, '-infinity'::date)
     and prc.created_at < coalesce(p_until + 1, 'infinity'::date)
    join public.prompt_results pr on pr.id = prc.prompt_result_id
    group by ou.page_key
  ),
  targeted as (
    -- Explicit targeting only. "A prompt covers this page's topic" is not
    -- something SQL can decide, and guessing it would put a made-up reason on
    -- a finding; a URL a customer attached to a prompt is a fact.
    select
      lower(public.normalize_page_path(ptu.url)) as page_key,
      count(distinct ptu.prompt_id)::bigint as targeting_prompts
    from public.prompt_target_urls ptu
    join public.prompts p on p.id = ptu.prompt_id
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
    group by 1
  ),
  pages as (
    select
      lower(public.normalize_page_path(gps.landing_page)) as page_key,
      min(public.normalize_page_path(gps.landing_page)) as landing_page,
      sum(gps.sessions)::bigint as sessions,
      sum(gps.engaged_sessions)::bigint as engaged_sessions,
      sum(gps.key_events)::bigint as key_events,
      sum(gps.transactions)::bigint as transactions,
      sum(gps.purchase_revenue) as revenue,
      sum(gps.engagement_duration_seconds)::bigint as engagement_seconds
    from public.ga_page_stats gps
    where gps.brand_id = p_brand_id
      and gps.date >= coalesce(p_since, '-infinity'::date)
      and gps.date <= coalesce(p_until, 'infinity'::date)
    group by 1
  ),
  ai as (
    select
      lower(public.normalize_page_path(gat.landing_page)) as page_key,
      sum(gat.sessions)::bigint as ai_sessions,
      array_remove(array_agg(distinct gat.platform), null) as ai_platforms
    from public.ga_ai_traffic_stats gat
    where gat.brand_id = p_brand_id
      and gat.date >= coalesce(p_since, '-infinity'::date)
      and gat.date <= coalesce(p_until, 'infinity'::date)
      and gat.landing_page <> ''
    group by 1
  ),
  snippet as (
    -- (brand_id, created_at) is indexed, so this reads the window's visits
    -- only.
    select
      lower(public.normalize_page_path(atl.url)) as page_key,
      count(*)::bigint as snippet_visits
    from public.ai_traffic_logs atl
    where atl.brand_id = p_brand_id
      and atl.created_at >= coalesce(p_since, '-infinity'::date)
      and atl.created_at < coalesce(p_until + 1, 'infinity'::date)
    group by 1
  )
  select
    p.landing_page,
    p.sessions,
    p.engaged_sessions,
    p.key_events,
    p.transactions,
    p.revenue,
    p.engagement_seconds,
    coalesce(a.ai_sessions, 0),
    coalesce(a.ai_platforms, '{}'::text[]),
    coalesce(c.citations, 0),
    coalesce(c.citing_prompts, 0),
    coalesce(t.targeting_prompts, 0),
    coalesce(s.snippet_visits, 0)
  from pages p
  left join ai a on a.page_key = p.page_key
  left join cited c on c.page_key = p.page_key
  left join targeted t on t.page_key = p.page_key
  left join snippet s on s.page_key = p.page_key;
$$;

-- Service-role only, as 00075 had it.
revoke all on function public.ga_page_ai_visibility(uuid, date, date)
  from public, anon, authenticated;
grant execute on function public.ga_page_ai_visibility(uuid, date, date) to service_role;

comment on function public.ga_page_ai_visibility(uuid, date, date) is
  'Per landing page for one brand (#719, AT-002): Analytics totals, AI-referred sessions, tracking-snippet AI visits, own-domain citations and prompt targeting, between p_since and p_until (both inclusive, both optional). Feeds nightly detection and the AI Traffic page''s range.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00172_ai_traffic_visits.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00172: one visit per session in the tracking snippet's data (AT-003)
-- ============================================================================
-- The snippet sends a beacon on every AI-referred page load, so a reload, a
-- back-and-forward or a second link from the same answer was stored, and
-- counted, as another visit. Recent AI Referral Visits showed three
-- identical Gemini rows for one person, and every count on the AI Traffic
-- page was a pageview count (F5).
--
-- A visit is now a session, as Google Analytics counts one: the same
-- visitor (IP address and user agent) from the same AI platform, with less
-- than 30 minutes between pageviews. A different platform starts a new
-- visit, as a new traffic source starts a new session in GA4.
--
--   * visit_of is null on the row that starts a visit and holds that row's
--     id on each further pageview of it. The beacon route decides it when
--     it stores a pageview (backend/src/lib/trafficVisits.js); the rows
--     already stored are grouped below with the same rule.
--   * A row with no IP address or no user agent can't be matched to another,
--     so it is a visit of its own.
--   * Counting visits is counting rows where visit_of is null; pageviews are
--     still every row. The partial index keeps the visit counts and the
--     visit list on the rows they read.

alter table public.ai_traffic_logs
  add column if not exists visit_of uuid
    references public.ai_traffic_logs (id) on delete cascade;

comment on column public.ai_traffic_logs.visit_of is
  'Null when this pageview starts a visit; otherwise the id of the pageview that started it. Same IP address, user agent and platform, under 30 minutes apart (AT-003).';

with ordered as (
  select
    id,
    brand_id,
    source_platform,
    ip_address,
    user_agent,
    created_at,
    ip_address is null or user_agent is null
      or lag(created_at) over visitor is null
      or created_at - lag(created_at) over visitor >= interval '30 minutes' as starts
  from public.ai_traffic_logs
  window visitor as (
    partition by brand_id, source_platform, ip_address, user_agent
    order by created_at, id
  )
),
numbered as (
  select
    *,
    count(*) filter (where starts) over (
      partition by brand_id, source_platform, ip_address, user_agent
      order by created_at, id
      rows between unbounded preceding and current row
    ) as visit_no
  from ordered
),
firsts as (
  select
    id,
    starts,
    first_value(id) over (
      partition by brand_id, source_platform, ip_address, user_agent, visit_no
      order by created_at, id
    ) as first_id
  from numbered
)
update public.ai_traffic_logs l
set visit_of = f.first_id
from firsts f
where l.id = f.id
  and not f.starts;

create index if not exists idx_ai_traffic_logs_brand_visits
  on public.ai_traffic_logs (brand_id, created_at desc)
  where visit_of is null;

create index if not exists idx_ai_traffic_logs_visit_of
  on public.ai_traffic_logs (visit_of)
  where visit_of is not null;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00173_traffic_reads_count_visits.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00173: the Action Center's traffic reads count visits, not pageviews
-- ============================================================================
-- 00172 made a visit one session: a row of ai_traffic_logs whose visit_of is
-- null starts a visit, and the rows pointing at it are its reloads and
-- further links. The AI Traffic page counts visits since then, but the two
-- detector reads below still counted every row as a session, so a signal
-- could rest on a number the page no longer shows.
--
-- Each now reads the snippet's visit starts only. Analytics' side is
-- unchanged: it already reports sessions. The bodies are otherwise 00091's
-- (ae_ai_traffic_pages) and 00143's (ae_page_traffic_evidence); the
-- signatures and return types are the same, so CREATE OR REPLACE keeps their
-- grants, and their settings are restated as they were.
--
-- Counts fall where visitors reloaded or followed a second link (14,777
-- rows were 8,983 visits on production when 00172 ran), so a detector
-- threshold is reached later on the same traffic.

create or replace function public.ae_ai_traffic_pages(
  p_brand_id uuid, p_cur_from date, p_cur_to date, p_prev_from date, p_prev_to date
) returns jsonb
language sql stable
as $$
  with ga as (
    select landing_page as page,
      sum(sessions) filter (where date between p_cur_from and p_cur_to) as cur_sessions,
      sum(sessions) filter (where date between p_prev_from and p_prev_to) as prev_sessions,
      sum(engaged_sessions) filter (where date between p_cur_from and p_cur_to) as cur_engaged,
      sum(key_events) filter (where date between p_cur_from and p_cur_to) as cur_key_events,
      sum(key_events) filter (where date between p_prev_from and p_prev_to) as prev_key_events
    from public.ga_ai_traffic_stats
    where brand_id = p_brand_id and date between p_prev_from and p_cur_to
    group by landing_page
  ),
  snippet as (
    select url as page,
      count(*) filter (where created_at::date between p_cur_from and p_cur_to) as cur_sessions,
      count(*) filter (where created_at::date between p_prev_from and p_prev_to) as prev_sessions
    from public.ai_traffic_logs
    where brand_id = p_brand_id and created_at >= p_prev_from
      and visit_of is null
    group by url
  )
  select jsonb_build_object(
    'analytics', (select coalesce(jsonb_agg(row_to_json(g)), '[]'::jsonb) from (select * from ga order by cur_sessions desc nulls last limit 300) g),
    'snippet', (select coalesce(jsonb_agg(row_to_json(s)), '[]'::jsonb) from (select * from snippet order by cur_sessions desc nulls last limit 300) s)
  )
$$;

create or replace function public.ae_page_traffic_evidence(
  p_brand_id uuid,
  p_pages text[],
  p_cur_from date,
  p_cur_to date,
  p_prev_from date,
  p_prev_to date,
  p_exact boolean default false
) returns jsonb
language sql
stable
set search_path = public
as $$
  with pages as (
    select distinct page,
      case when p_exact then page else lower(normalize_page_path(page)) end as match_key,
      lower(normalize_page_path(page)) as page_key
    from unnest(p_pages) as page
  ),
  -- Each visit row's key is computed once, so the join below is an equality
  -- the planner can hash, not a function call per row and page.
  ga_rows as (
    select platform, date, sessions,
      case
        when p_pages is null then null
        when p_exact then landing_page
        else lower(normalize_page_path(landing_page))
      end as match_key
    from ga_ai_traffic_stats
    where brand_id = p_brand_id
      and date between p_prev_from and p_cur_to
      and (p_pages is null or landing_page <> '')
  ),
  -- A visit's first pageview only (00172): its reloads are not more visits.
  log_rows as (
    select source_platform as platform, created_at,
      case
        when p_pages is null then null
        when p_exact then url
        else lower(normalize_page_path(url))
      end as match_key
    from ai_traffic_logs
    where brand_id = p_brand_id
      and created_at >= p_prev_from
      and visit_of is null
      and (p_pages is null or not p_exact or url = any(p_pages))
  ),
  analytics as (
    select pg.page, r.platform,
      coalesce(sum(r.sessions) filter (where r.date between p_cur_from and p_cur_to), 0) as cur_sessions,
      coalesce(sum(r.sessions) filter (where r.date between p_prev_from and p_prev_to), 0) as prev_sessions
    from ga_rows r
    left join pages pg on pg.match_key = r.match_key
    where p_pages is null or pg.page is not null
    group by pg.page, r.platform
  ),
  snippet as (
    select pg.page, r.platform,
      count(*) filter (where r.created_at::date between p_cur_from and p_cur_to) as cur_sessions,
      count(*) filter (where r.created_at::date between p_prev_from and p_prev_to) as prev_sessions
    from log_rows r
    left join pages pg on pg.match_key = r.match_key
    where p_pages is null or pg.page is not null
    group by pg.page, r.platform
  ),
  targeted as (
    -- Explicit targeting only, as in 00075: a URL a customer attached to a
    -- prompt is a fact; "a prompt covers this page's topic" is a guess. A
    -- paused prompt is not asked, so the page can't be cited on it.
    select distinct pg.page, p.id as prompt_id, p.text
    from prompt_target_urls ptu
    join prompts p on p.id = ptu.prompt_id
    join prompt_sets ps on ps.id = p.prompt_set_id
    join pages pg on pg.page_key = lower(normalize_page_path(ptu.url))
    where ps.brand_id = p_brand_id
      and p.is_active
  )
  select jsonb_build_object(
    'analytics', coalesce((select jsonb_agg(a) from analytics a), '[]'::jsonb),
    'snippet', coalesce((select jsonb_agg(s) from snippet s), '[]'::jsonb),
    'prompts', coalesce(
      (select jsonb_agg(t order by t.page, t.text, t.prompt_id) from targeted t),
      '[]'::jsonb
    )
  )
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00174_traffic_google_totals.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00174: Google Analytics and Search Console totals for the AI Traffic KPIs
-- ============================================================================
-- The AI Traffic page's second row of KPI cards (AT-017, spec §3.2) reads
-- Google: AI share of traffic and engaged visits and key events from AI
-- (Analytics), and Google clicks (Search Console). The tables hold a row per
-- page or query per day — up to 5,000 pages a day for Analytics — so the
-- sums are taken here rather than shipped to the browser row by row.
--
-- Both read as the caller (security invoker), so the tables' member select
-- policies decide whose brand they see, and both are granted to signed-in
-- members: the page calls them through the member's session. A null p_since
-- reads from the start (all time).

-- ─── Analytics: all sessions, and the AI channel's ─────────────────────────

create or replace function public.ga_traffic_totals(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns table (
  sessions bigint,
  ai_sessions bigint,
  ai_engaged_sessions bigint,
  ai_key_events bigint
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  select
    (
      select coalesce(sum(gps.sessions), 0)::bigint
      from public.ga_page_stats gps
      where gps.brand_id = p_brand_id
        and gps.date >= coalesce(p_since, '-infinity'::date)
        and gps.date <= p_until
    ),
    coalesce(sum(gat.sessions), 0)::bigint,
    coalesce(sum(gat.engaged_sessions), 0)::bigint,
    coalesce(sum(gat.key_events), 0)::bigint
  from public.ga_ai_traffic_stats gat
  where gat.brand_id = p_brand_id
    and gat.date >= coalesce(p_since, '-infinity'::date)
    and gat.date <= p_until;
$$;

-- ─── Search Console: clicks, against the period before ─────────────────────
--
-- Google reports with about a two-day delay, so a short range ending today
-- would read as zero clicks. With p_latest the window ends on the latest day
-- Google has reported instead, keeping its length, and the result says which
-- days it covers so the card can label them (spec §3.01). The previous
-- period is the same length, just before; all time has none.

create or replace function public.gsc_click_totals(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_latest boolean default false
)
returns table (
  since date,
  until date,
  clicks bigint,
  prev_clicks bigint,
  last_date date
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  with latest as (
    select max(g.date) as d
    from public.gsc_query_stats g
    where g.brand_id = p_brand_id
  ),
  w as (
    select
      case
        when p_latest and l.d < p_until then l.d - (p_until - p_since)
        else p_since
      end as since,
      case when p_latest and l.d < p_until then l.d else p_until end as until,
      l.d as last_date
    from latest l
  )
  select
    w.since,
    w.until,
    (
      select coalesce(sum(g.clicks), 0)::bigint
      from public.gsc_query_stats g
      where g.brand_id = p_brand_id
        and g.date >= coalesce(w.since, '-infinity'::date)
        and g.date <= w.until
    ),
    case
      when w.since is null then null
      else (
        select coalesce(sum(g.clicks), 0)::bigint
        from public.gsc_query_stats g
        where g.brand_id = p_brand_id
          and g.date >= w.since - (w.until - w.since) - 1
          and g.date < w.since
      )
    end,
    w.last_date
  from w;
$$;

revoke all on function public.ga_traffic_totals(uuid, date, date) from public, anon;
grant execute on function public.ga_traffic_totals(uuid, date, date) to authenticated, service_role;

revoke all on function public.gsc_click_totals(uuid, date, date, boolean) from public, anon;
grant execute on function public.gsc_click_totals(uuid, date, date, boolean)
  to authenticated, service_role;

comment on function public.ga_traffic_totals(uuid, date, date) is
  'AI Traffic KPIs (AT-017): all sessions and the AI channel''s sessions, engaged sessions and key events for one brand between two days (p_since null = from the start). Security invoker: RLS decides the brand.';

comment on function public.gsc_click_totals(uuid, date, date, boolean) is
  'AI Traffic KPIs (AT-017): Search Console clicks for one brand and the same-length period before. p_latest ends the window on the latest reported day. Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00175_ai_source_list.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00175: one versioned AI source list for the snippet and Google Analytics (AT-004)
-- ============================================================================
-- The tracking snippet and the Google Analytics sync each had their own list
-- of AI assistants, and they disagreed: the snippet stored chat.openai.com
-- as an engine of its own and didn't know Grok or DeepSeek; the sync didn't
-- know Google Labs or subdomains. Both now read backend/src/lib/ai-sources.json
-- (spec §5.1), which names each engine by one key.
--
--   * source_list_version records the list version that counted a row, so a
--     step in the history can be traced to a change of the list rather than
--     of the traffic. Null on rows stored before the list was versioned
--     (version 1: the two separate lists) and on visits from a cached copy of
--     the old snippet.
--   * The snippet's rows stored before it are moved onto the list's keys:
--     chat.openai.com and the bare names some old snippets sent ("chatgpt",
--     "gemini") become chatgpt.com and gemini.google.com, so one engine is
--     one row in every breakdown. Every pageview of a visit carries the same
--     value, so visits stay grouped (00172). Google Analytics rows already
--     use the keys; a history backfill re-reads them with the new list.

alter table public.ai_traffic_logs
  add column if not exists source_list_version smallint;

alter table public.ga_ai_traffic_stats
  add column if not exists source_list_version smallint;

comment on column public.ai_traffic_logs.source_list_version is
  'The AI source list version (backend/src/lib/ai-sources.json) that counted this visit; null before the list was versioned or from a cached older snippet (AT-004).';

comment on column public.ga_ai_traffic_stats.source_list_version is
  'The AI source list version (backend/src/lib/ai-sources.json) that classified this row; null before the list was versioned (AT-004).';

update public.ai_traffic_logs t
set source_platform = m.key
from (
  values
    ('chat.openai.com', 'chatgpt.com'),
    ('search.chatgpt.com', 'chatgpt.com'),
    ('chatgpt', 'chatgpt.com'),
    ('openai', 'chatgpt.com'),
    ('openai.com', 'chatgpt.com'),
    ('perplexity', 'perplexity.ai'),
    ('www.perplexity.ai', 'perplexity.ai'),
    ('claude', 'claude.ai'),
    ('gemini', 'gemini.google.com'),
    ('bard', 'gemini.google.com'),
    ('bard.google.com', 'gemini.google.com'),
    ('copilot', 'copilot.microsoft.com'),
    ('grok', 'grok.com'),
    ('deepseek', 'deepseek.com'),
    ('chat.deepseek.com', 'deepseek.com')
) as m (raw, key)
where lower(t.source_platform) = m.raw;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00176_ai_traffic_merged.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00176: AI traffic from the snippet and Google Analytics, day by day (AT-004)
-- ============================================================================
-- The AI Traffic page counted only the tracking snippet, so a brand saw no
-- history from before it installed the snippet, and nothing for days the
-- snippet was missing, although Google Analytics had those visits. Spec §5.2:
-- the snippet is the primary source for days when it was active; Google
-- Analytics fills the history before installation and any days the snippet
-- was missing. The two are never added together.
--
-- A UTC day is the snippet's when the brand has at least one snippet visit
-- that day; any other day is Google Analytics' (its AI sessions, as
-- ga_ai_traffic_stats stores them). Both now name engines by the same keys
-- (00175), so a day's platforms read the same whichever origin it came from.
--
--   * The window is [p_from, p_to] (p_to included unless p_to_inclusive is
--     false, as the previous period ends where the current one starts; a
--     null p_from reads from the start, a null p_to up to now). Snippet visits are counted by their
--     time; Analytics counts whole days, so it fills only the days fully
--     inside the window — the partial first day is left to the snippet — up
--     to p_to's day, today included.
--   * p_analytics = false reads the snippet alone: the 24-hour range trends
--     hour by hour, which Analytics can't fill.
--   * Pages are keyed by normalize_page_path (path, no query or trailing
--     slash), so a snippet URL and an Analytics landing page name one page.
--
-- Returns one jsonb value — no row cap applies — with the visits, the
-- snippet's pageviews in the window, the days Analytics filled, and the
-- visits by platform, by page and by day and platform. Security invoker: the
-- tables' member select policies decide whose brand it reads.

create or replace function public.ai_traffic_merged(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_to_inclusive boolean default true,
  p_analytics boolean default true
)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  with bounds as (
    select
      -- The first whole UTC day inside the window.
      case
        when p_from is null then null
        when (p_from at time zone 'utc')::time = time '00:00' then (p_from at time zone 'utc')::date
        else (p_from at time zone 'utc')::date + 1
      end as first_day,
      coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date) as last_day
  ),
  snippet as (
    select
      (l.created_at at time zone 'utc')::date as day,
      coalesce(nullif(l.source_platform, ''), 'unknown') as platform,
      public.normalize_page_path(l.url) as page
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at < p_to or (p_to_inclusive and l.created_at = p_to))
  ),
  -- Days the snippet was active, over the whole day, not just the window.
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l, bounds b
    where p_analytics
      and l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce((b.first_day::timestamp at time zone 'utc'), '-infinity'::timestamptz)
      and l.created_at < ((b.last_day + 1)::timestamp at time zone 'utc')
  ),
  analytics as (
    select
      g.date as day,
      coalesce(g.platform, g.source) as platform,
      public.normalize_page_path(g.landing_page) as page,
      g.sessions as visits
    from public.ga_ai_traffic_stats g, bounds b
    where p_analytics
      and g.brand_id = p_brand_id
      and g.sessions > 0
      and g.date >= coalesce(b.first_day, '-infinity'::date)
      and g.date <= b.last_day
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  merged as (
    select day, platform, page, 1::bigint as visits, 'snippet' as origin from snippet
    union all
    select day, platform, page, visits::bigint, 'analytics' from analytics
  )
  select jsonb_build_object(
    'visits', (select coalesce(sum(visits), 0) from merged),
    'pageviews', (
      select count(*)
      from public.ai_traffic_logs l
      where l.brand_id = p_brand_id
        and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
        and (p_to is null or l.created_at < p_to or (p_to_inclusive and l.created_at = p_to))
    ),
    'analytics_days', (
      select coalesce(jsonb_agg(distinct day order by day), '[]'::jsonb) from analytics
    ),
    'platforms', (
      select coalesce(jsonb_agg(jsonb_build_object('platform', platform, 'visits', visits) order by visits desc, platform), '[]'::jsonb)
      from (select platform, sum(visits) as visits from merged group by platform) t
    ),
    'pages', (
      select coalesce(jsonb_agg(jsonb_build_object('page', page, 'visits', visits) order by visits desc, page), '[]'::jsonb)
      from (select page, sum(visits) as visits from merged group by page) t
    ),
    'days', (
      select coalesce(jsonb_agg(jsonb_build_object('day', day, 'platform', platform, 'visits', visits) order by day, platform), '[]'::jsonb)
      from (select day, platform, sum(visits) as visits from merged group by day, platform) t
    )
  );
$$;

revoke all on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean)
  from public, anon;
grant execute on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean)
  to authenticated, service_role;

comment on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean) is
  'AI Traffic (AT-004, spec §5.2): AI-referred visits for one brand in a window, from the tracking snippet on days it was active and from Google Analytics on other whole days, never summed. Returns visits, the snippet''s pageviews, the days Analytics filled, and visits by platform, page and day. Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00177_traffic_platform_value.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00177: what AI visitors are worth, per platform and against Google organic (AT-005)
-- ============================================================================
-- Spec §1 question 2, "are those visitors worth anything?": engagement, key
-- events and revenue per AI platform, compared with Google organic (F6).
--
--   * ga_channel_stats: Google Analytics' sessions per day and default
--     channel group (Organic Search, Direct, AI Assistant, …) for every
--     mapped brand, synced with the AI report. Organic Search is the
--     comparison the AI Traffic page draws; a dozen rows a day per brand.
--   * key_event_sessions: the sessions with at least one key event, from
--     GA4's session key event rate. Key events alone can't give a rate — one
--     session can hold several — so the rate is this count over sessions,
--     the figure GA4's own reports show. Added to the AI and page tables
--     too; rows synced before it stay 0 until the history backfill
--     (backfillGaAiHistory.js) re-reads them.
--   * ga_traffic_totals (00174) also returns the AI sessions with a key
--     event, the AI purchase revenue, and Google organic's sessions, engaged
--     sessions and sessions with a key event, for the KPI cards.
--   * ga_platform_value: per AI platform, Analytics' sessions, engaged
--     sessions, key events and sessions with a key event, for the Referrals
--     by Platform table.
--
-- Both functions read as the caller (security invoker), so the tables'
-- member select policies decide whose brand they see.

-- ─── Channel totals ─────────────────────────────────────────────────────────

create table if not exists public.ga_channel_stats (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  date date not null,
  channel text not null,
  sessions integer not null default 0,
  engaged_sessions integer not null default 0,
  key_events integer not null default 0,
  key_event_sessions integer not null default 0,
  total_users integer not null default 0,
  transactions integer not null default 0,
  purchase_revenue double precision not null default 0,
  engagement_duration_seconds integer not null default 0,
  created_at timestamptz not null default now(),
  unique (brand_id, date, channel)
);

create index if not exists ga_channel_stats_brand_date_idx
  on public.ga_channel_stats (brand_id, date desc);

alter table public.ga_channel_stats enable row level security;

create policy "ga_channel_stats: member select" on public.ga_channel_stats
  for select using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

grant select on public.ga_channel_stats to authenticated;

comment on table public.ga_channel_stats is
  'Google Analytics sessions per day and default channel group, per brand (AT-005). Written by the GA sync with the service role; Organic Search is the AI Traffic page''s comparison.';

-- ─── Sessions with a key event ──────────────────────────────────────────────

alter table public.ga_ai_traffic_stats
  add column if not exists key_event_sessions integer not null default 0;

alter table public.ga_page_stats
  add column if not exists key_event_sessions integer not null default 0;

comment on column public.ga_ai_traffic_stats.key_event_sessions is
  'Sessions with at least one key event (GA4 session key event rate × sessions), for a rate GA4''s reports agree with (AT-005).';

comment on column public.ga_page_stats.key_event_sessions is
  'Sessions with at least one key event (GA4 session key event rate × sessions), for a rate GA4''s reports agree with (AT-005).';

-- ─── The KPI cards' Analytics totals, with Google organic ───────────────────

drop function if exists public.ga_traffic_totals(uuid, date, date);

create function public.ga_traffic_totals(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns table (
  sessions bigint,
  ai_sessions bigint,
  ai_engaged_sessions bigint,
  ai_key_events bigint,
  ai_key_event_sessions bigint,
  ai_revenue double precision,
  organic_sessions bigint,
  organic_engaged_sessions bigint,
  organic_key_events bigint,
  organic_key_event_sessions bigint
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  with ai as (
    select
      coalesce(sum(gat.sessions), 0)::bigint as sessions,
      coalesce(sum(gat.engaged_sessions), 0)::bigint as engaged_sessions,
      coalesce(sum(gat.key_events), 0)::bigint as key_events,
      coalesce(sum(gat.key_event_sessions), 0)::bigint as key_event_sessions,
      coalesce(sum(gat.purchase_revenue), 0)::double precision as revenue
    from public.ga_ai_traffic_stats gat
    where gat.brand_id = p_brand_id
      and gat.date >= coalesce(p_since, '-infinity'::date)
      and gat.date <= p_until
  ),
  organic as (
    select
      coalesce(sum(gcs.sessions), 0)::bigint as sessions,
      coalesce(sum(gcs.engaged_sessions), 0)::bigint as engaged_sessions,
      coalesce(sum(gcs.key_events), 0)::bigint as key_events,
      coalesce(sum(gcs.key_event_sessions), 0)::bigint as key_event_sessions
    from public.ga_channel_stats gcs
    where gcs.brand_id = p_brand_id
      and gcs.channel = 'Organic Search'
      and gcs.date >= coalesce(p_since, '-infinity'::date)
      and gcs.date <= p_until
  )
  select
    (
      select coalesce(sum(gps.sessions), 0)::bigint
      from public.ga_page_stats gps
      where gps.brand_id = p_brand_id
        and gps.date >= coalesce(p_since, '-infinity'::date)
        and gps.date <= p_until
    ),
    ai.sessions,
    ai.engaged_sessions,
    ai.key_events,
    ai.key_event_sessions,
    ai.revenue,
    organic.sessions,
    organic.engaged_sessions,
    organic.key_events,
    organic.key_event_sessions
  from ai, organic;
$$;

revoke all on function public.ga_traffic_totals(uuid, date, date) from public, anon;
grant execute on function public.ga_traffic_totals(uuid, date, date) to authenticated, service_role;

comment on function public.ga_traffic_totals(uuid, date, date) is
  'AI Traffic KPIs (AT-017, AT-005): all sessions; the AI channel''s sessions, engaged sessions, key events, sessions with a key event and purchase revenue; and Google organic''s sessions, engaged sessions, key events and sessions with a key event — for one brand between two days (p_since null = from the start). Security invoker: RLS decides the brand.';

-- ─── Per AI platform, for the Referrals by Platform table ───────────────────

create or replace function public.ga_platform_value(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns table (
  platform text,
  sessions bigint,
  engaged_sessions bigint,
  key_events bigint,
  key_event_sessions bigint
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  select
    coalesce(gat.platform, gat.source) as platform,
    coalesce(sum(gat.sessions), 0)::bigint,
    coalesce(sum(gat.engaged_sessions), 0)::bigint,
    coalesce(sum(gat.key_events), 0)::bigint,
    coalesce(sum(gat.key_event_sessions), 0)::bigint
  from public.ga_ai_traffic_stats gat
  where gat.brand_id = p_brand_id
    and gat.date >= coalesce(p_since, '-infinity'::date)
    and gat.date <= p_until
  group by 1;
$$;

revoke all on function public.ga_platform_value(uuid, date, date) from public, anon;
grant execute on function public.ga_platform_value(uuid, date, date) to authenticated, service_role;

comment on function public.ga_platform_value(uuid, date, date) is
  'AI Traffic (AT-005): Google Analytics'' sessions, engaged sessions, key events and sessions with a key event per AI platform, for one brand between two days (p_since null = from the start). Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00178_ai_traffic_pages.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00178: the AI Traffic page's Pages section and its status tabs (AT-006)
-- ============================================================================
-- Spec §3.5, "which answers send visitors": one table of the brand's pages
-- for the page's range, joining AI visits with how often tracked AI answers
-- cite the page and the prompts that point to it, with three work lists:
--
--   * No AI traffic — pages with traffic in Google Analytics or in the
--     site's sitemap (site_pages) that got no AI visit, ranked by value:
--     revenue, key events, then sessions and engagement. Replaces "Pages AI
--     engines aren't sending traffic to", in the page's own window (F2).
--   * Cited, not clicked — cited at least 20 times in the range, no AI visit.
--   * Traffic, no prompt — AI visits, but no tracked prompt's answer cited
--     the page in the range.
--
-- Pages are keyed by lower(normalize_page_path(...)), so a snippet URL, an
-- Analytics landing page, a cited URL and a sitemap URL name one page. AI
-- visits are ai_traffic_merged's (00176): the snippet on days it was active,
-- Analytics on the others, never summed. Checkout, login, legal and similar
-- pages are left out, as the nightly page detection leaves them out
-- (backend/src/lib/pagePaths.js; a server test keeps the two lists equal).
--
-- citation_urls has no member select policy, so both functions run as their
-- owner, after checking the caller belongs to the brand's organization; a
-- caller from elsewhere gets nothing.

-- ─── Citations of the brand's own pages ─────────────────────────────────────

create or replace function public.ai_traffic_page_citations(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns table (page_key text, page text, citations bigint)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return;
  end if;

  return query
  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  )
  select
    lower(public.normalize_page_path(cu.url)),
    min(public.normalize_page_path(cu.url)),
    sum(d.citations)::bigint
  from public.citation_url_daily d
  join public.citation_urls cu on cu.id = d.url_id
  where d.brand_id = p_brand_id
    and d.day >= coalesce(p_since, '-infinity'::date)
    and d.day <= coalesce(p_until, 'infinity'::date)
    and cu.domain in (select domain from own_domains)
  group by 1;
end;
$$;

revoke all on function public.ai_traffic_page_citations(uuid, date, date) from public, anon;
grant execute on function public.ai_traffic_page_citations(uuid, date, date)
  to authenticated, service_role;

comment on function public.ai_traffic_page_citations(uuid, date, date) is
  'AI Traffic (AT-006): how often tracked AI answers cited each of the brand''s own pages between two days, keyed by lower(normalize_page_path). Security definer with an organization check: citation_urls has no member select policy.';

-- ─── The Pages section ──────────────────────────────────────────────────────

create or replace function public.ai_traffic_pages(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_tab text default 'all',
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_since date := (p_from at time zone 'utc')::date;
  v_until date := coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date);
  -- The 24-hour range reads the snippet alone, as the rest of the page does:
  -- Analytics has no hours (00176).
  v_hourly boolean := p_from is not null and coalesce(p_to, now()) - p_from <= interval '25 hours';
  v_result jsonb;
begin
  if p_tab not in ('all', 'no_ai_traffic', 'cited_not_clicked', 'traffic_no_prompt') then
    raise exception 'unknown tab %', p_tab;
  end if;
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  with
  -- AI visits per page, day by day from the snippet or Analytics (00176).
  ai as (
    select lower(e->>'page') as page_key, min(e->>'page') as page, sum((e->>'visits')::bigint) as visits
    from jsonb_array_elements(
      public.ai_traffic_merged(p_brand_id, p_from, p_to, true, not v_hourly) -> 'pages'
    ) e
    group by 1
  ),
  -- Days the snippet was active, over the whole UTC day (00176's rule).
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(v_since::timestamp at time zone 'utc', '-infinity'::timestamptz)
      and l.created_at < (v_until + 1)::timestamp at time zone 'utc'
  ),
  -- Which assistants sent them, counted as the AI visits are: the snippet,
  -- and Analytics on days without it (never within 24 hours).
  platform_visits as (
    select lower(public.normalize_page_path(l.url)) as page_key,
           coalesce(nullif(l.source_platform, ''), 'unknown') as platform,
           count(*)::bigint as visits
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at <= p_to)
    group by 1, 2
    union all
    select lower(public.normalize_page_path(g.landing_page)),
           coalesce(g.platform, g.source),
           sum(g.sessions)::bigint
    from public.ga_ai_traffic_stats g
    where not v_hourly
      and g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.sessions > 0
      and g.date >= coalesce(v_since, '-infinity'::date)
      and g.date <= v_until
      and not exists (select 1 from snippet_days s where s.day = g.date)
    group by 1, 2
  ),
  platforms as (
    select page_key, (array_agg(platform order by visits desc, platform))[1:3] as platforms
    from (select page_key, platform, sum(visits) as visits from platform_visits group by 1, 2) t
    group by 1
  ),
  -- Key events in AI sessions: only Analytics has them, and it has no hours.
  ai_key_events as (
    select lower(public.normalize_page_path(g.landing_page)) as page_key, sum(g.key_events)::bigint as key_events
    from public.ga_ai_traffic_stats g
    where not v_hourly
      and g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= coalesce(v_since, '-infinity'::date)
      and g.date <= v_until
    group by 1
  ),
  -- Every channel's traffic, for the No AI traffic list's value.
  traffic as (
    select
      lower(public.normalize_page_path(gps.landing_page)) as page_key,
      min(public.normalize_page_path(gps.landing_page)) as page,
      sum(gps.sessions)::bigint as sessions,
      sum(gps.engaged_sessions)::bigint as engaged_sessions,
      sum(gps.key_events)::bigint as key_events,
      sum(gps.transactions)::bigint as transactions,
      sum(gps.purchase_revenue) as revenue,
      sum(gps.engagement_duration_seconds)::bigint as engagement_seconds
    from public.ga_page_stats gps
    where gps.brand_id = p_brand_id
      and gps.date >= coalesce(v_since, '-infinity'::date)
      and gps.date <= v_until
    group by 1
  ),
  cited as (
    select c.page_key, c.page, c.citations
    from public.ai_traffic_page_citations(p_brand_id, v_since, v_until) c
  ),
  -- Prompts pointing to the page: an active prompt's target URL.
  targeted as (
    select lower(public.normalize_page_path(ptu.url)) as page_key,
           count(distinct ptu.prompt_id)::bigint as prompts
    from public.prompt_target_urls ptu
    join public.prompts p on p.id = ptu.prompt_id and p.is_active
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
    group by 1
  ),
  in_sitemap as (
    select distinct lower(public.normalize_page_path(sp.url)) as page_key,
           public.normalize_page_path(sp.url) as page
    from public.site_pages sp
    where sp.brand_id = p_brand_id
      and 'sitemap' = any(sp.sources)
  ),
  keys as (
    select page_key, page from ai
    union select page_key, page from traffic
    union select page_key, page from cited
    union select page_key, page from in_sitemap
  ),
  pages as (
    select
      k.page_key,
      min(k.page) as page,
      coalesce(max(ai.visits), 0) as ai_visits,
      coalesce(max(ke.key_events), 0) as ai_key_events,
      coalesce(max(pl.platforms), '{}'::text[]) as ai_platforms,
      coalesce(max(c.citations), 0) as citations,
      coalesce(max(t.prompts), 0) as targeting_prompts,
      coalesce(max(tr.sessions), 0) as sessions,
      coalesce(max(tr.engaged_sessions), 0) as engaged_sessions,
      coalesce(max(tr.key_events), 0) as key_events,
      coalesce(max(tr.transactions), 0) as transactions,
      coalesce(max(tr.revenue), 0) as revenue,
      coalesce(max(tr.engagement_seconds), 0) as engagement_seconds,
      bool_or(s.page_key is not null) as in_sitemap
    from keys k
    left join ai on ai.page_key = k.page_key
    left join ai_key_events ke on ke.page_key = k.page_key
    left join platforms pl on pl.page_key = k.page_key
    left join cited c on c.page_key = k.page_key
    left join targeted t on t.page_key = k.page_key
    left join traffic tr on tr.page_key = k.page_key
    left join in_sitemap s on s.page_key = k.page_key
    group by k.page_key
  ),
  kept as (
    select p.*,
      -- The page's place on the site by value, among pages with traffic.
      case when p.sessions > 0 then
        rank() over (
          partition by (p.sessions > 0)
          order by p.revenue desc, p.key_events desc, p.sessions desc, p.engagement_seconds desc
        )
      end as value_rank,
      p.ai_visits = 0 and (p.sessions > 0 or p.in_sitemap) as no_ai_traffic,
      p.citations >= 20 and p.ai_visits = 0 as cited_not_clicked,
      p.ai_visits > 0 and p.citations = 0 as traffic_no_prompt
    from pages p
    where p.page not in ('', '(not set)', '(other)')
      -- The nightly detection's excluded segments (pagePaths.js).
      and not exists (
        select 1
        from unnest(string_to_array(lower(p.page), '/')) seg
        where seg = any (array[
          'checkout', 'cart', 'basket', 'order', 'orders', 'order-confirmation',
          'confirmation', 'thank-you', 'thanks', 'payment', 'pay', 'login', 'signin',
          'sign-in', 'signup', 'sign-up', 'register', 'logout', 'account', 'my-account',
          'profile', 'dashboard', 'admin', 'wishlist', 'favorites', 'search', 'career',
          'careers', 'jobs', 'job', 'cookie-policy', 'privacy', 'privacy-policy', 'terms',
          'terms-of-service', 'legal', 'unsubscribe'
        ])
      )
  ),
  tab as (
    select * from kept
    where case p_tab
      when 'no_ai_traffic' then no_ai_traffic
      when 'cited_not_clicked' then cited_not_clicked
      when 'traffic_no_prompt' then traffic_no_prompt
      else true
    end
  )
  select jsonb_build_object(
    'counts', (
      select jsonb_build_object(
        'all', count(*),
        'no_ai_traffic', count(*) filter (where no_ai_traffic),
        'cited_not_clicked', count(*) filter (where cited_not_clicked),
        'traffic_no_prompt', count(*) filter (where traffic_no_prompt)
      )
      from kept
    ),
    'rows', coalesce((
      select jsonb_agg(to_jsonb(r) - 'page_key' - 'no_ai_traffic' - 'cited_not_clicked' - 'traffic_no_prompt')
      from (
        select * from tab
        order by
          -- Each list in the order it's worked through.
          case when p_tab = 'no_ai_traffic' then revenue end desc nulls last,
          case when p_tab = 'no_ai_traffic' then key_events end desc nulls last,
          case when p_tab = 'no_ai_traffic' then sessions end desc nulls last,
          case when p_tab = 'no_ai_traffic' then engagement_seconds end desc nulls last,
          case when p_tab = 'cited_not_clicked' then citations end desc nulls last,
          ai_visits desc, citations desc, sessions desc, page
        limit greatest(p_limit, 0) offset greatest(p_offset, 0)
      ) r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer)
  from public, anon;
grant execute on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer) is
  'AI Traffic Pages section (AT-006, spec §3.5): the brand''s pages in a window with AI visits (ai_traffic_merged), AI key events, top platforms, citations, prompts pointing to them, all-channel traffic and sitemap presence; the counts of the No AI traffic / Cited, not clicked / Traffic, no prompt lists and one page of the asked tab''s rows. Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00179_ai_traffic_conversions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00179: where AI visitors convert (AT-014)
-- ============================================================================
-- Spec §3.4b, two cards that need Google Analytics:
--
--   * Top converting pages from AI — landing pages ranked by the key events
--     (or revenue, when the property reports purchases) of their AI-referred
--     sessions, with those sessions, the sessions with a key event (the rate,
--     00177) and the platform whose visitors converted most.
--   * Which answers bring buyers — AI platform × topic: the key events of a
--     platform's visitors on the pages that tracked answers in a topic cite,
--     so the topics worth protecting first are the ones that bring buyers.
--
-- Both read Analytics' own AI sessions (ga_ai_traffic_stats): the key events
-- are theirs, so the visits and the rate come from the same sessions. Pages
-- are keyed by lower(normalize_page_path(...)), as the Pages section's are
-- (00178). A topic is one of the tracked prompts whose answers cited the page
-- in the window, on any platform; a page cited in two topics counts in both.
--
-- citation_urls has no member select policy, so this runs as its owner after
-- checking the caller belongs to the brand's organization; a caller from
-- elsewhere gets nothing.

create or replace function public.ai_traffic_conversions(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_limit integer default 50
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  with
  -- Analytics' AI sessions per page and platform over the window's days.
  by_platform as (
    select
      lower(public.normalize_page_path(g.landing_page)) as page_key,
      min(public.normalize_page_path(g.landing_page)) as page,
      coalesce(g.platform, g.source) as platform,
      sum(g.sessions)::bigint as sessions,
      sum(g.key_events)::bigint as key_events,
      sum(g.key_event_sessions)::bigint as key_event_sessions,
      sum(g.transactions)::bigint as transactions,
      coalesce(sum(g.purchase_revenue), 0)::numeric as revenue
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= coalesce(p_since, '-infinity'::date)
      and g.date <= coalesce(p_until, 'infinity'::date)
    group by 1, 3
  ),
  pages as (
    select
      page_key,
      min(page) as page,
      sum(sessions)::bigint as sessions,
      sum(key_events)::bigint as key_events,
      sum(key_event_sessions)::bigint as key_event_sessions,
      sum(transactions)::bigint as transactions,
      sum(revenue) as revenue
    from by_platform
    group by page_key
  ),
  -- The platform whose visitors converted most on each page.
  best as (
    select distinct on (page_key) page_key, platform
    from by_platform
    where key_events > 0 or revenue > 0
    order by page_key, revenue desc, key_events desc, sessions desc, platform
  ),
  converting as (
    select p.*, b.platform as best_platform
    from pages p
    left join best b on b.page_key = p.page_key
    where p.key_events > 0 or p.revenue > 0
  ),
  -- The topics of the tracked prompts whose answers cited a converting page.
  own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as (
    -- citation_urls.domain is stored lowercased and without www: an index probe.
    select cu.id, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  cited_topics as (
    select distinct ou.page_key, t.id as topic_id, t.name as topic
    from own_urls ou
    join converting c on c.page_key = ou.page_key
    join public.prompt_result_citations prc
      on prc.url_id = ou.id
     and prc.brand_id = p_brand_id
     and prc.created_at >= coalesce(p_since::timestamp at time zone 'utc', '-infinity'::timestamptz)
     and prc.created_at < coalesce((p_until + 1)::timestamp at time zone 'utc', 'infinity'::timestamptz)
    join public.prompt_results pr on pr.id = prc.prompt_result_id
    join public.prompts p on p.id = pr.prompt_id
    join public.topics t on t.id = p.topic_id
  ),
  answers as (
    select
      bp.platform,
      ct.topic_id,
      min(ct.topic) as topic,
      count(distinct bp.page_key)::bigint as pages,
      sum(bp.sessions)::bigint as sessions,
      sum(bp.key_events)::bigint as key_events,
      sum(bp.key_event_sessions)::bigint as key_event_sessions,
      sum(bp.revenue) as revenue
    from by_platform bp
    join cited_topics ct on ct.page_key = bp.page_key
    group by bp.platform, ct.topic_id
    having sum(bp.key_events) > 0 or sum(bp.revenue) > 0
  )
  select jsonb_build_object(
    -- All AI sessions in the window, converting or not: the caller widens a
    -- short range that has too few to say anything.
    'sessions', (select coalesce(sum(sessions), 0) from pages),
    'has_revenue', exists (select 1 from pages where revenue > 0),
    'page_count', (select count(*) from converting),
    'answer_count', (select count(*) from answers),
    -- Ranked by revenue, which is 0 everywhere without purchases, then key events.
    'pages', coalesce((
      select jsonb_agg(to_jsonb(r) - 'page_key')
      from (
        select * from converting
        order by revenue desc, key_events desc, sessions desc, page
        limit p_limit
      ) r
    ), '[]'::jsonb),
    'answers', coalesce((
      select jsonb_agg(to_jsonb(a))
      from (
        select * from answers
        order by revenue desc, key_events desc, sessions desc, platform, topic
        limit p_limit
      ) a
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_conversions(uuid, date, date, integer) from public, anon;
grant execute on function public.ai_traffic_conversions(uuid, date, date, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_conversions(uuid, date, date, integer) is
  'AI Traffic "Where AI visitors convert" (AT-014, spec §3.4b): converting landing pages from Analytics'' AI sessions (sessions, key events, sessions with a key event, revenue, best platform) and AI platform × topic of the tracked prompts whose answers cite them. Security definer with an organization check: citation_urls has no member select policy.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00180_ai_traffic_google_trend.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00180: AI visits vs Google clicks (AT-008, part A)
-- ============================================================================
-- Spec §3.3: the AI Referral Trend card gets a "vs Google clicks" view. It
-- shows AI visits and Google organic clicks, each indexed to 100 at the
-- start of the range, with markers on the days actions entered the Action
-- Center and prompts were added. The AI line is the page's own trend; this
-- reads the rest, by UTC day like the trend's buckets:
--
--   * clicks: Search Console clicks per day, summed over the brand's queries
--     the way the Google clicks card sums them (00174);
--   * first_day / last_day: the first and latest day Search Console has rows
--     for the brand. Before the first the sync has no history (it keeps 90
--     days); after the latest Google hasn't reported yet (about two days
--     late, §3.01). The chart leaves both blank rather than drawing 0;
--   * markers: per day, the actions created in the Action Center and the
--     prompts added to the brand's sets.
--
-- Security invoker: gsc_query_stats, actions and prompts each have a member
-- select policy, so RLS decides the brand.

create or replace function public.ai_traffic_google_trend(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  select jsonb_build_object(
    'first_day', (
      select min(g.date) from public.gsc_query_stats g where g.brand_id = p_brand_id
    ),
    'last_day', (
      select max(g.date) from public.gsc_query_stats g where g.brand_id = p_brand_id
    ),
    'clicks', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'clicks', d.clicks) order by d.day)
      from (
        select g.date as day, sum(g.clicks)::bigint as clicks
        from public.gsc_query_stats g
        where g.brand_id = p_brand_id
          and g.date >= p_since
          and g.date <= p_until
        group by g.date
      ) d
    ), '[]'::jsonb),
    'markers', coalesce((
      select jsonb_agg(
        jsonb_build_object('day', m.day, 'actions', m.actions, 'prompts', m.prompts)
        order by m.day
      )
      from (
        select
          e.day,
          count(*) filter (where e.kind = 'action') as actions,
          count(*) filter (where e.kind = 'prompt') as prompts
        from (
          select (a.created_at at time zone 'UTC')::date as day, 'action' as kind
          from public.actions a
          where a.brand_id = p_brand_id
            and a.created_at >= p_since::timestamp at time zone 'UTC'
            and a.created_at < (p_until + 1)::timestamp at time zone 'UTC'
          union all
          select (p.created_at at time zone 'UTC')::date, 'prompt'
          from public.prompts p
          join public.prompt_sets s on s.id = p.prompt_set_id
          where s.brand_id = p_brand_id
            and p.created_at >= p_since::timestamp at time zone 'UTC'
            and p.created_at < (p_until + 1)::timestamp at time zone 'UTC'
        ) e
        group by e.day
      ) m
    ), '[]'::jsonb)
  );
$$;

revoke all on function public.ai_traffic_google_trend(uuid, date, date) from public, anon;
grant execute on function public.ai_traffic_google_trend(uuid, date, date)
  to authenticated, service_role;

comment on function public.ai_traffic_google_trend(uuid, date, date) is
  'AI Traffic "vs Google clicks" trend (AT-008, spec §3.3): Search Console clicks per UTC day, the first and latest day Search Console has rows for the brand, and per day the actions created in the Action Center and the prompts added. Security invoker: RLS decides the brand.';

