-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00181_gsc_page_stats.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00181: Search Console by page, and "Is AI taking Google clicks?" (AT-008, part B)
-- ============================================================================
-- Spec §3.6: pages whose Google impressions rose at least 15% while their
-- click-through rate fell at least 20% against the period before — the
-- pattern of an AI Overview answering in place of the click. The next step
-- for each page is the Positions panel of a tracked prompt about it.
--
-- gsc_query_stats (00047) holds Search Console by query, which can't say
-- which page lost clicks, and drops anonymised queries. gsc_page_stats holds
-- it by page and day, synced alongside (backend/src/lib/gscSync.js): a
-- brand's sync reads 190 days so a 90-day range has a whole period before it,
-- Google's delay included, until one gets through them all for its property
-- (brands.gsc_pages_backfilled_property); later ones read the last 28, and
-- rows older than 190 days are pruned. The sync (service role) upserts on
-- (brand_id, page, date); org members read.
--
-- page_key is the page as the Pages section keys it (00178), stored: worked
-- out per row at read time it took 4 s warm, 18 s cold, on 110k rows (the
-- largest brand's 600 pages × 183 days); grouped by the column, 46 ms.

create table public.gsc_page_stats (
    id uuid primary key default gen_random_uuid(),
    brand_id uuid not null references public.brands(id) on delete cascade,
    page text not null,
    page_key text generated always as (lower(public.normalize_page_path(page))) stored,
    date date not null,
    clicks integer not null default 0,
    impressions integer not null default 0,
    ctr double precision not null default 0,
    position double precision not null default 0,
    created_at timestamptz not null default now(),
    unique (brand_id, page, date)
);

create index gsc_page_stats_brand_date_idx
    on public.gsc_page_stats (brand_id, date desc);

-- The sync's table-wide retention prune (date < 190 days ago).
create index gsc_page_stats_date_idx
    on public.gsc_page_stats (date);

-- The property whose 190 days of pages the sync has read in full. Until it
-- matches gsc_property, every sync reads them again, so a first sync cut
-- short resumes; when it names another property, that one's page rows are
-- dropped first.
alter table public.brands
    add column if not exists gsc_pages_backfilled_property text;

alter table public.gsc_page_stats enable row level security;

create policy "gsc_page_stats: member select" on public.gsc_page_stats
    for select using (
        brand_id in (
            select b.id
            from public.brands b
            join public.profiles p on p.organization_id = b.organization_id
            where p.id = auth.uid()
        )
    );

grant select on public.gsc_page_stats to authenticated;

-- ─── Is AI taking Google clicks? ────────────────────────────────────────────
--
-- Pages are keyed by lower(normalize_page_path(...)), as the Pages section's
-- are (00178). A page qualifies when the period before had at least
-- p_min_impressions impressions (fewer would make the percentages noise),
-- impressions rose by 15% or more and the CTR fell by 20% or more. Rows come
-- most clicks lost first: the previous CTR's clicks on this period's
-- impressions, minus the clicks there were.
--
-- Google reports about two days late: with p_latest the window ends on the
-- latest day it has reported, keeping its length (§3.01), as the Google
-- clicks card's does (00174). All time (p_since null) has no period before.
-- When the brand's page history doesn't reach back to the start of the
-- period before (a property connected lately, a long custom range), its
-- impressions would read low and every page as rising: the result says
-- `incomplete` and lists nothing.
--
-- Each row names one tracked prompt about the page, for its Positions panel:
-- an active prompt whose target URL is the page, else an active prompt whose
-- answers cited it over the last 90 days. citation_urls has no member select
-- policy, so this runs as its owner after checking the caller belongs to the
-- brand's organization; a caller from elsewhere gets nothing.

create or replace function public.ai_traffic_google_pages(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_latest boolean default false,
  p_min_impressions integer default 100,
  p_limit integer default 50
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_first date;
  v_last date;
  v_since date;
  v_until date;
  v_prev_since date;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  select min(g.date), max(g.date) into v_first, v_last
  from public.gsc_page_stats g
  where g.brand_id = p_brand_id;

  if p_since is null or v_last is null then
    return jsonb_build_object(
      'last_day', v_last,
      'since', null, 'until', null, 'prev_since', null, 'prev_until', null,
      'incomplete', false, 'count', 0, 'rows', '[]'::jsonb
    );
  end if;

  v_since := p_since;
  v_until := p_until;
  if p_latest and v_last < p_until then
    v_since := v_last - (p_until - p_since);
    v_until := v_last;
  end if;
  v_prev_since := v_since - (v_until - v_since) - 1;

  if v_first > v_prev_since then
    return jsonb_build_object(
      'last_day', v_last,
      'since', v_since, 'until', v_until,
      'prev_since', v_prev_since, 'prev_until', v_since - 1,
      'incomplete', true, 'count', 0, 'rows', '[]'::jsonb
    );
  end if;

  with by_page as (
    select
      g.page_key,
      min(g.page) as url,
      sum(g.impressions) filter (where g.date >= v_since)::bigint as impressions,
      sum(g.clicks) filter (where g.date >= v_since)::bigint as clicks,
      sum(g.impressions) filter (where g.date < v_since)::bigint as prev_impressions,
      sum(g.clicks) filter (where g.date < v_since)::bigint as prev_clicks
    from public.gsc_page_stats g
    where g.brand_id = p_brand_id
      and g.date >= v_prev_since
      and g.date <= v_until
    group by 1
  ),
  flagged as (
    select
      bp.*,
      bp.clicks::double precision / nullif(bp.impressions, 0) as ctr,
      bp.prev_clicks::double precision / nullif(bp.prev_impressions, 0) as prev_ctr
    from by_page bp
    where bp.prev_impressions >= greatest(p_min_impressions, 1)
      and bp.prev_clicks > 0
      and bp.impressions >= bp.prev_impressions * 1.15
      and bp.clicks::double precision / nullif(bp.impressions, 0)
          <= 0.8 * bp.prev_clicks::double precision / nullif(bp.prev_impressions, 0)
  ),
  -- Only the rows shown work out their display path.
  ranked as (
    select f.*, public.normalize_page_path(f.url) as page,
      f.prev_ctr * f.impressions - f.clicks as clicks_lost
    from flagged f
    order by clicks_lost desc, f.impressions desc, f.page_key
    limit p_limit
  ),
  -- A tracked prompt pointing to the page.
  targeted as (
    select distinct on (lower(public.normalize_page_path(ptu.url)))
      lower(public.normalize_page_path(ptu.url)) as page_key,
      ptu.prompt_id
    from public.prompt_target_urls ptu
    join public.prompts p on p.id = ptu.prompt_id and p.is_active
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and lower(public.normalize_page_path(ptu.url)) in (select page_key from ranked)
    order by lower(public.normalize_page_path(ptu.url)), p.created_at, ptu.prompt_id
  ),
  -- Else an active prompt that cited the page in 90 days.
  own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as (
    select cu.id, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
      and lower(public.normalize_page_path(cu.url)) in (
        select r.page_key from ranked r
        where r.page_key not in (select t.page_key from targeted t)
      )
  ),
  -- The first citation found whose prompt is active, not the latest or the
  -- most-citing one: ordering needs every citation's created_at, a heap read
  -- for each (the (url_id, brand_id) index has none), 35,700 rows and 7.5 s
  -- cold on the largest brand's 50 pages, past the 8 s timeout with the rest.
  -- Stopping at the first match read about 2,100 pages, in 2 s. Any prompt
  -- that cited the page serves the Positions link, and a paused one is
  -- skipped rather than leaving the page without one.
  cited as (
    select pk.page_key, c.prompt_id
    from (
      select ou.page_key, array_agg(ou.id) as url_ids
      from own_urls ou
      group by ou.page_key
    ) pk
    cross join lateral (
      select pr.prompt_id
      from public.prompt_result_citations prc
      join public.prompt_results pr on pr.id = prc.prompt_result_id
      join public.prompts p on p.id = pr.prompt_id and p.is_active
      where prc.url_id = any (pk.url_ids)
        and prc.brand_id = p_brand_id
        and prc.created_at >= now() - interval '90 days'
      limit 1
    ) c
  )
  select jsonb_build_object(
    'last_day', v_last,
    'since', v_since,
    'until', v_until,
    'prev_since', v_prev_since,
    'prev_until', v_since - 1,
    'incomplete', false,
    'count', (select count(*) from flagged),
    'rows', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', r.page,
          'url', r.url,
          'impressions', r.impressions,
          'prev_impressions', r.prev_impressions,
          'clicks', r.clicks,
          'prev_clicks', r.prev_clicks,
          'prompt_id', coalesce(t.prompt_id, c.prompt_id)
        )
        order by r.clicks_lost desc, r.impressions desc, r.page_key
      )
      from ranked r
      left join targeted t on t.page_key = r.page_key
      left join cited c on c.page_key = r.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_google_pages(uuid, date, date, boolean, integer, integer)
  from public, anon;
grant execute on function public.ai_traffic_google_pages(uuid, date, date, boolean, integer, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_google_pages(uuid, date, date, boolean, integer, integer) is
  'AI Traffic "Is AI taking Google clicks?" (AT-008, spec §3.6): pages whose Search Console impressions rose 15%+ while CTR fell 20%+ against the period before (at least p_min_impressions impressions before), most clicks lost first, each with a tracked prompt about it for its Positions panel (its target URL, else an active prompt that cited it in 90 days). p_latest ends the window on Google''s latest reported day. Security definer with an organization check: citation_urls has no member select policy.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00182_ai_traffic_google_queries.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00182: Google queries you don't track yet (AT-009)
-- ============================================================================
-- Spec §3.6: the top Search Console queries by clicks that match no tracked
-- prompt, to track with one click. This reads the queries with clicks in
-- the window, most clicks first. Which of them a prompt already covers is
-- the server's call (backend/src/lib/untrackedQueries.js), with the rule
-- Prompt Suggestions uses for Google queries, so the two pages agree.
--
-- Google reports about two days late: with p_latest the window ends on the
-- latest day it has reported, keeping its length (§3.01), as the Google
-- clicks card's does (00174). All time (p_since null) reads every day kept.
-- At most p_limit queries; `capped` says there were more.
--
-- Security invoker: gsc_query_stats has a member select policy, so RLS
-- decides the brand. The server reads it as the service role, after
-- checking the member's access to the brand.

create or replace function public.ai_traffic_google_queries(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_latest boolean default false,
  p_limit integer default 5000
)
returns jsonb
language plpgsql
stable
security invoker
set search_path to 'public'
as $$
declare
  v_last date;
  v_since date;
  v_until date;
  v_rows jsonb;
  v_count integer;
begin
  select max(g.date) into v_last from public.gsc_query_stats g where g.brand_id = p_brand_id;
  if v_last is null then
    return jsonb_build_object(
      'last_day', null, 'since', null, 'until', null, 'capped', false, 'rows', '[]'::jsonb
    );
  end if;

  v_since := p_since;
  v_until := p_until;
  if p_latest and v_last < p_until then
    v_until := v_last;
    if p_since is not null then
      v_since := v_last - (p_until - p_since);
    end if;
  end if;

  select
    coalesce(jsonb_agg(
      jsonb_build_object('query', q.query, 'clicks', q.clicks, 'impressions', q.impressions)
      order by q.clicks desc, q.impressions desc, q.query
    ), '[]'::jsonb),
    count(*)
  into v_rows, v_count
  from (
    select g.query, sum(g.clicks)::bigint as clicks, sum(g.impressions)::bigint as impressions
    from public.gsc_query_stats g
    where g.brand_id = p_brand_id
      and g.date >= coalesce(v_since, '-infinity'::date)
      and g.date <= v_until
    group by g.query
    having sum(g.clicks) > 0
    order by sum(g.clicks) desc, sum(g.impressions) desc, g.query
    limit greatest(p_limit, 0) + 1
  ) q;

  if v_count > p_limit then
    v_rows := v_rows - p_limit;
  end if;

  return jsonb_build_object(
    'last_day', v_last,
    'since', v_since,
    'until', v_until,
    'capped', v_count > p_limit,
    'rows', v_rows
  );
end;
$$;

revoke all on function public.ai_traffic_google_queries(uuid, date, date, boolean, integer)
  from public, anon;
grant execute on function public.ai_traffic_google_queries(uuid, date, date, boolean, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_google_queries(uuid, date, date, boolean, integer) is
  'AI Traffic "Google queries you don''t track yet" (AT-009, spec §3.6): Search Console queries with clicks between two days, most clicks first, at most p_limit (capped says there were more). p_latest ends the window on Google''s latest reported day. The server drops the ones a tracked prompt covers. Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00183_ai_bot_events.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00183: AI bots reading the site — ingestion and its hard caps (AT-010, part A)
-- ============================================================================
-- Spec §3.7 and §6: which AI bots read the brand's pages, sent from the
-- customer's own Cloudflare or Vercel. A request counts only when its user
-- agent names a bot on the list (backend/src/lib/ai-bots.json) and its IP is
-- in that operator's published ranges; the server checks both before
-- writing, and keeps no IP.
--
--   * ai_bot_connections — one per way a brand sends events (a Cloudflare
--     Worker, a Logpush job, a Vercel drain), each with its own secret.
--     Only the secret's SHA-256 is kept; the person sees it once.
--   * ai_bot_events — one row per verified request, kept 90 days.
--   * ai_bot_daily — bot × page × day counters, always added to. When the
--     month's cap is reached they are all that is written ("Detailed rows
--     paused until Nov 1, totals still counted", §6.3), and past it a bot's
--     hits of the day go on one '(other)' row instead of a row per page:
--     crawler hits are mostly a page, day and bot of their own, so page rows
--     would grow by about one per event. The cap is then a hard ceiling on
--     what is stored.
--   * ai_bot_usage — per organization (the workspace) and month: rows
--     stored, events counted, when the cap was reached, and when the 80%
--     alert fired (§6.3 guardrails).
--
-- Members read their brands' events, counters and connections (all but the
-- secret's hash); only the service role writes.

create table public.ai_bot_connections (
    id uuid primary key default gen_random_uuid(),
    brand_id uuid not null references public.brands(id) on delete cascade,
    kind text not null check (kind in ('cloudflare_worker', 'cloudflare_logpush', 'vercel_drain')),
    secret_hash text not null unique,
    created_by uuid references public.profiles(id) on delete set null,
    created_at timestamptz not null default now(),
    last_event_at timestamptz,
    revoked_at timestamptz
);

create index ai_bot_connections_brand_idx on public.ai_bot_connections (brand_id);

create table public.ai_bot_events (
    id bigint generated always as identity primary key,
    brand_id uuid not null references public.brands(id) on delete cascade,
    bot text not null,
    bot_type text not null check (bot_type in ('training', 'search', 'user')),
    -- The path, as the Pages section keys pages (lower(normalize_page_path)).
    page text not null,
    status smallint,
    country text,
    occurred_at timestamptz not null,
    received_at timestamptz not null default now()
);

create index ai_bot_events_brand_time_idx on public.ai_bot_events (brand_id, occurred_at desc);
-- The daily prune deletes by time across every brand.
create index ai_bot_events_time_idx on public.ai_bot_events (occurred_at);

create table public.ai_bot_daily (
    brand_id uuid not null references public.brands(id) on delete cascade,
    day date not null,
    bot text not null,
    bot_type text not null check (bot_type in ('training', 'search', 'user')),
    page text not null,
    hits integer not null default 0,
    last_seen timestamptz not null,
    primary key (brand_id, day, bot, page)
);

create index ai_bot_daily_brand_day_idx on public.ai_bot_daily (brand_id, day desc);
create index ai_bot_daily_day_idx on public.ai_bot_daily (day);

create table public.ai_bot_usage (
    organization_id uuid not null references public.organizations(id) on delete cascade,
    month date not null,
    stored_events bigint not null default 0,
    counted_events bigint not null default 0,
    capped_at timestamptz,
    alerted_at timestamptz,
    primary key (organization_id, month)
);

alter table public.ai_bot_connections enable row level security;
alter table public.ai_bot_events enable row level security;
alter table public.ai_bot_daily enable row level security;
alter table public.ai_bot_usage enable row level security;

create policy "ai_bot_connections: member select" on public.ai_bot_connections
    for select using (
        brand_id in (
            select b.id
            from public.brands b
            join public.profiles p on p.organization_id = b.organization_id
            where p.id = auth.uid()
        )
    );

create policy "ai_bot_events: member select" on public.ai_bot_events
    for select using (
        brand_id in (
            select b.id
            from public.brands b
            join public.profiles p on p.organization_id = b.organization_id
            where p.id = auth.uid()
        )
    );

create policy "ai_bot_daily: member select" on public.ai_bot_daily
    for select using (
        brand_id in (
            select b.id
            from public.brands b
            join public.profiles p on p.organization_id = b.organization_id
            where p.id = auth.uid()
        )
    );

create policy "ai_bot_usage: member select" on public.ai_bot_usage
    for select using (
        organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid())
    );

-- The secret's hash stays with the server: members read every other column.
revoke all on public.ai_bot_connections from anon, authenticated;
grant select (id, brand_id, kind, created_by, created_at, last_event_at, revoked_at)
    on public.ai_bot_connections to authenticated;
grant select on public.ai_bot_events to authenticated;
grant select on public.ai_bot_daily to authenticated;
grant select on public.ai_bot_usage to authenticated;

-- ─── One batch of verified events, within the month's cap ──────────────────
--
-- p_events: [{bot, bot_type, page, status, country, at}], already verified;
-- `page` is the request's URL or path, keyed here as the Pages section keys
-- pages (lower(normalize_page_path), 00178).
-- The usage row is locked for the batch, so two batches for one
-- organization can't both take the last of its room. Rows are stored while
-- the month has room (p_cap < 0: no cap; 0: none stored); counters are
-- always added, by page for the events stored and on the bot's '(other)' row
-- of the day for the rest. Returns what was received and stored, the month's use, and
-- whether this batch took it past 80% of the cap (the server alerts once).

create or replace function public.ai_bot_ingest(
  p_connection_id uuid,
  p_cap bigint,
  p_events jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_brand uuid;
  v_org uuid;
  v_month date := date_trunc('month', now() at time zone 'utc')::date;
  v_used bigint;
  v_received integer := coalesce(jsonb_array_length(p_events), 0);
  v_room bigint;
  v_stored integer := 0;
  v_alerted timestamptz;
  v_crossed boolean := false;
begin
  select c.brand_id, b.organization_id into v_brand, v_org
  from public.ai_bot_connections c
  join public.brands b on b.id = c.brand_id
  where c.id = p_connection_id and c.revoked_at is null;
  if v_brand is null then
    return jsonb_build_object('error', 'connection');
  end if;

  insert into public.ai_bot_usage (organization_id, month)
  values (v_org, v_month)
  on conflict (organization_id, month) do nothing;

  select u.stored_events, u.alerted_at into v_used, v_alerted
  from public.ai_bot_usage u
  where u.organization_id = v_org and u.month = v_month
  for update;

  v_room := case when p_cap < 0 then v_received else greatest(0, least(v_received, p_cap - v_used)) end;

  if v_room > 0 then
    insert into public.ai_bot_events (brand_id, bot, bot_type, page, status, country, occurred_at)
    select
      v_brand,
      x.ev ->> 'bot',
      x.ev ->> 'bot_type',
      lower(public.normalize_page_path(x.ev ->> 'page')),
      (x.ev ->> 'status')::smallint,
      x.ev ->> 'country',
      (x.ev ->> 'at')::timestamptz
    from jsonb_array_elements(p_events) with ordinality as x(ev, n)
    order by x.n
    limit v_room;
    get diagnostics v_stored = row_count;
  end if;

  insert into public.ai_bot_daily (brand_id, day, bot, bot_type, page, hits, last_seen)
  select v_brand, e.day, e.bot, min(e.bot_type), e.page, count(*), max(e.at)
  from (
    select
      (r.at at time zone 'utc')::date as day,
      r.bot,
      r.bot_type,
      case
        when x.n <= v_room then lower(public.normalize_page_path(r.page))
        else '(other)'
      end as page,
      r.at
    from jsonb_array_elements(p_events) with ordinality as x(ev, n)
    cross join lateral jsonb_to_record(x.ev)
      as r(bot text, bot_type text, page text, at timestamptz)
  ) e
  group by e.day, e.bot, e.page
  on conflict (brand_id, day, bot, page) do update
    set hits = public.ai_bot_daily.hits + excluded.hits,
        last_seen = greatest(public.ai_bot_daily.last_seen, excluded.last_seen);

  v_crossed := p_cap > 0 and v_alerted is null and v_used + v_stored >= 0.8 * p_cap;

  update public.ai_bot_usage u
  set stored_events = u.stored_events + v_stored,
      counted_events = u.counted_events + v_received,
      capped_at = case
        when p_cap >= 0 and u.capped_at is null and v_stored < v_received then now()
        else u.capped_at
      end,
      alerted_at = case when v_crossed then now() else u.alerted_at end
  where u.organization_id = v_org and u.month = v_month;

  update public.ai_bot_connections c
  set last_event_at = now()
  where c.id = p_connection_id and v_received > 0;

  return jsonb_build_object(
    'brand_id', v_brand,
    'organization_id', v_org,
    'received', v_received,
    'stored', v_stored,
    'used', v_used + v_stored,
    'cap', p_cap,
    'crossed80', v_crossed
  );
end;
$$;

revoke all on function public.ai_bot_ingest(uuid, bigint, jsonb) from public, anon, authenticated;
grant execute on function public.ai_bot_ingest(uuid, bigint, jsonb) to service_role;

comment on function public.ai_bot_ingest(uuid, bigint, jsonb) is
  'AI bots (AT-010, spec §6.3): one batch of verified bot events for a connection. Stores rows while the organization''s month has room under p_cap (<0 = no cap), always adds bot × page × day counters, and reports whether the batch crossed 80% of the cap. Locks the usage row so concurrent batches cannot exceed it. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00184_ai_bot_raw_records.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00184: the raw-record cap for log senders (AT-010, part B)
-- ============================================================================
-- Spec §6.1 and §6.3: a Vercel drain sends every request log and the server
-- filters them, so it needs its own cap on what it receives (Growth 20M raw
-- records a month, Enterprise 200M). A Cloudflare Logpush job is filtered to
-- AI bots at the edge, but a job set up without the filter would send every
-- line, so the same cap guards it.
--
-- ai_bot_usage gains the month's raw records and when that cap was reached;
-- ai_bot_ingested_files keeps a retried file from being read twice.
-- ai_bot_count_raw adds a batch's records under the usage row's lock and
-- says whether the batch may be read: yes while the month was under the cap
-- when it arrived, so a month overshoots by at most the batch that crosses
-- it (a drain sends at most 1 MB). After that, batches are only counted.

alter table public.ai_bot_usage
  add column raw_records bigint not null default 0,
  add column raw_capped_at timestamptz;

-- A log file a sender sends again (it timed out waiting, say) is read once:
-- each connection's files by the SHA-256 of their body, claimed before the
-- read and given back when it fails, kept 7 days (the daily prune). No
-- policies: only the service role reads or writes.
create table public.ai_bot_ingested_files (
    connection_id uuid not null references public.ai_bot_connections(id) on delete cascade,
    body_hash text not null,
    received_at timestamptz not null default now(),
    primary key (connection_id, body_hash)
);

create index ai_bot_ingested_files_time_idx on public.ai_bot_ingested_files (received_at);

alter table public.ai_bot_ingested_files enable row level security;

create or replace function public.ai_bot_count_raw(
  p_connection_id uuid,
  p_count bigint,
  p_cap bigint
)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_org uuid;
  v_month date := date_trunc('month', now() at time zone 'utc')::date;
  v_raw bigint;
  v_allowed boolean;
begin
  select b.organization_id into v_org
  from public.ai_bot_connections c
  join public.brands b on b.id = c.brand_id
  where c.id = p_connection_id and c.revoked_at is null;
  if v_org is null then
    return jsonb_build_object('error', 'connection');
  end if;

  insert into public.ai_bot_usage (organization_id, month)
  values (v_org, v_month)
  on conflict (organization_id, month) do nothing;

  select u.raw_records into v_raw
  from public.ai_bot_usage u
  where u.organization_id = v_org and u.month = v_month
  for update;

  v_allowed := p_cap < 0 or v_raw < p_cap;

  update public.ai_bot_usage u
  set raw_records = u.raw_records + greatest(p_count, 0),
      raw_capped_at = case
        when p_cap >= 0 and u.raw_capped_at is null and u.raw_records + greatest(p_count, 0) >= p_cap
          then now()
        else u.raw_capped_at
      end
  where u.organization_id = v_org and u.month = v_month;

  return jsonb_build_object(
    'allowed', v_allowed,
    'raw', v_raw + greatest(p_count, 0),
    'cap', p_cap
  );
end;
$$;

revoke all on function public.ai_bot_count_raw(uuid, bigint, bigint) from public, anon, authenticated;
grant execute on function public.ai_bot_count_raw(uuid, bigint, bigint) to service_role;

comment on function public.ai_bot_count_raw(uuid, bigint, bigint) is
  'AI bots (AT-010, spec §6.3): adds a log sender''s batch to the organization''s raw records this month and says whether it may be read (the month was under p_cap when it arrived; <0 = no cap). Locks the usage row. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00185_ai_bot_report.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00185: the AI bot report (AT-011)
-- ============================================================================
-- Spec §3.7, "AI bots reading your site": the verified AI-bot requests a
-- brand's Cloudflare or Vercel sent (00183), read from the bot × page × day
-- counters, which hold every request even past the month's cap:
--
--   * types — training crawlers, search crawlers and user fetches, reported
--     separately: hits, pages read and when last seen, with the bots seen;
--   * bots — the same per bot;
--   * pages — the most read pages, with when each type last read them (the
--     per-page last crawl);
--   * uncrawled — the alert "cited pages not read by any search bot in 30
--     days": pages tracked AI answers cited in the last 30 days that no
--     search crawler read in them. It only means something while the bot
--     data is whole, so it is null, and alert_state says why, until the
--     first request is 30 days old ('waiting'), and when no live connection
--     has sent for 2 days or search hits went on '(other)' rows past the
--     month's cap in those 30 days ('stale': a sender stopped, was revoked
--     or hit its raw cap, and the 30 days of pages read would drain).
--
-- "All time" (p_since null) covers the last 90 days here: a site crawled at
-- 10k pages a day keeps millions of rows over the counters' 400 days. The
-- rows are added up once by bot and page, and the first and last day come
-- from the ends of the (brand_id, day) index.
--
-- Pages are keyed as the Pages section keys them (00178). citation_urls has
-- no member select policy, so this runs as its owner after checking the
-- caller belongs to the brand's organization; a caller from elsewhere gets
-- nothing.

create or replace function public.ai_bot_report(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_limit integer default 20
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_first date;
  v_last_day date;
  v_last timestamptz;
  v_since date;
  v_alert text;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  select d.day into v_first
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id
  order by d.day
  limit 1;
  select d.day into v_last_day
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id
  order by d.day desc
  limit 1;
  select max(d.last_seen) into v_last
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id and d.day = v_last_day;

  v_since := coalesce(p_since, current_date - 89);

  v_alert := case
    when v_first is null or v_first > current_date - 29 then 'waiting'
    when not exists (
      select 1 from public.ai_bot_connections c
      where c.brand_id = p_brand_id
        and c.revoked_at is null
        and c.last_event_at >= now() - interval '2 days'
    ) or exists (
      select 1 from public.ai_bot_daily d
      where d.brand_id = p_brand_id
        and d.bot_type = 'search'
        and d.page = '(other)'
        and d.day >= current_date - 29
    ) then 'stale'
    else 'on'
  end;

  with g as (
    -- Each bot's hits on each page in the range, added up once.
    select
      d.bot_type,
      d.bot,
      d.page,
      sum(d.hits)::bigint as hits,
      max(d.last_seen) as last_seen
    from public.ai_bot_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_since
      and d.day <= p_until
    group by d.bot_type, d.bot, d.page
  ),
  types as (
    select
      g.bot_type,
      sum(g.hits)::bigint as hits,
      count(distinct g.page) filter (where g.page <> '(other)')::bigint as pages,
      max(g.last_seen) as last_seen,
      array_agg(distinct g.bot order by g.bot) as bots
    from g
    group by g.bot_type
  ),
  bots as (
    select
      g.bot,
      min(g.bot_type) as bot_type,
      sum(g.hits)::bigint as hits,
      count(*) filter (where g.page <> '(other)')::bigint as pages,
      max(g.last_seen) as last_seen
    from g
    group by g.bot
  ),
  -- Hits folded past the month's cap ('(other)') aren't a page.
  pages as (
    select
      g.page,
      sum(g.hits)::bigint as hits,
      max(g.last_seen) filter (where g.bot_type = 'training') as training_last,
      max(g.last_seen) filter (where g.bot_type = 'search') as search_last,
      max(g.last_seen) filter (where g.bot_type = 'user') as user_last
    from g
    where g.page <> '(other)'
    group by g.page
  ),
  -- The alert reads its own 30 days, whatever the range.
  uncrawled as (
    select c.page, c.citations
    from public.ai_traffic_page_citations(p_brand_id, current_date - 29, current_date) c
    where v_alert = 'on'
      and not exists (
        select 1 from public.ai_bot_daily d
        where d.brand_id = p_brand_id
          and d.bot_type = 'search'
          and d.page = c.page_key
          and d.day >= current_date - 29
      )
  )
  select jsonb_build_object(
    'first_day', v_first,
    'last_seen', v_last,
    'types', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'type', t.bot_type, 'hits', t.hits, 'pages', t.pages,
          'last_seen', t.last_seen, 'bots', to_jsonb(t.bots)
        )
        order by array_position(array['training', 'search', 'user'], t.bot_type)
      )
      from types t
    ), '[]'::jsonb),
    'bots', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'bot', b.bot, 'type', b.bot_type, 'hits', b.hits, 'pages', b.pages,
          'last_seen', b.last_seen
        )
        order by b.hits desc, b.bot
      )
      from bots b
    ), '[]'::jsonb),
    'page_count', (select count(*) from pages),
    'pages', coalesce((
      select jsonb_agg(to_jsonb(p) order by p.hits desc, p.page)
      from (select * from pages order by hits desc, page limit p_limit) p
    ), '[]'::jsonb),
    -- Null unless the bot data is whole (alert_state 'on').
    'uncrawled_count', case when v_alert = 'on' then (select count(*) from uncrawled) end,
    'uncrawled', case
      when v_alert = 'on' then coalesce((
        select jsonb_agg(to_jsonb(u) order by u.citations desc, u.page)
        from (select * from uncrawled order by citations desc, page limit 10) u
      ), '[]'::jsonb)
    end,
    'alert_state', v_alert,
    'alert_from', case when v_first is not null then v_first + 29 end,
    'since', v_since
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_bot_report(uuid, date, date, integer) from public, anon;
grant execute on function public.ai_bot_report(uuid, date, date, integer)
  to authenticated, service_role;

comment on function public.ai_bot_report(uuid, date, date, integer) is
  'AI Traffic "AI bots reading your site" (AT-011, spec §3.7): verified AI-bot hits between two days by type (training, search, user) and by bot, the most read pages with each type''s last read, and the cited pages no search bot read in the last 30 days (null until 30 days of bot data). Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00186_ai_traffic_broken_links.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00186: broken AI links (AT-012)
-- ============================================================================
-- Spec §3.5: "AI-referred visits that landed on a 404 → suggested redirect,
-- exportable as a redirect list." Snippet only (§3.8b).
--
-- The snippet now sends the landing page's HTTP status as the browser saw it
-- (the navigation entry's responseStatus). Browsers that don't report one
-- (Safari) send none, and say instead whether the page's title read "404" or
-- "not found":
--
--   * http_status — the status, or null when the browser didn't tell;
--   * not_found_title — no status, and the title said "not found".
--
-- A page is broken in a range when AI visitors found it missing in the range
-- and its latest pageview with a status, up to now, still says 404 or 410.
-- With no status at all, a title saying "not found" counts unless the nightly
-- page read (site_pages, 00104) found the page working: a post about fixing
-- 404s is not a missing page. A page the nightly read found working after its
-- last miss is fixed, and isn't listed. The status is decided per address
-- (the path plus its query, utm_* and click ids such as gclid left out), and
-- a path is broken only when none of its addresses last answered 2xx or 3xx:
-- on a shop where /index.php?route=product&id=42 is gone and the other
-- products work, /index.php isn't broken. When every missing address of a
-- page carries a query (a route on it, not the page), no redirect is
-- suggested: one from the path would move the whole route. Its visits are
-- the pageviews that found it missing (404, 410, or no status and a
-- not-found title), not those from before it broke.
--
-- Each other broken page gets a suggested redirect to a page known to work
-- (read 2xx by the nightly page read, or its address without a query landed
-- on with a 2xx in the last 90 days), the first that fits of:
--
--   * similar — the most path words in common, at least half of both pages'
--     words together, a plural read as its singular
--     (/blog/best-tools-2025 → /blog/best-tools-2026);
--   * parent — the nearest working page above it (/guides/old → /guides);
--   * home — the home page.
--
-- The Pages section's Traffic, no prompt list leaves broken pages out: their
-- next step is a redirect, not prompts. ai_traffic_pages is redefined from
-- 00178 for that, and its rows say whether a page is broken.
--
-- Pages are keyed as the Pages section keys them (00178). citation_urls has
-- no member select policy, so both reports run as their owner after
-- checking the caller belongs to the brand's organization; a caller from
-- elsewhere gets nothing. The rule itself (ai_traffic_broken_pages) has no
-- check of its own, so members can't call it.

-- Beacon inserts don't queue behind the column change for long: it gives up
-- after 3 s instead (run it again).
set lock_timeout = '3s';

alter table public.ai_traffic_logs
  add column if not exists http_status smallint,
  add column if not exists not_found_title boolean not null default false;

reset lock_timeout;

comment on column public.ai_traffic_logs.http_status is
  'The landing page''s HTTP status as the visitor''s browser saw it; null when the browser doesn''t report one (Safari) or from an older snippet (AT-012).';
comment on column public.ai_traffic_logs.not_found_title is
  'True when the browser reported no status and the page''s title read "404" or "not found" (AT-012).';

-- ─── Which pages are broken ─────────────────────────────────────────────────
-- The rule above, for both the Broken AI links tab and the Pages section's
-- other lists, which leave these pages out (a missing page needs a redirect,
-- not prompts). No organization check of its own: only the two functions
-- below call it, after theirs.

create or replace function public.ai_traffic_broken_pages(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz
)
returns table (page_key text, status text, routed boolean)
language sql
stable
set search_path to 'public'
as $$
  with
  -- Only the pageviews that say something about the page: a status, or a
  -- not-found title. Read up to now, so a page that works again since the
  -- window ended isn't listed.
  logs as (
    select
      n.page_key,
      -- The address: the path plus its query, tracking parameters left out,
      -- in one order. Worked out only when the URL has a query.
      case when q.query is null then n.page_key else n.page_key || '?' || q.query end as address,
      l.created_at,
      l.http_status,
      l.not_found_title,
      (p_to is null or l.created_at <= p_to)
        and (l.http_status in (404, 410) or (l.http_status is null and l.not_found_title))
        as failed_in_window
    from public.ai_traffic_logs l
    cross join lateral (select lower(public.normalize_page_path(l.url)) as page_key) n
    cross join lateral (
      select case when strpos(l.url, '?') > 0 then (
        select string_agg(qp.part, '&' order by qp.part)
        from unnest(string_to_array(split_part(split_part(l.url, '#', 1), '?', 2), '&')) as qp(part)
        where qp.part <> ''
          and qp.part !~* '^(utm_[^=]*|gclid|fbclid|msclkid|srsltid|_gl|ref)(=|$)'
      ) end as query
    ) q
    where l.brand_id = p_brand_id
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (l.http_status is not null or l.not_found_title)
  ),
  address_state as (
    select
      page_key,
      address,
      (array_agg(http_status order by created_at desc) filter (where http_status is not null))[1]
        as last_status,
      bool_or(not_found_title) as title_not_found,
      max(created_at) filter (where failed_in_window) as last_failed_at
    from logs
    group by page_key, address
  ),
  page_state as (
    select
      page_key,
      max(last_status) filter (where last_status in (404, 410)) as last_status,
      bool_or(last_status is null and title_not_found) as title_not_found,
      -- No address with a status reads as not working, not as unknown.
      coalesce(bool_or(last_status between 200 and 399), false) as works,
      max(last_failed_at) as last_failed_at,
      -- Every missing address carries a query: a route on the page, not the page.
      bool_and(address <> page_key)
        filter (where last_status in (404, 410) or (last_status is null and title_not_found))
        as routed
    from address_state
    group by page_key
  ),
  -- What the nightly page read found (00104).
  fetched as (
    select lower(public.normalize_page_path(sp.url)) as page_key,
           bool_or(sp.fetch_status between 200 and 399) as works,
           max(sp.fetched_at) filter (where sp.fetch_status between 200 and 299) as last_ok_at
    from public.site_pages sp
    where sp.brand_id = p_brand_id
      and sp.fetch_status is not null
    group by 1
  )
  select
    s.page_key,
    case when s.last_status is not null then s.last_status::text else 'title' end,
    coalesce(s.routed, false)
  from page_state s
  left join fetched f on f.page_key = s.page_key
  where not s.works
    and s.last_failed_at is not null
    -- The nightly read found it working after its last miss: fixed since.
    and not coalesce(f.last_ok_at > s.last_failed_at, false)
    and (
      s.last_status in (404, 410)
      or (s.last_status is null and s.title_not_found and not coalesce(f.works, false))
    );
$$;

revoke all on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz)
  from public, anon, authenticated;
grant execute on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz)
  to service_role;

comment on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz) is
  'AI Traffic (AT-012): the brand''s pages AI visitors found missing in a window whose latest reported status up to now is 404 or 410, or, with no status, whose title said not found and that the nightly page read never found working; not those the nightly read found working after their last miss. Decided per address (path plus query, utm_* and click ids left out), and a path none of whose addresses last answered 2xx or 3xx; routed when every missing address carries a query. No organization check: called only by ai_traffic_broken_links and ai_traffic_pages, after theirs.';

-- ─── Broken AI links ────────────────────────────────────────────────────────

create or replace function public.ai_traffic_broken_links(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_since date := (p_from at time zone 'utc')::date;
  v_until date := coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date);
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  with
  logs as (
    select
      lower(n.page) as page_key,
      n.page,
      coalesce(l.visit_of, l.id) as visit,
      l.created_at,
      coalesce(nullif(l.source_platform, ''), 'unknown') as platform
    from public.ai_traffic_logs l
    cross join lateral (select public.normalize_page_path(l.url) as page) n
    where l.brand_id = p_brand_id
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at <= p_to)
      -- Only the pageviews that found the page missing, not those from before it broke.
      and (l.http_status in (404, 410) or (l.http_status is null and l.not_found_title))
  ),
  broken as (
    select bp.page_key, bp.status, bp.routed
    from public.ai_traffic_broken_pages(p_brand_id, p_from, p_to) bp
  ),
  visits as (
    select l.page_key, min(l.page) as page, count(distinct l.visit)::bigint as visits,
           max(l.created_at) as last_visit
    from logs l
    join broken b on b.page_key = l.page_key
    group by l.page_key
  ),
  platforms as (
    select page_key, (array_agg(platform order by visits desc, platform))[1:3] as platforms
    from (
      select l.page_key, l.platform, count(distinct l.visit) as visits
      from logs l
      join broken b on b.page_key = l.page_key
      group by 1, 2
    ) t
    group by 1
  ),
  cited as (
    select c.page_key, c.citations
    from public.ai_traffic_page_citations(p_brand_id, v_since, v_until) c
  ),
  -- Pages known to work, to redirect to. Only a page's own address counts:
  -- /product.php?id=5 answering 200 says nothing about /product.php.
  landed as (
    select lower(n.page) as page_key,
           min(n.page) as page,
           (array_agg(l.http_status order by l.created_at desc))[1] as last_status
    from public.ai_traffic_logs l
    cross join lateral (select public.normalize_page_path(l.url) as page) n
    where l.brand_id = p_brand_id
      and l.http_status is not null
      and l.created_at >= now() - interval '90 days'
      and (
        strpos(l.url, '?') = 0
        or not exists (
          select 1
          from unnest(string_to_array(split_part(split_part(l.url, '#', 1), '?', 2), '&')) as qp(part)
          where qp.part <> ''
            and qp.part !~* '^(utm_[^=]*|gclid|fbclid|msclkid|srsltid|_gl|ref)(=|$)'
        )
      )
    group by 1
  ),
  candidates as (
    select page_key, min(page) as page, max(weight) as weight
    from (
      select lower(public.normalize_page_path(sp.url)) as page_key,
             public.normalize_page_path(sp.url) as page,
             sp.ga_sessions as weight
      from public.site_pages sp
      where sp.brand_id = p_brand_id
        and sp.fetch_status between 200 and 299
      union all
      select page_key, page, 0 from landed where last_status between 200 and 299
    ) c
    where page_key not in (select page_key from broken)
    group by page_key
  ),
  candidate_words as (
    select distinct c.page_key, regexp_replace(w.word, '^(.{3,})s$', '\1') as word
    from candidates c
    cross join lateral regexp_split_to_table(c.page_key, '[^[:alnum:]]+') as w(word)
    where length(w.word) >= 2
  ),
  broken_words as (
    select distinct b.page_key, regexp_replace(w.word, '^(.{3,})s$', '\1') as word
    from broken b
    cross join lateral regexp_split_to_table(b.page_key, '[^[:alnum:]]+') as w(word)
    where length(w.word) >= 2
  ),
  candidate_sizes as (select page_key, count(*) as words from candidate_words group by 1),
  broken_sizes as (select page_key, count(*) as words from broken_words group by 1),
  similar_pages as (
    select distinct on (page_key) page_key, target
    from (
      select
        bw.page_key,
        c.page as target,
        c.weight,
        count(*)::numeric / (bs.words + cs.words - count(*)) as overlap
      from broken_words bw
      join candidate_words cw on cw.word = bw.word
      join candidates c on c.page_key = cw.page_key
      join broken_sizes bs on bs.page_key = bw.page_key
      join candidate_sizes cs on cs.page_key = cw.page_key
      group by bw.page_key, c.page_key, c.page, c.weight, bs.words, cs.words
    ) m
    where overlap >= 0.5
    order by page_key, overlap desc, weight desc, length(target), target
  ),
  parent_pages as (
    select distinct on (b.page_key) b.page_key, c.page as target
    from broken b
    join candidates c
      on c.page_key <> '/'
     and left(b.page_key, length(c.page_key) + 1) = c.page_key || '/'
    order by b.page_key, length(c.page_key) desc
  ),
  result_rows as (
    select
      v.page,
      v.visits,
      v.last_visit,
      b.status,
      coalesce(p.platforms, '{}'::text[]) as platforms,
      coalesce(ci.citations, 0)::bigint as citations,
      -- A route on the page (every missing address has a query) gets no
      -- redirect: one from its path would move the whole route.
      case when v.page_key <> '/' and not b.routed then coalesce(s.target, pa.target, '/') end
        as target,
      case
        when v.page_key = '/' then null
        when b.routed then 'query'
        when s.target is not null then 'similar'
        when pa.target is not null then 'parent'
        else 'home'
      end as target_reason
    from visits v
    join broken b on b.page_key = v.page_key
    left join platforms p on p.page_key = v.page_key
    left join cited ci on ci.page_key = v.page_key
    left join similar_pages s on s.page_key = v.page_key
    left join parent_pages pa on pa.page_key = v.page_key
  )
  select jsonb_build_object(
    'count', (select count(*) from result_rows),
    'rows', coalesce((
      select jsonb_agg(to_jsonb(r))
      from (
        select * from result_rows
        order by visits desc, citations desc, last_visit desc, page
        limit greatest(p_limit, 0) offset greatest(p_offset, 0)
      ) r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer)
  from public, anon;
grant execute on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer) is
  'AI Traffic "Broken AI links" (AT-012, spec §3.5): the pages AI-referred visitors landed on that answered 404 or 410 (or, without a status, whose title said not found) in a window, with their visits, platforms, citations and a suggested redirect to a working page (similar path, parent page or home; none for a route on the page, target_reason query). Security definer with an organization check.';

-- ─── The Pages section leaves broken pages out of Traffic, no prompt ─────────
-- 00178's function with one change: a page AI visitors found missing is not
-- "Traffic, no prompt" (its next step is a redirect, on Broken AI links), and
-- each row says whether it is broken. Everything else is as 00178 wrote it.

create or replace function public.ai_traffic_pages(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_tab text default 'all',
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_since date := (p_from at time zone 'utc')::date;
  v_until date := coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date);
  -- The 24-hour range reads the snippet alone, as the rest of the page does:
  -- Analytics has no hours (00176).
  v_hourly boolean := p_from is not null and coalesce(p_to, now()) - p_from <= interval '25 hours';
  v_result jsonb;
begin
  if p_tab not in ('all', 'no_ai_traffic', 'cited_not_clicked', 'traffic_no_prompt') then
    raise exception 'unknown tab %', p_tab;
  end if;
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  with
  -- AI visits per page, day by day from the snippet or Analytics (00176).
  ai as (
    select lower(e->>'page') as page_key, min(e->>'page') as page, sum((e->>'visits')::bigint) as visits
    from jsonb_array_elements(
      public.ai_traffic_merged(p_brand_id, p_from, p_to, true, not v_hourly) -> 'pages'
    ) e
    group by 1
  ),
  -- Days the snippet was active, over the whole UTC day (00176's rule).
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(v_since::timestamp at time zone 'utc', '-infinity'::timestamptz)
      and l.created_at < (v_until + 1)::timestamp at time zone 'utc'
  ),
  -- Which assistants sent them, counted as the AI visits are: the snippet,
  -- and Analytics on days without it (never within 24 hours).
  platform_visits as (
    select lower(public.normalize_page_path(l.url)) as page_key,
           coalesce(nullif(l.source_platform, ''), 'unknown') as platform,
           count(*)::bigint as visits
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at <= p_to)
    group by 1, 2
    union all
    select lower(public.normalize_page_path(g.landing_page)),
           coalesce(g.platform, g.source),
           sum(g.sessions)::bigint
    from public.ga_ai_traffic_stats g
    where not v_hourly
      and g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.sessions > 0
      and g.date >= coalesce(v_since, '-infinity'::date)
      and g.date <= v_until
      and not exists (select 1 from snippet_days s where s.day = g.date)
    group by 1, 2
  ),
  platforms as (
    select page_key, (array_agg(platform order by visits desc, platform))[1:3] as platforms
    from (select page_key, platform, sum(visits) as visits from platform_visits group by 1, 2) t
    group by 1
  ),
  -- Key events in AI sessions: only Analytics has them, and it has no hours.
  ai_key_events as (
    select lower(public.normalize_page_path(g.landing_page)) as page_key, sum(g.key_events)::bigint as key_events
    from public.ga_ai_traffic_stats g
    where not v_hourly
      and g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= coalesce(v_since, '-infinity'::date)
      and g.date <= v_until
    group by 1
  ),
  -- Every channel's traffic, for the No AI traffic list's value.
  traffic as (
    select
      lower(public.normalize_page_path(gps.landing_page)) as page_key,
      min(public.normalize_page_path(gps.landing_page)) as page,
      sum(gps.sessions)::bigint as sessions,
      sum(gps.engaged_sessions)::bigint as engaged_sessions,
      sum(gps.key_events)::bigint as key_events,
      sum(gps.transactions)::bigint as transactions,
      sum(gps.purchase_revenue) as revenue,
      sum(gps.engagement_duration_seconds)::bigint as engagement_seconds
    from public.ga_page_stats gps
    where gps.brand_id = p_brand_id
      and gps.date >= coalesce(v_since, '-infinity'::date)
      and gps.date <= v_until
    group by 1
  ),
  cited as (
    select c.page_key, c.page, c.citations
    from public.ai_traffic_page_citations(p_brand_id, v_since, v_until) c
  ),
  -- Prompts pointing to the page: an active prompt's target URL.
  targeted as (
    select lower(public.normalize_page_path(ptu.url)) as page_key,
           count(distinct ptu.prompt_id)::bigint as prompts
    from public.prompt_target_urls ptu
    join public.prompts p on p.id = ptu.prompt_id and p.is_active
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
    group by 1
  ),
  -- Pages that answered 404 or 410 to AI visitors (AT-012): Broken AI links.
  broken as (
    select bp.page_key from public.ai_traffic_broken_pages(p_brand_id, p_from, p_to) bp
  ),
  in_sitemap as (
    select distinct lower(public.normalize_page_path(sp.url)) as page_key,
           public.normalize_page_path(sp.url) as page
    from public.site_pages sp
    where sp.brand_id = p_brand_id
      and 'sitemap' = any(sp.sources)
  ),
  keys as (
    select page_key, page from ai
    union select page_key, page from traffic
    union select page_key, page from cited
    union select page_key, page from in_sitemap
  ),
  pages as (
    select
      k.page_key,
      min(k.page) as page,
      coalesce(max(ai.visits), 0) as ai_visits,
      coalesce(max(ke.key_events), 0) as ai_key_events,
      coalesce(max(pl.platforms), '{}'::text[]) as ai_platforms,
      coalesce(max(c.citations), 0) as citations,
      coalesce(max(t.prompts), 0) as targeting_prompts,
      coalesce(max(tr.sessions), 0) as sessions,
      coalesce(max(tr.engaged_sessions), 0) as engaged_sessions,
      coalesce(max(tr.key_events), 0) as key_events,
      coalesce(max(tr.transactions), 0) as transactions,
      coalesce(max(tr.revenue), 0) as revenue,
      coalesce(max(tr.engagement_seconds), 0) as engagement_seconds,
      bool_or(s.page_key is not null) as in_sitemap,
      bool_or(br.page_key is not null) as broken
    from keys k
    left join ai on ai.page_key = k.page_key
    left join ai_key_events ke on ke.page_key = k.page_key
    left join platforms pl on pl.page_key = k.page_key
    left join cited c on c.page_key = k.page_key
    left join targeted t on t.page_key = k.page_key
    left join traffic tr on tr.page_key = k.page_key
    left join in_sitemap s on s.page_key = k.page_key
    left join broken br on br.page_key = k.page_key
    group by k.page_key
  ),
  kept as (
    select p.*,
      -- The page's place on the site by value, among pages with traffic.
      case when p.sessions > 0 then
        rank() over (
          partition by (p.sessions > 0)
          order by p.revenue desc, p.key_events desc, p.sessions desc, p.engagement_seconds desc
        )
      end as value_rank,
      p.ai_visits = 0 and (p.sessions > 0 or p.in_sitemap) as no_ai_traffic,
      p.citations >= 20 and p.ai_visits = 0 as cited_not_clicked,
      -- A missing page needs a redirect, not prompts (AT-012).
      p.ai_visits > 0 and p.citations = 0 and not p.broken as traffic_no_prompt
    from pages p
    where p.page not in ('', '(not set)', '(other)')
      -- The nightly detection's excluded segments (pagePaths.js).
      and not exists (
        select 1
        from unnest(string_to_array(lower(p.page), '/')) seg
        where seg = any (array[
          'checkout', 'cart', 'basket', 'order', 'orders', 'order-confirmation',
          'confirmation', 'thank-you', 'thanks', 'payment', 'pay', 'login', 'signin',
          'sign-in', 'signup', 'sign-up', 'register', 'logout', 'account', 'my-account',
          'profile', 'dashboard', 'admin', 'wishlist', 'favorites', 'search', 'career',
          'careers', 'jobs', 'job', 'cookie-policy', 'privacy', 'privacy-policy', 'terms',
          'terms-of-service', 'legal', 'unsubscribe'
        ])
      )
  ),
  tab as (
    select * from kept
    where case p_tab
      when 'no_ai_traffic' then no_ai_traffic
      when 'cited_not_clicked' then cited_not_clicked
      when 'traffic_no_prompt' then traffic_no_prompt
      else true
    end
  )
  select jsonb_build_object(
    'counts', (
      select jsonb_build_object(
        'all', count(*),
        'no_ai_traffic', count(*) filter (where no_ai_traffic),
        'cited_not_clicked', count(*) filter (where cited_not_clicked),
        'traffic_no_prompt', count(*) filter (where traffic_no_prompt),
        -- The Broken AI links tab's count, so the card needn't read that list for it.
        'broken_ai_links', (select count(*) from broken)
      )
      from kept
    ),
    'rows', coalesce((
      select jsonb_agg(to_jsonb(r) - 'page_key' - 'no_ai_traffic' - 'cited_not_clicked' - 'traffic_no_prompt')
      from (
        select * from tab
        order by
          -- Each list in the order it's worked through.
          case when p_tab = 'no_ai_traffic' then revenue end desc nulls last,
          case when p_tab = 'no_ai_traffic' then key_events end desc nulls last,
          case when p_tab = 'no_ai_traffic' then sessions end desc nulls last,
          case when p_tab = 'no_ai_traffic' then engagement_seconds end desc nulls last,
          case when p_tab = 'cited_not_clicked' then citations end desc nulls last,
          ai_visits desc, citations desc, sessions desc, page
        limit greatest(p_limit, 0) offset greatest(p_offset, 0)
      ) r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer)
  from public, anon;
grant execute on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_pages(uuid, timestamptz, timestamptz, text, integer, integer) is
  'AI Traffic Pages section (AT-006, spec §3.5): the brand''s pages in a window with AI visits (ai_traffic_merged), AI key events, top platforms, citations, prompts pointing to them, all-channel traffic, sitemap presence and whether AI visitors found the page missing (AT-012); the counts of the No AI traffic / Cited, not clicked / Traffic, no prompt lists, which leave missing pages out, and one page of the asked tab''s rows. Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00187_ai_traffic_digest.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00187: the AI Traffic weekly digest (AT-013)
-- ============================================================================
-- Spec §3.8: "A weekly e-mail digest with the summary line and the top three
-- changes." Sent on Mondays for the week before, per brand, to the Daily
-- Pulse's recipients (00036), unless the pulse is off (frequency 'off').
--
--   * pulse_settings.traffic_digest — on unless an admin or manager turns it
--     off in Settings › Notifications. A brand with no settings row gets it.
--   * ai_traffic_digests — one row per brand and week: the claim that stops
--     a second send, what went out, and when (sent_at, set just before the
--     e-mail goes, so a stop after the send never mails the week twice). A
--     claim with no sent_at was left by a sweep that stopped before sending;
--     the next one (through Wednesday) takes it over.
--
-- Written by the Express server's service-role client; members read their
-- brands' rows, as with sent_pulses.

alter table public.pulse_settings
  add column if not exists traffic_digest boolean not null default true;

comment on column public.pulse_settings.traffic_digest is
  'Whether the AI Traffic weekly digest (AT-013) is e-mailed for the brand, to the pulse''s recipients.';

create table if not exists public.ai_traffic_digests (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands (id) on delete cascade,
  -- The Monday the reported week starts on (UTC).
  week_start date not null,
  payload jsonb not null default '{}'::jsonb,
  email_sent boolean not null default false,
  email_recipient_count integer not null default 0,
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  unique (brand_id, week_start)
);

alter table public.ai_traffic_digests enable row level security;

grant select on public.ai_traffic_digests to authenticated;

create policy "ai_traffic_digests: member select" on public.ai_traffic_digests
  for select using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.ai_traffic_digests is
  'AI Traffic weekly digests sent (AT-013): one per brand and week, claimed before sending so a week is never mailed twice.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00188_organization_ai_keys.sql
-- ─────────────────────────────────────────────────────────────────────────
-- AI Providers (Settings): an organization's own keys for Chat, one per
-- provider — Anthropic, OpenAI, Google Gemini, Microsoft Azure OpenAI and
-- OpenRouter — and which one Chat uses (`active`, at most one per org).
--
-- Each key is the AES-256-GCM envelope from frontend/src/lib/agent/keyEncryption.ts,
-- as the Anthropic key on `organizations` was (00010); `last4` is display-only.
-- `settings` holds what a provider needs besides the key: Azure's endpoint
-- and deployment, OpenRouter's model.
--
-- RLS on with no policies: only the service role reads and writes it (the web
-- app's /api/settings/ai-providers route and Chat).

create table public.organization_ai_keys (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  provider text not null
    check (provider in ('anthropic', 'openai', 'google', 'azure', 'openrouter')),
  key_encrypted text not null,
  key_last4 text not null,
  settings jsonb not null default '{}'::jsonb,
  active boolean not null default false,
  set_at timestamptz not null default now(),
  set_by uuid references public.profiles(id) on delete set null,
  primary key (organization_id, provider)
);

create unique index organization_ai_keys_one_active
  on public.organization_ai_keys (organization_id)
  where active;

alter table public.organization_ai_keys enable row level security;

comment on table public.organization_ai_keys is
  'Organization-level AI provider keys for Chat (BYOK, cloud). Service role only.';
comment on column public.organization_ai_keys.active is
  'The provider Chat uses; at most one per organization.';

-- Existing Anthropic keys carry over as the provider Chat uses. The old
-- organizations.anthropic_api_key_* columns stay until a later migration.
insert into public.organization_ai_keys
  (organization_id, provider, key_encrypted, key_last4, active, set_at, set_by)
select id, 'anthropic', anthropic_api_key_encrypted, coalesce(anthropic_api_key_last4, ''),
       true, coalesce(anthropic_api_key_set_at, now()), anthropic_api_key_set_by
from public.organizations
where anthropic_api_key_encrypted is not null
on conflict (organization_id, provider) do nothing;

-- Makes one saved provider the one Chat uses; with p_only_if_none, only when
-- none is yet (a first key saved). The organization's rows are locked first,
-- so two switches at once queue rather than both setting `active` and one
-- failing the unique index. Others off first: that index is checked row by
-- row. False when the organization has no key for that provider.
create or replace function public.set_active_ai_provider(
  p_organization_id uuid,
  p_provider text,
  p_only_if_none boolean default false
) returns boolean
language plpgsql
set search_path = public
as $$
begin
  perform 1 from organization_ai_keys
  where organization_id = p_organization_id
  for update;

  if not exists (
    select 1 from organization_ai_keys
    where organization_id = p_organization_id and provider = p_provider
  ) then
    return false;
  end if;
  if p_only_if_none and exists (
    select 1 from organization_ai_keys
    where organization_id = p_organization_id and active
  ) then
    return true;
  end if;
  update organization_ai_keys set active = false
  where organization_id = p_organization_id and active and provider <> p_provider;
  update organization_ai_keys set active = true
  where organization_id = p_organization_id and provider = p_provider and not active;
  return true;
end;
$$;

revoke execute on function public.set_active_ai_provider(uuid, text, boolean)
  from public, anon, authenticated;
grant execute on function public.set_active_ai_provider(uuid, text, boolean)
  to service_role;

-- Removes a provider's key. When it was the one Chat used, the most recently
-- saved other key takes over, in the same transaction and under the same
-- lock as a switch. Returns the provider Chat uses afterwards, or null.
create or replace function public.remove_ai_provider_key(
  p_organization_id uuid,
  p_provider text
) returns text
language plpgsql
set search_path = public
as $$
declare
  v_was_active boolean;
  v_next text;
begin
  perform 1 from organization_ai_keys
  where organization_id = p_organization_id
  for update;

  delete from organization_ai_keys
  where organization_id = p_organization_id and provider = p_provider
  returning active into v_was_active;

  if coalesce(v_was_active, false) then
    select provider into v_next
    from organization_ai_keys
    where organization_id = p_organization_id
    order by set_at desc
    limit 1;
    if v_next is not null then
      update organization_ai_keys set active = true
      where organization_id = p_organization_id and provider = v_next;
    end if;
    return v_next;
  end if;

  select provider into v_next
  from organization_ai_keys
  where organization_id = p_organization_id and active;
  return v_next;
end;
$$;

revoke execute on function public.remove_ai_provider_key(uuid, text)
  from public, anon, authenticated;
grant execute on function public.remove_ai_provider_key(uuid, text)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00189_ai_bot_ingest_file.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00189: a bot log file read in one transaction, and bot rows pruned in batches
-- ============================================================================
-- Follow-ups from #1179's review (AT-010).
--
-- A Logpush file or a Vercel drain's delivery was read in steps, each its own
-- transaction: its claim (ai_bot_ingested_files), its raw records
-- (ai_bot_count_raw), then its verified events 500 at a time (ai_bot_ingest).
-- When a later step failed, the claim was given back, and the sender's retry
-- counted the raw records, and the chunks already written, a second time.
--
-- ai_bot_ingest_file takes all three steps in one transaction: a failure
-- leaves nothing behind, so the retry is read as new. A delivery of the same
-- file that arrives meanwhile waits on the claim's key, then reads as a
-- duplicate. A file holds at most 20,000 lines (botLogFormats.js), so its
-- events fit one call.
--
-- ai_bot_prune deletes at most p_limit rows past their retention from each
-- bot table per call. The daily run calls it until a call deletes fewer, so
-- no single DELETE runs into the statement timeout at Enterprise volume.

create or replace function public.ai_bot_ingest_file(
  p_connection_id uuid,
  p_body_hash text,
  p_records bigint,
  p_raw_cap bigint,
  p_cap bigint,
  p_events jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_claimed integer;
  v_raw jsonb;
  v_ingest jsonb;
begin
  insert into public.ai_bot_ingested_files (connection_id, body_hash)
  values (p_connection_id, p_body_hash)
  on conflict (connection_id, body_hash) do nothing;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('duplicate', true);
  end if;

  -- Raised rather than returned, so the claim rolls back with the rest.
  v_raw := public.ai_bot_count_raw(p_connection_id, p_records, p_raw_cap);
  if v_raw ? 'error' then
    raise exception 'ai_bot_count_raw: %', v_raw ->> 'error';
  end if;
  -- Past the month's raw cap the file is only counted.
  if not (v_raw ->> 'allowed')::boolean then
    return jsonb_build_object('raw_capped', true, 'raw', v_raw -> 'raw');
  end if;
  if coalesce(jsonb_array_length(p_events), 0) = 0 then
    return jsonb_build_object('received', 0, 'stored', 0, 'raw', v_raw -> 'raw');
  end if;

  v_ingest := public.ai_bot_ingest(p_connection_id, p_cap, p_events);
  if v_ingest ? 'error' then
    raise exception 'ai_bot_ingest: %', v_ingest ->> 'error';
  end if;
  return v_ingest || jsonb_build_object('raw', v_raw -> 'raw');
end;
$$;

revoke all on function public.ai_bot_ingest_file(uuid, text, bigint, bigint, bigint, jsonb)
  from public, anon, authenticated;
grant execute on function public.ai_bot_ingest_file(uuid, text, bigint, bigint, bigint, jsonb)
  to service_role;

comment on function public.ai_bot_ingest_file(uuid, text, bigint, bigint, bigint, jsonb) is
  'AI bots (AT-010): one log file of a connection in one transaction: claims it by its body hash (a duplicate returns {duplicate}), adds its records to the month''s raw count (past p_raw_cap returns {raw_capped}), then writes its verified events as ai_bot_ingest does. A failure rolls the claim back too. Service role only.';

create or replace function public.ai_bot_prune(
  p_events_before timestamptz,
  p_daily_before date,
  p_files_before timestamptz,
  p_limit integer
)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_events integer;
  v_daily integer;
  v_files integer;
begin
  delete from public.ai_bot_events e
  where e.id in (
    select o.id from public.ai_bot_events o
    where o.occurred_at < p_events_before
    limit p_limit
  );
  get diagnostics v_events = row_count;

  delete from public.ai_bot_daily d
  using (
    select o.brand_id, o.day, o.bot, o.page from public.ai_bot_daily o
    where o.day < p_daily_before
    limit p_limit
  ) old
  where d.brand_id = old.brand_id and d.day = old.day and d.bot = old.bot and d.page = old.page;
  get diagnostics v_daily = row_count;

  delete from public.ai_bot_ingested_files f
  using (
    select o.connection_id, o.body_hash from public.ai_bot_ingested_files o
    where o.received_at < p_files_before
    limit p_limit
  ) old
  where f.connection_id = old.connection_id and f.body_hash = old.body_hash;
  get diagnostics v_files = row_count;

  return jsonb_build_object('events', v_events, 'daily', v_daily, 'files', v_files);
end;
$$;

revoke all on function public.ai_bot_prune(timestamptz, date, timestamptz, integer)
  from public, anon, authenticated;
grant execute on function public.ai_bot_prune(timestamptz, date, timestamptz, integer)
  to service_role;

comment on function public.ai_bot_prune(timestamptz, date, timestamptz, integer) is
  'AI bots (AT-010): deletes at most p_limit rows from each of ai_bot_events (occurred_at), ai_bot_daily (day) and ai_bot_ingested_files (received_at) older than the given bounds, and returns how many it deleted from each. The daily run calls it until a call deletes fewer than p_limit. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00190_ai_bot_report_coverage.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00190: the AI bot report's alert waits for 30 whole days of bot data
-- ============================================================================
-- Follow-ups from #1182's review (AT-011).
--
-- The "cited pages no search bot read in 30 days" list (ai_bot_report's
-- `uncrawled`) only means something while the bot data covers those 30
-- days. 00185 checked their ends: the first bot day 30 days back, and a
-- live connection that sent in the last 2 days. A connection revoked on day
-- -25 with a new one made yesterday passed both, and every page crawled less
-- often than the new data's one day was listed as unread. The alert now also
-- looks at every one of the 30 days: no run of more than 7 days in a row
-- without rows. A site bots read once a week still passes; a hole of weeks
-- doesn't, however old the connection: a sender past the month's raw cap
-- (its files are only counted), a Worker route taken down for a while, a
-- Logpush job paused and resumed. Otherwise 'stale', which also pauses the
-- cited_page_uncrawled signals (they read as unread, #1195).
--
-- The gate's '(other)' check scanned the brand's 30 days of rows on every
-- read; a partial index on those rows makes it a probe. On a large
-- ai_bot_daily, build it by hand first with `create index concurrently`,
-- which doesn't hold back the ingest's writes; this statement then finds it
-- in place.
--
-- The rest of ai_bot_report is unchanged from 00185.

create index if not exists ai_bot_daily_other_idx
  on public.ai_bot_daily (brand_id, day)
  where page = '(other)';

create or replace function public.ai_bot_report(
  p_brand_id uuid,
  p_since date,
  p_until date,
  p_limit integer default 20
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_first date;
  v_last_day date;
  v_last timestamptz;
  v_since date;
  v_alert text;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  select d.day into v_first
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id
  order by d.day
  limit 1;
  select d.day into v_last_day
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id
  order by d.day desc
  limit 1;
  select max(d.last_seen) into v_last
  from public.ai_bot_daily d
  where d.brand_id = p_brand_id and d.day = v_last_day;

  v_since := coalesce(p_since, current_date - 89);

  v_alert := case
    when v_first is null or v_first > current_date - 29 then 'waiting'
    when not exists (
      select 1 from public.ai_bot_connections c
      where c.brand_id = p_brand_id
        and c.revoked_at is null
        and c.last_event_at >= now() - interval '2 days'
    ) or exists (
      select 1 from public.ai_bot_daily d
      where d.brand_id = p_brand_id
        and d.bot_type = 'search'
        and d.page = '(other)'
        and d.day >= current_date - 29
    ) then 'stale'
    -- The whole 30 days, not only their ends: the longest run of days
    -- without rows (one probe per day, then gaps and islands) is at most 7.
    when (
      select coalesce(max(r.days), 0)
      from (
        select count(*) as days
        from (
          select n, n - row_number() over (order by n) as run
          from generate_series(0, 29) n
          where not exists (
            select 1 from public.ai_bot_daily d
            where d.brand_id = p_brand_id and d.day = current_date - n
          )
        ) empty
        group by empty.run
      ) r
    ) > 7 then 'stale'
    else 'on'
  end;

  with g as (
    -- Each bot's hits on each page in the range, added up once.
    select
      d.bot_type,
      d.bot,
      d.page,
      sum(d.hits)::bigint as hits,
      max(d.last_seen) as last_seen
    from public.ai_bot_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_since
      and d.day <= p_until
    group by d.bot_type, d.bot, d.page
  ),
  types as (
    select
      g.bot_type,
      sum(g.hits)::bigint as hits,
      count(distinct g.page) filter (where g.page <> '(other)')::bigint as pages,
      max(g.last_seen) as last_seen,
      array_agg(distinct g.bot order by g.bot) as bots
    from g
    group by g.bot_type
  ),
  bots as (
    select
      g.bot,
      min(g.bot_type) as bot_type,
      sum(g.hits)::bigint as hits,
      count(*) filter (where g.page <> '(other)')::bigint as pages,
      max(g.last_seen) as last_seen
    from g
    group by g.bot
  ),
  -- Hits folded past the month's cap ('(other)') aren't a page.
  pages as (
    select
      g.page,
      sum(g.hits)::bigint as hits,
      max(g.last_seen) filter (where g.bot_type = 'training') as training_last,
      max(g.last_seen) filter (where g.bot_type = 'search') as search_last,
      max(g.last_seen) filter (where g.bot_type = 'user') as user_last
    from g
    where g.page <> '(other)'
    group by g.page
  ),
  -- The alert reads its own 30 days, whatever the range.
  uncrawled as (
    select c.page, c.citations
    from public.ai_traffic_page_citations(p_brand_id, current_date - 29, current_date) c
    where v_alert = 'on'
      and not exists (
        select 1 from public.ai_bot_daily d
        where d.brand_id = p_brand_id
          and d.bot_type = 'search'
          and d.page = c.page_key
          and d.day >= current_date - 29
      )
  )
  select jsonb_build_object(
    'first_day', v_first,
    'last_seen', v_last,
    'types', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'type', t.bot_type, 'hits', t.hits, 'pages', t.pages,
          'last_seen', t.last_seen, 'bots', to_jsonb(t.bots)
        )
        order by array_position(array['training', 'search', 'user'], t.bot_type)
      )
      from types t
    ), '[]'::jsonb),
    'bots', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'bot', b.bot, 'type', b.bot_type, 'hits', b.hits, 'pages', b.pages,
          'last_seen', b.last_seen
        )
        order by b.hits desc, b.bot
      )
      from bots b
    ), '[]'::jsonb),
    'page_count', (select count(*) from pages),
    'pages', coalesce((
      select jsonb_agg(to_jsonb(p) order by p.hits desc, p.page)
      from (select * from pages order by hits desc, page limit p_limit) p
    ), '[]'::jsonb),
    -- Null unless the bot data is whole (alert_state 'on').
    'uncrawled_count', case when v_alert = 'on' then (select count(*) from uncrawled) end,
    'uncrawled', case
      when v_alert = 'on' then coalesce((
        select jsonb_agg(to_jsonb(u) order by u.citations desc, u.page)
        from (select * from uncrawled order by citations desc, page limit 10) u
      ), '[]'::jsonb)
    end,
    'alert_state', v_alert,
    'alert_from', case when v_first is not null then v_first + 29 end,
    'since', v_since
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_bot_report(uuid, date, date, integer) from public, anon;
grant execute on function public.ai_bot_report(uuid, date, date, integer)
  to authenticated, service_role;

comment on function public.ai_bot_report(uuid, date, date, integer) is
  'AI Traffic "AI bots reading your site" (AT-011, spec §3.7): verified AI-bot hits between two days by type (training, search, user) and by bot, the most read pages with each type''s last read, and the cited pages no search bot read in the last 30 days (null until bot data covers those 30 days: rows on 28 of them, or a live connection 29+ days old that sent in the last 2). Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00191_same_mentions_kpis.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00191: Insights and Mentions count mentions and net sentiment the same way
-- ============================================================================
-- The two pages showed different "Mentions" and "Net sentiment" for the same
-- days. The product decision (2026-10-20):
--
--   * Mentions are every time an answer names the brand (an answer naming it
--     three times counts three), as Insights counted them. The Mentions
--     page's Total mentions card, its trend and its platform table now read
--     occurrences; its RPC gains them per day and per platform
--     (`daily[].occurrences`, `platforms[].occurrences`).
--   * Net sentiment is (positive − negative) over the answers that name the
--     brand, as the Mentions page computed it. Insights divided by answers
--     that name OR cite it (#508); cited-only answers are always neutral, so
--     they pulled its net toward zero. The Insights aggregates (the daily
--     rollup read and the raw window read) gain the answers that name the
--     brand (`mention_results`) and the sparkline series gains them per day
--     (`days[].mention_answers`).
--
-- Each function is the latest definition (00164, 00131, 00157) with only
-- those fields added, and Mentions' platforms ordered by occurrences, the
-- column they show; existing fields are unchanged, so a web build from
-- before this migration keeps working.

create or replace function public.insights_aggregates_daily(
  p_brand_id uuid,
  p_platform text default null,
  p_models text[] default null,
  p_region text default null,
  p_day_from date default null,
  p_day_to date default null,
  p_topic_id uuid default null
) returns jsonb
language sql
stable
set search_path to 'public'
as $$
  with topic_prompts as (
    select array(select p.id from public.prompts p where p.topic_id = p_topic_id) as ids
  ),
  filtered as (
    select d.model_used, d.answer_count, d.sum_visibility, d.total_mentions,
           d.total_citations, d.positive_count, d.mentioning_answers, d.max_created_at,
           d.citation_answers, d.negative_count, d.sum_position, d.position_count,
           d.mention_answers
    from public.insights_brand_daily d
    where p_topic_id is null
      and d.brand_id = p_brand_id
      and (p_platform is null or d.platform = p_platform)
      and (p_models is null or d.model_used = any (p_models))
      and (p_region is null or d.region = p_region)
      and (p_day_from is null or d.day >= p_day_from)
      and (p_day_to is null or d.day <= p_day_to)
    union all
    select d.model_used, d.answer_count, d.sum_visibility, d.total_mentions,
           d.total_citations, d.positive_count, d.mentioning_answers, d.max_created_at,
           d.citation_answers, d.negative_count, d.sum_position, d.position_count,
           d.mention_answers
    from public.insights_prompt_daily d, topic_prompts tp
    where p_topic_id is not null
      and d.brand_id = p_brand_id
      and d.prompt_id = any (tp.ids)
      and (p_platform is null or d.platform = p_platform)
      and (p_models is null or d.model_used = any (p_models))
      and (p_region is null or d.region = p_region)
      and (p_day_from is null or d.day >= p_day_from)
      and (p_day_to is null or d.day <= p_day_to)
  ),
  totals as (
    select
      coalesce(sum(answer_count), 0)       as total_results,
      coalesce(sum(sum_visibility), 0)     as sum_visibility,
      coalesce(sum(total_mentions), 0)     as total_mentions,
      coalesce(sum(total_citations), 0)    as total_citations,
      coalesce(sum(positive_count), 0)     as positive_count,
      coalesce(sum(mentioning_answers), 0) as mentioning_results,
      -- Answers naming the brand: Net sentiment's base, as on the Mentions page.
      coalesce(sum(mention_answers), 0)    as mention_results,
      max(max_created_at)                  as last_checked_at,
      coalesce(sum(citation_answers), 0)   as citation_answers,
      coalesce(sum(negative_count), 0)     as negative_count,
      sum(sum_position)                    as sum_position,
      coalesce(sum(position_count), 0)     as position_count,
      -- A day not rewritten since 00131 has no negative or position totals.
      not exists (select 1 from filtered where negative_count is null) as kpi_complete
    from filtered
  ),
  by_model as (
    select
      coalesce(model_used, 'unknown') as model_used,
      sum(sum_visibility)             as sum_visibility,
      sum(answer_count)               as result_count
    from filtered
    group by coalesce(model_used, 'unknown')
  )
  select jsonb_build_object(
    'total_results',      t.total_results,
    'sum_visibility',     t.sum_visibility,
    'total_mentions',     t.total_mentions,
    'total_citations',    t.total_citations,
    'positive_count',     t.positive_count,
    'mentioning_results', t.mentioning_results,
    'mention_results',    t.mention_results,
    'last_checked_at',    t.last_checked_at,
    'citation_answers',   t.citation_answers,
    'negative_count',     t.negative_count,
    'sum_position',       t.sum_position,
    'position_count',     t.position_count,
    'kpi_complete',       t.kpi_complete,
    'by_model', coalesce(
      (select jsonb_agg(jsonb_build_object(
                'model_used',     bm.model_used,
                'sum_visibility', bm.sum_visibility,
                'result_count',   bm.result_count)
              order by bm.result_count desc, bm.model_used)
       from by_model bm),
      '[]'::jsonb)
  )
  from totals t;
$$;

-- The raw window read (00131's definition, still security invoker) gains the
-- same base: reports (no `days`), the 24h window and the Daily Pulse read it,
-- and without it they'd fall back to answers that name or cite the brand.
CREATE OR REPLACE FUNCTION public.insights_aggregates(
  p_brand_id   uuid,
  p_platform   text         DEFAULT NULL,
  p_models     text[]       DEFAULT NULL,
  p_region     text         DEFAULT NULL,
  p_date_from  timestamptz  DEFAULT NULL,
  p_date_to    timestamptz  DEFAULT NULL,
  p_prompt_id  uuid         DEFAULT NULL,
  p_topic_id   uuid         DEFAULT NULL
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
  WITH filtered AS (
    SELECT pr.visibility_score, pr.mention_count, pr.citation_count,
           pr.sentiment, pr.model_used, pr.created_at, pr.mention_position
    FROM public.prompt_results pr
    WHERE pr.brand_id = p_brand_id
      AND pr.platform <> 'chatgpt-shopping'  -- #155 — isolate from Insights
      AND (p_platform  IS NULL OR pr.platform    = p_platform)
      AND (p_models    IS NULL OR pr.model_used  = ANY (p_models))
      AND (p_region    IS NULL OR pr.region      = p_region)
      AND (p_date_from IS NULL OR pr.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pr.created_at <= p_date_to)
      AND (p_prompt_id IS NULL OR pr.prompt_id   = p_prompt_id)
      AND (p_topic_id  IS NULL OR EXISTS (
             SELECT 1 FROM public.prompts p
             WHERE p.id = pr.prompt_id AND p.topic_id = p_topic_id))
  ),
  totals AS (
    SELECT
      COUNT(*)                                                AS total_results,
      COALESCE(SUM(visibility_score), 0)                      AS sum_visibility,
      COALESCE(SUM(mention_count), 0)                         AS total_mentions,
      COALESCE(SUM(citation_count), 0)                        AS total_citations,
      COUNT(*) FILTER (WHERE sentiment = 'positive')          AS positive_count,
      COUNT(*) FILTER (WHERE mention_count > 0
                          OR citation_count > 0)               AS mentioning_results,
      COUNT(*) FILTER (WHERE mention_count > 0)               AS mention_results,
      MAX(created_at)                                         AS last_checked_at,
      COUNT(*) FILTER (WHERE citation_count > 0)              AS citation_answers,
      COUNT(*) FILTER (WHERE sentiment = 'negative')          AS negative_count,
      SUM(mention_position)
        FILTER (WHERE mention_position IS NOT NULL)           AS sum_position,
      COUNT(*) FILTER (WHERE mention_position IS NOT NULL)    AS position_count
    FROM filtered
  ),
  by_model AS (
    SELECT
      COALESCE(model_used, 'unknown') AS model_used,
      SUM(visibility_score)           AS sum_visibility,
      COUNT(*)                        AS result_count
    FROM filtered
    GROUP BY COALESCE(model_used, 'unknown')
  )
  SELECT jsonb_build_object(
    'total_results',       t.total_results,
    'sum_visibility',      t.sum_visibility,
    'total_mentions',      t.total_mentions,
    'total_citations',     t.total_citations,
    'positive_count',      t.positive_count,
    'mentioning_results',  t.mentioning_results,
    'mention_results',     t.mention_results,
    'last_checked_at',     t.last_checked_at,
    'citation_answers',    t.citation_answers,
    'negative_count',      t.negative_count,
    'sum_position',        t.sum_position,
    'position_count',      t.position_count,
    'kpi_complete',        true,
    'by_model', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
                'model_used',     bm.model_used,
                'sum_visibility', bm.sum_visibility,
                'result_count',   bm.result_count)
              ORDER BY bm.result_count DESC, bm.model_used)
       FROM by_model bm),
      '[]'::jsonb)
  )
  FROM totals t;
$$;

create or replace function public.insights_kpi_series(
  p_brand_id uuid,
  p_day_from date default null,
  p_day_to date default null,
  p_models text[] default null,
  p_region text default null,
  p_topic_id uuid default null
)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  with prompt_rows as (
    select d.*
    from public.insights_prompt_daily d
    where d.brand_id = p_brand_id
      and (p_models is null or d.model_used = any (p_models))
      and (p_region is null or d.region = p_region)
      and (p_day_from is null or d.day >= p_day_from)
      and (p_day_to is null or d.day <= p_day_to)
      and (p_topic_id is null or exists (
             select 1 from public.prompts p
             where p.id = d.prompt_id and p.topic_id = p_topic_id))
  ),
  comp_days as (
    select cd.day, sum(cd.mention_count) as competitor_mentions
    from public.insights_competitor_prompt_daily cd
    where cd.brand_id = p_brand_id
      and (p_models is null or cd.model_used = any (p_models))
      and (p_region is null or cd.region = p_region)
      and (p_day_from is null or cd.day >= p_day_from)
      and (p_day_to is null or cd.day <= p_day_to)
      and (p_topic_id is null or exists (
             select 1 from public.prompts p
             where p.id = cd.prompt_id and p.topic_id = p_topic_id))
    group by cd.day
  ),
  days as (
    select r.day,
           sum(r.answer_count)       as answers,
           sum(r.citation_answers)   as citation_answers,
           sum(r.total_mentions)     as total_mentions,
           sum(r.total_citations)    as total_citations,
           sum(r.positive_count)     as positive_count,
           sum(r.negative_count)     as negative_count,
           sum(r.mentioning_answers) as mentioning_answers,
           sum(r.mention_answers)    as mention_answers,
           sum(r.sum_position)       as sum_position,
           sum(r.position_count)     as position_count,
           count(distinct r.prompt_id) filter (where r.has_mention or r.has_citation)
                                     as visible_prompts,
           count(distinct r.prompt_id) as active_prompts
    from prompt_rows r
    group by r.day
  )
  select jsonb_build_object(
    'complete', not exists (
                  select 1 from prompt_rows
                  where mention_answers is null or negative_count is null),
    'days', coalesce(
      (select jsonb_agg(jsonb_build_object(
                'day',                 d.day,
                'answers',             d.answers,
                'citation_answers',    d.citation_answers,
                'total_mentions',      d.total_mentions,
                'total_citations',     d.total_citations,
                'positive_count',      d.positive_count,
                'negative_count',      d.negative_count,
                'mentioning_answers',  d.mentioning_answers,
                'mention_answers',     d.mention_answers,
                'sum_position',        d.sum_position,
                'position_count',      d.position_count,
                'visible_prompts',     d.visible_prompts,
                'active_prompts',      d.active_prompts,
                'competitor_mentions', coalesce(c.competitor_mentions, 0))
              order by d.day)
       from days d
       left join comp_days c using (day)),
      '[]'::jsonb)
  );
$$;

create or replace function public.mentions_overview(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to        timestamptz := coalesce(p_date_to, now());
  v_from      timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_span      interval;
  -- Whole days the window spans, at least one, with an hour of slack: a
  -- rolling 7 days ends at now(), a moment after the browser started it.
  v_days      integer;
  -- Under two days the answers are read directly.
  v_raw       boolean;
  v_day_to    date;
  v_day_from  date;
  v_prev_from date;
  v_search    text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_result    jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  v_span      := v_to - v_from;
  v_days      := greatest(1, ceil(extract(epoch from v_span) / 86400.0 - 1.0 / 24)::integer);
  v_raw       := v_days < 2;
  v_day_to    := (v_to at time zone 'utc')::date;
  v_day_from  := v_day_to - (v_days - 1);
  v_prev_from := v_day_from - v_days;

  with
  prompts_in as (
    select p.id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  facts as (
    select (d.day >= v_day_from)            as cur,
           d.day,
           d.prompt_id,
           d.platform,
           d.answer_count::bigint            as answers,
           d.mention_answers::bigint         as mentions,
           d.mention_occurrences             as occurrences,
           d.positive_answers::bigint        as positive,
           d.negative_answers::bigint        as negative,
           d.position_sum,
           d.position_count::bigint          as position_count,
           d.last_answer_at
    from public.mentions_prompt_daily d
    join prompts_in pi on pi.id = d.prompt_id
    where not v_raw
      and d.brand_id = p_brand_id
      and d.day between v_prev_from and v_day_to
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    union all
    select (pr.created_at >= v_from),
           (pr.created_at at time zone 'utc')::date,
           pr.prompt_id,
           pr.platform,
           1,
           (pr.mention_count > 0)::int,
           coalesce(pr.mention_count, 0),
           (pr.mention_count > 0 and pr.sentiment = 'positive')::int,
           (pr.mention_count > 0 and pr.sentiment = 'negative')::int,
           case when pr.mention_count > 0 then coalesce(pr.mention_position, 0) else 0 end,
           (pr.mention_count > 0 and pr.mention_position is not null)::int,
           pr.created_at
    from public.prompt_results pr
    join prompts_in pi on pi.id = pr.prompt_id
    where v_raw
      and pr.brand_id = p_brand_id
      and pr.platform <> 'chatgpt-shopping'
      and pr.created_at >= v_from - v_span
      and pr.created_at <= v_to
      and (p_platform is null or pr.platform = p_platform)
      and (p_region is null or pr.region = p_region)
  ),
  totals as (
    select cur,
           sum(answers)::bigint                                     as answers,
           sum(mentions)::bigint                                    as mentions,
           sum(occurrences)::bigint                                 as occurrences,
           sum(positive)::bigint                                    as positive,
           sum(negative)::bigint                                    as negative,
           sum(position_sum)::bigint                                as position_sum,
           sum(position_count)::bigint                              as position_count,
           count(distinct prompt_id)                                as prompts,
           count(distinct prompt_id) filter (where mentions > 0)    as prompts_with_mentions,
           max(last_answer_at)                                      as last_answer_at
    from facts
    group by cur
  ),
  platforms as (
    select platform,
           coalesce(sum(answers)  filter (where cur), 0)::bigint      as answers,
           coalesce(sum(mentions) filter (where cur), 0)::bigint      as mentions,
           coalesce(sum(occurrences) filter (where cur), 0)::bigint   as occurrences,
           coalesce(sum(positive) filter (where cur), 0)::bigint      as positive,
           coalesce(sum(negative) filter (where cur), 0)::bigint      as negative,
           coalesce(sum(answers)  filter (where not cur), 0)::bigint  as prev_answers,
           coalesce(sum(mentions) filter (where not cur), 0)::bigint  as prev_mentions,
           coalesce(sum(positive) filter (where not cur), 0)::bigint  as prev_positive,
           coalesce(sum(negative) filter (where not cur), 0)::bigint  as prev_negative
    from facts
    group by platform
  ),
  daily as (
    select day,
           sum(answers)::bigint     as answers,
           sum(mentions)::bigint    as mentions,
           sum(occurrences)::bigint as occurrences,
           sum(positive)::bigint    as positive,
           sum(negative)::bigint    as negative
    from facts
    where cur
    group by day
  ),
  comp_facts as (
    select (c.day >= v_day_from)              as cur,
           c.competitor_id,
           c.mention_answers::bigint           as mentions,
           c.co_mention_answers::bigint        as co_mentions
    from public.mentions_competitor_daily c
    join prompts_in pi on pi.id = c.prompt_id
    where not v_raw
      and c.brand_id = p_brand_id
      and c.day between v_prev_from and v_day_to
      and (p_platform is null or c.platform = p_platform)
      and (p_region is null or c.region = p_region)
    union all
    select (pr.created_at >= v_from),
           cm.value->>'competitor_id',
           1,
           (pr.mention_count > 0)::int
    from public.prompt_results pr
    join prompts_in pi on pi.id = pr.prompt_id
    cross join lateral jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
    where v_raw
      and pr.brand_id = p_brand_id
      and pr.platform <> 'chatgpt-shopping'
      and pr.created_at >= v_from - v_span
      and pr.created_at <= v_to
      and (p_platform is null or pr.platform = p_platform)
      and (p_region is null or pr.region = p_region)
      and cm.value ? 'competitor_id'
      and coalesce((cm.value->>'mention_count')::int, 0) > 0
  ),
  competitors as (
    select co.id::text                                                 as competitor_id,
           co.name,
           coalesce(sum(f.mentions)    filter (where f.cur), 0)::bigint     as mentions,
           coalesce(sum(f.co_mentions) filter (where f.cur), 0)::bigint     as co_mentions,
           coalesce(sum(f.mentions)    filter (where not f.cur), 0)::bigint as prev_mentions
    from public.competitors co
    left join comp_facts f on f.competitor_id = co.id::text
    where co.brand_id = p_brand_id
    group by co.id, co.name
  )
  select jsonb_build_object(
    'window', jsonb_build_object(
      'from', v_from, 'to', v_to, 'days', v_days,
      'source', case when v_raw then 'answers' else 'days' end,
      'day_from', v_day_from, 'day_to', v_day_to),
    'current',     (select to_jsonb(t) - 'cur' from totals t where t.cur),
    'previous',    (select to_jsonb(t) - 'cur' from totals t where not t.cur),
    -- In the order of the column the table shows: occurrences, then responses.
    'platforms',   coalesce((select jsonb_agg(to_jsonb(p)
                                              order by p.occurrences desc, p.mentions desc, p.platform)
                             from platforms p), '[]'::jsonb),
    'daily',       coalesce((select jsonb_agg(to_jsonb(d) order by d.day) from daily d),
                            '[]'::jsonb),
    'competitors', coalesce((select jsonb_agg(to_jsonb(c) order by c.mentions desc, c.name)
                             from competitors c), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00192_rollup_integrity.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00192: the Mentions rollups refresh one at a time, and a deleted prompt
--        leaves the Insights rollups
-- ============================================================================
-- Two ways the Insights and Mentions pages could still show different numbers
-- for the same days once they count the same things (00191).
--
-- 1. refresh_mentions_daily (00157) deletes a day range and inserts it again
--    with no lock. A run's refresh and the nightly sweep (or a backfill) for
--    the same brand could overlap: both delete, both insert, and the days
--    they share are counted twice. refresh_insights_daily had the same gap
--    until 00164 (#1020). It now takes the same per-brand advisory lock, rows
--    written twice before are dropped (the copy with the latest answer is
--    kept; the next refresh of those days rewrites them anyway), and unique
--    keys make a second copy impossible.
--
-- 2. Deleting a prompt cascades its prompt_results. The Mentions page drops
--    its rows at read time (it reads existing prompts only), but
--    insights_brand_daily keeps them until something refreshes those days,
--    and the nightly sweep only covers the last 3. A trigger now queues the
--    brand with the deleted prompt's day range (read from
--    insights_prompt_daily before the delete), and the server refreshes that
--    range, as the citation rollups' queue does (00118).

-- ─── One refresh per brand at a time ────────────────────────────────────────

create or replace function public.refresh_mentions_daily(
  p_brand_id uuid,
  p_day_from date,
  p_day_to   date
) returns void
language plpgsql
set search_path to 'public'
as $$
declare
  -- The range's bounds as instants, so the answers are found by range.
  v_from timestamptz := p_day_from::timestamp at time zone 'utc';
  v_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
begin
  -- One refresh per brand at a time, as refresh_insights_daily (00164); the
  -- lock releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_mentions_daily:' || p_brand_id::text, 0));

  delete from public.mentions_prompt_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.mentions_competitor_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;

  insert into public.mentions_prompt_daily (
    brand_id, day, prompt_id, platform, region,
    answer_count, mention_answers, mention_occurrences,
    positive_answers, negative_answers, position_sum, position_count, last_answer_at)
  select
    p_brand_id,
    (pr.created_at at time zone 'utc')::date,
    pr.prompt_id, pr.platform, pr.region,
    count(*),
    count(*) filter (where pr.mention_count > 0),
    coalesce(sum(pr.mention_count), 0),
    count(*) filter (where pr.mention_count > 0 and pr.sentiment = 'positive'),
    count(*) filter (where pr.mention_count > 0 and pr.sentiment = 'negative'),
    coalesce(sum(pr.mention_position)
      filter (where pr.mention_count > 0 and pr.mention_position is not null), 0),
    count(*) filter (where pr.mention_count > 0 and pr.mention_position is not null),
    max(pr.created_at)
  from public.prompt_results pr
  where pr.brand_id = p_brand_id
    and pr.prompt_id is not null
    and pr.platform <> 'chatgpt-shopping'
    and pr.created_at >= v_from
    and pr.created_at < v_to
  group by 2, pr.prompt_id, pr.platform, pr.region;

  insert into public.mentions_competitor_daily (
    brand_id, day, prompt_id, platform, region, competitor_id,
    mention_answers, co_mention_answers)
  select
    p_brand_id,
    (pr.created_at at time zone 'utc')::date,
    pr.prompt_id, pr.platform, pr.region,
    cm.value->>'competitor_id',
    count(*),
    count(*) filter (where pr.mention_count > 0)
  from public.prompt_results pr
  cross join lateral jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
  where pr.brand_id = p_brand_id
    and pr.prompt_id is not null
    and pr.platform <> 'chatgpt-shopping'
    and pr.created_at >= v_from
    and pr.created_at < v_to
    and cm.value ? 'competitor_id'
    and coalesce((cm.value->>'mention_count')::int, 0) > 0
  group by 2, pr.prompt_id, pr.platform, pr.region, cm.value->>'competitor_id';
end;
$$;

revoke execute on function public.refresh_mentions_daily(uuid, date, date)
  from public, anon, authenticated;

-- ─── Rows written twice ─────────────────────────────────────────────────────

delete from public.mentions_prompt_daily d
using (
  select ctid,
         row_number() over (
           partition by brand_id, day, prompt_id, platform, region
           order by last_answer_at desc, answer_count desc) as n
  from public.mentions_prompt_daily
) x
where d.ctid = x.ctid and x.n > 1;

delete from public.mentions_competitor_daily d
using (
  select ctid,
         row_number() over (
           partition by brand_id, day, prompt_id, platform, region, competitor_id
           order by mention_answers desc) as n
  from public.mentions_competitor_daily
) x
where d.ctid = x.ctid and x.n > 1;

-- On large tables, build these by hand first with `create unique index
-- concurrently`, which doesn't hold back the refreshes; these statements then
-- find them in place. A null platform or region is one key, not many.
create unique index if not exists mentions_prompt_daily_key
  on public.mentions_prompt_daily (brand_id, day, prompt_id, platform, region)
  nulls not distinct;

create unique index if not exists mentions_competitor_daily_key
  on public.mentions_competitor_daily (brand_id, day, prompt_id, platform, region, competitor_id)
  nulls not distinct;

-- ─── A deleted prompt queues its days ───────────────────────────────────────

-- No foreign key on purpose, as citation_rollup_rebuilds: a brand delete must
-- never fail on it. A brand gone by the time the server reads its entry has
-- no rows left, so the refresh is a no-op and the entry is cleared.
create table if not exists public.insights_rollup_rebuilds (
  brand_id     uuid primary key,
  day_from     date not null,
  day_to       date not null,
  requested_at timestamptz not null default now()
);

-- Service role only: no policies.
alter table public.insights_rollup_rebuilds enable row level security;

-- Before the delete, so the prompt's rows are still there to give its days.
create or replace function public.queue_insights_rollup_rebuild()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_brand uuid;
  v_from  date;
  v_to    date;
begin
  -- Only for a brand that still exists: during a brand delete the cascade
  -- removes the brand first, so its prompts queue nothing.
  select ps.brand_id into v_brand
  from public.prompt_sets ps
  join public.brands b on b.id = ps.brand_id
  where ps.id = old.prompt_set_id;
  if v_brand is null then
    return old;
  end if;

  select min(d.day), max(d.day) into v_from, v_to
  from public.insights_prompt_daily d
  where d.brand_id = v_brand and d.prompt_id = old.id;
  if v_from is null then
    return old;
  end if;

  insert into public.insights_rollup_rebuilds as q (brand_id, day_from, day_to)
  values (v_brand, v_from, v_to)
  on conflict (brand_id) do update
    set day_from = least(q.day_from, excluded.day_from),
        day_to = greatest(q.day_to, excluded.day_to),
        requested_at = now();
  return old;
end;
$$;

revoke execute on function public.queue_insights_rollup_rebuild()
  from public, anon, authenticated;

drop trigger if exists prompts_queue_insights_rollup_rebuild on public.prompts;
create trigger prompts_queue_insights_rollup_rebuild
  before delete on public.prompts
  for each row execute function public.queue_insights_rollup_rebuild();

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00193_ai_traffic_platforms_seen.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00193: "is this AI platform new?" reads only the platforms in question
-- ============================================================================
-- Follow-up from #1195's review (AT-013). The nightly "new AI platform" check
-- (server signals/trafficPlatforms.js) read the brand's whole AI traffic
-- history before the week with ai_traffic_merged (00176), pages and days
-- included, only to learn which platforms had sent a visit before.
--
-- ai_traffic_platforms_seen answers that directly, for the few platforms the
-- week put forward: whether the brand had any AI visit before p_before, and
-- which of p_platforms did. A snippet visit or an Analytics session counts,
-- whichever day it fell on: for "seen before" any evidence will do, where
-- ai_traffic_merged keeps one source per day so visits aren't counted twice.
--
-- Each platform is an index probe on the new (brand_id, source_platform,
-- created_at) index; Analytics rows are daily and few. On a large
-- ai_traffic_logs, build the index by hand first with `create index
-- concurrently`, which doesn't hold back the beacon's writes; this statement
-- then finds it in place.

create index if not exists idx_ai_traffic_logs_brand_platform_time
  on public.ai_traffic_logs (brand_id, source_platform, created_at)
  where visit_of is null;

create or replace function public.ai_traffic_platforms_seen(
  p_brand_id uuid,
  p_before timestamptz,
  p_platforms text[]
)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  select jsonb_build_object(
    'any_before',
      exists (
        select 1 from public.ai_traffic_logs l
        where l.brand_id = p_brand_id
          and l.visit_of is null
          and l.created_at < p_before
      )
      or exists (
        select 1 from public.ga_ai_traffic_stats g
        where g.brand_id = p_brand_id
          and g.sessions > 0
          and g.date < (p_before at time zone 'utc')::date
      ),
    'seen', coalesce((
      select jsonb_agg(p.platform order by p.platform)
      from unnest(p_platforms) as p(platform)
      where exists (
          select 1 from public.ai_traffic_logs l
          where l.brand_id = p_brand_id
            and l.visit_of is null
            and l.source_platform = p.platform
            and l.created_at < p_before
        )
        or exists (
          select 1 from public.ga_ai_traffic_stats g
          where g.brand_id = p_brand_id
            and g.sessions > 0
            and coalesce(g.platform, g.source) = p.platform
            and g.date < (p_before at time zone 'utc')::date
        )
    ), '[]'::jsonb)
  );
$$;

revoke all on function public.ai_traffic_platforms_seen(uuid, timestamptz, text[])
  from public, anon;
grant execute on function public.ai_traffic_platforms_seen(uuid, timestamptz, text[])
  to authenticated, service_role;

comment on function public.ai_traffic_platforms_seen(uuid, timestamptz, text[]) is
  'AI Traffic (AT-013): whether a brand had any AI-referred visit before p_before (snippet or Analytics), and which of p_platforms sent one, for the nightly new-platform check. Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00194_ai_traffic_known_pages.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00194: which pages the weekly digest may name
-- ============================================================================
-- Follow-up from #1196's review (AT-013). The weekly AI Traffic e-mail names
-- the pages whose AI visits moved most, and the top broken AI link with its
-- suggested redirect. The snippet's beacon is public, so a page path in
-- ai_traffic_logs can be anything a caller sent (00186 also picks redirects
-- among the pages it logged), and the e-mail would print it.
--
-- ai_traffic_known_pages takes the page keys the digest would name (as the
-- Pages section keys them: lower(normalize_page_path), 00178) and returns
-- those a source the beacon can't write knows: the site's pages (site_pages,
-- 00104: up to 500 from the sitemap, Analytics and citations, nightly),
-- Google Analytics in the last 90 days, the pages tracked AI answers cited in
-- the last 90 days, and active prompts' target URLs — and the home page,
-- which every site has. The digest asks only about a handful of pages a
-- week. Service role only.

create or replace function public.ai_traffic_known_pages(
  p_brand_id uuid,
  p_pages text[]
)
returns text[]
language sql
stable
security definer
set search_path to 'public'
as $$
  with asked as (
    select distinct p.page from unnest(p_pages) as p(page)
  ),
  known as (
    select '/' as page
    union
    select lower(public.normalize_page_path(sp.url))
    from public.site_pages sp
    where sp.brand_id = p_brand_id
    union
    select lower(public.normalize_page_path(g.landing_page))
    from public.ga_page_stats g
    where g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= current_date - 90
    union
    select lower(public.normalize_page_path(g.landing_page))
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= current_date - 90
    union
    select c.page_key
    from public.ai_traffic_page_citations(p_brand_id, current_date - 90, current_date) c
    union
    select lower(public.normalize_page_path(ptu.url))
    from public.prompt_target_urls ptu
    join public.prompts p on p.id = ptu.prompt_id and p.is_active
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
  )
  select coalesce(array_agg(a.page order by a.page), '{}')
  from asked a
  where a.page in (select k.page from known k);
$$;

revoke all on function public.ai_traffic_known_pages(uuid, text[])
  from public, anon, authenticated;
grant execute on function public.ai_traffic_known_pages(uuid, text[])
  to service_role;

comment on function public.ai_traffic_known_pages(uuid, text[]) is
  'AI Traffic weekly digest (AT-013): of the given page keys, those the site''s pages, Google Analytics (90 days), AI answer citations (90 days) or active prompts'' target URLs know, so the e-mail never prints a path only the public beacon sent. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00195_mentions_same_prompt_changes.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00195: the Mentions page takes its changes on the same prompts as Insights
-- ============================================================================
-- After 00191 both pages show the same mentions and net sentiment, but their
-- "vs the previous period" changes still differed: Insights compares only the
-- prompts answered in both windows (insights_same_prompt_compare_daily,
-- 00164), so adding or removing prompts doesn't read as a rise or a fall; the
-- Mentions page compared all of them.
--
-- mentions_overview (00191's definition) now also returns `same`: how many
-- prompts both windows answered, how many are new or dropped, and both
-- windows' totals over the shared ones; each platform row gains the same
-- counts on them (same_*, same_prev_*). The page takes every change from
-- these. Existing fields are unchanged, so either deploy order works; the
-- platforms keep 00191's order by occurrences.

create or replace function public.mentions_overview(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to        timestamptz := coalesce(p_date_to, now());
  v_from      timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_span      interval;
  -- Whole days the window spans, at least one, with an hour of slack: a
  -- rolling 7 days ends at now(), a moment after the browser started it.
  v_days      integer;
  -- Under two days the answers are read directly.
  v_raw       boolean;
  v_day_to    date;
  v_day_from  date;
  v_prev_from date;
  v_search    text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_result    jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  v_span      := v_to - v_from;
  v_days      := greatest(1, ceil(extract(epoch from v_span) / 86400.0 - 1.0 / 24)::integer);
  v_raw       := v_days < 2;
  v_day_to    := (v_to at time zone 'utc')::date;
  v_day_from  := v_day_to - (v_days - 1);
  v_prev_from := v_day_from - v_days;

  with
  prompts_in as (
    select p.id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  facts as (
    select (d.day >= v_day_from)            as cur,
           d.day,
           d.prompt_id,
           d.platform,
           d.answer_count::bigint            as answers,
           d.mention_answers::bigint         as mentions,
           d.mention_occurrences             as occurrences,
           d.positive_answers::bigint        as positive,
           d.negative_answers::bigint        as negative,
           d.position_sum,
           d.position_count::bigint          as position_count,
           d.last_answer_at
    from public.mentions_prompt_daily d
    join prompts_in pi on pi.id = d.prompt_id
    where not v_raw
      and d.brand_id = p_brand_id
      and d.day between v_prev_from and v_day_to
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    union all
    select (pr.created_at >= v_from),
           (pr.created_at at time zone 'utc')::date,
           pr.prompt_id,
           pr.platform,
           1,
           (pr.mention_count > 0)::int,
           coalesce(pr.mention_count, 0),
           (pr.mention_count > 0 and pr.sentiment = 'positive')::int,
           (pr.mention_count > 0 and pr.sentiment = 'negative')::int,
           case when pr.mention_count > 0 then coalesce(pr.mention_position, 0) else 0 end,
           (pr.mention_count > 0 and pr.mention_position is not null)::int,
           pr.created_at
    from public.prompt_results pr
    join prompts_in pi on pi.id = pr.prompt_id
    where v_raw
      and pr.brand_id = p_brand_id
      and pr.platform <> 'chatgpt-shopping'
      and pr.created_at >= v_from - v_span
      and pr.created_at <= v_to
      and (p_platform is null or pr.platform = p_platform)
      and (p_region is null or pr.region = p_region)
  ),
  -- Prompts answered in both windows: every change is taken on them, as
  -- Insights takes its changes (insights_same_prompt_compare_daily, 00164),
  -- so adding or removing prompts doesn't read as a rise or a fall.
  presence as (
    select prompt_id,
           bool_or(cur and answers > 0)     as in_cur,
           bool_or(not cur and answers > 0) as in_prev
    from facts
    group by prompt_id
  ),
  flagged as (
    select f.*, (p.in_cur and p.in_prev) as shared
    from facts f
    join presence p using (prompt_id)
  ),
  same_totals as (
    select cur,
           sum(answers)::bigint                                     as answers,
           sum(mentions)::bigint                                    as mentions,
           sum(occurrences)::bigint                                 as occurrences,
           sum(positive)::bigint                                    as positive,
           sum(negative)::bigint                                    as negative,
           count(distinct prompt_id)                                as prompts,
           count(distinct prompt_id) filter (where mentions > 0)    as prompts_with_mentions
    from flagged
    where shared
    group by cur
  ),
  totals as (
    select cur,
           sum(answers)::bigint                                     as answers,
           sum(mentions)::bigint                                    as mentions,
           sum(occurrences)::bigint                                 as occurrences,
           sum(positive)::bigint                                    as positive,
           sum(negative)::bigint                                    as negative,
           sum(position_sum)::bigint                                as position_sum,
           sum(position_count)::bigint                              as position_count,
           count(distinct prompt_id)                                as prompts,
           count(distinct prompt_id) filter (where mentions > 0)    as prompts_with_mentions,
           max(last_answer_at)                                      as last_answer_at
    from facts
    group by cur
  ),
  platforms as (
    select platform,
           coalesce(sum(answers)  filter (where cur), 0)::bigint      as answers,
           coalesce(sum(mentions) filter (where cur), 0)::bigint      as mentions,
           coalesce(sum(occurrences) filter (where cur), 0)::bigint   as occurrences,
           coalesce(sum(positive) filter (where cur), 0)::bigint      as positive,
           coalesce(sum(negative) filter (where cur), 0)::bigint      as negative,
           coalesce(sum(answers)  filter (where not cur), 0)::bigint  as prev_answers,
           coalesce(sum(mentions) filter (where not cur), 0)::bigint  as prev_mentions,
           coalesce(sum(positive) filter (where not cur), 0)::bigint  as prev_positive,
           coalesce(sum(negative) filter (where not cur), 0)::bigint  as prev_negative,
           -- The same on the shared prompts, for the platform's change.
           coalesce(sum(answers)  filter (where cur and shared), 0)::bigint      as same_answers,
           coalesce(sum(mentions) filter (where cur and shared), 0)::bigint      as same_mentions,
           coalesce(sum(positive) filter (where cur and shared), 0)::bigint      as same_positive,
           coalesce(sum(negative) filter (where cur and shared), 0)::bigint      as same_negative,
           coalesce(sum(answers)  filter (where not cur and shared), 0)::bigint  as same_prev_answers,
           coalesce(sum(mentions) filter (where not cur and shared), 0)::bigint  as same_prev_mentions,
           coalesce(sum(positive) filter (where not cur and shared), 0)::bigint  as same_prev_positive,
           coalesce(sum(negative) filter (where not cur and shared), 0)::bigint  as same_prev_negative
    from flagged
    group by platform
  ),
  daily as (
    select day,
           sum(answers)::bigint     as answers,
           sum(mentions)::bigint    as mentions,
           sum(occurrences)::bigint as occurrences,
           sum(positive)::bigint    as positive,
           sum(negative)::bigint    as negative
    from facts
    where cur
    group by day
  ),
  comp_facts as (
    select (c.day >= v_day_from)              as cur,
           c.competitor_id,
           c.mention_answers::bigint           as mentions,
           c.co_mention_answers::bigint        as co_mentions
    from public.mentions_competitor_daily c
    join prompts_in pi on pi.id = c.prompt_id
    where not v_raw
      and c.brand_id = p_brand_id
      and c.day between v_prev_from and v_day_to
      and (p_platform is null or c.platform = p_platform)
      and (p_region is null or c.region = p_region)
    union all
    select (pr.created_at >= v_from),
           cm.value->>'competitor_id',
           1,
           (pr.mention_count > 0)::int
    from public.prompt_results pr
    join prompts_in pi on pi.id = pr.prompt_id
    cross join lateral jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
    where v_raw
      and pr.brand_id = p_brand_id
      and pr.platform <> 'chatgpt-shopping'
      and pr.created_at >= v_from - v_span
      and pr.created_at <= v_to
      and (p_platform is null or pr.platform = p_platform)
      and (p_region is null or pr.region = p_region)
      and cm.value ? 'competitor_id'
      and coalesce((cm.value->>'mention_count')::int, 0) > 0
  ),
  competitors as (
    select co.id::text                                                 as competitor_id,
           co.name,
           coalesce(sum(f.mentions)    filter (where f.cur), 0)::bigint     as mentions,
           coalesce(sum(f.co_mentions) filter (where f.cur), 0)::bigint     as co_mentions,
           coalesce(sum(f.mentions)    filter (where not f.cur), 0)::bigint as prev_mentions
    from public.competitors co
    left join comp_facts f on f.competitor_id = co.id::text
    where co.brand_id = p_brand_id
    group by co.id, co.name
  )
  select jsonb_build_object(
    'window', jsonb_build_object(
      'from', v_from, 'to', v_to, 'days', v_days,
      'source', case when v_raw then 'answers' else 'days' end,
      'day_from', v_day_from, 'day_to', v_day_to),
    'current',     (select to_jsonb(t) - 'cur' from totals t where t.cur),
    'previous',    (select to_jsonb(t) - 'cur' from totals t where not t.cur),
    'same',        jsonb_build_object(
                     'prompts',         (select count(*) from presence where in_cur and in_prev),
                     'new_prompts',     (select count(*) from presence where in_cur and not in_prev),
                     'dropped_prompts', (select count(*) from presence where in_prev and not in_cur),
                     'current',  (select to_jsonb(t) - 'cur' from same_totals t where t.cur),
                     'previous', (select to_jsonb(t) - 'cur' from same_totals t where not t.cur)),
    -- In the order of the column the table shows: occurrences, then responses.
    'platforms',   coalesce((select jsonb_agg(to_jsonb(p)
                                              order by p.occurrences desc, p.mentions desc, p.platform)
                             from platforms p), '[]'::jsonb),
    'daily',       coalesce((select jsonb_agg(to_jsonb(d) order by d.day) from daily d),
                            '[]'::jsonb),
    'competitors', coalesce((select jsonb_agg(to_jsonb(c) order by c.mentions desc, c.name)
                             from competitors c), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00196_getting_started.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00196: Getting started, per brand (New GetCito, AC-ALT2 §4)
-- ============================================================================
-- Getting started is a fixed set of 17 steps in the Actions page. It walks a
-- brand through setup (KPIs, competitors, topics, prompts, Search Console,
-- Analytics, the AI Traffic snippet), a first look at the analytics pages and
-- its first content. It sits beside the Action Center's generated actions
-- and never touches them: no signal, no Priority Score, no row in actions.
--
-- Most steps are done when the brand's own data says so (3 competitors, a
-- first AI visit, a finished audit…), so only what the data can't tell is
-- stored here:
--
--   * getting_started: one row per brand that runs it. Every brand created
--     from now on gets one (trigger below). An existing brand has none until
--     someone starts it from the Actions page. dismissed_at: skipped.
--   * getting_started_steps: what a person did that leaves no other trace.
--     They opened one of the analytics pages after the first answers came in
--     (the explore steps), skipped an optional step, or saved the KPIs from
--     the KPI screen. The ready-made KPIs (00163) appear on a visit, so they
--     don't count as set.
--
-- getting_started_facts reads everything the step list needs in one call;
-- the web turns it into the 17 steps (frontend/src/lib/getting-started/steps.ts).

create table if not exists public.getting_started (
  brand_id uuid primary key references public.brands(id) on delete cascade,
  started_at timestamptz not null default now(),
  dismissed_at timestamptz
);

comment on table public.getting_started is
  'Getting started (AC-ALT2): brands that run the setup steps in the Actions page. dismissed_at = skipped.';

create table if not exists public.getting_started_steps (
  brand_id uuid not null references public.brands(id) on delete cascade,
  -- A step key from the web's list. Not an enum: a new step must not take a
  -- migration.
  step text not null check (step ~ '^[a-z_]{1,40}$'),
  state text not null check (state in ('opened', 'skipped', 'done')),
  updated_at timestamptz not null default now(),
  primary key (brand_id, step)
);

comment on table public.getting_started_steps is
  'Getting started (AC-ALT2): steps a person finished that the brand''s data can''t show (a page opened, a step skipped, KPIs saved).';

alter table public.getting_started enable row level security;
alter table public.getting_started_steps enable row level security;

create policy "getting_started: member select"
  on public.getting_started
  for select
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

create policy "getting_started_steps: member select"
  on public.getting_started_steps
  for select
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

-- Any member records a page they opened; skipping a step or marking one
-- done is for admins and managers, who set the steps up (as kpi_definitions'
-- and getting_started's writes).
create policy "getting_started_steps: member insert"
  on public.getting_started_steps
  for insert
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and (
      state = 'opened'
      or exists (
        select 1 from public.profiles p
        where p.id = auth.uid()
          and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
      )
    )
  );

create policy "getting_started_steps: member update"
  on public.getting_started_steps
  for update
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  )
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and (
      state = 'opened'
      or exists (
        select 1 from public.profiles p
        where p.id = auth.uid()
          and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
      )
    )
  );

-- A new brand runs Getting started. Whoever adds it (onboarding, the brands
-- page, the API), its row is here before anyone opens the Actions page.
create or replace function public.start_brand_getting_started()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  insert into public.getting_started (brand_id)
  values (new.id)
  on conflict (brand_id) do nothing;
  return new;
end;
$$;

revoke all on function public.start_brand_getting_started() from public, anon, authenticated;

drop trigger if exists trg_brands_start_getting_started on public.brands;
create trigger trg_brands_start_getting_started
  after insert on public.brands
  for each row execute function public.start_brand_getting_started();

-- An explore step is done when its page was opened once the brand's first
-- answers are in: opened before them, the page had nothing to show. True when
-- the step is recorded (now or earlier).
create or replace function public.getting_started_page_opened(p_brand_id uuid, p_step text)
returns boolean
language plpgsql
security invoker
set search_path to 'public'
as $$
begin
  if exists (select 1 from public.prompt_results r where r.brand_id = p_brand_id) then
    insert into public.getting_started_steps (brand_id, step, state)
    values (p_brand_id, p_step, 'opened')
    on conflict (brand_id, step) do nothing;
  end if;
  return exists (
    select 1 from public.getting_started_steps s
    where s.brand_id = p_brand_id and s.step = p_step
  );
end;
$$;

revoke all on function public.getting_started_page_opened(uuid, text) from public, anon;
grant execute on function public.getting_started_page_opened(uuid, text) to authenticated;

-- Everything the step list reads, for one brand. Security invoker: RLS
-- decides the brand, and a brand the caller can't see returns null.
create or replace function public.getting_started_facts(p_brand_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  select jsonb_build_object(
    'started_at', gs.started_at,
    'dismissed_at', gs.dismissed_at,
    'steps', coalesce((
      select jsonb_object_agg(s.step, jsonb_build_object('state', s.state, 'at', s.updated_at))
      from public.getting_started_steps s
      where s.brand_id = p_brand_id
    ), '{}'::jsonb),
    'kpi_setup_at', b.kpi_setup_at,
    'competitors', (
      select count(*) from public.competitors c where c.brand_id = p_brand_id
    ),
    -- Active prompts in each active topic, oldest topic first.
    'topic_prompts', coalesce((
      select jsonb_agg(n.prompts order by t.created_at, t.id)
      from public.topics t
      cross join lateral (
        select count(*) as prompts
        from public.prompts p
        join public.prompt_sets ps on ps.id = p.prompt_set_id
        where p.topic_id = t.id
          and p.is_active
          and ps.brand_id = p_brand_id
      ) n
      where t.brand_id = p_brand_id
        and t.is_active
    ), '[]'::jsonb),
    -- Connected for the organization and mapped to a property for the brand,
    -- as Settings › Integrations shows it.
    'gsc', nullif(b.gsc_property, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-search-console'
        and ic.status = 'connected'
    ),
    'ga', nullif(b.ga_property_id, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-analytics'
        and ic.status = 'connected'
    ),
    'first_answer', exists (
      select 1 from public.prompt_results r where r.brand_id = p_brand_id
    ),
    'first_visit', exists (
      select 1 from public.ai_traffic_logs l where l.brand_id = p_brand_id
    ),
    -- Prompt suggestions built from Search Console and Analytics data.
    'data_suggestions', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga')
    ),
    'data_tracked', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga') and s.status = 'added'
    ),
    'content_suggestions', (
      select count(*) from public.content_opportunities o where o.brand_id = p_brand_id
    ),
    -- Picked: reviewed, sent to the Action Center or given a brief (00106).
    'content_picked', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status in ('reviewed', 'sent', 'in_progress', 'done') or o.brief is not null)
    ),
    -- Created: its work was completed, or it went to the CMS webhook. There
    -- is no published state until the Content Editor.
    'content_created', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status = 'done' or o.webhook_sent_at is not null)
    ),
    -- Audits a person ran (not the automatic sweep, 00167) that finished.
    'audits', (
      select count(*) from public.site_audits a
      where a.brand_id = p_brand_id and a.source = 'user' and a.status = 'completed'
    )
  )
  from public.brands b
  left join public.getting_started gs on gs.brand_id = b.id
  where b.id = p_brand_id;
$$;

revoke all on function public.getting_started_facts(uuid) from public, anon;
grant execute on function public.getting_started_facts(uuid) to authenticated;

comment on function public.getting_started_facts(uuid) is
  'Getting started (AC-ALT2): the counts and flags the 17 steps read, for one brand. Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00197_getting_started_start_skip.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00197: start and skip Getting started (New GetCito, AC-ALT2 §5)
-- ============================================================================
-- 00196 starts Getting started for every new brand. This lets a person start
-- and skip it from the Actions page, and asks first for a brand added to an
-- organization that already has one:
--
--   * getting_started.confirmed_at: when someone chose to run it. The first
--     brand of an organization (onboarding) runs it at once; a later brand
--     asks "Run Getting started for [brand]?" until someone answers, so its
--     row starts with confirmed_at null. dismissed_at stays "skipped", and
--     starting again clears it.
--   * admins and managers start and skip it (insert and update policies, as
--     for kpi_definitions); members keep reading it.
--   * getting_started_facts also returns confirmed_at and content_recent,
--     the content of the last 30 days, for the existing-customer rule: fewer
--     than 3 competitors or topics, no Search Console, or no content in 30
--     days offers "Start getting started".

alter table public.getting_started
  add column if not exists confirmed_at timestamptz;

comment on column public.getting_started.confirmed_at is
  'When someone chose to run Getting started for the brand; null while a later brand of the organization still asks.';

-- Rows from before this migration ran it at once.
update public.getting_started
   set confirmed_at = started_at
 where confirmed_at is null;

create or replace function public.start_brand_getting_started()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  insert into public.getting_started (brand_id, confirmed_at)
  values (
    new.id,
    -- The organization's first brand runs it; a later one asks first.
    case
      when exists (
        select 1 from public.brands b
        where b.organization_id = new.organization_id and b.id <> new.id
      ) then null
      else now()
    end
  )
  on conflict (brand_id) do nothing;
  return new;
end;
$$;

revoke all on function public.start_brand_getting_started() from public, anon, authenticated;

create policy "getting_started: admin/manager insert"
  on public.getting_started
  for insert
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
        and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

create policy "getting_started: admin/manager update"
  on public.getting_started
  for update
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
        and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

create or replace function public.getting_started_facts(p_brand_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  select jsonb_build_object(
    'started_at', gs.started_at,
    'dismissed_at', gs.dismissed_at,
    'confirmed_at', gs.confirmed_at,
    'steps', coalesce((
      select jsonb_object_agg(s.step, jsonb_build_object('state', s.state, 'at', s.updated_at))
      from public.getting_started_steps s
      where s.brand_id = p_brand_id
    ), '{}'::jsonb),
    'kpi_setup_at', b.kpi_setup_at,
    'competitors', (
      select count(*) from public.competitors c where c.brand_id = p_brand_id
    ),
    -- Active prompts in each active topic, oldest topic first.
    'topic_prompts', coalesce((
      select jsonb_agg(n.prompts order by t.created_at, t.id)
      from public.topics t
      cross join lateral (
        select count(*) as prompts
        from public.prompts p
        join public.prompt_sets ps on ps.id = p.prompt_set_id
        where p.topic_id = t.id
          and p.is_active
          and ps.brand_id = p_brand_id
      ) n
      where t.brand_id = p_brand_id
        and t.is_active
    ), '[]'::jsonb),
    -- Connected for the organization and mapped to a property for the brand,
    -- as Settings › Integrations shows it.
    'gsc', nullif(b.gsc_property, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-search-console'
        and ic.status = 'connected'
    ),
    'ga', nullif(b.ga_property_id, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-analytics'
        and ic.status = 'connected'
    ),
    'first_answer', exists (
      select 1 from public.prompt_results r where r.brand_id = p_brand_id
    ),
    'first_visit', exists (
      select 1 from public.ai_traffic_logs l where l.brand_id = p_brand_id
    ),
    -- Prompt suggestions built from Search Console and Analytics data.
    'data_suggestions', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga')
    ),
    'data_tracked', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga') and s.status = 'added'
    ),
    'content_suggestions', (
      select count(*) from public.content_opportunities o where o.brand_id = p_brand_id
    ),
    -- Picked: reviewed, sent to the Action Center or given a brief (00106).
    'content_picked', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status in ('reviewed', 'sent', 'in_progress', 'done') or o.brief is not null)
    ),
    -- Created: its work was completed, or it went to the CMS webhook. There
    -- is no published state until the Content Editor.
    'content_created', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status = 'done' or o.webhook_sent_at is not null)
    ),
    -- Content in the last 30 days, the same way: for the existing-customer
    -- rule (no content in 30 days → offer Getting started).
    'content_recent', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (
          o.webhook_sent_at >= now() - interval '30 days'
          or (o.status = 'done' and o.updated_at >= now() - interval '30 days')
        )
    ),
    -- Audits a person ran (not the automatic sweep, 00167) that finished.
    'audits', (
      select count(*) from public.site_audits a
      where a.brand_id = p_brand_id and a.source = 'user' and a.status = 'completed'
    )
  )
  from public.brands b
  left join public.getting_started gs on gs.brand_id = b.id
  where b.id = p_brand_id;
$$;

revoke all on function public.getting_started_facts(uuid) from public, anon;
grant execute on function public.getting_started_facts(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00198_webhook_event_subscriptions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00198: per-webhook event subscriptions
-- ============================================================================
-- Keep existing integrations receiving the events they already receive. Event
-- subscription controls are now available in Content → Configure Webhook.
-- Test deliveries use webhook.test directly and are not stored subscriptions.

alter table public.webhook_configs
  alter column events set default
    array['opportunity.sent', 'daily_pulse.created', 'action_task.sent']::text[];

update public.webhook_configs as config
set events = (
  select array_agg(subscription.event order by subscription.event)
  from (
    select distinct event
    from unnest(
      coalesce(config.events, array[]::text[])
      || array['opportunity.sent', 'daily_pulse.created', 'action_task.sent']::text[]
    ) as existing(event)
    where event = any(array['opportunity.sent', 'daily_pulse.created', 'action_task.sent']::text[])
  ) as subscription
);

alter table public.webhook_configs
  alter column events set not null;

alter table public.webhook_configs
  drop constraint if exists webhook_configs_events_allowed;

alter table public.webhook_configs
  add constraint webhook_configs_events_allowed
  check (events <@ array['opportunity.sent', 'daily_pulse.created', 'action_task.sent']::text[]);

comment on column public.webhook_configs.events is
  'Event types subscribed to by this webhook (opportunity.sent, daily_pulse.created, action_task.sent). webhook.test is always sent by the test action and is not stored here.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00199_serialize_citation_refreshes.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00199: the Citations rollups refresh one at a time (#1020)
-- ============================================================================
-- refresh_citations_daily (00118) deletes a brand's citation_*_daily rows for
-- a day range and inserts them again, with no lock and no unique key. A run's
-- refresh, the nightly sweep and the topic-move rebuild can overlap on the
-- same brand: the second refresh's delete waits for the first to commit, but
-- its snapshot predates the first one's insert, so it skips those rows and
-- adds its own, and the days they share are counted twice.
--
-- As 00164 did for refresh_insights_daily and 00192 for
-- refresh_mentions_daily: the function takes a per-brand advisory lock, rows
-- written twice before are dropped, and unique keys make a second copy
-- impossible.
--
-- The lock lasts one call. refreshCitationHistory rebuilds a brand in
-- 14-day calls (HISTORY_CHUNK_DAYS), so a refresh queued behind a rebuild
-- waits for one chunk, well inside the service role's 120s statement_timeout
-- (00100). The body is 00118's unchanged apart from the lock.

-- ─── One refresh per brand at a time ────────────────────────────────────────

create or replace function public.refresh_citations_daily(
  p_brand_id uuid,
  p_day_from date,
  p_day_to date
) returns void
language plpgsql
set search_path to 'public'
set work_mem to '256MB'
as $$
declare
  ts_from timestamptz := p_day_from::timestamp at time zone 'utc';
  ts_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
begin
  -- One refresh per brand at a time, as refresh_insights_daily (00164) and
  -- refresh_mentions_daily (00192); the lock releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_citations_daily:' || p_brand_id::text, 0));

  delete from public.citation_result_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_domain_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_url_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;

  insert into public.citation_result_daily (
    brand_id, day, model_used, platform, region, topic_id, answers)
  select p_brand_id,
         (pr.created_at at time zone 'utc')::date,
         pr.model_used, pr.platform, pr.region, p.topic_id,
         count(*)
  from public.prompt_results pr
  left join public.prompts p on p.id = pr.prompt_id
  where pr.brand_id = p_brand_id
    and pr.platform <> 'chatgpt-shopping'  -- #155 — isolate from analytics
    and pr.created_at >= ts_from and pr.created_at < ts_to
  group by 2, pr.model_used, pr.platform, pr.region, p.topic_id;

  -- A citation row carries its answer's created_at, so the citation index
  -- bounds the scan; the answer supplies the bucket.
  insert into public.citation_domain_daily (
    brand_id, day, model_used, platform, region, topic_id, domain, citations, results)
  select p_brand_id,
         (pr.created_at at time zone 'utc')::date,
         pr.model_used, pr.platform, pr.region, p.topic_id, cu.domain,
         count(*),
         count(distinct c.prompt_result_id)
  from public.prompt_result_citations c
  join public.prompt_results pr on pr.id = c.prompt_result_id
  left join public.prompts p on p.id = pr.prompt_id
  join public.citation_urls cu on cu.id = c.url_id
  where c.brand_id = p_brand_id
    and c.created_at >= ts_from and c.created_at < ts_to
    and pr.platform <> 'chatgpt-shopping'
  group by 2, pr.model_used, pr.platform, pr.region, p.topic_id, cu.domain;

  insert into public.citation_url_daily (
    brand_id, day, model_used, platform, region, topic_id, url_id, citations, results)
  select p_brand_id,
         (pr.created_at at time zone 'utc')::date,
         pr.model_used, pr.platform, pr.region, p.topic_id, c.url_id,
         count(*),
         count(distinct c.prompt_result_id)
  from public.prompt_result_citations c
  join public.prompt_results pr on pr.id = c.prompt_result_id
  left join public.prompts p on p.id = pr.prompt_id
  where c.brand_id = p_brand_id
    and c.created_at >= ts_from and c.created_at < ts_to
    and pr.platform <> 'chatgpt-shopping'
  group by 2, pr.model_used, pr.platform, pr.region, p.topic_id, c.url_id;
end;
$$;

revoke execute on function public.refresh_citations_daily(uuid, date, date)
  from public, anon, authenticated;

-- ─── Rows written twice ─────────────────────────────────────────────────────
-- Copies from an overlap are the same counts computed twice; keep one. The
-- next refresh of those days rewrites them anyway.

delete from public.citation_result_daily d
using (
  select ctid,
         row_number() over (
           partition by brand_id, day, model_used, platform, region, topic_id
           order by answers desc) as n
  from public.citation_result_daily
) x
where d.ctid = x.ctid and x.n > 1;

delete from public.citation_domain_daily d
using (
  select ctid,
         row_number() over (
           partition by brand_id, day, model_used, platform, region, topic_id, domain
           order by citations desc, results desc) as n
  from public.citation_domain_daily
) x
where d.ctid = x.ctid and x.n > 1;

delete from public.citation_url_daily d
using (
  select ctid,
         row_number() over (
           partition by brand_id, day, model_used, platform, region, topic_id, url_id
           order by citations desc, results desc) as n
  from public.citation_url_daily
) x
where d.ctid = x.ctid and x.n > 1;

-- On large tables, build these by hand first with `create unique index
-- concurrently`, which doesn't hold back the refreshes; these statements then
-- find them in place. A null model, platform, region or topic is one key, not
-- many.
create unique index if not exists citation_result_daily_key
  on public.citation_result_daily (brand_id, day, model_used, platform, region, topic_id)
  nulls not distinct;

create unique index if not exists citation_domain_daily_key
  on public.citation_domain_daily (brand_id, day, model_used, platform, region, topic_id, domain)
  nulls not distinct;

create unique index if not exists citation_url_daily_key
  on public.citation_url_daily (brand_id, day, model_used, platform, region, topic_id, url_id)
  nulls not distinct;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00200_ai_traffic_soft_404.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00200: soft 404s count as broken AI links
-- ============================================================================
-- Follow-up from #1192's review (AT-012). A single-page app answers every
-- path with 200 and shows its own "Page not found" route, so the browser's
-- status says the page works. The snippet now reads the title for a 2xx
-- landing page too (with a stricter pattern), a moment after load so the
-- app has set it, and the beacon keeps not_found_title with a 2xx status.
--
-- ai_traffic_broken_pages counts such a page as missing (status soft404)
-- once at least two visits saw it, doesn't let its 2xx count as working,
-- and doesn't let the nightly page read clear it: that read gets the app's
-- shell with a 200 too. The beacon is public, so one visit, stray or made
-- up, lists nothing (gkhngyk on #1247): nothing would clear it, and a cited
-- page would raise broken_citation_target from that visit. ai_traffic_broken_links reads those pageviews for the visits. The
-- rest of both functions is 00186's.

comment on column public.ai_traffic_logs.not_found_title is
  'True when the page''s title read "404" or "not found" and the browser reported no status, or a 2xx (a soft 404) (AT-012).';

create or replace function public.ai_traffic_broken_pages(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz
)
returns table (page_key text, status text, routed boolean)
language sql
stable
set search_path to 'public'
as $$
  with
  -- Only the pageviews that say something about the page: a status, or a
  -- not-found title. Read up to now, so a page that works again since the
  -- window ended isn't listed.
  logs as (
    select
      n.page_key,
      -- The address: the path plus its query, tracking parameters left out,
      -- in one order. Worked out only when the URL has a query.
      case when q.query is null then n.page_key else n.page_key || '?' || q.query end as address,
      l.created_at,
      l.http_status,
      l.not_found_title,
      -- The visit a pageview belongs to: a reload continues one (AT-003).
      coalesce(l.visit_of, l.id) as visit_id,
      -- A soft 404: the server answered 2xx and the page says not found (a
      -- single-page app's route that doesn't exist).
      coalesce(l.not_found_title and l.http_status between 200 and 299, false) as soft_404,
      (p_to is null or l.created_at <= p_to)
        and (
          l.http_status in (404, 410)
          or (l.not_found_title and (l.http_status is null or l.http_status between 200 and 299))
        )
        as failed_in_window
    from public.ai_traffic_logs l
    cross join lateral (select lower(public.normalize_page_path(l.url)) as page_key) n
    cross join lateral (
      select case when strpos(l.url, '?') > 0 then (
        select string_agg(qp.part, '&' order by qp.part)
        from unnest(string_to_array(split_part(split_part(l.url, '#', 1), '?', 2), '&')) as qp(part)
        where qp.part <> ''
          and qp.part !~* '^(utm_[^=]*|gclid|fbclid|msclkid|srsltid|_gl|ref)(=|$)'
      ) end as query
    ) q
    where l.brand_id = p_brand_id
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (l.http_status is not null or l.not_found_title)
  ),
  address_state as (
    select
      page_key,
      address,
      (array_agg(http_status order by created_at desc) filter (where http_status is not null))[1]
        as last_status,
      -- Whether that latest status was a soft 404.
      (array_agg(soft_404 order by created_at desc) filter (where http_status is not null))[1]
        as last_soft_404,
      bool_or(not_found_title) as title_not_found,
      max(created_at) filter (where failed_in_window) as last_failed_at
    from logs
    group by page_key, address
  ),
  -- The visits that saw each page as a soft 404.
  soft_visits as (
    select page_key, count(distinct visit_id) as visits
    from logs
    where soft_404
    group by page_key
  ),
  page_state as (
    select
      a.page_key,
      max(last_status) filter (where last_status in (404, 410)) as last_status,
      bool_or(last_status is null and title_not_found) as title_not_found,
      coalesce(bool_or(last_soft_404), false) and coalesce(max(v.visits), 0) >= 2 as soft_404,
      -- No address with a status reads as not working, not as unknown; a soft
      -- 404's 2xx doesn't either.
      coalesce(bool_or(last_status between 200 and 399 and not last_soft_404), false) as works,
      max(last_failed_at) as last_failed_at,
      -- Every missing address carries a query: a route on the page, not the page.
      bool_and(a.address <> a.page_key)
        filter (
          where last_status in (404, 410)
            or last_soft_404
            or (last_status is null and title_not_found)
        )
        as routed
    from address_state a
    left join soft_visits v on v.page_key = a.page_key
    group by a.page_key
  ),
  -- What the nightly page read found (00104).
  fetched as (
    select lower(public.normalize_page_path(sp.url)) as page_key,
           bool_or(sp.fetch_status between 200 and 399) as works,
           max(sp.fetched_at) filter (where sp.fetch_status between 200 and 299) as last_ok_at
    from public.site_pages sp
    where sp.brand_id = p_brand_id
      and sp.fetch_status is not null
    group by 1
  )
  select
    s.page_key,
    case
      when s.last_status in (404, 410) then s.last_status::text
      when s.soft_404 then 'soft404'
      else 'title'
    end,
    coalesce(s.routed, false)
  from page_state s
  left join fetched f on f.page_key = s.page_key
  where not s.works
    and s.last_failed_at is not null
    and (
      -- The nightly read gets the app's shell with a 200 as well: only the
      -- visitors' browsers can tell a soft 404.
      s.soft_404
      or (
        -- The nightly read found it working after its last miss: fixed since.
        not coalesce(f.last_ok_at > s.last_failed_at, false)
        and (
          s.last_status in (404, 410)
          or (s.last_status is null and s.title_not_found and not coalesce(f.works, false))
        )
      )
    );
$$;

revoke all on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz)
  from public, anon, authenticated;
grant execute on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz)
  to service_role;

comment on function public.ai_traffic_broken_pages(uuid, timestamptz, timestamptz) is
  'AI Traffic (AT-012): the brand''s pages AI visitors found missing in a window whose latest reported status up to now is 404 or 410, or a 2xx with a not-found title (a soft 404, status soft404), or, with no status, whose title said not found and that the nightly page read never found working; not those the nightly read found working after their last miss. Decided per address (path plus query, utm_* and click ids left out), and a path none of whose addresses last answered 2xx or 3xx; routed when every missing address carries a query. No organization check: called only by ai_traffic_broken_links and ai_traffic_pages, after theirs.';

-- ─── Broken AI links ────────────────────────────────────────────────────────

create or replace function public.ai_traffic_broken_links(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_since date := (p_from at time zone 'utc')::date;
  v_until date := coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date);
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;

  with
  logs as (
    select
      lower(n.page) as page_key,
      n.page,
      coalesce(l.visit_of, l.id) as visit,
      l.created_at,
      coalesce(nullif(l.source_platform, ''), 'unknown') as platform
    from public.ai_traffic_logs l
    cross join lateral (select public.normalize_page_path(l.url) as page) n
    where l.brand_id = p_brand_id
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at <= p_to)
      -- Only the pageviews that found the page missing, not those from before it broke.
      and (
        l.http_status in (404, 410)
        or (l.not_found_title and (l.http_status is null or l.http_status between 200 and 299))
      )
  ),
  broken as (
    select bp.page_key, bp.status, bp.routed
    from public.ai_traffic_broken_pages(p_brand_id, p_from, p_to) bp
  ),
  visits as (
    select l.page_key, min(l.page) as page, count(distinct l.visit)::bigint as visits,
           max(l.created_at) as last_visit
    from logs l
    join broken b on b.page_key = l.page_key
    group by l.page_key
  ),
  platforms as (
    select page_key, (array_agg(platform order by visits desc, platform))[1:3] as platforms
    from (
      select l.page_key, l.platform, count(distinct l.visit) as visits
      from logs l
      join broken b on b.page_key = l.page_key
      group by 1, 2
    ) t
    group by 1
  ),
  cited as (
    select c.page_key, c.citations
    from public.ai_traffic_page_citations(p_brand_id, v_since, v_until) c
  ),
  -- Pages known to work, to redirect to. Only a page's own address counts:
  -- /product.php?id=5 answering 200 says nothing about /product.php.
  landed as (
    select lower(n.page) as page_key,
           min(n.page) as page,
           (array_agg(l.http_status order by l.created_at desc))[1] as last_status
    from public.ai_traffic_logs l
    cross join lateral (select public.normalize_page_path(l.url) as page) n
    where l.brand_id = p_brand_id
      and l.http_status is not null
      and l.created_at >= now() - interval '90 days'
      and (
        strpos(l.url, '?') = 0
        or not exists (
          select 1
          from unnest(string_to_array(split_part(split_part(l.url, '#', 1), '?', 2), '&')) as qp(part)
          where qp.part <> ''
            and qp.part !~* '^(utm_[^=]*|gclid|fbclid|msclkid|srsltid|_gl|ref)(=|$)'
        )
      )
    group by 1
  ),
  candidates as (
    select page_key, min(page) as page, max(weight) as weight
    from (
      select lower(public.normalize_page_path(sp.url)) as page_key,
             public.normalize_page_path(sp.url) as page,
             sp.ga_sessions as weight
      from public.site_pages sp
      where sp.brand_id = p_brand_id
        and sp.fetch_status between 200 and 299
      union all
      select page_key, page, 0 from landed where last_status between 200 and 299
    ) c
    where page_key not in (select page_key from broken)
    group by page_key
  ),
  candidate_words as (
    select distinct c.page_key, regexp_replace(w.word, '^(.{3,})s$', '\1') as word
    from candidates c
    cross join lateral regexp_split_to_table(c.page_key, '[^[:alnum:]]+') as w(word)
    where length(w.word) >= 2
  ),
  broken_words as (
    select distinct b.page_key, regexp_replace(w.word, '^(.{3,})s$', '\1') as word
    from broken b
    cross join lateral regexp_split_to_table(b.page_key, '[^[:alnum:]]+') as w(word)
    where length(w.word) >= 2
  ),
  candidate_sizes as (select page_key, count(*) as words from candidate_words group by 1),
  broken_sizes as (select page_key, count(*) as words from broken_words group by 1),
  similar_pages as (
    select distinct on (page_key) page_key, target
    from (
      select
        bw.page_key,
        c.page as target,
        c.weight,
        count(*)::numeric / (bs.words + cs.words - count(*)) as overlap
      from broken_words bw
      join candidate_words cw on cw.word = bw.word
      join candidates c on c.page_key = cw.page_key
      join broken_sizes bs on bs.page_key = bw.page_key
      join candidate_sizes cs on cs.page_key = cw.page_key
      group by bw.page_key, c.page_key, c.page, c.weight, bs.words, cs.words
    ) m
    where overlap >= 0.5
    order by page_key, overlap desc, weight desc, length(target), target
  ),
  parent_pages as (
    select distinct on (b.page_key) b.page_key, c.page as target
    from broken b
    join candidates c
      on c.page_key <> '/'
     and left(b.page_key, length(c.page_key) + 1) = c.page_key || '/'
    order by b.page_key, length(c.page_key) desc
  ),
  result_rows as (
    select
      v.page,
      v.visits,
      v.last_visit,
      b.status,
      coalesce(p.platforms, '{}'::text[]) as platforms,
      coalesce(ci.citations, 0)::bigint as citations,
      -- A route on the page (every missing address has a query) gets no
      -- redirect: one from its path would move the whole route.
      case when v.page_key <> '/' and not b.routed then coalesce(s.target, pa.target, '/') end
        as target,
      case
        when v.page_key = '/' then null
        when b.routed then 'query'
        when s.target is not null then 'similar'
        when pa.target is not null then 'parent'
        else 'home'
      end as target_reason
    from visits v
    join broken b on b.page_key = v.page_key
    left join platforms p on p.page_key = v.page_key
    left join cited ci on ci.page_key = v.page_key
    left join similar_pages s on s.page_key = v.page_key
    left join parent_pages pa on pa.page_key = v.page_key
  )
  select jsonb_build_object(
    'count', (select count(*) from result_rows),
    'rows', coalesce((
      select jsonb_agg(to_jsonb(r))
      from (
        select * from result_rows
        order by visits desc, citations desc, last_visit desc, page
        limit greatest(p_limit, 0) offset greatest(p_offset, 0)
      ) r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer)
  from public, anon;
grant execute on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer)
  to authenticated, service_role;

comment on function public.ai_traffic_broken_links(uuid, timestamptz, timestamptz, integer, integer) is
  'AI Traffic "Broken AI links" (AT-012, spec §3.5): the pages AI-referred visitors landed on that answered 404 or 410 (or, without a status, whose title said not found) in a window, with their visits, platforms, citations and a suggested redirect to a working page (similar path, parent page or home; none for a route on the page, target_reason query). Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00201_gsc_pages_backfill_from.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00201: the Search Console page backfill resumes where it stopped
-- ============================================================================
-- Follow-up from #1177's review (AT-008). The page sync read the property's
-- 190 days again on every run until one got through them all
-- (gsc_pages_backfilled_property, 00181), so a window that kept failing made
-- every daily run read the whole history again. It now reads a week at a
-- time (gscSync.js), and keeps how far back the backfill has read:
--
--   * gsc_pages_backfilled_property: the property the brand's page rows
--     belong to. Set once its last 28 days are read, and when it names
--     another property, that one's page rows are dropped first.
--   * gsc_pages_backfill_from: the oldest day the property's backfill has
--     read so far, while it hasn't reached its 190 days; null once it has.
--     A sync cut short resumes the day after.
--
-- A brand backfilled before this column (property set, this null) reads as
-- done, as it was.

alter table public.brands
    add column if not exists gsc_pages_backfill_from date;

comment on column public.brands.gsc_pages_backfill_from is
  'AI Traffic (AT-008): the oldest day the Search Console page backfill for gsc_pages_backfilled_property has read while it hasn''t reached its 190 days; null once it has (gscSync.js).';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00202_getting_started_steps_update_using.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00202: only admins and managers change a step that isn't just opened
-- ============================================================================
-- Follow-up from #1234's review. 00196's update policy on
-- getting_started_steps checked the new row (`with check`: any member may
-- write `opened`, only an admin or a manager `skipped` or `done`), but not
-- the row being changed (`using`). So through PostgREST any member could
-- turn a skipped or done step back into opened. The app never does: the
-- page RPC inserts with `on conflict do nothing`, and skipping or saving the
-- KPIs is an admin's or a manager's.
--
-- `using` now also needs the row to be opened, or the user to be an admin or
-- a manager. The rest of the policy is 00196's.

drop policy if exists "getting_started_steps: member update" on public.getting_started_steps;

create policy "getting_started_steps: member update"
  on public.getting_started_steps
  for update
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and (
      state = 'opened'
      or exists (
        select 1 from public.profiles p
        where p.id = auth.uid()
          and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
      )
    )
  )
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and (
      state = 'opened'
      or exists (
        select 1 from public.profiles p
        where p.id = auth.uid()
          and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
      )
    )
  );

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00203_citation_gap_rollups.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00203: Competitor Gaps from the daily rollups (#1002)
-- ============================================================================
-- The Citations page's Domains and URLs tabs read daily rollups since 00118,
-- but the Gaps tab still ran citation_gap_domains and
-- citation_competitor_sources (00111) on every load. Both scan every answer
-- in the window and every citation of those answers, and unpack
-- competitor_mentions. On the largest brand a 30-day window took 69 s, far
-- past the authenticated role's 8 s statement timeout, so the tab failed.
--
-- The existing rollups can't answer these reads, because the measures are
-- per answer:
--   * present: the brand is mentioned, or one of its domains is cited in the
--     same answer;
--   * gap: a competitor is mentioned and the brand isn't present;
--   * weight: each answer splits 1 between the distinct domains it cites.
--
-- refresh_citations_daily now writes them too, at the same grain as
-- citation_domain_daily (day, model_used, platform, region, topic_id):
--   * citation_result_daily.present_answers, next to answers, for
--     our_answer_count;
--   * citation_gap_domain_daily, per domain: gap answers, their weight, and
--     present answers (appears_in_ours);
--   * citation_gap_competitor_daily, per (domain, competitor): the answers
--     mentioning the competitor that cite the domain and their weight (for
--     citation_competitor_sources), and how many of them are gap answers
--     (for competitor_names).
-- All three are written from one pass over the day range's answers and
-- citations.
--
-- Kept at read time, as the raw functions do:
--   * tagging a domain as the brand's or a competitor's, against the lists
--     the page sends, so a change to either is a filter;
--   * competitor names, from the live competitors table, falling back to the
--     name in the answer when the competitor is gone.
--
-- Whether the brand is present depends on its own domains when the rows are
-- written. A change to brand_domains therefore queues the brand in
-- citation_rollup_rebuilds, as a topic move does (00118), and the server's
-- rebuild drain (every five minutes) recomputes its history.
--
-- A single-prompt filter stays on the raw functions, as on the other tabs.
--
-- Rollout: apply, run `node src/scripts/backfillCitationsDaily.js` so the
-- history gets the new columns and rows, then deploy the web.

-- ─── Tables ─────────────────────────────────────────────────────────────────

alter table public.citation_result_daily
  add column if not exists present_answers integer not null default 0;

comment on column public.citation_result_daily.present_answers is
  'Answers where the brand is present: mentioned, or one of its brand_domains cited (#1002).';

create table if not exists public.citation_gap_domain_daily (
  brand_id        uuid not null references public.brands(id) on delete cascade,
  day             date not null,
  model_used      text,
  platform        text,
  region          text,
  topic_id        uuid,
  domain          text not null,
  -- Answers citing the domain where a competitor is mentioned and the brand
  -- isn't present.
  gap_answers     integer not null,
  -- The same answers' weight: each answer's 1 split between its domains.
  gap_strength    double precision not null,
  -- Answers citing the domain where the brand is present.
  present_answers integer not null
);

create index if not exists idx_citation_gap_domain_daily_brand_day
  on public.citation_gap_domain_daily (brand_id, day);

create unique index if not exists citation_gap_domain_daily_key
  on public.citation_gap_domain_daily (brand_id, day, model_used, platform, region, topic_id, domain)
  nulls not distinct;

create table if not exists public.citation_gap_competitor_daily (
  brand_id        uuid not null references public.brands(id) on delete cascade,
  day             date not null,
  model_used      text,
  platform        text,
  region          text,
  topic_id        uuid,
  domain          text not null,
  -- competitor_mentions[].competitor_id; text, as the answers carry it.
  competitor_id   text,
  -- The name the answer gave, for a competitor no longer in competitors.
  competitor_name text not null,
  -- Answers mentioning the competitor that cite the domain, and their weight.
  answers         integer not null,
  strength        double precision not null,
  -- Of those, the answers where the brand isn't present.
  gap_answers     integer not null
);

create index if not exists idx_citation_gap_competitor_daily_brand_day
  on public.citation_gap_competitor_daily (brand_id, day);

create unique index if not exists citation_gap_competitor_daily_key
  on public.citation_gap_competitor_daily
     (brand_id, day, model_used, platform, region, topic_id, domain, competitor_id)
  nulls not distinct;

-- ─── RLS, as the other citation rollups ─────────────────────────────────────

alter table public.citation_gap_domain_daily enable row level security;
alter table public.citation_gap_competitor_daily enable row level security;

drop policy if exists "Users can read own org citation gap domain rollups"
  on public.citation_gap_domain_daily;
create policy "Users can read own org citation gap domain rollups"
  on public.citation_gap_domain_daily for select
  using (brand_id in (
    select b.id from public.brands b
    join public.profiles p on p.organization_id = b.organization_id
    where p.id = auth.uid()));

drop policy if exists "Users can read own org citation gap competitor rollups"
  on public.citation_gap_competitor_daily;
create policy "Users can read own org citation gap competitor rollups"
  on public.citation_gap_competitor_daily for select
  using (brand_id in (
    select b.id from public.brands b
    join public.profiles p on p.organization_id = b.organization_id
    where p.id = auth.uid()));

-- ─── Refresh ────────────────────────────────────────────────────────────────
-- 00199's body, plus the gap rows. citation_result_daily's insert moves into
-- the gap pass, which already has each answer's bucket and presence.

create or replace function public.refresh_citations_daily(
  p_brand_id uuid,
  p_day_from date,
  p_day_to date
) returns void
language plpgsql
set search_path to 'public'
set work_mem to '256MB'
as $$
declare
  ts_from timestamptz := p_day_from::timestamp at time zone 'utc';
  ts_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
  v_brand_domains text[];
begin
  -- One refresh per brand at a time (00199); the lock releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_citations_daily:' || p_brand_id::text, 0));

  delete from public.citation_result_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_domain_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_url_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_gap_domain_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;
  delete from public.citation_gap_competitor_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;

  -- The brand's own domains as the page sends them (normalizeDomain in
  -- frontend/src/lib/citations/classify.ts): lower case, no scheme, no www.
  select coalesce(array_agg(distinct x.d) filter (where x.d is not null and x.d <> ''), '{}')
    into v_brand_domains
  from (
    select substring(lower(trim(bd.domain)) from '^(?:[a-z][a-z0-9+.-]*://)?(?:www\.)?([^/?#\s:]+)') as d
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ) x;

  with ans as materialized (
    select pr.id as rid,
           (pr.created_at at time zone 'utc')::date as day,
           pr.model_used, pr.platform, pr.region, p.topic_id,
           coalesce(pr.mention_count, 0) > 0 as we_mention,
           coalesce(
             jsonb_path_exists(pr.competitor_mentions, '$[*] ? (@.mention_count > 0)'),
             false
           ) as comp_present,
           pr.competitor_mentions
    from public.prompt_results pr
    left join public.prompts p on p.id = pr.prompt_id
    where pr.brand_id = p_brand_id
      and pr.platform <> 'chatgpt-shopping'  -- #155 — isolate from analytics
      and pr.created_at >= ts_from and pr.created_at < ts_to
  ),
  -- The distinct domains each answer cites. A citation row carries its
  -- answer's created_at, so the citation index bounds the scan.
  adom as materialized (
    select distinct c.prompt_result_id as rid, cu.domain as d
    from public.prompt_result_citations c
    join public.citation_urls cu on cu.id = c.url_id
    where c.brand_id = p_brand_id
      and c.created_at >= ts_from and c.created_at < ts_to
  ),
  dtags as materialized (
    select s.d,
           exists (select 1 from unnest(v_brand_domains) e
                   where s.d = e or right(s.d, length(e) + 1) = '.' || e) as is_you
    from (select distinct d from adom) s
  ),
  per_answer as (
    select ad.rid, count(*) as n, bool_or(t.is_you) as you_cited
    from adom ad join dtags t on t.d = ad.d
    group by ad.rid
  ),
  flags as materialized (
    select a.rid, a.day, a.model_used, a.platform, a.region, a.topic_id,
           a.comp_present, a.competitor_mentions,
           a.we_mention or coalesce(pa.you_cited, false) as present,
           a.comp_present and not (a.we_mention or coalesce(pa.you_cited, false)) as gap,
           coalesce(1.0 / pa.n, 0)::float8 as w
    from ans a
    left join per_answer pa on pa.rid = a.rid
  ),
  ins_result as (
    insert into public.citation_result_daily (
      brand_id, day, model_used, platform, region, topic_id, answers, present_answers)
    select p_brand_id, f.day, f.model_used, f.platform, f.region, f.topic_id,
           count(*), count(*) filter (where f.present)
    from flags f
    group by f.day, f.model_used, f.platform, f.region, f.topic_id
  ),
  ins_gap_domain as (
    insert into public.citation_gap_domain_daily (
      brand_id, day, model_used, platform, region, topic_id, domain,
      gap_answers, gap_strength, present_answers)
    select p_brand_id, f.day, f.model_used, f.platform, f.region, f.topic_id, ad.d,
           count(*) filter (where f.gap),
           coalesce(sum(f.w) filter (where f.gap), 0),
           count(*) filter (where f.present)
    from adom ad
    join flags f on f.rid = ad.rid
    group by f.day, f.model_used, f.platform, f.region, f.topic_id, ad.d
    having count(*) filter (where f.gap or f.present) > 0
  ),
  mentions as (
    select f.rid, f.day, f.model_used, f.platform, f.region, f.topic_id, f.gap, f.w,
           x.e ->> 'competitor_id' as competitor_id,
           coalesce(nullif(trim(x.e ->> 'name'), ''), 'Competitor') as competitor_name
    from flags f
    cross join lateral jsonb_array_elements(f.competitor_mentions) x(e)
    where f.comp_present
      and coalesce((x.e ->> 'mention_count')::numeric, 0) > 0
  )
  insert into public.citation_gap_competitor_daily (
    brand_id, day, model_used, platform, region, topic_id, domain,
    competitor_id, competitor_name, answers, strength, gap_answers)
  select p_brand_id, m.day, m.model_used, m.platform, m.region, m.topic_id, ad.d,
         m.competitor_id, max(m.competitor_name),
         count(distinct m.rid), sum(m.w),
         count(distinct m.rid) filter (where m.gap)
  from mentions m
  join adom ad on ad.rid = m.rid
  group by m.day, m.model_used, m.platform, m.region, m.topic_id, ad.d, m.competitor_id;

  insert into public.citation_domain_daily (
    brand_id, day, model_used, platform, region, topic_id, domain, citations, results)
  select p_brand_id,
         (pr.created_at at time zone 'utc')::date,
         pr.model_used, pr.platform, pr.region, p.topic_id, cu.domain,
         count(*),
         count(distinct c.prompt_result_id)
  from public.prompt_result_citations c
  join public.prompt_results pr on pr.id = c.prompt_result_id
  left join public.prompts p on p.id = pr.prompt_id
  join public.citation_urls cu on cu.id = c.url_id
  where c.brand_id = p_brand_id
    and c.created_at >= ts_from and c.created_at < ts_to
    and pr.platform <> 'chatgpt-shopping'
  group by 2, pr.model_used, pr.platform, pr.region, p.topic_id, cu.domain;

  insert into public.citation_url_daily (
    brand_id, day, model_used, platform, region, topic_id, url_id, citations, results)
  select p_brand_id,
         (pr.created_at at time zone 'utc')::date,
         pr.model_used, pr.platform, pr.region, p.topic_id, c.url_id,
         count(*),
         count(distinct c.prompt_result_id)
  from public.prompt_result_citations c
  join public.prompt_results pr on pr.id = c.prompt_result_id
  left join public.prompts p on p.id = pr.prompt_id
  where c.brand_id = p_brand_id
    and c.created_at >= ts_from and c.created_at < ts_to
    and pr.platform <> 'chatgpt-shopping'
  group by 2, pr.model_used, pr.platform, pr.region, p.topic_id, c.url_id;
end;
$$;

revoke execute on function public.refresh_citations_daily(uuid, date, date)
  from public, anon, authenticated;

-- ─── A brand domain change queues a rebuild ─────────────────────────────────

create or replace function public.queue_citation_rollup_rebuild_on_domains()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_brands uuid[];
begin
  if tg_op = 'INSERT' then
    v_brands := array[new.brand_id];
  elsif tg_op = 'DELETE' then
    v_brands := array[old.brand_id];
  elsif new.domain is not distinct from old.domain and new.brand_id = old.brand_id then
    return null;
  else
    v_brands := array[old.brand_id, new.brand_id];
  end if;
  -- Only for a brand that still exists: a brand delete removes the brand
  -- before its domains, so the cascade queues nothing.
  insert into public.citation_rollup_rebuilds (brand_id)
  select b.id from public.brands b where b.id = any(v_brands)
  on conflict (brand_id) do update set requested_at = now();
  return null;
end;
$$;

revoke execute on function public.queue_citation_rollup_rebuild_on_domains()
  from public, anon, authenticated;

drop trigger if exists brand_domains_queue_citation_rollup_rebuild on public.brand_domains;
create trigger brand_domains_queue_citation_rollup_rebuild
  after insert or update or delete on public.brand_domains
  for each row execute function public.queue_citation_rollup_rebuild_on_domains();

-- ─── Reads ──────────────────────────────────────────────────────────────────
-- Same rows as the raw functions for whole-day windows. Security definer with
-- the organization check made explicit (00119), and plpgsql with
-- force_custom_plan so each call is planned for its own brand and window.

create or replace function public.citation_gap_domains_daily(
  p_brand_id uuid,
  p_brand_domains text[],
  p_competitor_domains text[],
  p_day_from date default null,
  p_day_to date default null,
  p_models text[] default null,
  p_regions text[] default null,
  p_topic_ids uuid[] default null
)
returns table (
  domain text,
  competitor_answers bigint,
  appears_in_ours boolean,
  strength double precision,
  competitor_names text[],
  our_answer_count bigint,
  total_answers bigint
)
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
#variable_conflict use_column
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  with g as (
    select d.domain as dm,
           sum(d.gap_answers)::bigint as ga,
           sum(d.gap_strength) as gs,
           sum(d.present_answers)::bigint as pa
    from public.citation_gap_domain_daily d
    where d.brand_id = p_brand_id
      and (p_day_from  is null or d.day >= p_day_from)
      and (p_day_to    is null or d.day <= p_day_to)
      and (p_models    is null or d.model_used = any(p_models))
      and (p_regions   is null or d.region = any(p_regions))
      and (p_topic_ids is null or d.topic_id = any(p_topic_ids))
    group by d.domain
  ),
  -- Third-party domains only: neither the brand's nor a competitor's.
  third_party as (
    select g.* from g
    where not exists (select 1 from unnest(p_brand_domains) e
                      where g.dm = e or right(g.dm, length(e) + 1) = '.' || e)
      and not exists (select 1 from unnest(p_competitor_domains) e
                      where g.dm = e or right(g.dm, length(e) + 1) = '.' || e)
  ),
  -- The competitors mentioned in the gap answers citing each domain.
  names as (
    select n.dm, array_agg(distinct n.cname order by n.cname) as names
    from (
      select c.domain as dm,
             case when co.id is not null
                  then coalesce(nullif(trim(co.name), ''), 'Competitor')
                  else c.competitor_name
             end as cname
      from public.citation_gap_competitor_daily c
      left join public.competitors co
        on co.brand_id = p_brand_id and co.id::text = c.competitor_id
      where c.brand_id = p_brand_id
        and c.gap_answers > 0
        and (p_day_from  is null or c.day >= p_day_from)
        and (p_day_to    is null or c.day <= p_day_to)
        and (p_models    is null or c.model_used = any(p_models))
        and (p_regions   is null or c.region = any(p_regions))
        and (p_topic_ids is null or c.topic_id = any(p_topic_ids))
    ) n
    group by n.dm
  ),
  totals as (
    select coalesce(sum(r.answers), 0)::bigint as total_answers,
           coalesce(sum(r.present_answers), 0)::bigint as our_answer_count
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and (p_day_from  is null or r.day >= p_day_from)
      and (p_day_to    is null or r.day <= p_day_to)
      and (p_models    is null or r.model_used = any(p_models))
      and (p_regions   is null or r.region = any(p_regions))
      and (p_topic_ids is null or r.topic_id = any(p_topic_ids))
  )
  select t.dm, t.ga, t.pa > 0, coalesce(t.gs, 0)::float8,
         coalesce(n.names, '{}'::text[]), tt.our_answer_count, tt.total_answers
  from third_party t
  left join names n on n.dm = t.dm
  cross join totals tt
  where t.ga > 0 or t.pa > 0
  union all
  select null, 0::bigint, false, 0::float8, '{}'::text[], tt.our_answer_count, tt.total_answers
  from totals tt;
end;
$$;

create or replace function public.citation_competitor_sources_daily(
  p_brand_id uuid,
  p_brand_domains text[],
  p_competitor_domains text[],
  p_day_from date default null,
  p_day_to date default null,
  p_models text[] default null,
  p_regions text[] default null,
  p_topic_ids uuid[] default null
)
returns table (
  competitor_id text,
  domain text,
  answers_feeding bigint,
  strength double precision
)
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
#variable_conflict use_column
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  with agg as materialized (
    select c.competitor_id as cid, c.domain as dm,
           sum(c.answers)::bigint as af,
           sum(c.strength)::float8 as st
    from public.citation_gap_competitor_daily c
    where c.brand_id = p_brand_id
      and (p_day_from  is null or c.day >= p_day_from)
      and (p_day_to    is null or c.day <= p_day_to)
      and (p_models    is null or c.model_used = any(p_models))
      and (p_regions   is null or c.region = any(p_regions))
      and (p_topic_ids is null or c.topic_id = any(p_topic_ids))
    group by c.competitor_id, c.domain
  ),
  -- Third-party domains only, tagged once per domain.
  third_party as (
    select s.dm
    from (select distinct dm from agg) s
    where not exists (select 1 from unnest(p_brand_domains) e
                      where s.dm = e or right(s.dm, length(e) + 1) = '.' || e)
      and not exists (select 1 from unnest(p_competitor_domains) e
                      where s.dm = e or right(s.dm, length(e) + 1) = '.' || e)
  )
  select a.cid, a.dm, a.af, a.st
  from agg a
  join third_party t on t.dm = a.dm;
end;
$$;

revoke all on function public.citation_gap_domains_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) from public, anon;
grant execute on function public.citation_gap_domains_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) to authenticated, service_role;

revoke all on function public.citation_competitor_sources_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) from public, anon;
grant execute on function public.citation_competitor_sources_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) to authenticated, service_role;

comment on function public.citation_gap_domains_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) is
  'Competitor Gaps (#1002): citation_gap_domains over whole UTC days, from the daily rollups. Third-party domains with their gap answers, strength, whether they appear in an answer where the brand is present, and the competitors in those gap answers; plus a null-domain row with the window''s totals. Security definer with an organization check.';

comment on function public.citation_competitor_sources_daily(
  uuid, text[], text[], date, date, text[], text[], uuid[]) is
  'Competitor Gaps (#1002): citation_competitor_sources over whole UTC days, from the daily rollups. Per competitor, the third-party domains cited in answers that mention it, with the answer count and weight. Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00204_content_drafts.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00204: content drafts, the Content Library's rows (Content Editor, CE-002)
-- ============================================================================
-- The Content area writes and improves pages in GetCito (Content Editor spec
-- v2). Every page someone, or an agent, writes or changes there is a draft:
-- the Library lists them, the editor opens one.
--
--   * method: create (a new page) or optimize (an existing page).
--   * status: draft → in_review (an agent's draft waiting for a person) →
--     ready (Mark ready) → published (the person gives the live URL).
--     GetCito never publishes on its own.
--   * page_type: a key from the web's page type list (feature_page,
--     product_page, destination_page…). Not an enum: a new page type must not
--     take a migration.
--   * author: who wrote it, a person or the Content Agent. created_by is the
--     person who started it (null for an agent's draft).
--   * score_before / score_after: the page's AEO score before and after the
--     changes, once scoring runs (null until then).
--
-- Any member of the brand's organization reads and writes drafts, as with
-- reports and site audits: writing content is the team's daily work, not a
-- setting. No delete policy: nothing in the app deletes a draft yet.

create table if not exists public.content_drafts (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  title text not null default '' check (char_length(title) <= 300),
  page_type text check (page_type ~ '^[a-z_]{1,40}$'),
  method text not null default 'create' check (method in ('create', 'optimize')),
  status text not null default 'draft'
    check (status in ('draft', 'in_review', 'ready', 'published')),
  body_html text not null default '',
  author text not null default 'user' check (author in ('user', 'agent')),
  created_by uuid references public.profiles(id) on delete set null,
  score_before smallint check (score_before between 0 and 100),
  score_after smallint check (score_after between 0 and 100),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.content_drafts is
  'Content Editor (CE-002): pages written or changed in GetCito by a person or the Content Agent. The Content Library lists them.';

create index if not exists content_drafts_brand_updated_idx
  on public.content_drafts (brand_id, updated_at desc);

create or replace trigger content_drafts_updated_at
  before update on public.content_drafts
  for each row execute function public.handle_updated_at();

-- Who wrote a draft, its brand and its scores are the server's to set (the
-- Content Agent, scoring), as with guard_organization_server_columns (00062):
-- a member can't pass their draft off as the agent's, or score it.
create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace trigger content_drafts_guard_server_columns
  before insert or update on public.content_drafts
  for each row execute function public.guard_content_draft_server_columns();

alter table public.content_drafts enable row level security;

create policy "content_drafts: member select"
  on public.content_drafts
  for select
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

-- A person's own draft: the app writes created_by = the signed-in user, and
-- an agent's draft comes through the service role, which RLS doesn't apply to.
create policy "content_drafts: member insert"
  on public.content_drafts
  for insert
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and author = 'user'
    and created_by = auth.uid()
  );

-- The row being changed and the row it becomes both stay in the member's
-- organization, so an update can't move a draft to another brand's.
create policy "content_drafts: member update"
  on public.content_drafts
  for update
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  )
  with check (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00205_content_page_types.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00205: the brand's site type, and where a draft's page type comes from
--        (Content Editor, CE-023)
-- ============================================================================
-- Page types depend on the kind of site (Content Editor spec v2 §4): a B2B
-- SaaS site writes feature, comparison and pricing pages, a shop product and
-- category pages, a B2C site destination and help pages.
--
--   * brands.site_type: b2b, ecommerce or b2c, set in the brand's settings.
--     Null until someone chooses; until then the app guesses it from the
--     industry and Shopping mode. Updated under the brands policies, as the
--     industry is (admins and managers).
--   * content_drafts.page_type_source: 'detected' while the app keeps
--     page_type in step with the page (its URL, schema and title), 'user'
--     once a person picks the type. A picked type is never detected over.
--     New drafts start detected.

alter table public.brands
  add column if not exists site_type text
    check (site_type in ('b2b', 'ecommerce', 'b2c'));

comment on column public.brands.site_type is
  'Content Editor (CE-023): b2b, ecommerce or b2c; sets the page types the editor offers. Null = guessed from industry and shopping_mode_enabled.';

alter table public.content_drafts
  add column if not exists page_type_source text not null default 'detected'
    check (page_type_source in ('detected', 'user'));

comment on column public.content_drafts.page_type_source is
  'Content Editor (CE-023): detected = page_type follows the page as it changes; user = a person picked it.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00206_content_draft_start.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00206: what a draft was started for (Content Editor, CE-003 / CE-015)
-- ============================================================================
-- New content starts a draft from an opportunity, a tracked prompt or a
-- topic, or from content to optimize (Content Editor spec v2 §5, §9). The
-- draft keeps what it is for:
--
--   * opportunity_id: the Content Opportunity it was started from, if any.
--   * prompt_ids: the tracked prompts the page should answer: the
--     opportunity's, the one prompt picked, or a topic's active prompts. The
--     overlap check, Impact and the brief read them.
--
-- Both must belong to the draft's brand: a check trigger turns away another
-- brand's opportunity or prompts, which the foreign key alone would accept.
-- It checks only the prompt ids a write adds, and a deleted prompt leaves
-- every draft's prompt_ids (it has no foreign key to do that), so a draft
-- that had one can still take more.

alter table public.content_drafts
  add column if not exists opportunity_id uuid
    references public.content_opportunities(id) on delete set null,
  add column if not exists prompt_ids uuid[] not null default '{}'
    check (cardinality(prompt_ids) <= 500);

comment on column public.content_drafts.opportunity_id is
  'Content Editor (CE-003): the Content Opportunity the draft was started from.';
comment on column public.content_drafts.prompt_ids is
  'Content Editor (CE-003): the tracked prompts the page should answer.';

create index if not exists content_drafts_opportunity_idx
  on public.content_drafts (opportunity_id)
  where opportunity_id is not null;

-- Runs as the writer: a member sees only their organization's opportunities
-- and prompts, so another brand's ids read as missing and are refused.
create or replace function public.check_content_draft_links()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.opportunity_id is not null
     and (tg_op = 'INSERT' or new.opportunity_id is distinct from old.opportunity_id)
     and not exists (
       select 1
       from public.content_opportunities o
       where o.id = new.opportunity_id and o.brand_id = new.brand_id
     )
  then
    raise exception 'content draft opportunity belongs to another brand'
      using errcode = '23514';
  end if;

  if cardinality(new.prompt_ids) > 0
     and (tg_op = 'INSERT' or new.prompt_ids is distinct from old.prompt_ids)
     and exists (
       select 1
       from unnest(new.prompt_ids) as wanted(id)
       -- Only what this write adds: the ids already there were checked.
       where wanted.id <> all(case when tg_op = 'UPDATE' then old.prompt_ids else '{}' end)
         and not exists (
           select 1
           from public.prompts p
           join public.prompt_sets s on s.id = p.prompt_set_id
           where p.id = wanted.id and s.brand_id = new.brand_id
         )
     )
  then
    raise exception 'content draft prompt belongs to another brand'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create or replace trigger content_drafts_check_links
  before insert or update on public.content_drafts
  for each row execute function public.check_content_draft_links();

-- A deleted prompt leaves the drafts that had it, in one update per delete
-- statement (a topic's prompts go together). Definer: the drafts may be ones
-- the deleting member can't write, and the deletion is theirs to make.
create or replace function public.forget_deleted_draft_prompts()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_gone uuid[];
begin
  select coalesce(array_agg(id), '{}') into v_gone from deleted_prompts;
  update public.content_drafts d
  set prompt_ids = array(select x from unnest(d.prompt_ids) as x where x <> all(v_gone))
  where d.prompt_ids && v_gone;
  return null;
end;
$$;

revoke execute on function public.forget_deleted_draft_prompts() from public, anon, authenticated;

create or replace trigger prompts_forget_in_content_drafts
  after delete on public.prompts
  referencing old table as deleted_prompts
  for each statement execute function public.forget_deleted_draft_prompts();

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00207_content_page_overlap.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00207: the overlap check before a page is written (Content Editor, CE-015)
-- ============================================================================
-- Start checks for overlap before anything is written (Content Editor spec v2
-- §5): which of the brand's own pages AI already cites for the prompts the
-- new page should answer, how many of those prompts each one answers, how
-- often it is cited, and where it ranks on Google. One page that already
-- answers most of them is better optimized than competed with.
--
--   * content_page_overlap(brand, prompt ids): the brand's pages cited in
--     tracked answers to those prompts since p_since (30 days by default),
--     one row per page (lower(normalize_page_path) key): prompts in common,
--     citations, and the impression-weighted Google position over the last
--     28 days of Search Console data, when there is some. Most prompts in
--     common first. Security definer with an organization check, as
--     ai_traffic_page_citations (00176): citation_urls has no member select
--     policy. Read through citation_urls' domain index first, as
--     ga_page_ai_visibility does. The window's answers to the prompts come
--     from idx_prompt_results_brand_created_cover alone (an index-only scan,
--     hash-joined), never from prompt_results' wide rows one citation at a
--     time; ChatGPT Shopping is left out, as in Impact (00209). Planned for
--     each call's own values (plan_cache_mode): a generic plan of these
--     estimates is far slower.
--   * content_drafts.source_url: the existing page a draft optimizes, when
--     there is one (Start's "Optimize … instead"); the editor shows it beside
--     the page type.

alter table public.content_drafts
  add column if not exists source_url text
    check (
      source_url is null
      or (char_length(source_url) <= 2048 and source_url ~* '^https?://')
    );

comment on column public.content_drafts.source_url is
  'Content Editor (CE-015): the existing page this draft optimizes.';

create or replace function public.content_page_overlap(
  p_brand_id uuid,
  p_prompt_ids uuid[],
  p_since timestamptz default now() - interval '30 days'
)
returns table (
  page text,
  title text,
  prompts_in_common integer,
  citations bigint,
  gsc_position numeric
)
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return;
  end if;
  if coalesce(cardinality(p_prompt_ids), 0) = 0 then
    return;
  end if;

  return query
  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  -- The window's answers to these prompts, from the (brand_id, created_at)
  -- cover index alone.
  answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= p_since
      and pr.prompt_id = any(p_prompt_ids)
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  cited as (
    select ou.page_key, ou.url, ou.title, a.prompt_id
    from public.prompt_result_citations prc
    join answers a on a.id = prc.prompt_result_id
    join own_urls ou on ou.id = prc.url_id
    where prc.brand_id = p_brand_id
      and prc.created_at >= p_since
  ),
  pages as (
    select
      c.page_key,
      -- The address cited most often stands for the page.
      mode() within group (order by c.url) as page,
      max(c.title) as title,
      count(distinct c.prompt_id)::integer as prompts_in_common,
      count(*)::bigint as citations
    from cited c
    group by c.page_key
  ),
  google as (
    select
      g.page_key,
      round((sum(g.position * g.impressions) / nullif(sum(g.impressions), 0))::numeric, 1)
        as position
    from public.gsc_page_stats g
    where g.brand_id = p_brand_id
      and g.date >= (now() at time zone 'utc')::date - 28
      and g.page_key in (select p.page_key from pages p)
    group by g.page_key
  )
  select p.page, p.title, p.prompts_in_common, p.citations, gl.position
  from pages p
  left join google gl on gl.page_key = p.page_key
  order by p.prompts_in_common desc, p.citations desc, p.page
  limit 10;
end;
$$;

revoke all on function public.content_page_overlap(uuid, uuid[], timestamptz) from public, anon;
grant execute on function public.content_page_overlap(uuid, uuid[], timestamptz)
  to authenticated, service_role;

comment on function public.content_page_overlap(uuid, uuid[], timestamptz) is
  'Content Editor (CE-015): the brand''s own pages cited for these prompts since p_since, with prompts in common, citations and Google position, for Start''s overlap check. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00208_content_draft_action.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00208: a draft sent to the Action Center (Content Editor, CE-015)
-- ============================================================================
-- Start asks who does the page (Content Editor spec v2 §5): Me opens the
-- editor; Team sends it to the Action Center as an action (§15), for someone
-- on the team to write. The draft keeps the action it was sent as:
--
--   * content_drafts.action_id: the action, set by the server when it
--     creates it (fromContentDraft.js). Like the draft's author and
--     scores, it is the server's to write: guard_content_draft_server_columns
--     (00204) is redefined to keep members from setting or changing it, so a
--     draft can't claim another action.

alter table public.content_drafts
  add column if not exists action_id uuid references public.actions(id) on delete set null;

comment on column public.content_drafts.action_id is
  'Content Editor (CE-015): the Action Center action the draft was sent as (Start › Team). Server-set.';

create index if not exists content_drafts_action_idx
  on public.content_drafts (action_id)
  where action_id is not null;

create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
    if new.action_id is not null then
      raise exception 'content draft action is set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
     or new.action_id is distinct from old.action_id
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00209_content_page_impact.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00209: what a page earns, for the editor's Impact tab (Content Editor, CE-016)
-- ============================================================================
-- The Impact tab (Content Editor spec v2 §7) shows, for the page a draft
-- optimizes, the last N days against the N days before: citations, AI
-- visits, Google clicks and the prompts that cite it, with the ones it lost.
--
-- content_page_impact(brand, page, days) returns one jsonb:
--   * citations {cur, prev}: tracked answers citing the page, on the brand's
--     own domains (citation_urls' domain index first, as ga_page_ai_visibility
--     does); ChatGPT Shopping cards left out, as the Citations page does;
--   * aiVisits {cur, prev}: AI-referred visits, by ai_traffic_merged's (00176)
--     rule: the snippet on days it was active for the brand, Google Analytics
--     on other days, never both;
--   * gscClicks {cur, prev} and gscSince, the first day of Search Console page
--     data the brand has (null without any): page stats are kept 190 days, so
--     a window starting earlier is incomplete and the caller says so;
--   * promptCounts {cur, prev, lost}: prompts citing the page in each window,
--     and the ones it lost (cited before, not now), counted over all of them;
--   * prompts: each prompt that cited the page in either window, with its
--     citations and platforms in each, the most cited first (at most 100, to
--     list: the counts don't come from it);
--   * overlap: the brand's other pages cited in this window for the prompts
--     citing this one, with how many of them (at most 3): pages competing
--     with it for the same answers.
-- A page is one lower(normalize_page_path) key, so /x/ and /x?utm_source=…
-- are one page. Windows are whole UTC days ending yesterday: today's partial
-- day would read as a drop against whole ones.
--
-- Both windows' answers come from idx_prompt_results_brand_created_cover
-- alone (brand_id, created_at, with id, platform and prompt_id included),
-- materialized and hash-joined, never from prompt_results' wide rows one
-- citation at a time. The brand's other pages are found from the prompts
-- citing this one outward. Planned for each call's own values
-- (plan_cache_mode): after five calls plpgsql would switch to a generic plan,
-- many times slower here.
--
-- Security definer with an organization check, as ai_traffic_page_citations
-- (00176): citation_urls has no member select policy.

create or replace function public.content_page_impact(
  p_brand_id uuid,
  p_page text,
  p_days integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_key text := lower(public.normalize_page_path(p_page));
  -- The last whole day.
  v_last_day date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_prev timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 366 or p_page is null then
    raise exception 'content_page_impact: a page and 1 to 366 days are needed'
      using errcode = '22023';
  end if;

  v_cur_day := v_last_day - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_prev := v_prev_day::timestamp at time zone 'utc';
  v_until := (v_last_day + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_all as materialized (
    select cu.id, cu.url, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  own_urls as (
    select o.id from own_all o where o.page_key = v_key
  ),
  -- Both windows' answers, from the cover index alone.
  answers as materialized (
    select pr.id, pr.prompt_id, pr.platform, pr.created_at >= v_cur as is_cur
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= v_prev
      and pr.created_at < v_until
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  cites as (
    select a.prompt_id, a.platform, a.is_cur
    from public.prompt_result_citations prc
    join answers a on a.id = prc.prompt_result_id
    where prc.url_id in (select u.id from own_urls u)
      and prc.brand_id = p_brand_id
      and prc.created_at >= v_prev
      and prc.created_at < v_until
  ),
  per_prompt as (
    select
      c.prompt_id,
      count(*) filter (where c.is_cur) as cur,
      count(*) filter (where not c.is_cur) as prev,
      coalesce(array_agg(distinct c.platform) filter (where c.is_cur), '{}') as cur_platforms,
      coalesce(array_agg(distinct c.platform) filter (where not c.is_cur), '{}') as prev_platforms
    from cites c
    group by c.prompt_id
  ),
  -- This window's answers to the prompts citing the page, then their
  -- citations, then the brand's other pages among them.
  citing_answers as materialized (
    select a.id, a.prompt_id
    from answers a
    where a.is_cur
      and a.prompt_id in (select pp.prompt_id from per_prompt pp where pp.cur > 0)
  ),
  other_pages as (
    select o.page_key, min(o.url) as page, count(distinct ca.prompt_id) as prompts
    from citing_answers ca
    join public.prompt_result_citations prc
      on prc.prompt_result_id = ca.id
     and prc.brand_id = p_brand_id
     and prc.created_at >= v_cur
     and prc.created_at < v_until
    join own_all o on o.id = prc.url_id
    where o.page_key <> v_key
    group by o.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_prev
      and l.created_at < v_until
  ),
  visits as (
    select l.created_at >= v_cur as is_cur, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_prev
      and l.created_at < v_until
      and lower(public.normalize_page_path(l.url)) = v_key
    union all
    select g.date >= v_cur_day, g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_prev_day
      and g.date <= v_last_day
      and lower(public.normalize_page_path(g.landing_page)) = v_key
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  clicks as (
    select g.date >= v_cur_day as is_cur, g.clicks::bigint as n
    from public.gsc_page_stats g
    where g.brand_id = p_brand_id
      and g.page_key = v_key
      and g.date >= v_prev_day
      and g.date <= v_last_day
  )
  select jsonb_build_object(
    'citations', (
      select jsonb_build_object('cur', coalesce(sum(cur), 0), 'prev', coalesce(sum(prev), 0))
      from per_prompt
    ),
    'promptCounts', (
      select jsonb_build_object(
        'cur', count(*) filter (where cur > 0),
        'prev', count(*) filter (where prev > 0),
        'lost', count(*) filter (where cur = 0 and prev > 0)
      )
      from per_prompt
    ),
    'aiVisits', (
      select jsonb_build_object(
        'cur', coalesce(sum(n) filter (where is_cur), 0),
        'prev', coalesce(sum(n) filter (where not is_cur), 0)
      )
      from visits
    ),
    'gscClicks', (
      select jsonb_build_object(
        'cur', coalesce(sum(n) filter (where is_cur), 0),
        'prev', coalesce(sum(n) filter (where not is_cur), 0)
      )
      from clicks
    ),
    'gscSince', (select min(g.date) from public.gsc_page_stats g where g.brand_id = p_brand_id),
    'overlap', coalesce((
      select jsonb_agg(jsonb_build_object('page', op.page, 'prompts', op.prompts)
        order by op.prompts desc, op.page)
      from (select * from other_pages order by prompts desc, page limit 3) op
    ), '[]'::jsonb),
    'prompts', coalesce((
      select jsonb_agg(row order by (row->>'cur')::int desc, (row->>'prev')::int desc, row->>'text')
      from (
        select jsonb_build_object(
          'id', pp.prompt_id,
          'text', p.text,
          'cur', pp.cur,
          'prev', pp.prev,
          'curPlatforms', to_jsonb(pp.cur_platforms),
          'prevPlatforms', to_jsonb(pp.prev_platforms)
        ) as row
        from per_prompt pp
        join public.prompts p on p.id = pp.prompt_id
        order by pp.cur desc, pp.prev desc
        limit 100
      ) t
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.content_page_impact(uuid, text, integer) from public, anon;
grant execute on function public.content_page_impact(uuid, text, integer)
  to authenticated, service_role;

comment on function public.content_page_impact(uuid, text, integer) is
  'Content Editor (CE-016): one page''s citations, AI visits, Google clicks and citing prompts over the last N whole UTC days (ending yesterday) and the N before. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00210_content_page_results.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00210: results from AI visits per AI source, for the editor's Impact tab
-- ============================================================================
-- The Impact tab's "Results from AI visits" (Content Editor spec v2 §7,
-- CE-016) shows what visitors from AI assistants did after landing on the
-- page a draft optimizes, and which assistant sent them.
--
-- content_page_results(brand, page, days) returns one jsonb over the last N
-- whole UTC days, ending yesterday, as content_page_impact (00209) counts them:
--   * analytics: whether the brand has a Google Analytics property mapped;
--     conversions come only from it until the snippet records goals (CE-017);
--   * purchases: whether the property reported purchases in the window, on
--     any page or channel, so the tab shows orders and revenue even where
--     this page had none;
--   * sources: one row per AI source key (the AI source list's, 00175) with
--       - visits: AI-referred visits, by ai_traffic_merged's rule (00176):
--         the snippet on days it was active for the brand, Google Analytics
--         on other days, never both; they add up to the tab's AI visits;
--       - sessions, key_events, key_event_sessions, transactions, revenue:
--         Google Analytics' AI sessions that landed on the page, with their
--         key events, sessions with a key event (the rate, 00177), purchases
--         and purchase revenue, on every day of the window.
-- A page is one lower(normalize_page_path) key, as in 00209. Analytics rows
-- without a landing page are left out: normalize_page_path('') is '/'.
--
-- Security definer with an organization check, as content_page_impact, and
-- planned for each call's own values, as it is (plan_cache_mode).

create or replace function public.content_page_results(
  p_brand_id uuid,
  p_page text,
  p_days integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_key text := lower(public.normalize_page_path(p_page));
  -- The last whole day.
  v_last_day date := (now() at time zone 'utc')::date - 1;
  v_day date;
  v_from timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 366 or p_page is null then
    raise exception 'content_page_results: a page and 1 to 366 days are needed'
      using errcode = '22023';
  end if;

  v_day := v_last_day - p_days + 1;
  v_from := v_day::timestamp at time zone 'utc';
  v_until := (v_last_day + 1)::timestamp at time zone 'utc';

  with snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
  ),
  visits as (
    select coalesce(nullif(l.source_platform, ''), 'unknown') as platform, count(*)::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
      and lower(public.normalize_page_path(l.url)) = v_key
    group by 1
    union all
    select coalesce(g.platform, g.source), sum(g.sessions)::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      and g.landing_page <> ''
      and g.date >= v_day
      and g.date <= v_last_day
      and lower(public.normalize_page_path(g.landing_page)) = v_key
      and not exists (select 1 from snippet_days s where s.day = g.date)
    group by 1
  ),
  analytics as (
    select
      coalesce(g.platform, g.source) as platform,
      sum(g.sessions)::bigint as sessions,
      sum(g.key_events)::bigint as key_events,
      sum(g.key_event_sessions)::bigint as key_event_sessions,
      sum(g.transactions)::bigint as transactions,
      coalesce(sum(g.purchase_revenue), 0)::numeric as revenue
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.landing_page <> ''
      and g.date >= v_day
      and g.date <= v_last_day
      and lower(public.normalize_page_path(g.landing_page)) = v_key
    group by 1
  ),
  sources as (
    select
      p.platform,
      coalesce(v.n, 0) as visits,
      coalesce(a.sessions, 0) as sessions,
      coalesce(a.key_events, 0) as key_events,
      coalesce(a.key_event_sessions, 0) as key_event_sessions,
      coalesce(a.transactions, 0) as transactions,
      coalesce(a.revenue, 0) as revenue
    from (select platform from visits union select platform from analytics) p
    left join (select platform, sum(n) as n from visits group by platform) v on v.platform = p.platform
    left join analytics a on a.platform = p.platform
  )
  select jsonb_build_object(
    'analytics', (
      select nullif(b.ga_property_id, '') is not null
      from public.brands b where b.id = p_brand_id
    ),
    'purchases', exists (
      select 1 from public.ga_ai_traffic_stats g
      where g.brand_id = p_brand_id
        and g.date >= v_day
        and g.date <= v_last_day
        and (g.transactions > 0 or g.purchase_revenue > 0)
    ) or exists (
      select 1 from public.ga_channel_stats c
      where c.brand_id = p_brand_id
        and c.date >= v_day
        and c.date <= v_last_day
        and (c.transactions > 0 or c.purchase_revenue > 0)
    ),
    'sources', coalesce((
      select jsonb_agg(jsonb_build_object(
          'platform', s.platform,
          'visits', s.visits,
          'sessions', s.sessions,
          'keyEvents', s.key_events,
          'keyEventSessions', s.key_event_sessions,
          'transactions', s.transactions,
          'revenue', s.revenue
        ) order by s.visits desc, s.sessions desc, s.platform)
      from sources s
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.content_page_results(uuid, text, integer) from public, anon;
grant execute on function public.content_page_results(uuid, text, integer)
  to authenticated, service_role;

comment on function public.content_page_results(uuid, text, integer) is
  'Content Editor (CE-016): one page''s AI visits per AI source over the last N whole UTC days (ending yesterday), with Google Analytics'' AI sessions landing on it, their key events, purchases and revenue. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00211_content_draft_sources.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00211: the sources a draft is built from, for the editor's Sources tab
-- ============================================================================
-- The Sources tab (Content Editor spec v2 §10, CE-008) names every source a
-- draft draws on, with where the draft uses it, and lets a person leave one
-- out or add their own.
--
-- content_draft_sources(draft, days) reads the brand's data over the last N
-- days (30 by default) and returns one jsonb:
--   * prompts: the draft's prompts (content_drafts.prompt_ids) and, for a
--     draft optimizing a live page, the prompts whose answers cited that
--     page; each with its answers in the window and those naming the brand;
--   * fanouts: the searches AI engines ran while answering those prompts
--     (prompt_results.search_queries, 00021), one row per normalized query
--     with its platforms and the answers that ran it, most searched first
--     (at most 30);
--   * citedPages: the pages those answers cited, with citations and answers
--     (at most 20); ChatGPT Shopping cards left out, as the Citations page
--     does;
--   * gscQueries: the brand's Search Console queries over 28 days with
--     clicks and impressions (at most 300). Search Console keeps no queries
--     per page, so the caller keeps the ones sharing words with the draft,
--     as pagePromptSuggestions.js does;
--   * brandDomains and competitorDomains, to name each cited page's kind.
-- Security definer with an organization check through the draft's brand:
-- citation_urls has no member select policy. The page a draft optimizes is
-- its source URL's path on that URL's host, which must be one of the brand's
-- domains: /pricing on another site of the brand's, or on a site not the
-- brand's, isn't it. Prompts are the brand's through their prompt set, as
-- everywhere else (a prompt needs no topic). Bounded by the brand and the
-- window on (brand_id, created_at), with citations grouped by address before
-- any address is read, and planned for each call's own values
-- (plan_cache_mode).
--
-- content_draft_sources (the table) keeps a person's choices: a source left
-- out (included false), and a page address or Search Console query added by
-- hand (added true). A prompt added by hand joins the draft's prompt_ids.

create table if not exists public.content_draft_sources (
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  kind text not null check (kind in ('prompt', 'fanout', 'cited_page', 'gsc_query')),
  ref text not null check (char_length(ref) between 1 and 2048),
  included boolean not null default true,
  added boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (draft_id, kind, ref),
  -- Only pages and queries are added by hand; a prompt joins prompt_ids.
  check (not added or kind in ('cited_page', 'gsc_query'))
);

alter table public.content_draft_sources enable row level security;

-- A draft the member can read is one in their organization (content_drafts'
-- own member policies), so the choices follow it.
create policy "content_draft_sources: member select"
  on public.content_draft_sources
  for select
  using (draft_id in (select d.id from public.content_drafts d));

create policy "content_draft_sources: member insert"
  on public.content_draft_sources
  for insert
  with check (draft_id in (select d.id from public.content_drafts d));

create policy "content_draft_sources: member update"
  on public.content_draft_sources
  for update
  using (draft_id in (select d.id from public.content_drafts d))
  with check (draft_id in (select d.id from public.content_drafts d));

create policy "content_draft_sources: member delete"
  on public.content_draft_sources
  for delete
  using (draft_id in (select d.id from public.content_drafts d));

grant select, insert, update, delete on public.content_draft_sources to authenticated;

create or replace trigger content_draft_sources_updated_at
  before update on public.content_draft_sources
  for each row execute function public.handle_updated_at();

comment on table public.content_draft_sources is
  'Content Editor (CE-008): a person''s choices on a draft''s sources — one left out (included false), or a page address or Search Console query added by hand (added true).';

create or replace function public.content_draft_sources(
  p_draft_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_brand_id uuid;
  v_prompt_ids uuid[];
  v_page_key text;
  v_host text;
  v_since timestamptz;
  v_result jsonb;
begin
  select d.brand_id, d.prompt_ids, lower(public.normalize_page_path(d.source_url)),
    -- Lower-cased first: a scheme may be written HTTPS://.
    regexp_replace(substring(lower(d.source_url) from '^https?://([^/:?#]+)'), '^www\.', '')
    into v_brand_id, v_prompt_ids, v_page_key, v_host
  from public.content_drafts d
  where d.id = p_draft_id;

  if v_brand_id is null or (
    not exists (
      select 1 from public.brands b
      join public.profiles pf on pf.organization_id = b.organization_id
      where b.id = v_brand_id and pf.id = auth.uid()
    ) and auth.role() is distinct from 'service_role'
  ) then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'content_draft_sources: 1 to 90 days are needed' using errcode = '22023';
  end if;

  v_since := now() - make_interval(days => p_days);
  -- A page on a site that isn't the brand's is no page of the brand's.
  if v_host is null or not exists (
    select 1 from public.brand_domains bd
    where bd.brand_id = v_brand_id
      and lower(regexp_replace(bd.domain, '^www\.', '')) = v_host
  ) then
    v_page_key := null;
  end if;

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = v_brand_id
  ),
  -- The page's addresses: its path on its host.
  page_urls as materialized (
    select cu.id
    from public.citation_urls cu
    where v_page_key is not null
      and cu.domain = v_host
      and lower(public.normalize_page_path(cu.url)) = v_page_key
  ),
  -- The window's answers, from idx_prompt_results_brand_created_cover alone:
  -- only for a draft with a page, to find the prompts citing it.
  window_answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where v_page_key is not null
      and pr.brand_id = v_brand_id
      and pr.created_at >= v_since
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  -- The prompts whose answers cited the page the draft optimizes.
  page_prompts as (
    select distinct wa.prompt_id
    from public.prompt_result_citations prc
    join window_answers wa on wa.id = prc.prompt_result_id
    where prc.url_id in (select pu.id from page_urls pu)
      and prc.brand_id = v_brand_id
      and prc.created_at >= v_since
  ),
  source_prompts as (
    select p.id, p.text, p.id = any(v_prompt_ids) as in_draft,
      p.id in (select prompt_id from page_prompts) as cites_page
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = v_brand_id
      and (p.id = any(v_prompt_ids) or p.id in (select prompt_id from page_prompts))
  ),
  answers as materialized (
    select pr.id, pr.prompt_id, pr.platform, pr.mention_count, pr.search_queries
    from public.prompt_results pr
    where pr.brand_id = v_brand_id
      and pr.created_at >= v_since
      and pr.prompt_id in (select id from source_prompts)
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  prompt_counts as (
    select a.prompt_id, count(*) as answers, count(*) filter (where a.mention_count > 0) as mentioned
    from answers a
    group by a.prompt_id
  ),
  fanout_rows as (
    select
      a.id as answer_id,
      lower(trim(regexp_replace(q.item->>'query', '\s+', ' ', 'g'))) as norm,
      trim(regexp_replace(q.item->>'query', '\s+', ' ', 'g')) as query,
      coalesce(nullif(q.item->>'source_platform', ''), a.platform) as platform
    from answers a
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(a.search_queries) = 'array' then a.search_queries else '[]'::jsonb end
    ) as q(item)
    where coalesce(trim(q.item->>'query'), '') <> ''
  ),
  fanouts as (
    select min(query) as query, array_agg(distinct platform order by platform) as platforms,
      count(distinct answer_id) as searched
    from fanout_rows
    group by norm
    order by count(distinct answer_id) desc, min(query)
    limit 30
  ),
  -- Citations grouped by address first; only the top 20 addresses are read.
  cited_ids as (
    select prc.url_id, count(*) as citations, count(distinct a.id) as answers
    from answers a
    join public.prompt_result_citations prc
      on prc.prompt_result_id = a.id
     and prc.brand_id = v_brand_id
     and prc.created_at >= v_since
    group by prc.url_id
    order by count(*) desc, count(distinct a.id) desc, prc.url_id
    limit 20
  ),
  cited as (
    select cu.url, cu.title, cu.domain, ci.citations, ci.answers
    from cited_ids ci
    join public.citation_urls cu on cu.id = ci.url_id
  ),
  queries as (
    select g.query, sum(g.clicks)::bigint as clicks, sum(g.impressions)::bigint as impressions
    from public.gsc_query_stats g
    where g.brand_id = v_brand_id
      and g.date >= (now() at time zone 'utc')::date - 28
    group by g.query
    order by sum(g.clicks) desc, sum(g.impressions) desc, g.query
    limit 300
  )
  select jsonb_build_object(
    'prompts', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', sp.id,
          'text', sp.text,
          'inDraft', sp.in_draft,
          'citesPage', sp.cites_page,
          'answers', coalesce(pc.answers, 0),
          'mentioned', coalesce(pc.mentioned, 0)
        ) order by sp.in_draft desc, sp.text)
      from source_prompts sp
      left join prompt_counts pc on pc.prompt_id = sp.id
    ), '[]'::jsonb),
    'fanouts', coalesce((
      select jsonb_agg(jsonb_build_object(
          'query', f.query, 'platforms', to_jsonb(f.platforms), 'searched', f.searched
        ) order by f.searched desc, f.query)
      from fanouts f
    ), '[]'::jsonb),
    'citedPages', coalesce((
      select jsonb_agg(jsonb_build_object(
          'url', c.url, 'title', c.title, 'domain', c.domain,
          'citations', c.citations, 'answers', c.answers
        ) order by c.citations desc, c.answers desc, c.url)
      from cited c
    ), '[]'::jsonb),
    'gscQueries', coalesce((
      select jsonb_agg(jsonb_build_object(
          'query', q.query, 'clicks', q.clicks, 'impressions', q.impressions
        ) order by q.clicks desc, q.impressions desc, q.query)
      from queries q
    ), '[]'::jsonb),
    'brandDomains', coalesce((select jsonb_agg(domain order by domain) from own_domains), '[]'::jsonb),
    'competitorDomains', coalesce((
      select jsonb_agg(distinct lower(regexp_replace(c.domain, '^www\.', '')))
      from public.competitors c
      where c.brand_id = v_brand_id and coalesce(c.domain, '') <> ''
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.content_draft_sources(uuid, integer) from public, anon;
grant execute on function public.content_draft_sources(uuid, integer) to authenticated, service_role;

comment on function public.content_draft_sources(uuid, integer) is
  'Content Editor (CE-008): a draft''s sources over the last N days — its prompts and those citing its page, their AI fan-out searches, the pages their answers cited, the brand''s Search Console queries, and the brand and competitor domains. Security definer with an organization check through the draft''s brand.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00212_content_draft_brief.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00212: a draft's brief, for the editor's Brief tab (Content Editor, CE-007)
-- ============================================================================
-- The Brief tab (Content Editor spec v2 §10) shows what the page should do:
-- the page type and target address, then its goal, audience and length, and
-- an outline whose H2s each answer one of the searches AI engines ran
-- (a fan-out) on a platform. Rebuild outline writes it from the draft's
-- sources (the Sources tab, 00211); Edit brief changes it by hand.
--
--   * content_drafts.brief: the brief as jsonb — {goal, audience, outline:
--     [{heading, keyPoints, fanout, platform}], keywords, origin, builtAt,
--     builtFrom}. Null until one is built; the tab then offers the brief of
--     the opportunity the draft started from, if it has one. A member edits
--     it like the body, so it isn't a server column.
--   * prompt_improve_usage.content_draft_id: a rebuild is metered from the
--     organization's AI usage, the monthly budget the Improve tab and the
--     Action Center's task writer draw from (00120, 00150), not the content
--     brief quota, which stays with Opportunities' Generate Brief (spec §3).
--     The row names the draft it wrote the brief for.

alter table public.content_drafts
  add column if not exists brief jsonb
    check (brief is null or (jsonb_typeof(brief) = 'object' and octet_length(brief::text) <= 65536));

comment on column public.content_drafts.brief is
  'The draft''s brief (CE-007): goal, audience, outline (each H2 with the fan-out and platform it answers), keywords, and how it was made (origin, builtAt, builtFrom). Null until built.';

alter table public.prompt_improve_usage
  add column if not exists content_draft_id uuid references public.content_drafts(id) on delete set null;

comment on column public.prompt_improve_usage.content_draft_id is
  'The Content Editor draft whose brief this generation rebuilt (CE-007). Null for an Improve tab or task-writer generation.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00213_content_draft_rules.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00213: a draft's rules, for the editor's Rules tab (Content Editor, CE-009)
-- ============================================================================
-- The Rules tab (Content Editor spec v2 §10) lists the rules a page of its
-- type is written to — the type's own, then the shared groups (length and
-- structure, fan-outs and keywords, links and sources, style) — and reads
-- each one's status from the page as written. The rules themselves are the
-- app's (frontend/src/lib/content/rules.ts); a draft keeps only what the person
-- changed for it.
--
--   * content_drafts.rules: {set, overrides} — the page type whose set
--     applies (null follows the draft's type) and, per rule, whether it is
--     on and the value the draft uses ("Rule updated for this draft"). Null
--     until something changes. A member edits it like the body, so it isn't
--     a server column.

alter table public.content_drafts
  add column if not exists rules jsonb
    check (rules is null or (jsonb_typeof(rules) = 'object' and octet_length(rules::text) <= 32768));

comment on column public.content_drafts.rules is
  'The draft''s rule choices (CE-009): the page type whose rule set applies (null = the draft''s type) and per-rule overrides {on, value}. Null until changed.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00214_content_rule_sets.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00214: a workspace's own rules per page type (Content Editor, CE-009)
-- ============================================================================
-- The Rules tab's "Save as my rules" (Content Editor spec v2 §10) keeps a
-- draft's rule choices for the workspace, per page type: the values and
-- switches the person changed, and the rules they wrote in their own words.
-- A new draft of that type starts from them ("My rules"); Reset takes a
-- draft back to GetCito's default set. The rules themselves are the app's
-- (frontend/src/lib/content/rules.ts); a set keeps only what differs.
--
--   * content_rule_sets: one row per organization and page type, with
--     overrides {key: {on, value}} and text_rules [{id, text, on}] — the
--     same shapes as content_drafts.rules (00213). Pasted rule text is
--     writing guidance for the editor and the agent only; it changes no
--     access or safety rule (spec §10, CHAT-05).
--   * Members of the organization read them; admins and managers save them,
--     as they do the workspace's other settings (brand_domains), since every
--     new draft of the type starts from them.

create table if not exists public.content_rule_sets (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  page_type text not null check (char_length(page_type) between 1 and 40),
  overrides jsonb not null default '{}'::jsonb
    check (jsonb_typeof(overrides) = 'object' and octet_length(overrides::text) <= 16384),
  text_rules jsonb not null default '[]'::jsonb
    check (jsonb_typeof(text_rules) = 'array' and jsonb_array_length(text_rules) <= 50
      and octet_length(text_rules::text) <= 32768),
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (organization_id, page_type)
);

alter table public.content_rule_sets enable row level security;

create policy "content_rule_sets: member select"
  on public.content_rule_sets
  for select
  using (organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid()));

create policy "content_rule_sets: manager insert"
  on public.content_rule_sets
  for insert
  with check (
    organization_id in (
      select p.organization_id from public.profiles p
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
    and updated_by = auth.uid()
  );

create policy "content_rule_sets: manager update"
  on public.content_rule_sets
  for update
  using (
    organization_id in (
      select p.organization_id from public.profiles p
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  )
  with check (
    organization_id in (
      select p.organization_id from public.profiles p
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
    and updated_by = auth.uid()
  );

grant select, insert, update on public.content_rule_sets to authenticated;

comment on table public.content_rule_sets is
  'Content Editor (CE-009): a workspace''s "My rules" per page type — rule overrides and text rules a new draft of the type starts from.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00215_content_draft_versions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00215: a draft's version history, for the editor's History menu
-- ============================================================================
-- History (Content Editor spec v2 §8, CE-018) lists a draft's earlier
-- versions with their time and origin, and restores any of them:
--   * import: the live page, as Start imported it from its address;
--   * agent_before: the page before an agent's suggestions were accepted
--     (CE-018 part C writes it);
--   * ready: each Mark ready;
--   * publish: each publish (CE-013 writes it);
--   * restore: the page a restore replaced, so a restore loses nothing.
-- "Now" is the draft itself. Versions are kept 90 days: the server's daily
-- run prunes older ones (content_draft_versions_prune), and reads leave them
-- out until then. A draft keeps its newest 50 (History lists 50), and a
-- version that would repeat the draft's latest one (a restore after a
-- restore, Mark ready on an unchanged page) isn't kept again. Members write
-- import, agent_before and ready versions; publish is the server's.
--
-- A version is a copy of the draft's own title and body, which every save
-- checks against the draft allow-list. So members only read versions; the two
-- functions below write them from the draft row, and a hand-made version
-- with unchecked HTML can't be restored into a draft.
create table if not exists public.content_draft_versions (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  origin text not null
    check (origin in ('import', 'agent_before', 'ready', 'publish', 'restore')),
  title text not null default '',
  body_html text not null default '',
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists content_draft_versions_draft_idx
  on public.content_draft_versions (draft_id, created_at desc);
-- The daily prune walks the oldest first.
create index if not exists content_draft_versions_created_idx
  on public.content_draft_versions (created_at);

alter table public.content_draft_versions enable row level security;

-- A draft the member can read is one in their organization (content_drafts'
-- own member policies), so its versions follow it.
create policy "content_draft_versions: member select"
  on public.content_draft_versions
  for select
  using (draft_id in (select d.id from public.content_drafts d));

grant select on public.content_draft_versions to authenticated;

comment on table public.content_draft_versions is
  'Content Editor (CE-018): a draft''s earlier versions — the imported live page, each Mark ready and publish, the page before agent changes or a restore. Written by content_draft_snapshot / content_draft_restore; kept 90 days.';

-- Whether the caller may change the draft: a member of the organization that
-- owns its brand, or the server.
create or replace function public.content_draft_member(p_draft_id uuid)
returns boolean
language sql
stable
security definer
set search_path to 'public'
as $$
  select auth.role() = 'service_role' or exists (
    select 1
    from public.content_drafts d
    join public.brands b on b.id = d.brand_id
    join public.profiles pf on pf.organization_id = b.organization_id
    where d.id = p_draft_id and pf.id = auth.uid()
  );
$$;

revoke all on function public.content_draft_member(uuid) from public, anon;
grant execute on function public.content_draft_member(uuid) to authenticated, service_role;

-- Keeps the draft as it is now as a version of the given origin, unless its
-- latest version is already this page (that one's id comes back), and keeps
-- only the draft's newest 50. Called by the two functions below, not by
-- members.
create or replace function public.content_draft_keep_version(p_draft_id uuid, p_origin text)
returns uuid
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_latest public.content_draft_versions%rowtype;
  v_id uuid;
begin
  select * into v_latest
  from public.content_draft_versions v
  where v.draft_id = p_draft_id
  order by v.created_at desc, v.id desc
  limit 1;
  if v_latest.id is not null and exists (
    select 1 from public.content_drafts d
    where d.id = p_draft_id and d.title = v_latest.title and d.body_html = v_latest.body_html
  ) then
    return v_latest.id;
  end if;

  insert into public.content_draft_versions (draft_id, origin, title, body_html, created_by)
  select d.id, p_origin, d.title, d.body_html, auth.uid()
  from public.content_drafts d
  where d.id = p_draft_id
  returning id into v_id;

  delete from public.content_draft_versions v
  where v.draft_id = p_draft_id
    and v.id not in (
      select o.id from public.content_draft_versions o
      where o.draft_id = p_draft_id
      order by o.created_at desc, o.id desc
      limit 50
    );
  return v_id;
end;
$$;

revoke all on function public.content_draft_keep_version(uuid, text)
  from public, anon, authenticated;

-- Keeps the draft as it is now as a version of the given origin. Returns the
-- version's id, or null when the caller can't change the draft, or (a
-- publish) isn't the server.
create or replace function public.content_draft_snapshot(p_draft_id uuid, p_origin text)
returns uuid
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_id uuid;
begin
  -- A restore keeps its own version (content_draft_restore).
  if p_origin is null or p_origin not in ('import', 'agent_before', 'ready', 'publish') then
    raise exception 'content_draft_snapshot: unknown origin %', p_origin using errcode = '22023';
  end if;
  if not public.content_draft_member(p_draft_id)
     or (p_origin = 'publish' and auth.role() is distinct from 'service_role') then
    return null;
  end if;

  v_id := public.content_draft_keep_version(p_draft_id, p_origin);
  return v_id;
end;
$$;

revoke all on function public.content_draft_snapshot(uuid, text) from public, anon;
grant execute on function public.content_draft_snapshot(uuid, text) to authenticated, service_role;

-- Restores a version: the draft as it is now is kept first (origin restore),
-- then the draft takes the version's title and body; a draft that is already
-- that page is left as it is. Only versions past the draft's newest 50 are
-- ever deleted.
-- Returns the draft's title, body and updated_at after, or null when the
-- version is unknown, past its 90 days, or the caller can't change the draft.
create or replace function public.content_draft_restore(p_version_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_version public.content_draft_versions%rowtype;
  v_draft public.content_drafts%rowtype;
begin
  select * into v_version
  from public.content_draft_versions v
  where v.id = p_version_id and v.created_at >= now() - interval '90 days';
  if v_version.id is null or not public.content_draft_member(v_version.draft_id) then
    return null;
  end if;

  select * into v_draft from public.content_drafts d where d.id = v_version.draft_id;
  -- Already this page: nothing to keep or change.
  if v_draft.title is distinct from v_version.title
     or v_draft.body_html is distinct from v_version.body_html then
    perform public.content_draft_keep_version(v_version.draft_id, 'restore');

    update public.content_drafts d
    set title = v_version.title, body_html = v_version.body_html
    where d.id = v_version.draft_id
    returning * into v_draft;
  end if;

  return jsonb_build_object(
    'title', v_draft.title,
    'bodyHtml', v_draft.body_html,
    'updatedAt', v_draft.updated_at
  );
end;
$$;

revoke all on function public.content_draft_restore(uuid) from public, anon;
grant execute on function public.content_draft_restore(uuid) to authenticated, service_role;

-- Deletes at most p_limit versions older than p_before, oldest first; the
-- server's daily run calls it until fewer come back.
create or replace function public.content_draft_versions_prune(
  p_before timestamptz,
  p_limit integer
)
returns integer
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_deleted integer;
begin
  delete from public.content_draft_versions v
  where v.id in (
    select o.id from public.content_draft_versions o
    where o.created_at < p_before
    order by o.created_at
    limit p_limit
  );
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

revoke all on function public.content_draft_versions_prune(timestamptz, integer)
  from public, anon, authenticated;
grant execute on function public.content_draft_versions_prune(timestamptz, integer)
  to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00216_content_draft_cited_answers.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00216: the AI answers that cite a draft's page, for its locked passages
-- ============================================================================
-- Locked passages (Content Editor spec v2 §8, CE-018): a passage of the page
-- AI answers quote today gets a green border and "Cited by ChatGPT 14× and
-- Perplexity 6× in 30 days · keep wording", and a person is warned before
-- changing it.
--
-- content_draft_cited_answers(draft, days) returns the answers of the last N
-- days (30 by default) whose citations name the page the draft optimizes,
-- the latest first: one {platform, response} each, at most 200, each
-- response cut to 12,000 characters. The editor finds the passages they
-- quote. ChatGPT Shopping cards are left out, as the Citations page does.
-- The page is content_drafts.source_url's path on that URL's host, which
-- must be one of the brand's domains, as in content_draft_sources (00211):
-- /pricing on another site of the brand's isn't it. The 200 answers are
-- picked first, and only their responses are read.
--
-- Security definer with an organization check through the draft's brand:
-- citation_urls has no member select policy. A draft without a page gets [];
-- one the caller can't read gets null.
create or replace function public.content_draft_cited_answers(
  p_draft_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_brand_id uuid;
  v_page_key text;
  v_host text;
  v_since timestamptz;
  v_result jsonb;
begin
  select d.brand_id, lower(public.normalize_page_path(d.source_url)),
    -- Lower-cased first: a scheme may be written HTTPS://.
    regexp_replace(substring(lower(d.source_url) from '^https?://([^/:?#]+)'), '^www\.', '')
    into v_brand_id, v_page_key, v_host
  from public.content_drafts d
  where d.id = p_draft_id;

  if v_brand_id is null or (
    not exists (
      select 1 from public.brands b
      join public.profiles pf on pf.organization_id = b.organization_id
      where b.id = v_brand_id and pf.id = auth.uid()
    ) and auth.role() is distinct from 'service_role'
  ) then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'content_draft_cited_answers: 1 to 90 days are needed' using errcode = '22023';
  end if;
  -- No page, or a page on a site that isn't the brand's: nothing cites it.
  if v_page_key is null or v_host is null or not exists (
    select 1 from public.brand_domains bd
    where bd.brand_id = v_brand_id
      and lower(regexp_replace(bd.domain, '^www\.', '')) = v_host
  ) then
    return '[]'::jsonb;
  end if;

  v_since := now() - make_interval(days => p_days);

  with
  -- Each answer once, however many of its citations name the page.
  citing as (
    select distinct prc.prompt_result_id
    from public.citation_urls cu
    join public.prompt_result_citations prc
      on prc.url_id = cu.id
     and prc.brand_id = v_brand_id
     and prc.created_at >= v_since
    where cu.domain = v_host
      and lower(public.normalize_page_path(cu.url)) = v_page_key
  ),
  -- The latest 200 first; only their responses are read.
  latest as (
    select pr.id, pr.created_at
    from citing c
    join public.prompt_results pr on pr.id = c.prompt_result_id
    where pr.platform is distinct from 'chatgpt-shopping'
      and pr.response <> ''
    order by pr.created_at desc
    limit 200
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object('platform', pr.platform, 'response', left(pr.response, 12000))
      order by l.created_at desc
    ),
    '[]'::jsonb
  )
    into v_result
  from latest l
  join public.prompt_results pr on pr.id = l.id;

  return v_result;
end;
$$;

revoke all on function public.content_draft_cited_answers(uuid, integer) from public, anon;
grant execute on function public.content_draft_cited_answers(uuid, integer)
  to authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00217_content_draft_suggestions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00217: an agent's suggestions on a draft, for review in the editor
-- ============================================================================
-- Agent suggestions (Content Editor spec v2 §8, CE-018): an agent leaves
-- changes on a draft for a person to accept or reject, each with who made it
-- and why. They sit in the page as cards; accepting one changes the page,
-- and Undo, Restore and Undo all bring it back to review.
--
-- A suggestion is one of two kinds:
--   * replace: in the passage whose text is block_text, before_text becomes
--     after_text (plain text);
--   * insert: after the passage whose text is block_text, the blocks in
--     after_text (HTML, checked against the draft allow-list where it is
--     inserted) are added.
-- One agent run is a batch; the editor shows the latest. action_id names the
-- Action Center action the run came from ("from Action AC-214").
--
-- Agents write suggestions through the server (service role, CE-018 part D
-- and CE-022). Members read them, and decide them only through
-- content_draft_decide_suggestions, which records who decided and when.
create table if not exists public.content_draft_suggestions (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  batch_id uuid not null,
  action_id uuid references public.actions(id) on delete set null,
  agent text not null default 'content_agent' check (agent in ('content_agent')),
  kind text not null check (kind in ('replace', 'insert')),
  block_text text not null check (char_length(block_text) between 1 and 5000),
  before_text text not null default '' check (char_length(before_text) <= 5000),
  after_text text not null check (char_length(after_text) between 1 and 20000),
  reason text not null check (char_length(reason) between 1 and 300),
  rule_keys text[] not null default '{}',
  position integer not null default 0,
  status text not null default 'open' check (status in ('open', 'accepted', 'rejected')),
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  -- A replacement names the words it replaces.
  check (kind = 'insert' or before_text <> '')
);

create index if not exists content_draft_suggestions_draft_idx
  on public.content_draft_suggestions (draft_id, created_at desc);

alter table public.content_draft_suggestions enable row level security;

-- A draft the member can read is one in their organization (content_drafts'
-- own member policies), so its suggestions follow it.
create policy "content_draft_suggestions: member select"
  on public.content_draft_suggestions
  for select
  using (draft_id in (select d.id from public.content_drafts d));

grant select on public.content_draft_suggestions to authenticated;

comment on table public.content_draft_suggestions is
  'Content Editor (CE-018): an agent''s suggested changes on a draft — replace words in a passage, or insert blocks after one — open, accepted or rejected. Written by the server; decided through content_draft_decide_suggestions.';

-- Accepts, rejects, or sends back to review (open) the given suggestions of
-- drafts the caller may change, recording who decided and when. Returns how
-- many changed.
create or replace function public.content_draft_decide_suggestions(
  p_ids uuid[],
  p_status text
)
returns integer
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_count integer;
begin
  if p_status is null or p_status not in ('open', 'accepted', 'rejected') then
    raise exception 'content_draft_decide_suggestions: unknown status %', p_status
      using errcode = '22023';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then
    return 0;
  end if;
  if cardinality(p_ids) > 200 then
    raise exception 'content_draft_decide_suggestions: at most 200 at once' using errcode = '22023';
  end if;

  update public.content_draft_suggestions s
  set status = p_status,
      decided_by = case when p_status = 'open' then null else auth.uid() end,
      decided_at = case when p_status = 'open' then null else now() end
  where s.id = any(p_ids)
    and public.content_draft_member(s.draft_id);
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.content_draft_decide_suggestions(uuid[], text) from public, anon;
grant execute on function public.content_draft_decide_suggestions(uuid[], text)
  to authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00218_content_draft_action_work.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00218: one draft per action's work (Content Editor, CE-022)
-- ============================================================================
-- An Action Center action's writing task opens the Content Editor with a
-- draft linked to the action (content_drafts.action_id, 00208): "Create
-- content" for a new page, "Optimize page" for one of the pages the action
-- names. Opening it again opens the same draft. An action can hold both kinds
-- of work and name several pages, so the draft is one per action, method and
-- page; this index makes a second start (two clicks, two tabs) find the first
-- rather than write a second draft.
--
-- Start › Team (00208) links one draft to the action it creates, so the
-- drafts linked so far already meet it.
--
-- The page is indexed by its md5: an address may run to 2,048 characters,
-- and a non-ASCII one near that would pass btree's ~2.7 KB row limit and
-- fail the insert.

create unique index if not exists content_drafts_action_work_key
  on public.content_drafts (action_id, method, md5(coalesce(source_url, '')))
  where action_id is not null;

comment on index public.content_drafts_action_work_key is
  'Content Editor (CE-022): one draft per action, method and page.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00219_content_draft_agent_state.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00219: the Content Agent writing a draft (Content Editor, CE-015)
-- ============================================================================
-- "Agent" in Start (spec v2 §5): the Content Agent writes the page, and the
-- person reviews it in Library › In review. The writing runs on the server
-- after Start closes, so the draft says where it is:
--
--   * content_drafts.agent_state: 'writing' while the agent works on it,
--     'failed' when it couldn't finish (the person writes it, or tries
--     again), null otherwise. A 'writing' left by a server that stopped
--     reads as failed after a while (the app's WRITING_STALE_MS);
--   * content_drafts.agent_state_at: when it last changed.
--
-- Like the draft's author and action, they are the server's to write:
-- guard_content_draft_server_columns (00208) is redefined to keep members
-- from setting or changing them.

alter table public.content_drafts
  add column if not exists agent_state text,
  add column if not exists agent_state_at timestamptz;

alter table public.content_drafts
  drop constraint if exists content_drafts_agent_state_check;
alter table public.content_drafts
  add constraint content_drafts_agent_state_check
  check (agent_state is null or agent_state in ('writing', 'failed'));

comment on column public.content_drafts.agent_state is
  'Content Editor (CE-015): writing while the Content Agent writes the draft, failed when it could not finish, else null. Server-set.';
comment on column public.content_drafts.agent_state_at is
  'Content Editor (CE-015): when agent_state last changed. Server-set.';

create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
    if new.action_id is not null then
      raise exception 'content draft action is set server-side'
        using errcode = '42501';
    end if;
    if new.agent_state is not null or new.agent_state_at is not null then
      raise exception 'content draft agent state is set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
     or new.action_id is distinct from old.action_id
     or new.agent_state is distinct from old.agent_state
     or new.agent_state_at is distinct from old.agent_state_at
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00220_content_plan_pages.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00220: the brand's pages for the Content plan (Content Editor, CE-014)
-- ============================================================================
-- The Plan (spec v2 §4) answers what to work on first. Content Opportunities
-- name the new pages AI needs; this reads the brand's own pages, so the Plan
-- can tell which to optimize, which to protect and which compete:
--
--   * answers {cur, prev}: the brand's tracked answers in each window, the
--     denominator that makes the two windows comparable (a brand tracked
--     weekly, prompts added or removed);
--   * citations {cur, prev}: AI answers' citations of the page over the last
--     p_days whole UTC days to yesterday and the p_days before. Today is left
--     out: its runs land through the morning (UTC), so it would read short;
--   * platformsDown: the platforms citing it at a lower rate (citations per
--     answer of that platform) than before, the biggest drop first;
--   * aiVisits: AI-referred visits in the current window, by
--     ai_traffic_merged's rule (00176): the snippet's visits, and Analytics'
--     sessions on days the snippet has none;
--   * overlaps: how many of the brand's other pages are cited for at least
--     two of the same prompts in the current window (pages competing).
--
-- Citations come from the daily rollups (citation_url_daily, answers from
-- citation_result_daily), as ai_traffic_page_citations reads them, so the
-- cost follows the window and not the brand's history; ChatGPT Shopping is
-- left out, as there. Only the overlaps need each citation's prompt: raw
-- rows of the current window, for the chosen pages, through the covering
-- indexes (00207, 00209).
--
-- The 100 pages cited most over both windows. Security definer with an
-- organization check, as 00209; null outside the member's organization.

create or replace function public.content_plan_pages(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30) then
    raise exception 'p_days must be 7 or 30';
  end if;

  v_cur_day := v_last - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  url_counts as materialized (
    select d.url_id, d.platform, d.day >= v_cur_day as is_cur, sum(d.citations)::bigint as n
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day <= v_last
      and d.url_id in (select id from own_urls)
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id, d.platform, d.day >= v_cur_day
  ),
  url_totals as (
    select
      u.page_key,
      u.url,
      u.title,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    group by u.page_key, u.url, u.title
  ),
  pages as materialized (
    select
      t.page_key,
      -- The address cited most often stands for the page.
      (array_agg(t.url order by t.cur + t.prev desc, t.url))[1] as page,
      max(t.title) as title,
      sum(t.cur)::bigint as cur,
      sum(t.prev)::bigint as prev
    from url_totals t
    group by t.page_key
    order by sum(t.cur + t.prev) desc, t.page_key
    limit 100
  ),
  answers as (
    select
      r.platform,
      coalesce(sum(r.answers) filter (where r.day >= v_cur_day), 0)::bigint as cur,
      coalesce(sum(r.answers) filter (where r.day < v_cur_day), 0)::bigint as prev
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and r.day >= v_prev_day
      and r.day <= v_last
      and r.platform is distinct from 'chatgpt-shopping'
    group by r.platform
  ),
  per_platform as (
    select
      u.page_key,
      c.platform,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    where u.page_key in (select p.page_key from pages p)
      and c.platform is not null
    group by u.page_key, c.platform
  ),
  down as (
    -- A platform tracked in both windows, citing the page at a lower rate.
    select
      pp.page_key,
      array_agg(
        pp.platform
        order by pp.prev::numeric / a.prev - pp.cur::numeric / a.cur desc, pp.platform
      ) as platforms
    from per_platform pp
    join answers a on a.platform = pp.platform
    where a.prev > 0
      and a.cur > 0
      and pp.prev::numeric / a.prev > pp.cur::numeric / a.cur
    group by pp.page_key
  ),
  cur_answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= v_cur
      and pr.created_at < v_until
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  page_prompts as (
    select distinct u.page_key, a.prompt_id
    from public.prompt_result_citations prc
    join own_urls u on u.id = prc.url_id
    join cur_answers a on a.id = prc.prompt_result_id
    where prc.brand_id = p_brand_id
      and prc.created_at >= v_cur
      and prc.created_at < v_until
      and u.page_key in (select p.page_key from pages p)
  ),
  competing as (
    select a.page_key, b.page_key as other
    from page_prompts a
    join page_prompts b on b.prompt_id = a.prompt_id and b.page_key <> a.page_key
    group by a.page_key, b.page_key
    having count(*) >= 2
  ),
  page_overlaps as (
    select cm.page_key, count(*) as pages
    from competing cm
    group by cm.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page_key, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
    union all
    select lower(public.normalize_page_path(g.landing_page)), g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_cur_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  page_visits as (
    select v.page_key, sum(v.n) as visits
    from visits v
    where v.page_key in (select p.page_key from pages p)
    group by v.page_key
  )
  select jsonb_build_object(
    'days', p_days,
    'answers', (
      select jsonb_build_object(
        'cur', coalesce(sum(a.cur), 0),
        'prev', coalesce(sum(a.prev), 0)
      )
      from answers a
    ),
    'pages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', p.page,
          'title', p.title,
          'citations', jsonb_build_object('cur', p.cur, 'prev', p.prev),
          'platformsDown', coalesce(to_jsonb(d.platforms[1:3]), '[]'::jsonb),
          'aiVisits', coalesce(pv.visits, 0),
          'overlaps', coalesce(o.pages, 0)
        )
        order by p.cur + p.prev desc, p.page
      )
      from pages p
      left join down d on d.page_key = p.page_key
      left join page_overlaps o on o.page_key = p.page_key
      left join page_visits pv on pv.page_key = p.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.content_plan_pages(uuid, integer) from public, anon;
grant execute on function public.content_plan_pages(uuid, integer) to authenticated, service_role;

comment on function public.content_plan_pages(uuid, integer) is
  'Content Editor (CE-014): the brand''s 100 most cited pages over the last N (7 or 30) whole UTC days to yesterday and the N before, from the daily rollups: citations, the brand''s answers in each window, platforms citing at a lower rate, AI visits and how many of its other pages compete for the same prompts. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00221_content_plan_insights.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00221: what AI cites, and what AI visits bring in, for the Content plan
-- ============================================================================
-- The Plan (Content Editor CE-014, spec v2 §4) shows, under its cards:
--
--   * "What AI cites in your topics": one row per page type with the share
--     of AI citations in the brand's tracked answers going to that type of
--     page, and the brand's own mix. Page types are read from the address
--     and title (lib/content/pageTypes.ts), so this returns the addresses
--     over the last p_days whole UTC days to yesterday (as the Plan's pages,
--     00220), from the nightly rollup (citation_url_daily, 00118), ChatGPT
--     Shopping left out: every one of the brand's own (at most a few
--     thousand, so its mix is whole), and the 1,000 others cited most; with
--     the total, so the share the list covers is known;
--   * the AI results strip: what AI-referred visitors did on the whole site
--     over the same days, as the Impact tab's results (00210) read one page:
--     visits by ai_traffic_merged's rule (00176), and Google Analytics' AI
--     key events, purchases and revenue; whether a property is set (the app
--     checks the connection too), and whether it reported any purchase.
--
-- The Plan's period is now 7, 30 or 90 days (a quarter), so
-- content_plan_pages (00220) is redefined to take 90 as well, and to say
-- since when the brand is tracked: few brands have 180 days of history, so
-- at 90 days the earlier window is often only partly tracked, or not at all.
--
-- Security definer with an organization check, as 00209–00220.

create or replace function public.content_plan_insights(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  -- Whole days to yesterday, as the Plan's pages (00220).
  v_last date := (now() at time zone 'utc')::date - 1;
  v_day date;
  v_from timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_day := v_last - p_days + 1;
  v_from := v_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  cited as materialized (
    select d.url_id, sum(d.citations)::bigint as citations
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_day
      and d.day <= v_last
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id
  ),
  addresses as (
    select c.url_id, c.citations, cu.url, cu.title, cu.domain in (select domain from own_domains) as own
    from cited c
    join public.citation_urls cu on cu.id = c.url_id
  ),
  top_urls as (
    select a.* from addresses a where a.own
    union all
    (
      select a.* from addresses a
      where not a.own
      order by a.citations desc, a.url_id
      limit 1000
    )
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
  ),
  visits as (
    select count(*)::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
    union all
    select coalesce(sum(g.sessions), 0)::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      and g.date >= v_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  analytics as (
    select
      coalesce(sum(g.key_events), 0)::bigint as key_events,
      coalesce(sum(g.transactions), 0)::bigint as transactions,
      coalesce(sum(g.purchase_revenue), 0)::numeric as revenue
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.date >= v_day
      and g.date <= v_last
  )
  select jsonb_build_object(
    'days', p_days,
    'totalCitations', (select coalesce(sum(c.citations), 0) from cited c),
    'citations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'url', t.url,
          'title', t.title,
          'own', t.own,
          'citations', t.citations
        )
        order by t.citations desc, t.url
      )
      from top_urls t
    ), '[]'::jsonb),
    'results', (
      select jsonb_build_object(
        'visits', (select coalesce(sum(v.n), 0) from visits v),
        'keyEvents', a.key_events,
        'transactions', a.transactions,
        'revenue', a.revenue,
        'analytics', (
          select nullif(b.ga_property_id, '') is not null
          from public.brands b where b.id = p_brand_id
        ),
        'purchases', a.transactions > 0 or a.revenue > 0 or exists (
          select 1 from public.ga_channel_stats c
          where c.brand_id = p_brand_id
            and c.date >= v_day
            and c.date <= v_last
            and (c.transactions > 0 or c.purchase_revenue > 0)
        )
      )
      from analytics a
    )
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.content_plan_insights(uuid, integer) from public, anon;
grant execute on function public.content_plan_insights(uuid, integer) to authenticated, service_role;

comment on function public.content_plan_insights(uuid, integer) is
  'Content Editor (CE-014): the addresses AI answers cite for the brand over the last N (7, 30 or 90) whole UTC days to yesterday (from citation_url_daily): every own page and the 1,000 others cited most, with the total; and what AI-referred visitors did on the site: visits, Google Analytics AI key events, purchases and revenue. Security definer with an organization check.';

-- ─── content_plan_pages (00220), taking 90 days too ─────────────────────────
-- As 00220, with 90 days and the windows' tracking: 'prevFrom' and
-- 'trackedSince' tell the Plan when the earlier window isn't fully tracked.

create or replace function public.content_plan_pages(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_cur_day := v_last - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  url_counts as materialized (
    select d.url_id, d.platform, d.day >= v_cur_day as is_cur, sum(d.citations)::bigint as n
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day <= v_last
      and d.url_id in (select id from own_urls)
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id, d.platform, d.day >= v_cur_day
  ),
  url_totals as (
    select
      u.page_key,
      u.url,
      u.title,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    group by u.page_key, u.url, u.title
  ),
  pages as materialized (
    select
      t.page_key,
      -- The address cited most often stands for the page.
      (array_agg(t.url order by t.cur + t.prev desc, t.url))[1] as page,
      max(t.title) as title,
      sum(t.cur)::bigint as cur,
      sum(t.prev)::bigint as prev
    from url_totals t
    group by t.page_key
    order by sum(t.cur + t.prev) desc, t.page_key
    limit 100
  ),
  answers as (
    select
      r.platform,
      coalesce(sum(r.answers) filter (where r.day >= v_cur_day), 0)::bigint as cur,
      coalesce(sum(r.answers) filter (where r.day < v_cur_day), 0)::bigint as prev
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and r.day >= v_prev_day
      and r.day <= v_last
      and r.platform is distinct from 'chatgpt-shopping'
    group by r.platform
  ),
  per_platform as (
    select
      u.page_key,
      c.platform,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    where u.page_key in (select p.page_key from pages p)
      and c.platform is not null
    group by u.page_key, c.platform
  ),
  down as (
    -- A platform tracked in both windows, citing the page at a lower rate.
    select
      pp.page_key,
      array_agg(
        pp.platform
        order by pp.prev::numeric / a.prev - pp.cur::numeric / a.cur desc, pp.platform
      ) as platforms
    from per_platform pp
    join answers a on a.platform = pp.platform
    where a.prev > 0
      and a.cur > 0
      and pp.prev::numeric / a.prev > pp.cur::numeric / a.cur
    group by pp.page_key
  ),
  cur_answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= v_cur
      and pr.created_at < v_until
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  page_prompts as (
    select distinct u.page_key, a.prompt_id
    from public.prompt_result_citations prc
    join own_urls u on u.id = prc.url_id
    join cur_answers a on a.id = prc.prompt_result_id
    where prc.brand_id = p_brand_id
      and prc.created_at >= v_cur
      and prc.created_at < v_until
      and u.page_key in (select p.page_key from pages p)
  ),
  competing as (
    select a.page_key, b.page_key as other
    from page_prompts a
    join page_prompts b on b.prompt_id = a.prompt_id and b.page_key <> a.page_key
    group by a.page_key, b.page_key
    having count(*) >= 2
  ),
  page_overlaps as (
    select cm.page_key, count(*) as pages
    from competing cm
    group by cm.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page_key, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
    union all
    select lower(public.normalize_page_path(g.landing_page)), g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_cur_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  page_visits as (
    select v.page_key, sum(v.n) as visits
    from visits v
    where v.page_key in (select p.page_key from pages p)
    group by v.page_key
  )
  select jsonb_build_object(
    'days', p_days,
    -- The earlier window's first day, and the brand's first tracked day: a
    -- window before it is only partly tracked, or not at all.
    'prevFrom', v_prev_day,
    'trackedSince', (
      select min(r.day) from public.citation_result_daily r where r.brand_id = p_brand_id
    ),
    'answers', (
      select jsonb_build_object(
        'cur', coalesce(sum(a.cur), 0),
        'prev', coalesce(sum(a.prev), 0)
      )
      from answers a
    ),
    'pages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', p.page,
          'title', p.title,
          'citations', jsonb_build_object('cur', p.cur, 'prev', p.prev),
          'platformsDown', coalesce(to_jsonb(d.platforms[1:3]), '[]'::jsonb),
          'aiVisits', coalesce(pv.visits, 0),
          'overlaps', coalesce(o.pages, 0)
        )
        order by p.cur + p.prev desc, p.page
      )
      from pages p
      left join down d on d.page_key = p.page_key
      left join page_overlaps o on o.page_key = p.page_key
      left join page_visits pv on pv.page_key = p.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.content_plan_pages(uuid, integer) from public, anon;
grant execute on function public.content_plan_pages(uuid, integer) to authenticated, service_role;

comment on function public.content_plan_pages(uuid, integer) is
  'Content Editor (CE-014): the brand''s 100 most cited pages over the last N (7, 30 or 90) whole UTC days to yesterday and the N before, from the daily rollups: citations, the brand''s answers in each window, platforms citing at a lower rate, AI visits and how many of its other pages compete for the same prompts; with the earlier window''s first day and the brand''s first tracked day. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00222_cancellation_feedback.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00222: why a customer cancels, or asks for three days first
-- ============================================================================
-- Settings › Billing › Cancel Subscription asks what went wrong before the
-- plan is cancelled: a few reasons to tick and a message, both optional. The
-- customer then either cancels (at the end of the period, as before) or asks
-- the team to act within three days, and the plan stays as it is.
--
-- Each answer is e-mailed to the team (CANCEL_FEEDBACK_EMAILS on the server)
-- and kept here, so a failed e-mail loses nothing and the reasons can be
-- counted later.
--
-- Written and read by the Express server's service-role client only: RLS on,
-- no policies, and the default grants to anon and authenticated revoked (as
-- 00183 does), since the table holds customers' free-text messages.

create table if not exists public.cancellation_feedback (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  created_by uuid references auth.users (id) on delete set null,
  reasons text[] not null default '{}',
  message text not null default '' check (char_length(message) <= 2000),
  -- 'cancel': cancelled the plan; 'wait': asked the team to act within three days.
  choice text not null check (choice in ('cancel', 'wait')),
  -- The plan and its state when the answer was given.
  plan text,
  subscription_status text,
  -- What became of the e-mail: sent, refused, unknown or skipped (see backend/src/lib/email.js).
  email_status text,
  created_at timestamptz not null default now()
);

create index if not exists cancellation_feedback_org_created_idx
  on public.cancellation_feedback (organization_id, created_at desc);

alter table public.cancellation_feedback enable row level security;
revoke all on public.cancellation_feedback from anon, authenticated;

comment on table public.cancellation_feedback is
  'Why a customer cancels, or asks the team for three days first (Settings › Billing). E-mailed to CANCEL_FEEDBACK_EMAILS; server-only.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00223_mention_sentiment_override_api.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00223: "Sentiment is wrong" over the API and MCP (MS-13)
-- ============================================================================
-- override_mention_sentiment (00160) takes the person correcting from
-- auth.uid(), so it only works for a signed-in admin or manager. The API and
-- MCP tools authenticate with an API key and reach the database as the
-- service role, where auth.uid() is null.
--
-- Restated with p_user_id: the person the service role corrects for, the API
-- key's owner. It counts only for the service role; a signed-in caller is
-- always auth.uid(), whatever it passes. Either way the person must be an
-- admin or manager of the answer's organization, and the correction is logged
-- under their name, as from the dashboard.
--
-- The 3-argument function is dropped rather than overloaded: a call with
-- three arguments would match both, and the dashboard's call keeps working
-- through p_user_id's default.

drop function if exists public.override_mention_sentiment(uuid, text, text);

-- Returns jsonb { changed, previous, sentiment, override: { id, sentiment,
-- previous_sentiment, note, user_name, created_at } }. Raises:
--   42501  the person isn't an admin or manager of the answer's organization
--   P0002  no such answer
--   22023  not a sentiment, or an answer that doesn't name the brand
create or replace function public.override_mention_sentiment(
  p_result_id uuid,
  p_sentiment text,
  p_note      text default null,
  p_user_id   uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_row      record;
  v_user     record;
  v_day      date;
  v_note     text := nullif(btrim(coalesce(p_note, '')), '');
  v_override public.sentiment_overrides;
  -- Who corrects: the API key's owner for the service role, else the caller.
  v_person   uuid := case when auth.role() = 'service_role' then p_user_id else auth.uid() end;
begin
  if p_sentiment is null or p_sentiment not in ('positive', 'neutral', 'negative') then
    raise exception 'Invalid sentiment' using errcode = '22023';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'The note is longer than 500 characters' using errcode = '22023';
  end if;

  select pr.id, pr.brand_id, pr.sentiment, pr.mention_count, pr.created_at, b.organization_id
    into v_row
  from public.prompt_results pr
  join public.brands b on b.id = pr.brand_id
  where pr.id = p_result_id
  for update of pr;
  if not found then
    raise exception 'Answer not found' using errcode = 'P0002';
  end if;

  select p.id, p.full_name, p.role
    into v_user
  from public.profiles p
  where p.id = v_person
    and p.organization_id = v_row.organization_id
    and p.role = any (array['admin', 'manager']::public.user_role[]);
  if not found then
    raise exception 'Only admins and managers can correct a sentiment' using errcode = '42501';
  end if;

  -- Sentiment is only classified for answers that name the brand.
  if coalesce(v_row.mention_count, 0) <= 0 then
    raise exception 'This answer does not name the brand' using errcode = '22023';
  end if;

  if v_row.sentiment = p_sentiment then
    return jsonb_build_object('changed', false, 'previous', v_row.sentiment,
                              'sentiment', p_sentiment, 'override', null);
  end if;

  update public.prompt_results
     set sentiment = p_sentiment,
         visibility_score = greatest(0, least(100,
           coalesce(visibility_score, 0)
           - public.sentiment_visibility_bonus(v_row.sentiment)
           + public.sentiment_visibility_bonus(p_sentiment)))
   where id = p_result_id;

  insert into public.sentiment_overrides
    (result_id, brand_id, previous_sentiment, sentiment, note, user_id, user_name)
  values
    (p_result_id, v_row.brand_id, coalesce(v_row.sentiment, 'neutral'), p_sentiment, v_note,
     v_user.id, v_user.full_name)
  returning * into v_override;

  -- The answer's day in the rollups, now rather than at the nightly sweep.
  v_day := (v_row.created_at at time zone 'utc')::date;
  perform public.refresh_insights_daily(v_row.brand_id, v_day, v_day);
  perform public.refresh_mentions_daily(v_row.brand_id, v_day, v_day);

  return jsonb_build_object(
    'changed', true,
    'previous', v_override.previous_sentiment,
    'sentiment', v_override.sentiment,
    'override', jsonb_build_object(
      'id', v_override.id,
      'sentiment', v_override.sentiment,
      'previous_sentiment', v_override.previous_sentiment,
      'note', v_override.note,
      'user_name', v_override.user_name,
      'created_at', v_override.created_at));
end;
$$;

revoke execute on function public.override_mention_sentiment(uuid, text, text, uuid)
  from public, anon;
grant execute on function public.override_mention_sentiment(uuid, text, text, uuid)
  to authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00224_results_autovacuum.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00224: vacuum and analyze the answers and their citations daily
-- ============================================================================
-- prompt_results and prompt_result_citations only grow. At the default
-- scale factors, autovacuum's insert pass ran on them about every three
-- weeks, and analyze about every ten days on the citations (on 2026-10-21:
-- 78k answers and 784k citations inserted since their last vacuum).
--
-- The reads by brand and window (`idx_prompt_results_brand_created_cover`,
-- `prompt_result_citations_brand_created_cover_idx`) are about the latest
-- days, which were the very pages the visibility map didn't cover yet:
--   - their index-only scans still went to the heap, about 20k fetches for a
--     30-day window of the biggest brand, and a cold cache took seconds;
--   - the planner's statistics stopped before those days, so it estimated a
--     window of tens of thousands of citations as a single row.
--
-- At 1% of the rows inserted, the insert pass runs about once a day on each
-- table (about 6k answers and 50k citations a day now). It only reads the
-- pages that aren't all-visible yet, so a run stays small. Analyze runs at
-- 2% of the rows changed, about every other day.

alter table public.prompt_results set (
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

alter table public.prompt_result_citations set (
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00225_shopping_merchant_classification.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Shopping merchant classification needed for "Where AI sends shoppers"
-- and weekly Amazon share alerts (#1277, #1284).

alter table public.prompt_result_shopping_cards
  add column if not exists merchant_kind text,
  add column if not exists marketplace text,
  add column if not exists listing_id text;

alter table public.prompt_result_shopping_cards
  drop constraint if exists prompt_result_shopping_cards_merchant_kind_check;

alter table public.prompt_result_shopping_cards
  add constraint prompt_result_shopping_cards_merchant_kind_check
  check (merchant_kind is null or merchant_kind in ('own', 'marketplace', 'reseller'));

create index if not exists prompt_result_shopping_cards_amazon_share_idx
  on public.prompt_result_shopping_cards (brand_id, matched_brand_role, created_at)
  include (marketplace)
  where merchant_kind is not null;

comment on column public.prompt_result_shopping_cards.merchant_kind is
  'Destination kind from classifyMerchant: own, marketplace, or reseller. Null means the card has no merchant URL and cannot be classified.';
comment on column public.prompt_result_shopping_cards.marketplace is
  'Normalized marketplace id (for example amazon, ebay, walmart); null for own stores, resellers, and unclassified cards.';
comment on column public.prompt_result_shopping_cards.listing_id is
  'Marketplace-native listing identifier when it can be extracted safely (for example an Amazon ASIN).';

-- Return five complete rolling seven-day windows ending at p_as_of. Every
-- bucket covers exactly seven days, including when p_as_of falls mid-week.
-- Only brand-matched own products with a classified merchant destination
-- enter the denominator; cards without a merchant URL stay unclassified.
create or replace function public.shopping_amazon_share_weekly(
  p_brand_id uuid,
  p_as_of timestamptz default now()
)
returns table (
  week_start date,
  amazon_cards bigint,
  classified_cards bigint
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
#variable_conflict use_column
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1
    from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id
      and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  with weeks as (
    select
      g.i,
      p_as_of - (g.i + 1) * interval '7 days' as from_ts,
      p_as_of - g.i * interval '7 days' as to_ts
    from generate_series(0, 4) as g(i)
  )
  select
    (w.from_ts at time zone 'UTC')::date as week_start,
    count(c.id) filter (where c.marketplace = 'amazon') as amazon_cards,
    count(c.id) as classified_cards
  from weeks w
  left join public.prompt_result_shopping_cards c
    on c.brand_id = p_brand_id
   and c.matched_brand_role = 'own'
   and c.merchant_kind is not null
   and c.created_at >= w.from_ts
   and c.created_at < w.to_ts
  group by w.i, w.from_ts
  order by w.from_ts;
end;
$$;

revoke all on function public.shopping_amazon_share_weekly(uuid, timestamptz) from public, anon;
grant execute on function public.shopping_amazon_share_weekly(uuid, timestamptz) to authenticated, service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00226_content_reads_bounded.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00226: the Content Editor's reads, bounded by their window
-- ============================================================================
-- Four content reads, redefined after they were timed on production (the
-- reviews of #1287, #1292, #1308 and #1309). Each returns what it did; each
-- reads less to get there.
--
--   * content_page_overlap (00207): the window's answers come from
--     idx_prompt_results_brand_created_cover alone (an index-only scan), and
--     the prompts are picked where the citations meet them. A prompt filter
--     on the answers made the planner combine the prompt_id index with the
--     brand's and read about 16k heap blocks a call.
--   * content_draft_sources (00211) read every answer each source prompt
--     ever had, through the prompt_id index, and the citations' primary key
--     once per answer (8 s cold for a 92-prompt draft):
--       - the window's answers come from the cover index alone, for a draft
--         with prompts as well as one with a page, and the source prompts
--         are picked from them after;
--       - each prompt's answers are counted on that index; those naming the
--         brand come from the Mentions rollup (mentions_prompt_daily, 00157)
--         for the window's whole UTC days, and from the answer rows of its
--         first, partial day only;
--       - the fan-outs and the cited pages are read from each prompt's
--         latest 30 answers in the window, so "searched N×" and a page's
--         citations count those: they are the only answer rows fetched whole
--         (search_queries), and their citations a fifth of the window's.
--   * content_plan_pages (00220, as 00221 redefined it): the overlaps' pairs
--     take their window from the current answers alone. A date bound on the
--     citations too is estimated from prompt_result_citations' last analyze
--     (no index leads with created_at), at about one row for recent days,
--     and that plan rescanned the own addresses once per citation (15–19 s
--     at 7 days on the largest brand).
--   * content_plan_insights (00221) joined every address the brand had cited
--     in the window to citation_urls before keeping its own and the top
--     1,000. Now the own ids come from citation_urls' domain index first, the
--     rows are picked on the rollup's url ids, and only those picked are read
--     from citation_urls. The own list keeps the 5,000 cited most (a brand on
--     a large platform's domain has more), and each call is planned for its
--     own values (plan_cache_mode), as content_plan_pages is.
--
-- The index-only scans stay off the heap once prompt_results and
-- prompt_result_citations are vacuumed daily (00224), and that migration's
-- daily analyze keeps the planner's estimate of a recent window current.
-- Grants and comments carry over from 00207–00221 (create or replace); the
-- insights' comment is restated for its cap.

create or replace function public.content_page_overlap(
  p_brand_id uuid,
  p_prompt_ids uuid[],
  p_since timestamptz default now() - interval '30 days'
)
returns table (
  page text,
  title text,
  prompts_in_common integer,
  citations bigint,
  gsc_position numeric
)
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return;
  end if;
  if coalesce(cardinality(p_prompt_ids), 0) = 0 then
    return;
  end if;

  return query
  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  -- The window's answers, from the (brand_id, created_at) cover index
  -- alone. The prompts are picked in `cited`: a prompt filter here makes the
  -- planner combine the prompt_id index with the brand's and read the heap.
  answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= p_since
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  cited as (
    select ou.page_key, ou.url, ou.title, a.prompt_id
    from public.prompt_result_citations prc
    join answers a on a.id = prc.prompt_result_id
    join own_urls ou on ou.id = prc.url_id
    where prc.brand_id = p_brand_id
      and prc.created_at >= p_since
      and a.prompt_id = any(p_prompt_ids)
  ),
  pages as (
    select
      c.page_key,
      -- The address cited most often stands for the page.
      mode() within group (order by c.url) as page,
      max(c.title) as title,
      count(distinct c.prompt_id)::integer as prompts_in_common,
      count(*)::bigint as citations
    from cited c
    group by c.page_key
  ),
  google as (
    select
      g.page_key,
      round((sum(g.position * g.impressions) / nullif(sum(g.impressions), 0))::numeric, 1)
        as position
    from public.gsc_page_stats g
    where g.brand_id = p_brand_id
      and g.date >= (now() at time zone 'utc')::date - 28
      and g.page_key in (select p.page_key from pages p)
    group by g.page_key
  )
  select p.page, p.title, p.prompts_in_common, p.citations, gl.position
  from pages p
  left join google gl on gl.page_key = p.page_key
  order by p.prompts_in_common desc, p.citations desc, p.page
  limit 10;
end;
$$;

create or replace function public.content_draft_sources(
  p_draft_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_brand_id uuid;
  v_prompt_ids uuid[];
  v_page_key text;
  v_host text;
  v_since timestamptz;
  -- The window's first whole UTC day.
  v_first_day date;
  v_result jsonb;
begin
  select d.brand_id, d.prompt_ids, lower(public.normalize_page_path(d.source_url)),
    -- Lower-cased first: a scheme may be written HTTPS://.
    regexp_replace(substring(lower(d.source_url) from '^https?://([^/:?#]+)'), '^www\.', '')
    into v_brand_id, v_prompt_ids, v_page_key, v_host
  from public.content_drafts d
  where d.id = p_draft_id;

  if v_brand_id is null or (
    not exists (
      select 1 from public.brands b
      join public.profiles pf on pf.organization_id = b.organization_id
      where b.id = v_brand_id and pf.id = auth.uid()
    ) and auth.role() is distinct from 'service_role'
  ) then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'content_draft_sources: 1 to 90 days are needed' using errcode = '22023';
  end if;

  v_since := now() - make_interval(days => p_days);
  v_first_day := (v_since at time zone 'utc')::date + 1;
  -- A page on a site that isn't the brand's is no page of the brand's.
  if v_host is null or not exists (
    select 1 from public.brand_domains bd
    where bd.brand_id = v_brand_id
      and lower(regexp_replace(bd.domain, '^www\.', '')) = v_host
  ) then
    v_page_key := null;
  end if;

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = v_brand_id
  ),
  -- The page's addresses: its path on its host.
  page_urls as materialized (
    select cu.id
    from public.citation_urls cu
    where v_page_key is not null
      and cu.domain = v_host
      and lower(public.normalize_page_path(cu.url)) = v_page_key
  ),
  -- The window's answers, from idx_prompt_results_brand_created_cover alone
  -- (an index-only scan). The prompts are picked after this read: a prompt
  -- filter here makes the planner combine the prompt_id index with the
  -- brand's and read every answer each prompt ever had.
  window_answers as materialized (
    select pr.id, pr.prompt_id, pr.created_at
    from public.prompt_results pr
    where (v_page_key is not null or coalesce(cardinality(v_prompt_ids), 0) > 0)
      and pr.brand_id = v_brand_id
      and pr.created_at >= v_since
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  -- The prompts whose answers cited the page the draft optimizes.
  page_prompts as (
    select distinct wa.prompt_id
    from public.prompt_result_citations prc
    join window_answers wa on wa.id = prc.prompt_result_id
    where prc.url_id in (select pu.id from page_urls pu)
      and prc.brand_id = v_brand_id
      and prc.created_at >= v_since
  ),
  source_prompts as (
    select p.id, p.text, p.id = any(v_prompt_ids) as in_draft,
      p.id in (select prompt_id from page_prompts) as cites_page
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = v_brand_id
      and (p.id = any(v_prompt_ids) or p.id in (select prompt_id from page_prompts))
  ),
  -- The source prompts' answers in the window, newest first per prompt.
  answers as materialized (
    select wa.id, wa.prompt_id, wa.created_at,
      row_number() over (partition by wa.prompt_id order by wa.created_at desc) as recency
    from window_answers wa
    where wa.prompt_id in (select sp.id from source_prompts sp)
  ),
  -- The answers naming the brand: the window's whole UTC days from the
  -- Mentions rollup (mentions_prompt_daily, 00157), and its first, partial
  -- day from those answers' rows. A run still in progress joins the rollup
  -- when it completes.
  named as (
    select m.prompt_id, m.mention_answers as answers
    from public.mentions_prompt_daily m
    where m.brand_id = v_brand_id
      and m.day >= v_first_day
      and m.prompt_id in (select sp.id from source_prompts sp)
    union all
    select a.prompt_id, 1
    from answers a
    join public.prompt_results pr on pr.id = a.id
    where a.created_at < v_first_day::timestamp at time zone 'utc'
      and pr.mention_count > 0
  ),
  prompt_counts as (
    select a.prompt_id, a.answers, coalesce(n.mentioned, 0) as mentioned
    from (select prompt_id, count(*) as answers from answers group by prompt_id) a
    left join (
      select prompt_id, sum(answers) as mentioned from named group by prompt_id
    ) n on n.prompt_id = a.prompt_id
  ),
  -- The only answer rows read: each prompt's latest 30.
  sampled as (
    select pr.id, pr.platform, pr.search_queries
    from answers a
    join public.prompt_results pr on pr.id = a.id
    where a.recency <= 30
  ),
  fanout_rows as (
    select
      a.id as answer_id,
      lower(trim(regexp_replace(q.item->>'query', '\s+', ' ', 'g'))) as norm,
      trim(regexp_replace(q.item->>'query', '\s+', ' ', 'g')) as query,
      coalesce(nullif(q.item->>'source_platform', ''), a.platform) as platform
    from sampled a
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(a.search_queries) = 'array' then a.search_queries else '[]'::jsonb end
    ) as q(item)
    where coalesce(trim(q.item->>'query'), '') <> ''
  ),
  fanouts as (
    select min(query) as query, array_agg(distinct platform order by platform) as platforms,
      count(distinct answer_id) as searched
    from fanout_rows
    group by norm
    order by count(distinct answer_id) desc, min(query)
    limit 30
  ),
  -- The citations of the same sample as the fan-outs, each prompt's latest
  -- 30 answers: every answer in the window is 100k+ citations on a large
  -- brand, read one answer at a time. Grouped by address first; only the
  -- top 20 addresses are read.
  cited_ids as (
    select prc.url_id, count(*) as citations, count(distinct prc.prompt_result_id) as answers
    from answers a
    join public.prompt_result_citations prc
      on prc.prompt_result_id = a.id
     and prc.brand_id = v_brand_id
     and prc.created_at >= v_since
    where a.recency <= 30
    group by prc.url_id
    order by count(*) desc, count(distinct prc.prompt_result_id) desc, prc.url_id
    limit 20
  ),
  cited as (
    select cu.url, cu.title, cu.domain, ci.citations, ci.answers
    from cited_ids ci
    join public.citation_urls cu on cu.id = ci.url_id
  ),
  queries as (
    select g.query, sum(g.clicks)::bigint as clicks, sum(g.impressions)::bigint as impressions
    from public.gsc_query_stats g
    where g.brand_id = v_brand_id
      and g.date >= (now() at time zone 'utc')::date - 28
    group by g.query
    order by sum(g.clicks) desc, sum(g.impressions) desc, g.query
    limit 300
  )
  select jsonb_build_object(
    'prompts', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', sp.id,
          'text', sp.text,
          'inDraft', sp.in_draft,
          'citesPage', sp.cites_page,
          'answers', coalesce(pc.answers, 0),
          'mentioned', coalesce(pc.mentioned, 0)
        ) order by sp.in_draft desc, sp.text)
      from source_prompts sp
      left join prompt_counts pc on pc.prompt_id = sp.id
    ), '[]'::jsonb),
    'fanouts', coalesce((
      select jsonb_agg(jsonb_build_object(
          'query', f.query, 'platforms', to_jsonb(f.platforms), 'searched', f.searched
        ) order by f.searched desc, f.query)
      from fanouts f
    ), '[]'::jsonb),
    'citedPages', coalesce((
      select jsonb_agg(jsonb_build_object(
          'url', c.url, 'title', c.title, 'domain', c.domain,
          'citations', c.citations, 'answers', c.answers
        ) order by c.citations desc, c.answers desc, c.url)
      from cited c
    ), '[]'::jsonb),
    'gscQueries', coalesce((
      select jsonb_agg(jsonb_build_object(
          'query', q.query, 'clicks', q.clicks, 'impressions', q.impressions
        ) order by q.clicks desc, q.impressions desc, q.query)
      from queries q
    ), '[]'::jsonb),
    'brandDomains', coalesce((select jsonb_agg(domain order by domain) from own_domains), '[]'::jsonb),
    'competitorDomains', coalesce((
      select jsonb_agg(distinct lower(regexp_replace(c.domain, '^www\.', '')))
      from public.competitors c
      where c.brand_id = v_brand_id and coalesce(c.domain, '') <> ''
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

create or replace function public.content_plan_pages(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_cur_day := v_last - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  url_counts as materialized (
    select d.url_id, d.platform, d.day >= v_cur_day as is_cur, sum(d.citations)::bigint as n
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day <= v_last
      and d.url_id in (select id from own_urls)
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id, d.platform, d.day >= v_cur_day
  ),
  url_totals as (
    select
      u.page_key,
      u.url,
      u.title,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    group by u.page_key, u.url, u.title
  ),
  pages as materialized (
    select
      t.page_key,
      -- The address cited most often stands for the page.
      (array_agg(t.url order by t.cur + t.prev desc, t.url))[1] as page,
      max(t.title) as title,
      sum(t.cur)::bigint as cur,
      sum(t.prev)::bigint as prev
    from url_totals t
    group by t.page_key
    order by sum(t.cur + t.prev) desc, t.page_key
    limit 100
  ),
  answers as (
    select
      r.platform,
      coalesce(sum(r.answers) filter (where r.day >= v_cur_day), 0)::bigint as cur,
      coalesce(sum(r.answers) filter (where r.day < v_cur_day), 0)::bigint as prev
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and r.day >= v_prev_day
      and r.day <= v_last
      and r.platform is distinct from 'chatgpt-shopping'
    group by r.platform
  ),
  per_platform as (
    select
      u.page_key,
      c.platform,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    where u.page_key in (select p.page_key from pages p)
      and c.platform is not null
    group by u.page_key, c.platform
  ),
  down as (
    -- A platform tracked in both windows, citing the page at a lower rate.
    select
      pp.page_key,
      array_agg(
        pp.platform
        order by pp.prev::numeric / a.prev - pp.cur::numeric / a.cur desc, pp.platform
      ) as platforms
    from per_platform pp
    join answers a on a.platform = pp.platform
    where a.prev > 0
      and a.cur > 0
      and pp.prev::numeric / a.prev > pp.cur::numeric / a.cur
    group by pp.page_key
  ),
  cur_answers as materialized (
    select pr.id, pr.prompt_id
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.created_at >= v_cur
      and pr.created_at < v_until
      and pr.platform is distinct from 'chatgpt-shopping'
  ),
  -- The window comes from cur_answers: a citation carries its answer's
  -- created_at. A date bound on prc too would be estimated from
  -- prompt_result_citations' last analyze (no index leads with created_at),
  -- at about one row for recent days, and that plan rescans own_urls once
  -- per citation.
  page_prompts as (
    select distinct u.page_key, a.prompt_id
    from public.prompt_result_citations prc
    join own_urls u on u.id = prc.url_id
    join cur_answers a on a.id = prc.prompt_result_id
    where prc.brand_id = p_brand_id
      and u.page_key in (select p.page_key from pages p)
  ),
  competing as (
    select a.page_key, b.page_key as other
    from page_prompts a
    join page_prompts b on b.prompt_id = a.prompt_id and b.page_key <> a.page_key
    group by a.page_key, b.page_key
    having count(*) >= 2
  ),
  page_overlaps as (
    select cm.page_key, count(*) as pages
    from competing cm
    group by cm.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page_key, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
    union all
    select lower(public.normalize_page_path(g.landing_page)), g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_cur_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  page_visits as (
    select v.page_key, sum(v.n) as visits
    from visits v
    where v.page_key in (select p.page_key from pages p)
    group by v.page_key
  )
  select jsonb_build_object(
    'days', p_days,
    -- The earlier window's first day, and the brand's first tracked day: a
    -- window before it is only partly tracked, or not at all.
    'prevFrom', v_prev_day,
    'trackedSince', (
      select min(r.day) from public.citation_result_daily r where r.brand_id = p_brand_id
    ),
    'answers', (
      select jsonb_build_object(
        'cur', coalesce(sum(a.cur), 0),
        'prev', coalesce(sum(a.prev), 0)
      )
      from answers a
    ),
    'pages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', p.page,
          'title', p.title,
          'citations', jsonb_build_object('cur', p.cur, 'prev', p.prev),
          'platformsDown', coalesce(to_jsonb(d.platforms[1:3]), '[]'::jsonb),
          'aiVisits', coalesce(pv.visits, 0),
          'overlaps', coalesce(o.pages, 0)
        )
        order by p.cur + p.prev desc, p.page
      )
      from pages p
      left join down d on d.page_key = p.page_key
      left join page_overlaps o on o.page_key = p.page_key
      left join page_visits pv on pv.page_key = p.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

create or replace function public.content_plan_insights(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  -- Whole days to yesterday, as the Plan's pages (00220).
  v_last date := (now() at time zone 'utc')::date - 1;
  v_day date;
  v_from timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_day := v_last - p_days + 1;
  v_from := v_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  -- The brand's own addresses, through citation_urls' domain index, as
  -- content_plan_pages' own_urls (00220).
  own_ids as materialized (
    select cu.id
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  cited as materialized (
    select d.url_id, sum(d.citations)::bigint as citations
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_day
      and d.day <= v_last
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id
  ),
  chosen as (
    (
      select c.url_id, c.citations, true as own
      from cited c
      where exists (select 1 from own_ids o where o.id = c.url_id)
      order by c.citations desc, c.url_id
      limit 5000
    )
    union all
    (
      select c.url_id, c.citations, false
      from cited c
      where not exists (select 1 from own_ids o where o.id = c.url_id)
      order by c.citations desc, c.url_id
      limit 1000
    )
  ),
  top_urls as (
    select ch.url_id, ch.citations, ch.own, cu.url, cu.title
    from chosen ch
    join public.citation_urls cu on cu.id = ch.url_id
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
  ),
  visits as (
    select count(*)::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_from
      and l.created_at < v_until
    union all
    select coalesce(sum(g.sessions), 0)::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      and g.date >= v_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  analytics as (
    select
      coalesce(sum(g.key_events), 0)::bigint as key_events,
      coalesce(sum(g.transactions), 0)::bigint as transactions,
      coalesce(sum(g.purchase_revenue), 0)::numeric as revenue
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.date >= v_day
      and g.date <= v_last
  )
  select jsonb_build_object(
    'days', p_days,
    'totalCitations', (select coalesce(sum(c.citations), 0) from cited c),
    'citations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'url', t.url,
          'title', t.title,
          'own', t.own,
          'citations', t.citations
        )
        order by t.citations desc, t.url
      )
      from top_urls t
    ), '[]'::jsonb),
    'results', (
      select jsonb_build_object(
        'visits', (select coalesce(sum(v.n), 0) from visits v),
        'keyEvents', a.key_events,
        'transactions', a.transactions,
        'revenue', a.revenue,
        'analytics', (
          select nullif(b.ga_property_id, '') is not null
          from public.brands b where b.id = p_brand_id
        ),
        'purchases', a.transactions > 0 or a.revenue > 0 or exists (
          select 1 from public.ga_channel_stats c
          where c.brand_id = p_brand_id
            and c.date >= v_day
            and c.date <= v_last
            and (c.transactions > 0 or c.purchase_revenue > 0)
        )
      )
      from analytics a
    )
  )
  into v_result;

  return v_result;
end;
$$;

comment on function public.content_plan_insights(uuid, integer) is
  'Content Editor (CE-014): the addresses AI answers cite for the brand over the last N (7, 30 or 90) whole UTC days to yesterday (from citation_url_daily): its own pages (the 5,000 cited most) and the 1,000 others cited most, with the total; and what AI-referred visitors did on the site: visits, Google Analytics AI key events, purchases and revenue. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00227_content_rule_sets_site_type.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00227: a workspace's own rules per kind of site (Content Editor, CE-009)
-- ============================================================================
-- My rules (00214) were kept per organization and page type. Since the page
-- types follow the brand's kind of site (00205), a type such as "guide" (a
-- How-to guide) is written on a B2B site, a shop and a travel site alike, so
-- a set saved for one brand applied to the same organization's brands of
-- another kind, with rules meant for that site.
--
--   * content_rule_sets gets site_type, the brand's kind of site when the set
--     was saved (b2b, ecommerce or b2c, as brands.site_type), and the key
--     becomes (organization_id, site_type, page_type).
--   * A set saved before keeps applying where it did: it is copied to each
--     kind of site. The member policies are by organization and stay as they
--     are.

alter table public.content_rule_sets
  add column if not exists site_type text not null default 'b2b'
    check (site_type in ('b2b', 'ecommerce', 'b2c'));

alter table public.content_rule_sets drop constraint if exists content_rule_sets_pkey;
alter table public.content_rule_sets
  add constraint content_rule_sets_pkey primary key (organization_id, site_type, page_type);

insert into public.content_rule_sets (
  organization_id, site_type, page_type, overrides, text_rules, updated_by, updated_at
)
select r.organization_id, s.site_type, r.page_type, r.overrides, r.text_rules, r.updated_by,
  r.updated_at
from public.content_rule_sets r
cross join (values ('ecommerce'), ('b2c')) as s(site_type)
where r.site_type = 'b2b'
on conflict do nothing;

-- Every save names its kind of site.
alter table public.content_rule_sets alter column site_type drop default;

comment on column public.content_rule_sets.site_type is
  'Content Editor (CE-009): the kind of site the set is for (b2b, ecommerce or b2c, as brands.site_type); a brand''s drafts start from its own kind''s set.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00228_profiles_server_columns.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00228: a profile's role and organization are set by the server
-- ============================================================================
-- Roles change through team management, and a person joins an organization
-- through an invitation; both run with the service role. A member's own
-- update of their profile is for their name, avatar and onboarding state.
--
-- The one organization a person sets for themselves is the first, in
-- onboarding: right after creating it, while it has no other member. This
-- trigger keeps a profile's own update to that:
--   - `role` only changes with the service role;
--   - `organization_id` only changes with the service role, or from null to
--     an organization nobody else belongs to yet.

create or replace function public.organization_has_other_members(p_org uuid, p_except uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
    where p.organization_id = p_org and p.id <> p_except
  );
$$;
revoke all on function public.organization_has_other_members(uuid, uuid) from public, anon;
grant execute on function public.organization_has_other_members(uuid, uuid) to authenticated, service_role;

create or replace function public.guard_profile_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;
  if new.role is distinct from old.role then
    raise exception 'profile role is managed server-side' using errcode = '42501';
  end if;
  if new.organization_id is distinct from old.organization_id
     and (
       old.organization_id is not null
       or new.organization_id is null
       or public.organization_has_other_members(new.organization_id, new.id)
     )
  then
    raise exception 'profile organization is managed server-side' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_server_columns on public.profiles;
create trigger profiles_guard_server_columns
  before update on public.profiles
  for each row execute function public.guard_profile_server_columns();

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00229_content_plan_marks.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00229: the Content plan's row marks — priority and hidden (CE-014)
-- ============================================================================
-- The Plan's priority list is built on each read (content_plan_pages, 00221,
-- and the brand's open opportunities), so a row has no row of its own to
-- keep a choice on. Admins and managers mark a row as a priority, or hide
-- it, per brand:
--
--   * content_plan_marks: one row per brand and Plan row, keyed as the app
--     keys the rows: 'opportunity:<id>' or 'page:<host/path>'. priority puts
--     the row at the top of the list with a Priority tag; hidden_at takes it
--     off the list until someone shows it again. Hiding an opportunity's row
--     also dismisses the opportunity (the app does it through its status),
--     so the Opportunities page agrees; restore_status is the status it had,
--     given back when the row is shown again.
--   * Members of the brand's organization read the marks; admins and managers
--     write them, as they do the workspace's rule sets (00214).

create table if not exists public.content_plan_marks (
  brand_id uuid not null references public.brands(id) on delete cascade,
  row_key text not null check (char_length(row_key) between 1 and 600),
  priority boolean not null default false,
  hidden_at timestamptz,
  restore_status text check (restore_status in ('new', 'reviewed', 'sent', 'in_progress')),
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (brand_id, row_key)
);

alter table public.content_plan_marks enable row level security;

create policy "content_plan_marks: member select"
  on public.content_plan_marks
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

create policy "content_plan_marks: manager insert"
  on public.content_plan_marks
  for insert
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
    and updated_by = auth.uid()
  );

create policy "content_plan_marks: manager update"
  on public.content_plan_marks
  for update
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  )
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
    and updated_by = auth.uid()
  );

grant select, insert, update on public.content_plan_marks to authenticated;

comment on table public.content_plan_marks is
  'Content Editor (CE-014): an admin''s or manager''s marks on a Content plan row — priority (top of the list) or hidden (off it until shown again), with the opportunity''s status to give back.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00230_content_start_prompts.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00230: New content's prompts, marked where the brand already shows (CE-003)
-- ============================================================================
-- New content › Create from scratch › Prompt starts a page for a tracked
-- prompt. A prompt the brand is already named in or cited for needs no new
-- page, so Start lists the others; the editor's "Add source" still offers
-- every prompt.
--
--   * content_start_prompts(brand, days): the brand's active prompts, each
--     marked seen when an answer in the last p_days UTC days (today included)
--     named the brand or cited one of its pages, from the prompt-grain
--     Insights rollup (insights_prompt_daily, its (brand_id, day) index).
--     Those not seen come first, each group by text, up to p_limit; seen
--     counts every seen prompt, past the limit too, for Start's note.
--   * As the content reads (00226) are: plpgsql planned for its own values
--     (plan_cache_mode), security definer with the organization check made
--     explicit, null to a caller outside the brand's organization.

create or replace function public.content_start_prompts(
  p_brand_id uuid,
  p_days     integer default 30,
  p_limit    integer default 500
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_days  integer := least(greatest(coalesce(p_days, 30), 1), 365);
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 2000);
  v_result jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  with seen as (
    select distinct d.prompt_id
    from public.insights_prompt_daily d
    where d.brand_id = p_brand_id
      and d.day > current_date - v_days
      and (d.has_mention or d.has_citation)
  ),
  active as (
    select p.id, p.text, (s.prompt_id is not null) as seen
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    left join seen s on s.prompt_id = p.id
    where ps.brand_id = p_brand_id
      and p.is_active
  ),
  listed as (
    select a.id, a.text, a.seen
    from active a
    order by a.seen, a.text
    limit v_limit
  )
  select jsonb_build_object(
           'prompts', coalesce(
             (select jsonb_agg(jsonb_build_object('id', l.id, 'text', l.text, 'seen', l.seen)
                               order by l.seen, l.text)
              from listed l),
             '[]'::jsonb),
           'seen', (select count(*) from active a where a.seen))
  into v_result;

  return v_result;
end;
$$;

revoke execute on function public.content_start_prompts(uuid, integer, integer) from public, anon;
grant execute on function public.content_start_prompts(uuid, integer, integer) to authenticated, service_role;

comment on function public.content_start_prompts(uuid, integer, integer) is
  'Content Editor New content (CE-003): the brand''s active prompts, each marked seen when an answer in the last p_days UTC days named the brand or cited its pages (insights_prompt_daily); not seen first, by text, up to p_limit, with the count of seen ones. Security definer, planned with its arguments; null when the caller is not a member of the brand''s organization.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00231_mentions_perception_rollups.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00231: daily rollups for the Perception tab (Mentions & Sentiment, MS-09)
-- ============================================================================
-- mentions_perception (00161) read every answer's terms for the window and
-- the window before it, unnested per call: 30 days read 60 days of
-- mentions_answer_terms. On production the Perception tab's 30 and 90 days
-- failed on every try at the authenticated 8 s timeout (2026-10-21, the
-- GetCito brand; ~10 s cold at 30 days on the largest brand in #1124's
-- review). The terms are now counted once a day, when they are written. This
-- migration adds the rollups and keeps them current; 00237 moves the read
-- onto them once they are filled:
--
--   * mentions_entities_daily: per brand, UTC day, platform and region, the
--     answers naming each entity ('brand' or a competitor's id), and how many
--     of those name the brand too. Exact: the tab's mention counts, its top
--     competitors and its co-mentions come from here.
--   * mentions_terms_daily: per brand, day, platform, region and entity, the
--     answers each term is next to. A term is kept when it is among any
--     entity's 200 most frequent that day, platform and region, and then for
--     every entity there: the attributes heat map compares the entities on
--     the same terms, so a competitor's count of a term another entity uses a
--     lot must not be cut short (a cap per entity left those cells 25–60%
--     short on the largest brand). A rarer term's count can still come out
--     short on the days it missed every entity's 200, the price of a bounded
--     table (keeping every term would be 3.7× the rows).
--   * One row per key on both (unique, nulls not distinct), as 00192 gave the
--     Mentions rollups: the advisory lock alone kept a day from being counted
--     twice. The terms' key leads with the entity, so the read takes only the
--     entities the tab shows (5 of the largest brand's 19).
--   * refresh_mention_terms_daily(brand, from, to) rebuilds a day range from
--     mentions_answer_terms. refresh_mention_terms (00161) calls it after
--     writing the same days' terms, in the same transaction; the server's
--     deleted-prompt rebuild calls it for the days a deleted prompt leaves
--     (its terms rows went with its answers). Service-role only.
--
-- The history is not filled here: on production it would hold a lock on
-- brands (the tables reference it) for minutes, past the statement timeout.
-- Apply in this order:
--   1. this migration;
--   2. the server (its deleted-prompt rebuild calls refresh_mention_terms_daily);
--   3. `node src/scripts/backfillMentionTermsDaily.js` (server), which
--      rebuilds each brand's history a week per call;
--   4. 00237, the read.

-- ─── Tables ─────────────────────────────────────────────────────────────────

create table if not exists public.mentions_entities_daily (
  brand_id   uuid not null references public.brands(id) on delete cascade,
  day        date not null,
  platform   text not null,
  region     text,
  -- 'brand', or the competitor's id.
  entity     text not null,
  -- Answers naming it.
  answers    integer not null,
  -- Of those, answers naming the brand too.
  with_brand integer not null
);

create unique index if not exists mentions_entities_daily_key
  on public.mentions_entities_daily (brand_id, day, platform, region, entity)
  nulls not distinct;

create table if not exists public.mentions_terms_daily (
  brand_id uuid not null references public.brands(id) on delete cascade,
  day      date not null,
  platform text not null,
  region   text,
  entity   text not null,
  term     text not null,
  -- Answers whose sentences naming the entity hold the term.
  answers  integer not null
);

-- The entity first: the read joins the shown entities to it.
create unique index if not exists mentions_terms_daily_key
  on public.mentions_terms_daily (brand_id, entity, day, platform, region, term)
  nulls not distinct;

-- Read through mentions_perception (security definer) only.
alter table public.mentions_entities_daily enable row level security;
alter table public.mentions_terms_daily enable row level security;

comment on table public.mentions_entities_daily is
  'Mentions Perception (00231): per brand, UTC day, platform, region and entity, the answers naming it and those naming the brand too. Rebuilt from mentions_answer_terms by refresh_mention_terms_daily.';
comment on table public.mentions_terms_daily is
  'Mentions Perception (00231): per brand, UTC day, platform, region and entity, the answers next to each term among any entity''s 200 most frequent that day, platform and region. Rebuilt from mentions_answer_terms by refresh_mention_terms_daily.';

-- ─── Refresh ────────────────────────────────────────────────────────────────

create or replace function public.refresh_mention_terms_daily(
  p_brand_id uuid,
  p_day_from date,
  p_day_to   date
) returns void
language plpgsql
set search_path to 'public'
as $$
declare
  v_from timestamptz := p_day_from::timestamp at time zone 'utc';
  v_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
begin
  -- One rebuild per brand at a time: a run's refresh and the deleted-prompt
  -- rebuild can cover the same days. The lock releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_mention_terms_daily:' || p_brand_id::text, 0));

  -- The terms' key leads with the entity, so their rows go by the entities
  -- those days name (the same rows the entities' come from), before those.
  delete from public.mentions_terms_daily
    where brand_id = p_brand_id
      and entity in (
        select distinct e.entity
        from public.mentions_entities_daily e
        where e.brand_id = p_brand_id and e.day between p_day_from and p_day_to)
      and day between p_day_from and p_day_to;
  delete from public.mentions_entities_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;

  insert into public.mentions_entities_daily (
    brand_id, day, platform, region, entity, answers, with_brand)
  select p_brand_id, x.day, x.platform, x.region, x.entity,
         count(*), count(*) filter (where x.with_brand)
  from (
    select (t.created_at at time zone 'utc')::date as day, t.platform, t.region, t.entity,
           bool_or(t.entity = 'brand') over (partition by t.result_id) as with_brand
    from public.mentions_answer_terms t
    where t.brand_id = p_brand_id
      and t.created_at >= v_from
      and t.created_at < v_to
  ) x
  group by x.day, x.platform, x.region, x.entity;

  with c as materialized (
    select (t.created_at at time zone 'utc')::date as day, t.platform, t.region, t.entity,
           term, count(*)::integer as answers
    from public.mentions_answer_terms t
    cross join lateral unnest(t.terms) as term
    where t.brand_id = p_brand_id
      and t.created_at >= v_from
      and t.created_at < v_to
    group by 1, 2, 3, 4, 5
  ),
  -- The terms among any entity's 200 most frequent of a day, platform and
  -- region, kept for every entity there. coalesce rather than "is not
  -- distinct from", so the join below can hash.
  keep as (
    select distinct r.day, r.platform, coalesce(r.region, '') as region_key, r.term
    from (
      select c.day, c.platform, c.region, c.term,
             row_number() over (
               partition by c.day, c.platform, c.region, c.entity
               order by c.answers desc, c.term) as rn
      from c
    ) r
    where r.rn <= 200
  )
  insert into public.mentions_terms_daily (
    brand_id, day, platform, region, entity, term, answers)
  select p_brand_id, c.day, c.platform, c.region, c.entity, c.term, c.answers
  from c
  join keep k on k.day = c.day and k.platform = c.platform
             and k.region_key = coalesce(c.region, '') and k.term = c.term;
end;
$$;

revoke execute on function public.refresh_mention_terms_daily(uuid, date, date)
  from public, anon, authenticated;

-- 00161's terms refresh, unchanged but for the rollups at its end.

create or replace function public.refresh_mention_terms(
  p_brand_id uuid,
  p_day_from date,
  p_day_to   date
) returns void
language plpgsql
set search_path to 'public'
as $$
declare
  -- The range's bounds as instants, so the answers are found by range.
  v_from timestamptz := p_day_from::timestamp at time zone 'utc';
  v_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
begin
  -- One refresh per brand at a time, as refresh_mentions_daily (00192): a
  -- run's refresh and the nightly sweep can cover the same days, and the
  -- second insert would fail on the (result_id, entity) key. The lock
  -- releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_mention_terms:' || p_brand_id::text, 0));

  delete from public.mentions_answer_terms
    where brand_id = p_brand_id and created_at >= v_from and created_at < v_to;

  -- The terms next to each entity an answer names, matched by the same names
  -- tracking counts: the brand's name and domains, each competitor's name
  -- and domain.
  with brand_names as (
    select array_remove(array[b.name] || coalesce(
             (select array_agg(bd.domain) from public.brand_domains bd where bd.brand_id = b.id),
             '{}'), null) as names
    from public.brands b
    where b.id = p_brand_id
  ),
  competitor_names as (
    select c.id::text as entity, array_remove(array[c.name, nullif(c.domain, '')], null) as names
    from public.competitors c
    where c.brand_id = p_brand_id
  ),
  name_words as (
    select coalesce(array_agg(distinct w), '{}') as words
    from (
      select regexp_split_to_table(lower(n), '[^[:alnum:]-]+') as w
      from (
        select unnest(names) as n from brand_names
        union all
        select unnest(names) from competitor_names
      ) all_names
    ) split
    where w <> ''
  )
  insert into public.mentions_answer_terms (
    brand_id, result_id, created_at, prompt_id, platform, region, entity, terms)
  select
    p_brand_id, pr.id, pr.created_at, pr.prompt_id, pr.platform, pr.region, e.entity,
    public.mention_terms(
      pr.response,
      e.names,
      (select words from name_words) || regexp_split_to_array(lower(p.text), '[^[:alnum:]-]+'))
  from public.prompt_results pr
  join public.prompts p on p.id = pr.prompt_id
  cross join lateral (
    select 'brand'::text as entity, (select names from brand_names) as names
    where pr.mention_count > 0
    union all
    select cn.entity, cn.names
    from competitor_names cn
    where exists (
      select 1
      from jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
      where cm.value->>'competitor_id' = cn.entity
        and coalesce((cm.value->>'mention_count')::int, 0) > 0)
  ) e
  where pr.brand_id = p_brand_id
    and pr.prompt_id is not null
    and pr.platform <> 'chatgpt-shopping'
    and pr.created_at >= v_from
    and pr.created_at < v_to;

  -- The Perception tab's daily rollups of the same days (00231), in the
  -- same transaction, so they never lag the terms.
  perform public.refresh_mention_terms_daily(p_brand_id, p_day_from, p_day_to);
end;
$$;

revoke execute on function public.refresh_mention_terms(uuid, date, date)
  from public, anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00232_prompt_results_metrics_cover.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00232: the Prompts table's visibility and positions from an index alone
-- ============================================================================
-- On production the Prompts page's read failed after a tab switch
-- (2026-10-21, React #441 with a request at the 8.6 s authenticated
-- timeout), and the page showed "No prompts yet" (#1324 makes it say the
-- read failed). Its two window reads over the brand's answers both go to
-- the heap for every answer:
--
--   * prompt_visibility_summaries (00072) sums visibility_score,
--     mention_count, citation_count and mention_position;
--   * prompt_position_summaries_json (00153) sums mention_count,
--     mention_position and mentioned_entity_count, for the window and the
--     one before it.
--
-- idx_prompt_results_brand_created_cover (citations_domains) carries the
-- columns those reads filter on but not the ones they add up, and a
-- prompt_results row carries the whole answer text, so each answer is its
-- own page read (8–25 s cold for a 30-day window there).
--
--   1. idx_prompt_results_brand_created_metrics: the same key, the cover
--      index's columns and those figures, so both reads (and every read the
--      cover index serves) come from the index alone. Build it on production
--      with CREATE INDEX CONCURRENTLY before this runs; `if not exists` makes
--      it a no-op there. The cover index then serves nothing this one
--      doesn't: drop it (DROP INDEX CONCURRENTLY) once the plans show this
--      one in use.
--   2. prompt_visibility_summaries, the same rows: plpgsql planned for each
--      call's window (plan_cache_mode), security definer with the
--      organization check made explicit (the brand's rows only, instead of
--      prompt_results' row policy per answer), as the content reads (00226)
--      and prompt_position_summaries_json (00153) are. A caller outside the
--      brand's organization gets no rows, as row security gave before.

create index if not exists idx_prompt_results_brand_created_metrics
  on public.prompt_results (brand_id, created_at desc)
  include (id, platform, model_used, region, prompt_id,
           visibility_score, mention_count, citation_count,
           mention_position, mentioned_entity_count);

-- Dropped first: a database that ran another body with other columns can't
-- take the new one through create or replace.
drop function if exists public.prompt_visibility_summaries(uuid, timestamptz, timestamptz, text);

create function public.prompt_visibility_summaries(
  p_brand_id  uuid,
  p_date_from timestamptz default null,
  p_date_to   timestamptz default null,
  p_region    text default null
)
returns table (
  prompt_id              uuid,
  avg_visibility         double precision,
  avg_visibility_visible double precision,
  total_mentions         bigint,
  total_citations        bigint,
  runs                   bigint,
  visible_runs           bigint,
  mention_answers        bigint,
  citation_answers       bigint,
  position_factor        double precision,
  last_run_at            timestamptz
)
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  select pr.prompt_id,
         avg(coalesce(pr.visibility_score, 0))::double precision,
         (avg(coalesce(pr.visibility_score, 0))
            filter (where pr.mention_count > 0 or pr.citation_count > 0))::double precision,
         coalesce(sum(pr.mention_count), 0)::bigint,
         coalesce(sum(pr.citation_count), 0)::bigint,
         count(*)::bigint,
         count(*) filter (where pr.mention_count > 0 or pr.citation_count > 0)::bigint,
         count(*) filter (where pr.mention_count > 0)::bigint,
         count(*) filter (where pr.citation_count > 0)::bigint,
         (avg(1.0 / pr.mention_position)
            filter (where pr.mention_position is not null))::double precision,
         max(pr.created_at)
  from public.prompt_results pr
  where pr.brand_id = p_brand_id
    and pr.prompt_id is not null
    and pr.platform <> 'chatgpt-shopping'  -- #155 - isolate from analytics
    and (p_date_from is null or pr.created_at >= p_date_from)
    and (p_date_to   is null or pr.created_at <= p_date_to)
    and (p_region    is null or pr.region = p_region)
  group by pr.prompt_id;
end;
$$;

revoke execute on function public.prompt_visibility_summaries(uuid, timestamptz, timestamptz, text)
  from public, anon;
grant execute on function public.prompt_visibility_summaries(uuid, timestamptz, timestamptz, text)
  to authenticated, service_role;

comment on function public.prompt_visibility_summaries(uuid, timestamptz, timestamptz, text) is
  'Per-prompt visibility/mention aggregates for the All Prompts table. p_region scopes to one tracked location (#691); NULL blends every location. Planned with its arguments and read from idx_prompt_results_brand_created_metrics (00232); security definer, no rows when the caller is not a member of the brand''s organization.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00233_content_drafts_archive.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00233: archive and delete Library drafts (Content Editor, CE-002)
-- ============================================================================
-- The Library's rows get a menu (the user's request): a status to pick, Send
-- to Archive, and Delete. Admins and managers archive and delete, as they
-- hide the Plan's rows (00229); every member can still change a status.
--
--   * content_drafts.archived_at / archived_by: an archived draft keeps its
--     status, so Restore puts it back where it was. Archive is not a status:
--     the Agent API, MCP and the editor read the four statuses unchanged.
--   * guard_content_draft_archive: only an admin or a manager of the brand's
--     organization (or the server) sets or clears archived_at; archived_by is
--     the person who archived, set here rather than trusted from the app. A
--     member's new draft is never archived: an insert with either column set
--     is refused (42501), as guard_content_draft_server_columns refuses its
--     columns.
--   * content_drafts_action_work_key (00218), one draft per action, method
--     and page, now counts only drafts not archived. A task's Start skips an
--     archived draft (readActionDrafts), so it writes a new one rather than
--     fail on the old key; restoring the archived one while a newer one does
--     the same work is refused (23505), and the Library says so.
--   * "content_drafts: manager delete": content_drafts had no delete policy,
--     so no member could delete a draft. Its versions, sources and
--     suggestions go with it (on delete cascade); the Action Center task it
--     was sent as stays, and Improve usage keeps its row (set null).

alter table public.content_drafts
  add column if not exists archived_at timestamptz,
  add column if not exists archived_by uuid references public.profiles(id) on delete set null;

comment on column public.content_drafts.archived_at is
  'When an admin or manager archived the draft (Library › Archived); null when it is not archived. It keeps its status.';
comment on column public.content_drafts.archived_by is
  'Who archived the draft; set by guard_content_draft_archive.';

create or replace function public.guard_content_draft_archive()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    -- A role that bypasses RLS is server-side (service role, migrations).
    if (new.archived_at is not null or new.archived_by is not null)
       and not (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)
    then
      raise exception 'a new content draft is not archived'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.archived_at is not distinct from old.archived_at then
    -- archived_by follows archived_at only.
    new.archived_by := old.archived_by;
    return new;
  end if;

  -- A role that bypasses RLS is server-side (service role, migrations).
  if not (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)
     and not exists (
       select 1
       from public.brands b
       join public.profiles p on p.organization_id = b.organization_id
       where b.id = new.brand_id
         and p.id = auth.uid()
         and p.role in ('admin', 'manager')
     )
  then
    raise exception 'only admins and managers archive content drafts'
      using errcode = '42501';
  end if;

  new.archived_by := case when new.archived_at is null then null else auth.uid() end;
  return new;
end;
$$;

create or replace trigger content_drafts_guard_archive
  before insert or update on public.content_drafts
  for each row execute function public.guard_content_draft_archive();

drop index if exists public.content_drafts_action_work_key;
create unique index if not exists content_drafts_action_work_key
  on public.content_drafts (action_id, method, md5(coalesce(source_url, '')))
  where action_id is not null and archived_at is null;

comment on index public.content_drafts_action_work_key is
  'Content Editor (CE-022, 00233): one draft not archived per action, method and page.';

create policy "content_drafts: manager delete"
  on public.content_drafts
  for delete
  using (
    brand_id in (
      select b.id
      from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  );

grant delete on public.content_drafts to authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00234_getting_started_plan_steps.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00234: Getting started's content steps open the Content Plan (AC-ALT2)
-- ============================================================================
-- The user's request: Getting started's "Create your first content" and
-- "Optimize a page" steps now open two items of the Content Plan (CE-014)
-- in New content's Start, the Plan's top Create row and its top Optimize
-- row, instead of Content Opportunities and Site Audit.
--
-- getting_started_facts (00197) counts what the Content Editor finished
-- too, so those steps complete there:
--   * drafts_created: the brand's "create" drafts made ready or published;
--   * drafts_optimized: its "optimize" drafts made ready or published.
-- Everything else is 00197's: the old ways to complete the steps (content
-- sent to the CMS or done, a page audited) still count, so a step already
-- done stays done.

create or replace function public.getting_started_facts(p_brand_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  select jsonb_build_object(
    'started_at', gs.started_at,
    'dismissed_at', gs.dismissed_at,
    'confirmed_at', gs.confirmed_at,
    'steps', coalesce((
      select jsonb_object_agg(s.step, jsonb_build_object('state', s.state, 'at', s.updated_at))
      from public.getting_started_steps s
      where s.brand_id = p_brand_id
    ), '{}'::jsonb),
    'kpi_setup_at', b.kpi_setup_at,
    'competitors', (
      select count(*) from public.competitors c where c.brand_id = p_brand_id
    ),
    -- Active prompts in each active topic, oldest topic first.
    'topic_prompts', coalesce((
      select jsonb_agg(n.prompts order by t.created_at, t.id)
      from public.topics t
      cross join lateral (
        select count(*) as prompts
        from public.prompts p
        join public.prompt_sets ps on ps.id = p.prompt_set_id
        where p.topic_id = t.id
          and p.is_active
          and ps.brand_id = p_brand_id
      ) n
      where t.brand_id = p_brand_id
        and t.is_active
    ), '[]'::jsonb),
    -- Connected for the organization and mapped to a property for the brand,
    -- as Settings › Integrations shows it.
    'gsc', nullif(b.gsc_property, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-search-console'
        and ic.status = 'connected'
    ),
    'ga', nullif(b.ga_property_id, '') is not null and exists (
      select 1 from public.integration_connections ic
      where ic.organization_id = b.organization_id
        and ic.provider = 'google-analytics'
        and ic.status = 'connected'
    ),
    'first_answer', exists (
      select 1 from public.prompt_results r where r.brand_id = p_brand_id
    ),
    'first_visit', exists (
      select 1 from public.ai_traffic_logs l where l.brand_id = p_brand_id
    ),
    -- Prompt suggestions built from Search Console and Analytics data.
    'data_suggestions', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga')
    ),
    'data_tracked', (
      select count(*) from public.prompt_suggestions s
      where s.brand_id = p_brand_id and s.source in ('gsc', 'ga') and s.status = 'added'
    ),
    'content_suggestions', (
      select count(*) from public.content_opportunities o where o.brand_id = p_brand_id
    ),
    -- Picked: reviewed, sent to the Action Center or given a brief (00106).
    'content_picked', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status in ('reviewed', 'sent', 'in_progress', 'done') or o.brief is not null)
    ),
    -- Created: its work was completed, or it went to the CMS webhook. There
    -- is no published state until the Content Editor.
    'content_created', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (o.status = 'done' or o.webhook_sent_at is not null)
    ),
    -- Content in the last 30 days, the same way: for the existing-customer
    -- rule (no content in 30 days → offer Getting started).
    'content_recent', (
      select count(*) from public.content_opportunities o
      where o.brand_id = p_brand_id
        and (
          o.webhook_sent_at >= now() - interval '30 days'
          or (o.status = 'done' and o.updated_at >= now() - interval '30 days')
        )
    ),
    -- Content Editor drafts (00204) made ready or published, by method: the
    -- create and optimize steps now open the Content Plan's rows (00234).
    'drafts_created', (
      select count(*) from public.content_drafts d
      where d.brand_id = p_brand_id
        and d.method = 'create'
        and d.status in ('ready', 'published')
    ),
    'drafts_optimized', (
      select count(*) from public.content_drafts d
      where d.brand_id = p_brand_id
        and d.method = 'optimize'
        and d.status in ('ready', 'published')
    ),
    -- Audits a person ran (not the automatic sweep, 00167) that finished.
    'audits', (
      select count(*) from public.site_audits a
      where a.brand_id = p_brand_id and a.source = 'user' and a.status = 'completed'
    )
  )
  from public.brands b
  left join public.getting_started gs on gs.brand_id = b.id
  where b.id = p_brand_id;
$$;

revoke all on function public.getting_started_facts(uuid) from public, anon;
grant execute on function public.getting_started_facts(uuid) to authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00235_service_write_policies_role.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00235: the service-role write policies apply to service_role
-- ============================================================================
-- These insert and delete policies were written for the server's writes but
-- created without a role, so they applied to every role. Only the server
-- (service_role) writes these tables, and service_role bypasses row security
-- anyway; scoping the policies to it leaves the server's writes as they are.

alter policy "Service role can insert prompt results" on public.prompt_results to service_role;
alter policy "Service role can delete prompt results" on public.prompt_results to service_role;

alter policy "Service role can insert citations" on public.prompt_result_citations to service_role;
alter policy "Service role can delete citations" on public.prompt_result_citations to service_role;

alter policy "Service role can insert shopping cards" on public.prompt_result_shopping_cards to service_role;
alter policy "Service role can delete shopping cards" on public.prompt_result_shopping_cards to service_role;

alter policy "Service role can insert signals" on public.signals to service_role;
alter policy "Service role can delete signals" on public.signals to service_role;

alter policy "Service role can insert traffic logs" on public.ai_traffic_logs to service_role;

alter policy "Service role can insert citation urls" on public.citation_urls to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00236_topics_overview_speed.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00236: the Topics tab's 24 hours and long windows, under the time it gets
-- ============================================================================
-- Measured on production on 2026-10-22, for the GetCito brand, as the page
-- runs it: the Topics tab's default 24 hours failed every time ("Failed to
-- load", the request ending at the authenticated role's 8 s statement
-- timeout), and 90 days took 5.9 s. 7 and 30 days took 2.9 and 3.5 s.
--
-- * 24 hours. topics_overview_window (00156, 00170) reads a window under two
--   days from the answers themselves: both windows' rows, each with its
--   competitor_mentions jsonb, which only the answer's row holds. Now the
--   counts come from idx_prompt_results_brand_created_metrics (00232) alone,
--   an index-only scan, and competitor_mentions is read for the window's
--   answers only, the half the competitor share counts. Output is 00170's.
-- * Longer windows read insights_prompt_daily and
--   insights_competitor_prompt_daily by (brand_id, day), then each row's
--   page for its figures. Covering indexes on the same key hold those
--   figures, so the reads are index-only; they replace the plain
--   (brand_id, day) indexes. On a large table, build them by hand first with
--   `create index concurrently` (and drop the old ones the same way), which
--   doesn't hold back the nightly refresh's writes; these statements then
--   find the work done.
-- * The morning health report (backend/src/lib/health) timed
--   topics_overview_aggregates, which the page stopped reading at 00156: its
--   fixed 30 days of raw answers ran past 20 s while the page itself never
--   waited on it. health_probe gains 'topics_overview_window', so the report
--   times the tab's own reads: 24 hours and 90 days.


create index if not exists idx_insights_prompt_daily_brand_day_cover
  on public.insights_prompt_daily (brand_id, day)
  include (prompt_id, answer_count, mention_answers, citation_answers, mentioning_answers,
           total_mentions, total_citations, sum_inv_position, position_count, max_created_at);

create index if not exists idx_insights_competitor_prompt_daily_brand_day_cover
  on public.insights_competitor_prompt_daily (brand_id, day)
  include (prompt_id, competitor_id, mention_count);

-- Each replaces the plain (brand_id, day) index (00066): same key, so every
-- read that used it can use these, and the planner no longer picks the
-- narrower one and fetches the rows anyway.
drop index if exists public.idx_insights_prompt_daily_brand_day;
drop index if exists public.idx_insights_competitor_prompt_daily_brand_day;

-- An index-only scan skips a row's page only once the visibility map covers
-- it. The nightly refresh rewrites the latest days of both tables, which at
-- the default scale factors autovacuum reached weeks later; as 00224 does for
-- the answers, vacuum and analyze them about daily.
alter table public.insights_prompt_daily set (
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

alter table public.insights_competitor_prompt_daily set (
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

create or replace function public.topics_overview_window(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null
)
returns table (
  topic_id              uuid,
  answers               bigint,
  mention_answers       bigint,
  citation_answers      bigint,
  pos_sum               double precision,
  pos_n                 bigint,
  prev_answers          bigint,
  prev_mention_answers  bigint,
  prev_citation_answers bigint,
  prev_pos_sum          double precision,
  prev_pos_n            bigint,
  total_mentions        bigint,
  total_citations       bigint,
  comp_mentions         bigint,
  active_prompts        bigint,
  visible_prompts       bigint,
  last_run_at           timestamptz,
  competitors           jsonb,
  daily                 jsonb
)
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
#variable_conflict use_column
declare
  v_to        timestamptz := coalesce(p_date_to, now());
  v_from      timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  -- Whole days the window spans, at least one, with an hour of slack: a
  -- rolling 7 days starts where the browser put it and ends at now(), a
  -- moment later, which must not make it 8 (lib/topicTrend.ts counts alike).
  v_days      integer;
  -- The rollup days of a longer window, and of the window before it.
  v_day_to    date;
  v_day_from  date;
  v_prev_from date;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return;
  end if;

  v_days := greatest(1, ceil(extract(epoch from (v_to - v_from)) / 86400.0 - 1.0 / 24)::integer);

  if v_days < 2 then
    return query
    with
    topic_prompts as (
      select p.id as prompt_id, p.topic_id
      from public.prompts p
      join public.prompt_sets ps on ps.id = p.prompt_set_id
      where ps.brand_id = p_brand_id
        and p.topic_id is not null
    ),
    -- Both windows' answers from idx_prompt_results_brand_created_metrics
    -- (00232) alone: every column read here is in the index, so the answers'
    -- rows (and their competitor_mentions) stay unread.
    rows as materialized (
      select tp.topic_id,
             pr.prompt_id,
             pr.created_at,
             (pr.created_at >= v_from)                        as in_window,
             coalesce(pr.mention_count, 0)                    as mentions,
             coalesce(pr.citation_count, 0)                   as citations,
             pr.mention_position,
             (coalesce(pr.mention_count, 0) > 0
               or coalesce(pr.citation_count, 0) > 0)         as visible
      from public.prompt_results pr
      join topic_prompts tp on tp.prompt_id = pr.prompt_id
      where pr.brand_id = p_brand_id
        and pr.platform <> 'chatgpt-shopping'
        and pr.created_at >= v_from - (v_to - v_from)
        and pr.created_at <= v_to
    ),
    -- The competitor share is the window's alone, so only the window's
    -- answers are read for their competitor_mentions: half the rows 00156
    -- read, and none of the window before.
    comps as (
      select tp.topic_id,
             cm.value->>'competitor_id'                              as competitor_id,
             min(c.name)                                             as name,
             sum(coalesce((cm.value->>'mention_count')::int, 0))::bigint as mentions
      from public.prompt_results pr
      join topic_prompts tp on tp.prompt_id = pr.prompt_id
      cross join lateral jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
      join public.competitors c on c.id::text = cm.value->>'competitor_id' and c.brand_id = p_brand_id
      where pr.brand_id = p_brand_id
        and pr.platform <> 'chatgpt-shopping'
        and pr.created_at >= v_from
        and pr.created_at <= v_to
      group by tp.topic_id, cm.value->>'competitor_id'
      having sum(coalesce((cm.value->>'mention_count')::int, 0)) > 0
    ),
    comp_totals as (
      select topic_id,
             sum(mentions)::bigint as comp_mentions,
             jsonb_object_agg(competitor_id, jsonb_build_object('name', name, 'sov', mentions))
               as competitors
      from comps
      group by topic_id
    ),
    main as (
      select r.topic_id,
             count(*) filter (where r.in_window)::bigint                          as answers,
             count(*) filter (where r.in_window and r.mentions > 0)::bigint       as mention_answers,
             count(*) filter (where r.in_window and r.citations > 0)::bigint      as citation_answers,
             coalesce(sum(1.0 / r.mention_position)
               filter (where r.in_window and r.mention_position > 0), 0)::double precision
                                                                                   as pos_sum,
             count(*) filter (where r.in_window and r.mention_position > 0)::bigint
                                                                                   as pos_n,
             count(*) filter (where not r.in_window)::bigint                      as prev_answers,
             count(*) filter (where not r.in_window and r.mentions > 0)::bigint   as prev_mention_answers,
             count(*) filter (where not r.in_window and r.citations > 0)::bigint  as prev_citation_answers,
             coalesce(sum(1.0 / r.mention_position)
               filter (where not r.in_window and r.mention_position > 0), 0)::double precision
                                                                                   as prev_pos_sum,
             count(*) filter (where not r.in_window and r.mention_position > 0)::bigint
                                                                                   as prev_pos_n,
             coalesce(sum(r.mentions) filter (where r.in_window), 0)::bigint      as total_mentions,
             coalesce(sum(r.citations) filter (where r.in_window), 0)::bigint     as total_citations,
             count(distinct r.prompt_id) filter (where r.in_window)::bigint       as active_prompts,
             count(distinct r.prompt_id) filter (where r.in_window and r.visible)::bigint
                                                                                   as visible_prompts,
             max(r.created_at) filter (where r.in_window)                         as last_run_at
      from rows r
      group by r.topic_id
    )
    select m.topic_id,
           m.answers, m.mention_answers, m.citation_answers, m.pos_sum, m.pos_n,
           m.prev_answers, m.prev_mention_answers, m.prev_citation_answers, m.prev_pos_sum, m.prev_pos_n,
           m.total_mentions, m.total_citations,
           coalesce(ct.comp_mentions, 0)::bigint,
           m.active_prompts, m.visible_prompts, m.last_run_at,
           coalesce(ct.competitors, '{}'::jsonb),
           '{}'::jsonb
    from main m
    left join comp_totals ct on ct.topic_id = m.topic_id
    where m.answers > 0;
    return;
  end if;

  v_day_to := (v_to at time zone 'UTC')::date;
  v_day_from := v_day_to - (v_days - 1);
  v_prev_from := v_day_from - v_days;

  return query
  with
  topic_prompts as (
    select p.id as prompt_id, p.topic_id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and p.topic_id is not null
  ),
  -- The brand's rows of both windows, read by (brand_id, day) and only then
  -- matched to the topics' prompts (see the header).
  prompt_rows as materialized (
    select d.prompt_id,
           d.day,
           d.answer_count,
           d.mention_answers,
           d.citation_answers,
           d.mentioning_answers,
           d.total_mentions,
           d.total_citations,
           d.sum_inv_position,
           d.position_count,
           d.max_created_at
    from public.insights_prompt_daily d
    where d.brand_id = p_brand_id
      and d.day between v_prev_from and v_day_to
  ),
  days as (
    select tp.topic_id,
           r.prompt_id,
           r.day,
           (r.day >= v_day_from) as in_window,
           r.answer_count,
           r.mention_answers,
           r.citation_answers,
           r.mentioning_answers,
           r.total_mentions,
           r.total_citations,
           r.sum_inv_position,
           r.position_count,
           r.max_created_at
    from prompt_rows r
    join topic_prompts tp on tp.prompt_id = r.prompt_id
  ),
  sightings as materialized (
    select cpd.prompt_id, cpd.competitor_id, cpd.mention_count
    from public.insights_competitor_prompt_daily cpd
    where cpd.brand_id = p_brand_id
      and cpd.day between v_day_from and v_day_to
  ),
  comps as (
    select tp.topic_id,
           s.competitor_id,
           min(c.name)                   as name,
           sum(s.mention_count)::bigint  as mentions
    from sightings s
    join topic_prompts tp     on tp.prompt_id = s.prompt_id
    join public.competitors c on c.id::text = s.competitor_id and c.brand_id = p_brand_id
    group by tp.topic_id, s.competitor_id
    having sum(s.mention_count) > 0
  ),
  comp_totals as (
    select topic_id,
           sum(mentions)::bigint as comp_mentions,
           jsonb_object_agg(competitor_id, jsonb_build_object('name', name, 'sov', mentions))
             as competitors
    from comps
    group by topic_id
  ),
  -- A point per UTC day, keyed as the client builds its keys
  -- (Date.toISOString()).
  daily as (
    select x.topic_id,
           jsonb_object_agg(x.day, jsonb_build_object('visible', x.visible, 'count', x.count))
             as daily
    from (
      select topic_id,
             to_char(day, 'YYYY-MM-DD')     as day,
             sum(mentioning_answers)::bigint as visible,
             sum(answer_count)::bigint       as count
      from days
      where in_window
      group by topic_id, day
    ) x
    group by x.topic_id
  ),
  -- Each topic's last answer in the window, from the rollups (00164).
  last_runs as (
    select topic_id, max(max_created_at) as last_run_at
    from days
    where in_window
    group by topic_id
  ),
  main as (
    select topic_id,
           coalesce(sum(answer_count) filter (where in_window), 0)::bigint         as answers,
           coalesce(sum(mention_answers) filter (where in_window), 0)::bigint      as mention_answers,
           coalesce(sum(citation_answers) filter (where in_window), 0)::bigint     as citation_answers,
           coalesce(sum(sum_inv_position) filter (where in_window), 0)::double precision
                                                                                   as pos_sum,
           coalesce(sum(position_count) filter (where in_window), 0)::bigint       as pos_n,
           coalesce(sum(answer_count) filter (where not in_window), 0)::bigint     as prev_answers,
           coalesce(sum(mention_answers) filter (where not in_window), 0)::bigint  as prev_mention_answers,
           coalesce(sum(citation_answers) filter (where not in_window), 0)::bigint as prev_citation_answers,
           coalesce(sum(sum_inv_position) filter (where not in_window), 0)::double precision
                                                                                   as prev_pos_sum,
           coalesce(sum(position_count) filter (where not in_window), 0)::bigint   as prev_pos_n,
           coalesce(sum(total_mentions) filter (where in_window), 0)::bigint       as total_mentions,
           coalesce(sum(total_citations) filter (where in_window), 0)::bigint      as total_citations,
           count(distinct prompt_id) filter (where in_window and answer_count > 0)::bigint
                                                                                   as active_prompts,
           count(distinct prompt_id) filter (where in_window and mentioning_answers > 0)::bigint
                                                                                   as visible_prompts
    from days
    group by topic_id
  )
  select m.topic_id,
         m.answers, m.mention_answers, m.citation_answers, m.pos_sum, m.pos_n,
         m.prev_answers, m.prev_mention_answers, m.prev_citation_answers, m.prev_pos_sum, m.prev_pos_n,
         m.total_mentions, m.total_citations,
         coalesce(ct.comp_mentions, 0)::bigint,
         m.active_prompts, m.visible_prompts, lr.last_run_at,
         coalesce(ct.competitors, '{}'::jsonb),
         coalesce(dl.daily, '{}'::jsonb)
  from main m
  left join comp_totals ct on ct.topic_id = m.topic_id
  left join daily dl       on dl.topic_id = m.topic_id
  left join last_runs lr   on lr.topic_id = m.topic_id
  where m.answers > 0;
end;
$$;


revoke execute on function public.topics_overview_window(uuid, timestamptz, timestamptz)
  from public, anon;
grant execute on function public.topics_overview_window(uuid, timestamptz, timestamptz)
  to authenticated, service_role;

create or replace function public.health_probe(
  p_user_id uuid,
  p_brand_id uuid,
  p_probe text,
  p_days integer default null
) returns numeric
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  t0 timestamptz;
  ts_from timestamptz := case when p_days is null then null else now() - make_interval(days => p_days) end;
  day_from date := (now() at time zone 'utc')::date - coalesce(p_days, 0);
  page_day_from date := case when p_days is null then null
                             else (now() at time zone 'utc')::date - (p_days - 1) end;
  n bigint;
begin
  perform set_config('role', 'authenticated', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
    true
  );
  t0 := clock_timestamp();

  case p_probe
    when 'citations_window_stats' then
      select count(*) into n from public.citations_window_stats(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_domains' then
      select count(*) into n from public.citations_domains(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_urls' then
      select count(*) into n from public.citations_urls(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null,
        p_limit => 100, p_domains => null, p_exclude_domains => null);
    when 'citations_domains_daily' then
      select count(*) into n from public.citations_domains_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null);
    when 'citations_urls_daily' then
      select count(*) into n from public.citations_urls_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null,
        p_limit => 2000);
    when 'insights_aggregates_daily' then
      select count(*) into n from public.insights_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'competitor_aggregates_daily' then
      select count(*) into n from public.competitor_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'topics_overview_aggregates' then
      select count(*) into n from public.topics_overview_aggregates(p_brand_id => p_brand_id);
    -- What the Topics tab runs: its window, the last p_days days (a day when
    -- unset, the tab's default 24 hours).
    when 'topics_overview_window' then
      select count(*) into n from public.topics_overview_window(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 1)),
        p_date_to => null);
    else
      raise exception 'unknown health probe: %', p_probe;
  end case;

  return round(extract(epoch from clock_timestamp() - t0)::numeric, 2);
end;
$$;


revoke all on function public.health_probe(uuid, uuid, text, integer) from public, anon, authenticated;
grant execute on function public.health_probe(uuid, uuid, text, integer) to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00237_mentions_perception_read_rollups.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00237: the Perception tab reads the daily rollups (Mentions & Sentiment, MS-09)
-- ============================================================================
-- 00161's read, the same jsonb and the same rules. For whole UTC days (two
-- days or more) without a topic or a search, the rollups 00231 adds stand in
-- for the answers' terms; under two days, or filtered to some prompts, it
-- reads the answers' terms as before.
--
-- Apply it after 00231, the server and
-- `node src/scripts/backfillMentionTermsDaily.js` (server): this read
-- doesn't fall back to the answers' terms, so a day not yet in the rollups
-- would show as empty. Timed on production (as owner, rolled back): 30 days
-- 0.95 s and 90 days 1.36 s, against 6.2–16.3 s for 00161's read.

create or replace function public.mentions_perception(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to         timestamptz := coalesce(p_date_to, now());
  v_from       timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_days       integer;
  v_day_to     date;
  v_start      timestamptz;
  v_end        timestamptz;
  v_prev_start timestamptz;
  v_search     text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_rollup     boolean;
  v_start_day  date;
  v_end_day    date;
  v_prev_day   date;
  v_result     jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  v_days := greatest(1, ceil(extract(epoch from v_to - v_from) / 86400.0 - 1.0 / 24)::integer);
  if v_days < 2 then
    v_start := v_from;
    v_end   := v_to + interval '1 microsecond';
  else
    v_day_to := (v_to at time zone 'utc')::date;
    v_start  := (v_day_to - (v_days - 1))::timestamp at time zone 'utc';
    v_end    := (v_day_to + 1)::timestamp at time zone 'utc';
  end if;
  v_prev_start := v_start - (v_end - v_start);
  -- Whole UTC days with no topic or search read the daily rollups (00231);
  -- a window under two days, or a filter on the prompts, reads the answers'
  -- terms as before. The branch not taken is pruned (plan_cache_mode).
  v_rollup    := v_days >= 2 and p_topic_id is null and v_search is null;
  v_start_day := (v_start at time zone 'utc')::date;
  v_end_day   := (v_end at time zone 'utc')::date;
  v_prev_day  := (v_prev_start at time zone 'utc')::date;

  with
  prompts_in as (
    select p.id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  rows_in as (
    select t.result_id, t.entity, t.terms, (t.created_at >= v_start) as cur
    from public.mentions_answer_terms t
    join prompts_in pi on pi.id = t.prompt_id
    where not v_rollup
      and t.brand_id = p_brand_id
      and t.created_at >= v_prev_start
      and t.created_at < v_end
      and (p_platform is null or t.platform = p_platform)
      and (p_region is null or t.region = p_region)
  ),
  entity_counts as (
    select entity,
           count(*) filter (where cur)     as mentions,
           count(*) filter (where not cur) as prev_mentions
    from rows_in
    group by entity
    union all
    select d.entity,
           coalesce(sum(d.answers) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.answers) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
  ),
  shown as (
    select 'brand'::text as entity, 0 as rank
    union all
    select * from (
      select ec.entity, row_number() over (order by ec.mentions desc, ec.entity)::int
      from entity_counts ec
      join public.competitors co on co.id::text = ec.entity and co.brand_id = p_brand_id
      where ec.mentions > 0
      order by ec.mentions desc, ec.entity
      limit 4
    ) top_competitors
  ),
  term_counts_all as (
    select r.entity, term,
           count(*) filter (where r.cur)     as answers,
           count(*) filter (where not r.cur) as prev_answers
    from rows_in r
    join shown s on s.entity = r.entity
    cross join lateral unnest(r.terms) as term
    group by r.entity, term
    union all
    select d.entity, d.term,
           coalesce(sum(d.answers) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.answers) filter (where d.day < v_start_day), 0)
    from public.mentions_terms_daily d
    join shown s on s.entity = d.entity
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity, d.term
  ),
  -- Each entity's 60 most frequent terms are the candidates.
  candidates as (
    select entity, term, answers, prev_answers
    from (
      select t.*, row_number() over (partition by t.entity order by t.answers desc, t.term) as rn
      from term_counts_all t
      where t.answers > 0
    ) ranked
    where rn <= 60
  ),
  -- A word that nearly always comes in one phrase is that phrase: "fresh" and
  -- "roast" give way to "fresh roast" when it has 80% of their answers.
  term_counts as (
    select c.*
    from candidates c
    where position(' ' in c.term) > 0
       or not exists (
         select 1 from candidates p
         where p.entity = c.entity
           and position(' ' in p.term) > 0
           and (p.term like c.term || ' %' or p.term like '% ' || c.term)
           and p.answers >= 0.8 * c.answers)
  ),
  brand_terms as (
    select term, answers, prev_answers
    from term_counts
    where entity = 'brand' and answers > 0
    order by answers desc, term
    limit 15
  ),
  -- The terms that tell the brands apart most: the widest spread between the
  -- highest and lowest share of mentions, then the highest shares.
  attributes as (
    select u.term
    from (select distinct term from term_counts) u
    cross join shown s
    left join term_counts_all tc on tc.entity = s.entity and tc.term = u.term
    left join entity_counts ec on ec.entity = s.entity
    group by u.term
    order by
      max(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0))
        - min(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      sum(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      u.term
    limit 8
  ),
  -- A competitor's rows in answers that name the brand too, in one pass.
  co as (
    select x.entity,
           count(*) filter (where x.cur)     as co_mentions,
           count(*) filter (where not x.cur) as prev_co_mentions
    from (
      select r.entity, r.cur,
             bool_or(r.entity = 'brand') over (partition by r.result_id) as with_brand
      from rows_in r
    ) x
    where x.entity <> 'brand' and x.with_brand
    group by x.entity
    union all
    select d.entity,
           coalesce(sum(d.with_brand) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.with_brand) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.entity <> 'brand'
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
    having sum(d.with_brand) > 0
  )
  select jsonb_build_object(
    'window', jsonb_build_object('from', v_start, 'to', v_end, 'days', v_days),
    'entities', coalesce((
      select jsonb_agg(jsonb_build_object(
               'entity', s.entity,
               'name', case when s.entity = 'brand' then b.name else co.name end,
               'is_brand', s.entity = 'brand',
               'mentions', coalesce(ec.mentions, 0),
               'prev_mentions', coalesce(ec.prev_mentions, 0))
             order by s.rank)
      from shown s
      left join entity_counts ec on ec.entity = s.entity
      left join public.brands b on s.entity = 'brand' and b.id = p_brand_id
      left join public.competitors co on co.id::text = s.entity and co.brand_id = p_brand_id
    ), '[]'::jsonb),
    'brand_terms', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', bt.term, 'answers', bt.answers, 'prev_answers', bt.prev_answers)
             order by bt.answers desc, bt.term)
      from brand_terms bt
    ), '[]'::jsonb),
    'attributes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', a.term,
               'values', (
                 select jsonb_agg(jsonb_build_object(
                          'entity', s.entity, 'answers', coalesce(tc.answers, 0))
                        order by s.rank)
                 from shown s
                 left join term_counts_all tc on tc.entity = s.entity and tc.term = a.term)))
      from attributes a
    ), '[]'::jsonb),
    'co_mentions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'competitor_id', c.entity,
               'name', comp.name,
               'co_mentions', c.co_mentions,
               'prev_co_mentions', c.prev_co_mentions)
             order by c.co_mentions desc, comp.name)
      from co c
      join public.competitors comp on comp.id::text = c.entity and comp.brand_id = p_brand_id
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke execute on function public.mentions_perception(uuid, timestamptz, timestamptz, text, text, uuid, text)
  from public, anon;
grant execute on function public.mentions_perception(uuid, timestamptz, timestamptz, text, text, uuid, text)
  to authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00238_content_plan_pages_no_overlaps.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00238: content_plan_pages without the overlaps (Content Editor, CE-014)
-- ============================================================================
-- Since #1320 the Plan shows the brand's cited pages as an Overview, and
-- nothing reads content_plan_pages' `overlaps` any more (contentPlan.ts no
-- longer maps it). Its four steps (cur_answers, page_prompts, competing,
-- page_overlaps) were the only part of the read that walked prompt_results
-- and prompt_result_citations row by row: with a cold cache the 30-day call
-- took 8.7–9.5 s on the largest brand, over the 8 s statement timeout,
-- against 0.7 s (30 days) and 1.1 s (90 days) without them.
--
-- The function is otherwise 00226's, with the same signature, so its grants
-- and comment carry over (create or replace). 00237 is left for the Mentions
-- Perception read (#1325).

create or replace function public.content_plan_pages(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_cur_day := v_last - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  url_counts as materialized (
    select d.url_id, d.platform, d.day >= v_cur_day as is_cur, sum(d.citations)::bigint as n
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day <= v_last
      and d.url_id in (select id from own_urls)
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id, d.platform, d.day >= v_cur_day
  ),
  url_totals as (
    select
      u.page_key,
      u.url,
      u.title,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    group by u.page_key, u.url, u.title
  ),
  pages as materialized (
    select
      t.page_key,
      -- The address cited most often stands for the page.
      (array_agg(t.url order by t.cur + t.prev desc, t.url))[1] as page,
      max(t.title) as title,
      sum(t.cur)::bigint as cur,
      sum(t.prev)::bigint as prev
    from url_totals t
    group by t.page_key
    order by sum(t.cur + t.prev) desc, t.page_key
    limit 100
  ),
  answers as (
    select
      r.platform,
      coalesce(sum(r.answers) filter (where r.day >= v_cur_day), 0)::bigint as cur,
      coalesce(sum(r.answers) filter (where r.day < v_cur_day), 0)::bigint as prev
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and r.day >= v_prev_day
      and r.day <= v_last
      and r.platform is distinct from 'chatgpt-shopping'
    group by r.platform
  ),
  per_platform as (
    select
      u.page_key,
      c.platform,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    where u.page_key in (select p.page_key from pages p)
      and c.platform is not null
    group by u.page_key, c.platform
  ),
  down as (
    -- A platform tracked in both windows, citing the page at a lower rate.
    select
      pp.page_key,
      array_agg(
        pp.platform
        order by pp.prev::numeric / a.prev - pp.cur::numeric / a.cur desc, pp.platform
      ) as platforms
    from per_platform pp
    join answers a on a.platform = pp.platform
    where a.prev > 0
      and a.cur > 0
      and pp.prev::numeric / a.prev > pp.cur::numeric / a.cur
    group by pp.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page_key, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
    union all
    select lower(public.normalize_page_path(g.landing_page)), g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_cur_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  page_visits as (
    select v.page_key, sum(v.n) as visits
    from visits v
    where v.page_key in (select p.page_key from pages p)
    group by v.page_key
  )
  select jsonb_build_object(
    'days', p_days,
    -- The earlier window's first day, and the brand's first tracked day: a
    -- window before it is only partly tracked, or not at all.
    'prevFrom', v_prev_day,
    'trackedSince', (
      select min(r.day) from public.citation_result_daily r where r.brand_id = p_brand_id
    ),
    'answers', (
      select jsonb_build_object(
        'cur', coalesce(sum(a.cur), 0),
        'prev', coalesce(sum(a.prev), 0)
      )
      from answers a
    ),
    'pages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', p.page,
          'title', p.title,
          'citations', jsonb_build_object('cur', p.cur, 'prev', p.prev),
          'platformsDown', coalesce(to_jsonb(d.platforms[1:3]), '[]'::jsonb),
          'aiVisits', coalesce(pv.visits, 0)
        )
        order by p.cur + p.prev desc, p.page
      )
      from pages p
      left join down d on d.page_key = p.page_key
      left join page_visits pv on pv.page_key = p.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00239_mentions_list_index_only.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00239: the Mentions table's read from its index alone (Mentions & Sentiment)
-- ============================================================================
-- mentions_list (00158) read every mention in the window from the table,
-- each with its competitor_mentions jsonb, to count competitors named beside
-- the brand. On the largest brand that took 8.4 s cold at 30 days, past the
-- 8 s statement timeout, and 4.9 s at 90 days (prod, 2026-10-22). The user's
-- target is every Mentions & Sentiment tab under 3-4 s cold.
--
-- Two changes, with the same output for every filter, sort and group:
--   1. The partial index on the brand's mentions carries the columns the
--      window needs (id, prompt_id, platform, region, sentiment), so the
--      total, the prompt count and the page's order come from the index
--      alone. It replaces 00158's idx_prompt_results_brand_mentions, which
--      had the same key and predicate, so every read that used it can use
--      this one.
--   2. competitor_mentions is read only when the table sorts by competitors
--      named or filters by a competitor; the page's 100 rows still read it
--      for the names shown beside each answer.
--
-- On a large prompt_results, build the index by hand first, which doesn't
-- hold back tracking's writes; this migration then finds it in place:
--   create index concurrently if not exists idx_prompt_results_brand_mentions_cover
--     on public.prompt_results (brand_id, created_at desc)
--     include (id, prompt_id, platform, region, sentiment)
--     where mention_count > 0;
--   drop index concurrently if exists public.idx_prompt_results_brand_mentions;
--
-- health_probe also gains 'mentions_list' and 'mentions_perception', timed
-- over the last p_days days, so the morning report shows these reads.

create index if not exists idx_prompt_results_brand_mentions_cover
  on public.prompt_results (brand_id, created_at desc)
  include (id, prompt_id, platform, region, sentiment)
  where mention_count > 0;

drop index if exists public.idx_prompt_results_brand_mentions;

create or replace function public.mentions_list(
  p_brand_id      uuid,
  p_date_from     timestamptz,
  p_date_to       timestamptz default null,
  p_platform      text default null,
  p_region        text default null,
  p_topic_id      uuid default null,
  p_search        text default null,
  p_sentiment     text default null,
  p_competitor_id text default null,
  p_sort          text default 'newest',
  p_group         text default null,
  p_limit         integer default 100,
  p_offset        integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to       timestamptz := coalesce(p_date_to, now());
  v_from     timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_days     integer;
  v_day_to   date;
  v_start    timestamptz;
  v_end      timestamptz;
  v_search   text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_limit    integer := least(greatest(coalesce(p_limit, 100), 1), 100);
  v_offset   integer := greatest(coalesce(p_offset, 0), 0);
  v_group    text := case when p_group in ('prompt', 'platform') then p_group end;
  -- Only these read each answer's competitor_mentions: the rest of the
  -- table's choices are answered from the index alone.
  v_competitors boolean := p_sort = 'co_mentions' or p_competitor_id is not null;
  v_result   jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  -- The same window as mentions_overview's current one.
  v_days := greatest(1, ceil(extract(epoch from v_to - v_from) / 86400.0 - 1.0 / 24)::integer);
  if v_days < 2 then
    v_start := v_from;
    v_end   := v_to + interval '1 microsecond';
  else
    v_day_to := (v_to at time zone 'utc')::date;
    v_start  := (v_day_to - (v_days - 1))::timestamp at time zone 'utc';
    v_end    := (v_day_to + 1)::timestamp at time zone 'utc';
  end if;

  with
  prompts_in as (
    select p.id, p.text, p.topic_id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  -- The brand's mentions in the window, read first, through the partial
  -- index above, and only then joined to the prompts. Driven by the prompts
  -- instead, the planner walks each prompt's whole history: 8.8 s for 30
  -- days of the largest brand, against 0.2 s this way. Every column here is
  -- in that index, so the window is read without visiting the table.
  mention_rows as materialized (
    select pr.id, pr.created_at, pr.prompt_id, pr.platform, pr.sentiment
    from public.prompt_results pr
    where pr.brand_id = p_brand_id
      and pr.mention_count > 0
      and pr.platform <> 'chatgpt-shopping'
      and pr.created_at >= v_start
      and pr.created_at < v_end
      and (p_platform is null or pr.platform = p_platform)
      and (p_region is null or pr.region = p_region)
      and (p_sentiment is null
           or (p_sentiment in ('positive', 'negative') and pr.sentiment = p_sentiment)
           or (p_sentiment = 'neutral'
               and pr.sentiment is distinct from 'positive'
               and pr.sentiment is distinct from 'negative'))
  ),
  hits as (
    select m.id,
           m.created_at,
           m.prompt_id,
           pi.text as prompt_text,
           m.platform,
           m.sentiment,
           co.co_count,
           co.with_competitor
    from mention_rows m
    join prompts_in pi on pi.id = m.prompt_id
    -- Competitors named beside you (the array lists every competitor, named
    -- or not), read from the answer only when the sort or the competitor
    -- filter asks: otherwise v_competitors is false, the plan's one-time
    -- filter skips it, and co_count is never used.
    left join lateral (
      select (select count(*)
                from jsonb_array_elements(coalesce(x.competitor_mentions, '[]'::jsonb)) cm
               where cm.value ? 'competitor_id'
                 and coalesce((cm.value->>'mention_count')::int, 0) > 0) as co_count,
             (p_competitor_id is not null and p_competitor_id <> 'none' and exists (
                select 1
                  from jsonb_array_elements(coalesce(x.competitor_mentions, '[]'::jsonb)) cm
                 where cm.value->>'competitor_id' = p_competitor_id
                   and coalesce((cm.value->>'mention_count')::int, 0) > 0)) as with_competitor
      from public.prompt_results x
      where v_competitors and x.id = m.id
    ) co on true
  ),
  filtered as (
    select h.*,
           case v_group
             when 'prompt' then h.prompt_id::text
             when 'platform' then h.platform
           end as group_key
    from hits h
    where p_competitor_id is null
       or (p_competitor_id = 'none' and h.co_count = 0)
       or h.with_competitor
  ),
  grouped as (
    select f.*,
           case when v_group is not null
                then count(*) over (partition by f.group_key) end as group_count
    from filtered f
  ),
  page as (
    select g.*
    from grouped g
    order by
      case when v_group is not null then g.group_count end desc nulls last,
      case when v_group = 'prompt' then lower(g.prompt_text) end,
      g.group_key,
      case when p_sort = 'negative' then
        case g.sentiment when 'negative' then 0 when 'positive' then 2 else 1 end
      end,
      case when p_sort = 'co_mentions' then g.co_count end desc nulls last,
      case when p_sort = 'oldest' then g.created_at end,
      g.created_at desc,
      g.id
    limit v_limit
    offset v_offset
  ),
  rows_out as (
    select pg.*,
           pr.model_used,
           pr.region,
           pr.mention_count,
           pr.mention_position,
           pr.mentioned_entity_count,
           pr.response,
           pi.topic_id,
           t.name as topic_name,
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'competitor_id', cm.value->>'competitor_id',
                      'name', coalesce(co.name, cm.value->>'name'),
                      'mention_position', cm.value->'mention_position')
                    order by (cm.value->>'mention_position')::int nulls last,
                             coalesce(co.name, cm.value->>'name'))
               from jsonb_array_elements(coalesce(pr.competitor_mentions, '[]'::jsonb)) cm
               left join public.competitors co
                 on co.id::text = cm.value->>'competitor_id' and co.brand_id = p_brand_id
              where cm.value ? 'competitor_id'
                and coalesce((cm.value->>'mention_count')::int, 0) > 0
           ), '[]'::jsonb) as co_mentioned
    from page pg
    join public.prompt_results pr on pr.id = pg.id
    join prompts_in pi on pi.id = pg.prompt_id
    left join public.topics t on t.id = pi.topic_id
  )
  select jsonb_build_object(
    'total',   (select count(*) from filtered),
    'prompts', (select count(distinct prompt_id) from filtered),
    'rows',    coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id,
               'created_at', r.created_at,
               'prompt_id', r.prompt_id,
               'prompt_text', r.prompt_text,
               'topic_id', r.topic_id,
               'topic_name', r.topic_name,
               'platform', r.platform,
               'model_used', r.model_used,
               'region', r.region,
               'sentiment', r.sentiment,
               'mention_count', r.mention_count,
               'mention_position', r.mention_position,
               'mentioned_entity_count', r.mentioned_entity_count,
               'co_mentioned', r.co_mentioned,
               'response', r.response,
               'group_key', r.group_key,
               'group_count', r.group_count)
             order by
               case when v_group is not null then r.group_count end desc nulls last,
               case when v_group = 'prompt' then lower(r.prompt_text) end,
               r.group_key,
               case when p_sort = 'negative' then
                 case r.sentiment when 'negative' then 0 when 'positive' then 2 else 1 end
               end,
               case when p_sort = 'co_mentions' then r.co_count end desc nulls last,
               case when p_sort = 'oldest' then r.created_at end,
               r.created_at desc,
               r.id)
      from rows_out r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke execute on function public.mentions_list(
  uuid, timestamptz, timestamptz, text, text, uuid, text, text, text, text, text, integer, integer)
  from public, anon;
grant execute on function public.mentions_list(
  uuid, timestamptz, timestamptz, text, text, uuid, text, text, text, text, text, integer, integer)
  to authenticated, service_role;

create or replace function public.health_probe(
  p_user_id uuid,
  p_brand_id uuid,
  p_probe text,
  p_days integer default null
) returns numeric
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  t0 timestamptz;
  ts_from timestamptz := case when p_days is null then null else now() - make_interval(days => p_days) end;
  day_from date := (now() at time zone 'utc')::date - coalesce(p_days, 0);
  page_day_from date := case when p_days is null then null
                             else (now() at time zone 'utc')::date - (p_days - 1) end;
  n bigint;
begin
  perform set_config('role', 'authenticated', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
    true
  );
  t0 := clock_timestamp();

  case p_probe
    when 'citations_window_stats' then
      select count(*) into n from public.citations_window_stats(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_domains' then
      select count(*) into n from public.citations_domains(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_urls' then
      select count(*) into n from public.citations_urls(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null,
        p_limit => 100, p_domains => null, p_exclude_domains => null);
    when 'citations_domains_daily' then
      select count(*) into n from public.citations_domains_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null);
    when 'citations_urls_daily' then
      select count(*) into n from public.citations_urls_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null,
        p_limit => 2000);
    when 'insights_aggregates_daily' then
      select count(*) into n from public.insights_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'competitor_aggregates_daily' then
      select count(*) into n from public.competitor_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'topics_overview_aggregates' then
      select count(*) into n from public.topics_overview_aggregates(p_brand_id => p_brand_id);
    -- What the Topics tab runs: its window, the last p_days days (a day when
    -- unset, the tab's default 24 hours).
    when 'topics_overview_window' then
      select count(*) into n from public.topics_overview_window(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 1)),
        p_date_to => null);
    -- The Mentions & Sentiment tabs' reads over the last p_days days (a
    -- month when unset), as the page asks for them: the table's first page,
    -- newest first, and the Perception figures.
    when 'mentions_list' then
      perform public.mentions_list(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 30)),
        p_date_to => null);
    when 'mentions_perception' then
      perform public.mentions_perception(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 30)),
        p_date_to => null);
    else
      raise exception 'unknown health probe: %', p_probe;
  end case;

  return round(extract(epoch from clock_timestamp() - t0)::numeric, 2);
end;
$$;


revoke all on function public.health_probe(uuid, uuid, text, integer) from public, anon, authenticated;
grant execute on function public.health_probe(uuid, uuid, text, integer) to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00240_content_draft_suggestion_links.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00240: the links on an agent's replace suggestion
-- ============================================================================
-- Content Agent rule gaps, A: the agent could never meet the Internal links,
-- Outbound links or Cite sources inline rules, because a replace's new words
-- were plain text (00217) and it had nowhere to link to. The server now gives
-- it the brand's own pages and the draft's sources, and keeps a link only to
-- one of those URLs.
--
-- A replace's after_text stays plain text: the editor finds an accepted one
-- again by its words. Its links sit beside it, each the words from start to
-- end (offsets into after_text) linked to href, and the editor puts them on
-- as link marks when the suggestion is accepted. An insert keeps its links in
-- its HTML, as its other blocks.
alter table public.content_draft_suggestions
  add column if not exists after_links jsonb
    check (
      after_links is null
      or (
        kind = 'replace'
        and jsonb_typeof(after_links) = 'array'
        and jsonb_array_length(after_links) between 1 and 20
      )
    );

comment on column public.content_draft_suggestions.after_links is
  'A replace''s links: [{ "start", "end", "href" }], offsets into after_text (00240).';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00241_mentions_perception_snapshots.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00241: the Perception tab's default view, precomputed (Mentions & Sentiment, MS-09)
-- ============================================================================
-- 00237's rollup read took 0.95 s (30 days) and 1.36 s (90 days) warm on
-- production, but on 2026-10-23 the GetCito brand's first load took 8.7 s
-- at 30 days (past the 8 s statement timeout: "Couldn't load") and 8.1 s at
-- 90, its retry 5.3 s: a cold read of the rollups' pages. The target is
-- 2–3 s cold.
--
-- The view everyone opens, the last 7, 30 or 90 days on every platform and
-- region, with no topic or search, is now computed ahead: one row per brand
-- and window in mentions_perception_snapshots, refreshed by the server when
-- a brand's Mentions rollups are (each completed tracking run, the nightly
-- sweep, the deleted-prompt rebuild). Reading it is one primary-key lookup.
--
--   * mentions_perception_live: 00237's read, unchanged, without the access
--     check; only this file's functions call it.
--   * mentions_perception: the access check, then the brand's snapshot for
--     the window when it fits the request (a preset window up to now, no
--     filters, computed today or yesterday, UTC); otherwise the live read.
--     A snapshot from yesterday shows its own window, which ends at the end
--     of yesterday: the day's runs refresh it.
--   * refresh_mentions_perception_snapshot(brand, days): one window per
--     call, so the largest brand's 90 days stay well inside the service
--     role's statement timeout.
--   * A brand's snapshots are set aside when a competitor is renamed or
--     removed, or the brand is renamed: the live read stands in until the
--     next refresh, so names and the competitors shown never go stale.
--   * health_probe gains 'mentions_perception_live', timing the read a
--     filtered view (or a brand without a snapshot) still makes.

create table if not exists public.mentions_perception_snapshots (
  brand_id    uuid not null references public.brands(id) on delete cascade,
  days        smallint not null
    constraint mentions_perception_snapshots_days_check check (days in (7, 30, 90)),
  -- The UTC day the window ends on (its last whole day).
  day_to      date not null,
  payload     jsonb not null,
  computed_at timestamptz not null default now(),
  primary key (brand_id, days)
);

comment on table public.mentions_perception_snapshots is
  'The Perception tab''s default view (MS-09) per brand and window (7, 30 or 90 days, every platform and region, no topic or search), as mentions_perception returns it. Written by refresh_mentions_perception_snapshot; dropped when the brand''s competitors or name change.';

-- Service-role only, no policy: read through mentions_perception.
alter table public.mentions_perception_snapshots enable row level security;
revoke all on table public.mentions_perception_snapshots from anon, authenticated;
grant all on table public.mentions_perception_snapshots to service_role;

-- 00237's read, word for word, without the access check (mentions_perception keeps it).
create or replace function public.mentions_perception_live(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to         timestamptz := coalesce(p_date_to, now());
  v_from       timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_days       integer;
  v_day_to     date;
  v_start      timestamptz;
  v_end        timestamptz;
  v_prev_start timestamptz;
  v_search     text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_rollup     boolean;
  v_start_day  date;
  v_end_day    date;
  v_prev_day   date;
  v_result     jsonb;
begin
  v_days := greatest(1, ceil(extract(epoch from v_to - v_from) / 86400.0 - 1.0 / 24)::integer);
  if v_days < 2 then
    v_start := v_from;
    v_end   := v_to + interval '1 microsecond';
  else
    v_day_to := (v_to at time zone 'utc')::date;
    v_start  := (v_day_to - (v_days - 1))::timestamp at time zone 'utc';
    v_end    := (v_day_to + 1)::timestamp at time zone 'utc';
  end if;
  v_prev_start := v_start - (v_end - v_start);
  -- Whole UTC days with no topic or search read the daily rollups (00231);
  -- a window under two days, or a filter on the prompts, reads the answers'
  -- terms as before. The branch not taken is pruned (plan_cache_mode).
  v_rollup    := v_days >= 2 and p_topic_id is null and v_search is null;
  v_start_day := (v_start at time zone 'utc')::date;
  v_end_day   := (v_end at time zone 'utc')::date;
  v_prev_day  := (v_prev_start at time zone 'utc')::date;

  with
  prompts_in as (
    select p.id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  rows_in as (
    select t.result_id, t.entity, t.terms, (t.created_at >= v_start) as cur
    from public.mentions_answer_terms t
    join prompts_in pi on pi.id = t.prompt_id
    where not v_rollup
      and t.brand_id = p_brand_id
      and t.created_at >= v_prev_start
      and t.created_at < v_end
      and (p_platform is null or t.platform = p_platform)
      and (p_region is null or t.region = p_region)
  ),
  entity_counts as (
    select entity,
           count(*) filter (where cur)     as mentions,
           count(*) filter (where not cur) as prev_mentions
    from rows_in
    group by entity
    union all
    select d.entity,
           coalesce(sum(d.answers) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.answers) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
  ),
  shown as (
    select 'brand'::text as entity, 0 as rank
    union all
    select * from (
      select ec.entity, row_number() over (order by ec.mentions desc, ec.entity)::int
      from entity_counts ec
      join public.competitors co on co.id::text = ec.entity and co.brand_id = p_brand_id
      where ec.mentions > 0
      order by ec.mentions desc, ec.entity
      limit 4
    ) top_competitors
  ),
  term_counts_all as (
    select r.entity, term,
           count(*) filter (where r.cur)     as answers,
           count(*) filter (where not r.cur) as prev_answers
    from rows_in r
    join shown s on s.entity = r.entity
    cross join lateral unnest(r.terms) as term
    group by r.entity, term
    union all
    select d.entity, d.term,
           coalesce(sum(d.answers) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.answers) filter (where d.day < v_start_day), 0)
    from public.mentions_terms_daily d
    join shown s on s.entity = d.entity
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity, d.term
  ),
  -- Each entity's 60 most frequent terms are the candidates.
  candidates as (
    select entity, term, answers, prev_answers
    from (
      select t.*, row_number() over (partition by t.entity order by t.answers desc, t.term) as rn
      from term_counts_all t
      where t.answers > 0
    ) ranked
    where rn <= 60
  ),
  -- A word that nearly always comes in one phrase is that phrase: "fresh" and
  -- "roast" give way to "fresh roast" when it has 80% of their answers.
  term_counts as (
    select c.*
    from candidates c
    where position(' ' in c.term) > 0
       or not exists (
         select 1 from candidates p
         where p.entity = c.entity
           and position(' ' in p.term) > 0
           and (p.term like c.term || ' %' or p.term like '% ' || c.term)
           and p.answers >= 0.8 * c.answers)
  ),
  brand_terms as (
    select term, answers, prev_answers
    from term_counts
    where entity = 'brand' and answers > 0
    order by answers desc, term
    limit 15
  ),
  -- The terms that tell the brands apart most: the widest spread between the
  -- highest and lowest share of mentions, then the highest shares.
  attributes as (
    select u.term
    from (select distinct term from term_counts) u
    cross join shown s
    left join term_counts_all tc on tc.entity = s.entity and tc.term = u.term
    left join entity_counts ec on ec.entity = s.entity
    group by u.term
    order by
      max(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0))
        - min(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      sum(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      u.term
    limit 8
  ),
  -- A competitor's rows in answers that name the brand too, in one pass.
  co as (
    select x.entity,
           count(*) filter (where x.cur)     as co_mentions,
           count(*) filter (where not x.cur) as prev_co_mentions
    from (
      select r.entity, r.cur,
             bool_or(r.entity = 'brand') over (partition by r.result_id) as with_brand
      from rows_in r
    ) x
    where x.entity <> 'brand' and x.with_brand
    group by x.entity
    union all
    select d.entity,
           coalesce(sum(d.with_brand) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.with_brand) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.entity <> 'brand'
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
    having sum(d.with_brand) > 0
  )
  select jsonb_build_object(
    'window', jsonb_build_object('from', v_start, 'to', v_end, 'days', v_days),
    'entities', coalesce((
      select jsonb_agg(jsonb_build_object(
               'entity', s.entity,
               'name', case when s.entity = 'brand' then b.name else co.name end,
               'is_brand', s.entity = 'brand',
               'mentions', coalesce(ec.mentions, 0),
               'prev_mentions', coalesce(ec.prev_mentions, 0))
             order by s.rank)
      from shown s
      left join entity_counts ec on ec.entity = s.entity
      left join public.brands b on s.entity = 'brand' and b.id = p_brand_id
      left join public.competitors co on co.id::text = s.entity and co.brand_id = p_brand_id
    ), '[]'::jsonb),
    'brand_terms', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', bt.term, 'answers', bt.answers, 'prev_answers', bt.prev_answers)
             order by bt.answers desc, bt.term)
      from brand_terms bt
    ), '[]'::jsonb),
    'attributes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', a.term,
               'values', (
                 select jsonb_agg(jsonb_build_object(
                          'entity', s.entity, 'answers', coalesce(tc.answers, 0))
                        order by s.rank)
                 from shown s
                 left join term_counts_all tc on tc.entity = s.entity and tc.term = a.term)))
      from attributes a
    ), '[]'::jsonb),
    'co_mentions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'competitor_id', c.entity,
               'name', comp.name,
               'co_mentions', c.co_mentions,
               'prev_co_mentions', c.prev_co_mentions)
             order by c.co_mentions desc, comp.name)
      from co c
      join public.competitors comp on comp.id::text = c.entity and comp.brand_id = p_brand_id
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.mentions_perception_live(uuid, timestamptz, timestamptz, text, text, uuid, text)
  from public, anon, authenticated;
grant execute on function public.mentions_perception_live(uuid, timestamptz, timestamptz, text, text, uuid, text)
  to service_role;

create or replace function public.mentions_perception(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
as $$
declare
  v_to       timestamptz := coalesce(p_date_to, now());
  v_from     timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_days     integer;
  v_snapshot jsonb;
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) then
    return null;
  end if;

  -- The window's whole days, as mentions_perception_live counts them.
  v_days := greatest(1, ceil(extract(epoch from v_to - v_from) / 86400.0 - 1.0 / 24)::integer);
  if p_date_to is null
     and v_days in (7, 30, 90)
     and p_platform is null
     and p_region is null
     and p_topic_id is null
     and nullif(btrim(coalesce(p_search, '')), '') is null then
    select s.payload into v_snapshot
    from public.mentions_perception_snapshots s
    where s.brand_id = p_brand_id
      and s.days = v_days
      and s.day_to >= (now() at time zone 'utc')::date - 1;
    if v_snapshot is not null then
      return v_snapshot;
    end if;
  end if;

  return public.mentions_perception_live(
    p_brand_id, p_date_from, p_date_to, p_platform, p_region, p_topic_id, p_search);
end;
$$;

revoke execute on function public.mentions_perception(uuid, timestamptz, timestamptz, text, text, uuid, text)
  from public, anon;
grant execute on function public.mentions_perception(uuid, timestamptz, timestamptz, text, text, uuid, text)
  to authenticated, service_role;

-- One window of one brand's default view, computed now and kept. The
-- server calls it for 7, 30 and 90 days after it refreshes the brand's
-- Mentions rollups.
create or replace function public.refresh_mentions_perception_snapshot(
  p_brand_id uuid,
  p_days     integer
)
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_now timestamptz := now();
begin
  if p_days is null or p_days not in (7, 30, 90) then
    raise exception 'a Perception snapshot covers 7, 30 or 90 days, not %', p_days;
  end if;
  insert into public.mentions_perception_snapshots as s (brand_id, days, day_to, payload, computed_at)
  values (
    p_brand_id,
    p_days,
    (v_now at time zone 'utc')::date,
    public.mentions_perception_live(p_brand_id, v_now - make_interval(days => p_days)),
    v_now)
  on conflict (brand_id, days) do update
    set day_to = excluded.day_to,
        payload = excluded.payload,
        computed_at = excluded.computed_at
    -- A slower refresh that started earlier never writes over a newer one,
    -- nor over a snapshot set aside since (forget_mentions_perception_snapshots).
    where s.computed_at < excluded.computed_at;
end;
$$;

revoke all on function public.refresh_mentions_perception_snapshot(uuid, integer)
  from public, anon, authenticated;
grant execute on function public.refresh_mentions_perception_snapshot(uuid, integer)
  to service_role;

-- A competitor renamed or removed, or the brand renamed, changes what the
-- view lists: its snapshots are set aside (a day_to the read never takes),
-- and the live read stands in. Set aside, not deleted, and stamped now: a
-- refresh already under way when this ran (it started earlier) can't put
-- the old names back. A competitor added changes nothing yet: no answer
-- named it when the rollups were counted.
create or replace function public.forget_mentions_perception_snapshots()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  v_brands uuid[];
begin
  if tg_table_name = 'brands' then
    v_brands := array[new.id];
  elsif tg_op = 'UPDATE' then
    v_brands := array[old.brand_id, new.brand_id];
  else
    v_brands := array[old.brand_id];
  end if;
  update public.mentions_perception_snapshots
  set day_to = date '1970-01-01', computed_at = clock_timestamp()
  where brand_id = any (v_brands);
  return null;
end;
$$;

revoke all on function public.forget_mentions_perception_snapshots() from public, anon, authenticated;

drop trigger if exists competitors_forget_perception_snapshots on public.competitors;
create trigger competitors_forget_perception_snapshots
  after delete or update of name, brand_id on public.competitors
  for each row execute function public.forget_mentions_perception_snapshots();

drop trigger if exists brands_forget_perception_snapshots on public.brands;
create trigger brands_forget_perception_snapshots
  after update of name on public.brands
  for each row
  when (old.name is distinct from new.name)
  execute function public.forget_mentions_perception_snapshots();

-- health_probe as 00239 left it, with 'mentions_perception_live'.
create or replace function public.health_probe(
  p_user_id uuid,
  p_brand_id uuid,
  p_probe text,
  p_days integer default null
) returns numeric
language plpgsql
security invoker
set search_path to 'public'
as $$
declare
  t0 timestamptz;
  ts_from timestamptz := case when p_days is null then null else now() - make_interval(days => p_days) end;
  day_from date := (now() at time zone 'utc')::date - coalesce(p_days, 0);
  page_day_from date := case when p_days is null then null
                             else (now() at time zone 'utc')::date - (p_days - 1) end;
  n bigint;
begin
  perform set_config('role', 'authenticated', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
    true
  );
  t0 := clock_timestamp();

  case p_probe
    when 'citations_window_stats' then
      select count(*) into n from public.citations_window_stats(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_domains' then
      select count(*) into n from public.citations_domains(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null);
    when 'citations_urls' then
      select count(*) into n from public.citations_urls(
        p_brand_id => p_brand_id, p_date_from => ts_from, p_date_to => null,
        p_models => null, p_regions => null, p_prompt_ids => null, p_topic_ids => null,
        p_limit => 100, p_domains => null, p_exclude_domains => null);
    when 'citations_domains_daily' then
      select count(*) into n from public.citations_domains_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null);
    when 'citations_urls_daily' then
      select count(*) into n from public.citations_urls_daily(
        p_brand_id => p_brand_id, p_day_from => page_day_from, p_day_to => null,
        p_limit => 2000);
    when 'insights_aggregates_daily' then
      select count(*) into n from public.insights_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'competitor_aggregates_daily' then
      select count(*) into n from public.competitor_aggregates_daily(
        p_brand_id => p_brand_id, p_platform => null, p_models => null, p_region => null,
        p_day_from => case when p_days is null then null else day_from end, p_day_to => null);
    when 'topics_overview_aggregates' then
      select count(*) into n from public.topics_overview_aggregates(p_brand_id => p_brand_id);
    -- What the Topics tab runs: its window, the last p_days days (a day when
    -- unset, the tab's default 24 hours).
    when 'topics_overview_window' then
      select count(*) into n from public.topics_overview_window(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 1)),
        p_date_to => null);
    -- The Mentions & Sentiment tabs' reads over the last p_days days (a
    -- month when unset), as the page asks for them: the table's first page,
    -- newest first, and the Perception figures.
    when 'mentions_list' then
      perform public.mentions_list(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 30)),
        p_date_to => null);
    when 'mentions_perception' then
      perform public.mentions_perception(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 30)),
        p_date_to => null);
    -- The read a filtered Perception view makes (and the default view's,
    -- for a brand without a snapshot): an explicit end skips the snapshot.
    when 'mentions_perception_live' then
      perform public.mentions_perception(
        p_brand_id => p_brand_id,
        p_date_from => now() - make_interval(days => coalesce(p_days, 30)),
        p_date_to => now());
    else
      raise exception 'unknown health probe: %', p_probe;
  end case;

  return round(extract(epoch from clock_timestamp() - t0)::numeric, 2);
end;
$$;


revoke all on function public.health_probe(uuid, uuid, text, integer) from public, anon, authenticated;
grant execute on function public.health_probe(uuid, uuid, text, integer) to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00242_ai_usage_by_feature.sql
-- ─────────────────────────────────────────────────────────────────────────
-- What each AI usage row was for, and the period's spend by feature, for the
-- Billing page's "This period's AI usage" meter.
--
-- prompt_improve_usage (00120) is the workspace's one AI budget
-- (plan.limits.improveMonthlyBudgetUsd): Improve suggestions, the Content
-- Editor's AI (briefs, the Content Agent, Start Agent) and the Action
-- Center's task writer all charge it. A row named what it was for only
-- through prompt_id / action_id (00150) / content_draft_id (00212), each set
-- null when its prompt, action or draft is deleted; feature keeps it.

alter table public.prompt_improve_usage
  add column if not exists feature text
    constraint prompt_improve_usage_feature_check
      check (feature is null or feature in ('improve', 'content', 'action_center'));

comment on column public.prompt_improve_usage.feature is
  'What the AI call was for: improve (the Improve tab), content (the Content Editor''s AI) or action_center (the task writer). Null on rows from before 00242 whose prompt, draft or action was deleted.';

-- Rows from before: read from the item each still names.
update public.prompt_improve_usage
set feature = case
    when action_id is not null then 'action_center'
    when content_draft_id is not null then 'content'
    when prompt_id is not null then 'improve'
  end
where feature is null
  and (action_id is not null or content_draft_id is not null or prompt_id is not null);

-- The organization's spend since p_since (its quota period's start), by
-- feature; rows with none come back as 'other'. Summed in the database: the
-- meter reads every row of the period, however many.
create or replace function public.ai_usage_by_feature(
  p_organization_id uuid,
  p_since timestamptz
)
returns table (feature text, cost_usd numeric)
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(u.feature, 'other') as feature, sum(u.cost_usd) as cost_usd
  from public.prompt_improve_usage u
  where u.organization_id = p_organization_id
    and u.used_at >= p_since
  group by 1;
$$;

comment on function public.ai_usage_by_feature(uuid, timestamptz) is
  'An organization''s AI spend since p_since by prompt_improve_usage.feature (''other'' when unknown), for the Billing page''s AI usage meter (getAiUsage).';

revoke all on function public.ai_usage_by_feature(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.ai_usage_by_feature(uuid, timestamptz) to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00243_ai_usage_reservation.sql
-- ─────────────────────────────────────────────────────────────────────────
-- A call's share of the workspace's AI budget, held before the call runs.
--
-- The budget (plan.limits.improveMonthlyBudgetUsd: Improve, the Content
-- Editor's AI, the Action Center's task writer) was checked by reading the
-- period's spend, and each call's cost written once the model answered. Calls
-- running at once for one workspace (two tabs, a teammate, an Action Center
-- sweep over several actions) all read the same spend and all ran, so the
-- budget could be passed by as many calls as were in flight.
--
-- reserve_ai_usage takes a per-organization lock, reads the period's spend
-- (reservations included), and, while it is under the budget, writes a row
-- for the call at its estimated cost and returns its id. The server turns
-- that row into the call's real cost once the model answers, or deletes it
-- when nothing was charged. The rule stays the one before: a call runs while
-- the spend is under the budget; only now the calls in flight count too.

create or replace function public.reserve_ai_usage(
  p_organization_id  uuid,
  p_since            timestamptz,
  p_budget           numeric,
  p_cost             numeric,
  p_feature          text,
  p_model            text,
  p_prompt_id        uuid default null,
  p_action_id        uuid default null,
  p_content_draft_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_spent numeric;
  v_id    uuid;
begin
  -- One reservation at a time per organization: the next waits and sees this one.
  perform pg_advisory_xact_lock(hashtext('ai_usage:' || p_organization_id::text));

  select coalesce(sum(cost_usd), 0) into v_spent
  from public.prompt_improve_usage
  where organization_id = p_organization_id
    and used_at >= p_since;

  if v_spent >= p_budget then
    return null;
  end if;

  insert into public.prompt_improve_usage (
    organization_id, feature, model, prompt_id, action_id, content_draft_id, cost_usd)
  values (
    p_organization_id, p_feature, p_model, p_prompt_id, p_action_id, p_content_draft_id,
    greatest(p_cost, 0))
  returning id into v_id;
  return v_id;
end;
$$;

comment on function public.reserve_ai_usage(uuid, timestamptz, numeric, numeric, text, text, uuid, uuid, uuid) is
  'Holds an AI call''s estimated cost on its organization''s budget under a per-organization lock, while the period''s spend since p_since is under p_budget; returns the usage row to settle (reserveAiBudget), or null when the budget is spent.';

revoke all on function public.reserve_ai_usage(uuid, timestamptz, numeric, numeric, text, text, uuid, uuid, uuid)
  from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, timestamptz, numeric, numeric, text, text, uuid, uuid, uuid)
  to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00244_action_entities.sql
-- ─────────────────────────────────────────────────────────────────────────
-- AC-009: one count source for an action's prompts, pages, competitors…
--
-- One action showed 13 prompts in its title, 12 in its detail and 13 in a
-- task: the title and the tasks read the count saved in the payload when the
-- action was created, the detail, Copy all and the exports re-counted the
-- signals the nightly pass rewrites, and nothing changed when a prompt was
-- deleted or paused.
--
-- An action now keeps the list of what it is about, once, when it is created:
-- one action_entities row per prompt, page, competitor… (its payload's
-- targetEntity), written by a trigger on actions so every way an action is
-- made (the engine, Send to Action Center from content, prompts, mentions,
-- topics, traffic) keeps it the same way. A prompt deleted or paused, or a
-- competitor deleted, marks its rows removed (a prompt resumed is back), so
-- every place can say "12 prompts (1 removed since this action was
-- created)" and name the one removed.
--
-- Actions made before this keep what their payload still names: the first 50
-- of a bigger group (their count stays the payload's).

create table if not exists public.action_entities (
  action_id      uuid not null references public.actions(id) on delete cascade,
  -- The payload's targetEntity: prompts, pages, competitors, platforms…
  entity_type    text not null,
  -- The target's id (a prompt or competitor id, an address, a platform).
  entity_key     text not null,
  label          text,
  removed_at     timestamptz,
  removed_reason text
    constraint action_entities_removed_reason_check
      check (removed_reason is null or removed_reason in ('deleted', 'paused')),
  -- When the list was written: as the action was created, or by this
  -- migration's backfill for one made before (the nightly check, AC-009
  -- part 3, judges only lists kept at creation).
  kept_at        timestamptz not null default now(),
  primary key (action_id, entity_type, entity_key)
);

-- A prompt or competitor going: every action naming it, at once.
create index if not exists action_entities_entity_idx
  on public.action_entities (entity_type, entity_key)
  where entity_type in ('prompts', 'competitors');

comment on table public.action_entities is
  'AC-009: what an action is about (its payload''s targetEntity: prompts, pages, competitors…), kept once when the action is created; removed_at marks a prompt deleted or paused, or a competitor deleted, since. Every count of the action reads this list.';

alter table public.action_entities enable row level security;

drop policy if exists "action_entities: member select" on public.action_entities;
create policy "action_entities: member select" on public.action_entities
  for select using (
    action_id in (
      select a.id from public.actions a
      join public.brands b on b.id = a.brand_id
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

revoke all on table public.action_entities from anon, authenticated;
grant select on table public.action_entities to authenticated;
grant all on table public.action_entities to service_role;

-- An action's list from its payload: every key it lists (targetIds; a
-- person-sent action's promptIds or pages), else the targets it names
-- (`targets`, or the list under its targetEntity, as Improve's `platforms`),
-- with the names it gives. A prompt is named by its text where the payload
-- gives none. Empty lists name nothing: the next one down is read.
create or replace function public.snapshot_action_entities(
  p_action_id uuid,
  p_brand_id  uuid,
  p_payload   jsonb,
  -- Mark a prompt already deleted or paused, a competitor already deleted, as
  -- removed: for actions kept before 00244, whose list is written now. A new
  -- action's list is what it was made from: nothing is removed yet.
  p_mark_gone boolean default false
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_type  text := nullif(btrim(coalesce(p_payload->>'targetEntity', '')), '');
  v_keys  jsonb;
  v_named jsonb;
begin
  if v_type is null then
    return;
  end if;
  v_named := case
    when jsonb_typeof(p_payload->'targets') = 'array' then p_payload->'targets'
    when jsonb_typeof(p_payload->v_type) = 'array' then p_payload->v_type
    else '[]'::jsonb
  end;
  v_keys := case
    when jsonb_typeof(p_payload->'targetIds') = 'array'
     and jsonb_array_length(p_payload->'targetIds') > 0 then p_payload->'targetIds'
    when v_type = 'prompts' and jsonb_typeof(p_payload->'promptIds') = 'array'
     and jsonb_array_length(p_payload->'promptIds') > 0 then p_payload->'promptIds'
    when v_type = 'pages' and jsonb_typeof(p_payload->'pages') = 'array'
     and jsonb_array_length(p_payload->'pages') > 0 then p_payload->'pages'
  end;

  insert into public.action_entities (
    action_id, entity_type, entity_key, label, removed_at, removed_reason)
  select p_action_id, v_type, k.key,
         coalesce(n.label, pr.text),
         case when p_mark_gone then
           case
             when v_type = 'prompts' and k.uid is not null and pr.id is null then now()
             when v_type = 'prompts' and pr.id is not null and not coalesce(pr.is_active, true) then now()
             when v_type = 'competitors' and co.id is null then now()
           end
         end,
         case when p_mark_gone then
           case
             when v_type = 'prompts' and k.uid is not null and pr.id is null then 'deleted'
             when v_type = 'prompts' and pr.id is not null and not coalesce(pr.is_active, true) then 'paused'
             when v_type = 'competitors' and co.id is null then 'deleted'
           end
         end
  from (
    -- Listed keys when the payload has them, else the named targets' keys,
    -- once each, in the payload's order. A uuid key is cast here, never in a
    -- join: a key that is a prompt's text would fail the cast there.
    select key, min(ord) as ord,
           case when key ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then key::uuid end as uid
    from (
      select btrim(x.value) as key, x.ord
      from jsonb_array_elements_text(coalesce(v_keys, '[]'::jsonb)) with ordinality as x(value, ord)
      union all
      select coalesce(t->>'id', t->>'label', case when jsonb_typeof(t) = 'string' then t #>> '{}' end),
             t_ord + 1000000
      from jsonb_array_elements(
             case when v_keys is null then v_named else '[]'::jsonb end
           ) with ordinality as y(t, t_ord)
    ) keys
    -- An object where an id belongs (old signals' { url, score }) is no key.
    where coalesce(key, '') <> '' and left(key, 1) not in ('{', '[')
    group by key
    order by min(ord)
    limit 1000
  ) k
  -- The names the payload gives.
  left join lateral (
    select case when jsonb_typeof(t) = 'string' then t #>> '{}' else nullif(t->>'label', '') end as label
    from jsonb_array_elements(v_named) as z(t)
    where coalesce(t->>'id', t->>'label', case when jsonb_typeof(t) = 'string' then t #>> '{}' end) = k.key
    limit 1
  ) n on true
  left join public.prompts pr
    on v_type = 'prompts' and pr.id = k.uid
  left join public.competitors co
    on v_type = 'competitors' and co.brand_id = p_brand_id
   and (co.id::text = k.key or co.name = k.key)
  on conflict do nothing;
end;
$$;

revoke all on function public.snapshot_action_entities(uuid, uuid, jsonb, boolean) from public, anon, authenticated;

create or replace function public.actions_snapshot_entities()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  begin
    perform public.snapshot_action_entities(new.id, new.brand_id, new.payload);
    -- The list is kept here now: the payload doesn't carry a thousand keys
    -- to every read of the action.
    if new.payload ? 'targetIds' then
      update public.actions set payload = payload - 'targetIds' where id = new.id;
    end if;
  exception when others then
    -- An action is never refused for its list: the nightly check finds one
    -- kept without it.
    raise warning 'action % kept no entities: %', new.id, sqlerrm;
  end;
  return null;
end;
$$;

revoke all on function public.actions_snapshot_entities() from public, anon, authenticated;

drop trigger if exists actions_snapshot_entities on public.actions;
create trigger actions_snapshot_entities
  after insert on public.actions
  for each row execute function public.actions_snapshot_entities();

-- A prompt deleted: removed from every action that names it.
create or replace function public.action_entities_prompts_deleted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.action_entities e
  set removed_at = now(), removed_reason = 'deleted'
  from deleted_prompts d
  where e.entity_type = 'prompts'
    and e.entity_key = d.id::text
    and e.removed_reason is distinct from 'deleted';
  return null;
end;
$$;

revoke all on function public.action_entities_prompts_deleted() from public, anon, authenticated;

drop trigger if exists prompts_remove_from_actions on public.prompts;
create trigger prompts_remove_from_actions
  after delete on public.prompts
  referencing old table as deleted_prompts
  for each statement execute function public.action_entities_prompts_deleted();

-- A prompt paused is removed until it is resumed. (Transition tables can't
-- name columns, so every prompt update passes here; only an is_active change
-- touches a row.)
create or replace function public.action_entities_prompts_paused()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.action_entities e
  set removed_at = now(), removed_reason = 'paused'
  from changed_prompts n
  join earlier_prompts o on o.id = n.id
  where e.entity_type = 'prompts'
    and e.entity_key = n.id::text
    and coalesce(o.is_active, true) and not coalesce(n.is_active, true)
    and e.removed_at is null;

  update public.action_entities e
  set removed_at = null, removed_reason = null
  from changed_prompts n
  join earlier_prompts o on o.id = n.id
  where e.entity_type = 'prompts'
    and e.entity_key = n.id::text
    and not coalesce(o.is_active, true) and coalesce(n.is_active, true)
    and e.removed_reason = 'paused';
  return null;
end;
$$;

revoke all on function public.action_entities_prompts_paused() from public, anon, authenticated;

drop trigger if exists prompts_pause_in_actions on public.prompts;
create trigger prompts_pause_in_actions
  after update on public.prompts
  referencing old table as earlier_prompts new table as changed_prompts
  for each statement execute function public.action_entities_prompts_paused();

-- A competitor deleted: removed from its brand's actions, by id or by name
-- (older signals name competitors by name).
create or replace function public.action_entities_competitors_deleted()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.action_entities e
  set removed_at = now(), removed_reason = 'deleted'
  from deleted_competitors d
  join public.actions a on a.brand_id = d.brand_id
  where e.action_id = a.id
    and e.entity_type = 'competitors'
    and (e.entity_key = d.id::text or e.entity_key = d.name)
    and e.removed_at is null;
  return null;
end;
$$;

revoke all on function public.action_entities_competitors_deleted() from public, anon, authenticated;

drop trigger if exists competitors_remove_from_actions on public.competitors;
create trigger competitors_remove_from_actions
  after delete on public.competitors
  referencing old table as deleted_competitors
  for each statement execute function public.action_entities_competitors_deleted();

-- Each action's list in one read, for every place that shows a count: per
-- entity type, how many it was made with, how many are removed since, the names
-- of the removed (up to 20, for the hover) and their keys (to leave them out
-- of a list). Read through the member's policy: only their brands' actions
-- answer.
create or replace function public.action_entity_counts(p_action_ids uuid[])
returns table (
  action_id      uuid,
  entity_type    text,
  total          integer,
  removed        integer,
  removed_labels text[],
  removed_keys   text[]
)
language sql
stable
security invoker
set search_path = public
as $$
  select e.action_id,
         e.entity_type,
         count(*)::integer,
         count(*) filter (where e.removed_at is not null)::integer,
         (array_agg(coalesce(e.label, e.entity_key) order by e.removed_at, e.entity_key)
            filter (where e.removed_at is not null))[1:20],
         array_agg(e.entity_key order by e.removed_at, e.entity_key)
            filter (where e.removed_at is not null)
  from public.action_entities e
  where e.action_id = any (p_action_ids[1:500])
  group by e.action_id, e.entity_type;
$$;

revoke execute on function public.action_entity_counts(uuid[]) from public, anon;
grant execute on function public.action_entity_counts(uuid[]) to authenticated, service_role;

-- The actions made before: their list from what their payload still names.
-- A topic opportunity counts its suggestions (targets), not the tracked
-- prompts it measures (promptIds). An action that names nothing a list can
-- hold keeps none; the web then shows its saved count (part 2).
select public.snapshot_action_entities(
  a.id,
  a.brand_id,
  case when a.kind = 'topic_opportunity' then a.payload - 'promptIds' else a.payload end,
  true)
from public.actions a
where a.deleted_at is null;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00245_action_count_drift.sql
-- ─────────────────────────────────────────────────────────────────────────
-- AC-009, part 3: the nightly check that every action's count and its list agree.
--
-- An action keeps its list once, when it is created (action_entities, 00244),
-- and everything it shows counts from it. The daily health e-mail now says
-- how many open actions disagree with their own list, and names a few:
--
--   * missing:  an action about something (a targetCount) made since lists
--     are kept that kept none;
--   * mismatch: one whose list holds another number than the count it saved.
--     A new action keeps up to 1000 (MAX_TARGET_IDS): a list cut there is
--     the cap, not a mismatch;
--   * tasks:    one with a planned task naming another count of the same
--     thing than the action saved ("across 13 prompts" under 12).
--
-- The last two judge only lists kept as their action was created
-- (action_entities.kept_at): an action from before 00244 got the list its
-- payload still named, and an older count may never have matched it.
-- Each should be 0; the server's health report raises any that isn't.

create or replace function public.action_count_drift(p_examples integer default 5)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  with open_actions as (
    select a.id, a.action_no, a.created_at, a.payload->>'targetEntity' as entity, x.target_count
    from public.actions a
    -- A number only: anything else in the payload is no count to check.
    cross join lateral (
      select case when jsonb_typeof(a.payload->'targetCount') = 'number'
                  then (a.payload #>> '{targetCount}')::numeric end as target_count
    ) x
    where a.deleted_at is null
      and a.status not in ('completed', 'dismissed')
      and x.target_count > 0
      and coalesce(a.payload->>'targetEntity', '') <> ''
  ),
  -- Lists started being kept here: actions before had theirs written by
  -- 00244's backfill, from what their payload still named, if anything.
  since as (
    select coalesce(min(kept_at), '-infinity'::timestamptz) as at from public.action_entities
  ),
  kept as (
    select o.id, o.action_no, o.created_at, o.target_count, l.total, l.at_creation
    from open_actions o
    -- Each action's own rows, through the primary key.
    cross join lateral (
      select count(*) as total,
             -- Kept as it was created (the trigger), not by the backfill.
             coalesce(bool_or(e.kept_at <= o.created_at + interval '1 minute'), false) as at_creation
      from public.action_entities e
      where e.action_id = o.id and e.entity_type = o.entity
    ) l
  ),
  missing as (
    select k.action_no from kept k, since
    where k.total = 0 and k.created_at >= since.at
  ),
  mismatch as (
    select action_no from kept
    where at_creation
      and total > 0
      and total <> target_count
      -- The cap a list was cut at, not a mismatch.
      and not (total = 1000 and target_count > total)
  ),
  tasks as (
    select distinct k.action_no
    from kept k
    join open_actions o on o.id = k.id
    join public.action_tasks t on t.action_id = o.id
    cross join lateral (
      select case when jsonb_typeof(t.title_params->'count') = 'number'
                  then (t.title_params #>> '{count}')::numeric end as task_count
    ) c
    where k.at_creation
      and t.title_params->>'entity' = o.entity
      and c.task_count <> o.target_count
  )
  -- The newest first: a regression shows before the long-open ones.
  select jsonb_build_object(
    'checked', (select count(*) from open_actions),
    'missing', jsonb_build_object(
      'count', (select count(*) from missing),
      'examples', coalesce((select jsonb_agg(action_no order by action_no desc)
                            from (select action_no from missing order by action_no desc limit p_examples) x), '[]'::jsonb)),
    'mismatch', jsonb_build_object(
      'count', (select count(*) from mismatch),
      'examples', coalesce((select jsonb_agg(action_no order by action_no desc)
                            from (select action_no from mismatch order by action_no desc limit p_examples) x), '[]'::jsonb)),
    'tasks', jsonb_build_object(
      'count', (select count(*) from tasks),
      'examples', coalesce((select jsonb_agg(action_no order by action_no desc)
                            from (select action_no from tasks order by action_no desc limit p_examples) x), '[]'::jsonb))
  );
$$;

comment on function public.action_count_drift(integer) is
  'AC-009: open actions whose saved count and kept list (action_entities) disagree, by kind (missing list, list ≠ count, a task naming another count), with a few action numbers each; read by the daily health report. Each should be 0.';

revoke all on function public.action_count_drift(integer) from public, anon, authenticated;
grant execute on function public.action_count_drift(integer) to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00246_perception_snapshots_follow_rollups.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00246: the Perception snapshots never older than their rollups (MS-09)
-- ============================================================================
-- 00241 serves the Perception tab's default view from a snapshot the server
-- refreshes after a brand's Mentions rollups are rebuilt. When that refresh
-- failed, or the rollups were rebuilt another way (a backfill in SQL), the
-- default view kept the snapshot's older figures until the next refresh,
-- while a filtered view already read the new rollups.
--
-- refresh_mention_terms_daily (00231), which every rebuild of the Perception
-- rollups goes through, now sets the brand's snapshots aside at its end, in
-- the rebuild's transaction: once new rollups commit, the tab reads them
-- live until the snapshots are refreshed. A refresh already under way can't
-- write over that; only one starting in the instant between the set-aside
-- and the commit could, and the refresh after the rebuild replaces it. The
-- function is otherwise 00231's, unchanged.

create or replace function public.refresh_mention_terms_daily(
  p_brand_id uuid,
  p_day_from date,
  p_day_to   date
) returns void
language plpgsql
set search_path to 'public'
as $$
declare
  v_from timestamptz := p_day_from::timestamp at time zone 'utc';
  v_to   timestamptz := (p_day_to + 1)::timestamp at time zone 'utc';
begin
  -- One rebuild per brand at a time: a run's refresh and the deleted-prompt
  -- rebuild can cover the same days. The lock releases at commit.
  perform pg_advisory_xact_lock(
    hashtextextended('refresh_mention_terms_daily:' || p_brand_id::text, 0));

  -- The terms' key leads with the entity, so their rows go by the entities
  -- those days name (the same rows the entities' come from), before those.
  delete from public.mentions_terms_daily
    where brand_id = p_brand_id
      and entity in (
        select distinct e.entity
        from public.mentions_entities_daily e
        where e.brand_id = p_brand_id and e.day between p_day_from and p_day_to)
      and day between p_day_from and p_day_to;
  delete from public.mentions_entities_daily
    where brand_id = p_brand_id and day between p_day_from and p_day_to;

  insert into public.mentions_entities_daily (
    brand_id, day, platform, region, entity, answers, with_brand)
  select p_brand_id, x.day, x.platform, x.region, x.entity,
         count(*), count(*) filter (where x.with_brand)
  from (
    select (t.created_at at time zone 'utc')::date as day, t.platform, t.region, t.entity,
           bool_or(t.entity = 'brand') over (partition by t.result_id) as with_brand
    from public.mentions_answer_terms t
    where t.brand_id = p_brand_id
      and t.created_at >= v_from
      and t.created_at < v_to
  ) x
  group by x.day, x.platform, x.region, x.entity;

  with c as materialized (
    select (t.created_at at time zone 'utc')::date as day, t.platform, t.region, t.entity,
           term, count(*)::integer as answers
    from public.mentions_answer_terms t
    cross join lateral unnest(t.terms) as term
    where t.brand_id = p_brand_id
      and t.created_at >= v_from
      and t.created_at < v_to
    group by 1, 2, 3, 4, 5
  ),
  -- The terms among any entity's 200 most frequent of a day, platform and
  -- region, kept for every entity there. coalesce rather than "is not
  -- distinct from", so the join below can hash.
  keep as (
    select distinct r.day, r.platform, coalesce(r.region, '') as region_key, r.term
    from (
      select c.day, c.platform, c.region, c.term,
             row_number() over (
               partition by c.day, c.platform, c.region, c.entity
               order by c.answers desc, c.term) as rn
      from c
    ) r
    where r.rn <= 200
  )
  insert into public.mentions_terms_daily (
    brand_id, day, platform, region, entity, term, answers)
  select p_brand_id, c.day, c.platform, c.region, c.entity, c.term, c.answers
  from c
  join keep k on k.day = c.day and k.platform = c.platform
             and k.region_key = coalesce(c.region, '') and k.term = c.term;

  -- The brand's precomputed default views (00241) now count from rollups
  -- older than these: set aside, as forget_mentions_perception_snapshots
  -- does, so the tab reads the rollups live until the server refreshes
  -- them, never older figures. Last, in the same transaction: a refresh
  -- that started before this (and read the old rollups) can't write over
  -- it, as its computed_at is earlier.
  update public.mentions_perception_snapshots
  set day_to = date '1970-01-01', computed_at = clock_timestamp()
  where brand_id = p_brand_id;
end;
$$;

revoke execute on function public.refresh_mention_terms_daily(uuid, date, date)
  from public, anon, authenticated;

comment on table public.mentions_perception_snapshots is
  'The Perception tab''s default view (MS-09) per brand and window (7, 30 or 90 days, every platform and region, no topic or search), as mentions_perception returns it. Written by refresh_mentions_perception_snapshot; set aside when the brand''s competitors or name change, or its Perception rollups are rebuilt (00246).';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00247_content_page_suggestions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00247: a whole-page suggestion (Content Editor, Rewrite the page to these rules)
-- ============================================================================
-- Apply rules with Agent leaves at most 8 small edits a run, which can't
-- bring a 19,000-character page to an 8,000-character Length (about 2% a
-- run on prod, 2026-10-23). Rewrite the page to these rules has the Content
-- Agent rewrite the whole page in one call, left as ONE suggestion the
-- person compares with their page and accepts or rejects:
--
--   * kind 'page': after_text is the whole page's HTML, up to 500,000
--     characters (the editor's body limit), not 20,000;
--   * before_html: the page as the agent read it, which the editor checks
--     the page against before applying it and puts back on Undo. A page
--     suggestion has it; the others don't;
--   * before_text stays '' for it, as for an insert.
--
-- Rows are still written by the server only; the decide RPC (00217) and
-- RLS are unchanged.
--
-- content_drafts.agent_run says which run holds the draft ('write' or
-- 'rewrite'), so every device knows a failed rewrite from a failed Start;
-- 00219's guard keeps it server-set.

alter table public.content_draft_suggestions
  add column if not exists before_html text;

alter table public.content_draft_suggestions
  drop constraint if exists content_draft_suggestions_kind_check,
  add constraint content_draft_suggestions_kind_check
    check (kind in ('replace', 'insert', 'page'));

alter table public.content_draft_suggestions
  drop constraint if exists content_draft_suggestions_after_text_check,
  add constraint content_draft_suggestions_after_text_check
    check (char_length(after_text) between 1 and case when kind = 'page' then 500000 else 20000 end);

alter table public.content_draft_suggestions
  drop constraint if exists content_draft_suggestions_check,
  add constraint content_draft_suggestions_check
    check (kind in ('insert', 'page') or before_text <> '');

alter table public.content_draft_suggestions
  drop constraint if exists content_draft_suggestions_before_html_check,
  add constraint content_draft_suggestions_before_html_check
    check ((kind = 'page') = (before_html is not null)
           and char_length(coalesce(before_html, '')) <= 500000);

comment on column public.content_draft_suggestions.before_html is
  'A page suggestion''s page as the agent read it (kind ''page'', 00247): checked against the editor''s page before applying, and put back on Undo. Null for the others.';

-- Which run holds the draft, or last held it (agent_state): Start with Agent
-- ('write': a new page, or suggestions on a live one) or Rewrite the page to
-- these rules ('rewrite'). The editor reads it to say which run failed and to
-- try that one again, on any device: a failed rewrite tried again is a
-- rewrite to compare, never a new page over the current one. Server-set,
-- with agent_state.
alter table public.content_drafts
  add column if not exists agent_run text;

alter table public.content_drafts
  drop constraint if exists content_drafts_agent_run_check,
  add constraint content_drafts_agent_run_check
    check (agent_run is null or agent_run in ('write', 'rewrite'));

comment on column public.content_drafts.agent_run is
  'Content Editor: the run that holds the draft or last held it (00247): ''write'' (Start with Agent) or ''rewrite'' (Rewrite the page to these rules). Server-set, with agent_state.';

-- 00219's guard, with agent_run among the columns only the server sets.
create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
    if new.action_id is not null then
      raise exception 'content draft action is set server-side'
        using errcode = '42501';
    end if;
    if new.agent_state is not null or new.agent_state_at is not null
       or new.agent_run is not null then
      raise exception 'content draft agent state is set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
     or new.action_id is distinct from old.action_id
     or new.agent_state is distinct from old.agent_state
     or new.agent_state_at is distinct from old.agent_state_at
     or new.agent_run is distinct from old.agent_run
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00248_content_suggestion_sources.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00248: the sources an agent's suggestion was written from
-- ============================================================================
-- Content Editor v1.1, CE-033: the Content Agent writes from the sources the
-- Sources tab keeps (prompts, fan-outs, cited pages, Search Console queries),
-- numbered, and says which ones each suggestion used and the words each one
-- supports. The editor shows them as "Based on" chips under the suggestion
-- and ¹ ² marks on its words; a chip opens its source in Sources. A number
-- the agent adds with no source is not kept (contentSources.js).
--
-- sources: [{ "kind", "ref", "label" }], kind one of prompt, fanout,
-- cited_page, gsc_query; ref as the Sources tab keys its row (a prompt's id,
-- a normalized query, a page's address).
--
-- source_marks: [{ "start", "end", "source" }], offsets into the words a
-- replace puts in (after_text) or an insert's HTML read as text; source is an
-- index into sources. A page rewritten whole names its sources, with no marks.
alter table public.content_draft_suggestions
  add column if not exists sources jsonb
    check (
      sources is null
      or (
        jsonb_typeof(sources) = 'array'
        and jsonb_array_length(sources) between 1 and 8
      )
    ),
  add column if not exists source_marks jsonb
    check (
      source_marks is null
      or (
        kind in ('replace', 'insert')
        and sources is not null
        and jsonb_typeof(source_marks) = 'array'
        and jsonb_array_length(source_marks) between 1 and 12
      )
    );

comment on column public.content_draft_suggestions.sources is
  'The sources an agent suggestion was written from: [{ "kind", "ref", "label" }] (00248).';
comment on column public.content_draft_suggestions.source_marks is
  'The words each source supports: [{ "start", "end", "source" }], offsets into after_text (a replace) or an insert''s text, source an index into sources (00248).';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00249_content_agent_runs.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00249: the Content Agent's runs, step by step
-- ============================================================================
-- Content Editor v1.1, CE-027 and CE-035: while the agent works, the editor
-- shows its real steps, short names for the work the server does ("Reading 4
-- rules → Gathering 52 sources → Writing 3 changes → Checking sources"), and
-- Stop. The server writes each run here as it goes; the
-- editor reads the draft's latest. Stop marks it stopped: the server drops
-- whatever the run had and changes nothing.
--
-- A table of its own, not columns on content_drafts: a step written there
-- would move the draft's updated_at, which the editor's saves check against.
--
-- steps: [{ "key", "count" }], key one of read_rules, gather_sources,
-- write_changes, rewrite_page, write_page, write_outline, match_fanouts,
-- check_sources; count null where there is none.
-- step: the one under way (steps' index); all done once finished.
-- outcome is what happened: a Stop that lands after the run's last check
-- may leave stopped_at set on a run that ended 'done'. A run a stopped server
-- left unfinished is closed 'failed' when the next starts on the draft.
-- claimed_at: a Start or Rewrite run's claim on the draft (the
-- content_drafts.agent_state_at it wrote); null for Fix and the brief, which
-- hold no draft. A Stop lets go only of the claim the stopped run holds, so a
-- Stop on a Fix leaves a Start on the same draft its claim.
create table if not exists public.content_agent_runs (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.content_drafts (id) on delete cascade,
  kind text not null check (kind in ('fix', 'rewrite', 'write', 'brief')),
  steps jsonb not null check (
    jsonb_typeof(steps) = 'array' and jsonb_array_length(steps) between 1 and 6
  ),
  step smallint not null default 0 check (step between 0 and 6),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  stopped_at timestamptz,
  outcome text check (outcome in ('done', 'stopped', 'failed')),
  claimed_at timestamptz
);

-- For a database that ran this file before claimed_at was added to it.
alter table public.content_agent_runs add column if not exists claimed_at timestamptz;

create index if not exists content_agent_runs_draft_started
  on public.content_agent_runs (draft_id, started_at desc);

alter table public.content_agent_runs enable row level security;

-- A draft the member can read is one in their organization (content_drafts'
-- own member policies), so its runs follow it, as its suggestions do (00217).
create policy "content_agent_runs: member select"
  on public.content_agent_runs
  for select
  using (draft_id in (select d.id from public.content_drafts d));

grant select on public.content_agent_runs to authenticated;

comment on table public.content_agent_runs is
  'Content Editor v1.1 (CE-027/035): the Content Agent''s runs on a draft, step by step, and whether one was stopped (00249). Written by the server; read by the editor.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00250_traffic_anonymous_visitors.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00250: the tracking snippet's visitors, without their IP addresses (GDPR)
-- ============================================================================
-- ai_traffic_logs kept each AI-referred visitor's IP address. It was only
-- needed to tell one visitor's pageviews from another's for half an hour
-- (a visit, 00172) and to find the pageview a not-found title belongs to
-- (00200).
--
-- The server now stores a visitor key instead (backend/src/lib/visitorKey.js):
-- a one-way hash of the IP address, the brand and a salt that changes every
-- day. Each day's salt is made here on first use and deleted after two days,
-- so once it is gone nothing links its keys to an address, and a visitor's
-- days can't be joined. Visits are grouped by the key and the user agent, as
-- they were by the IP address; a visit across midnight (UTC) counts as two.
--
-- The IP addresses already stored are erased. The visits they grouped are
-- kept: each pageview's visit_of was decided when it was stored.

create table if not exists public.traffic_daily_salts (
  day  date primary key,
  salt text not null
);

comment on table public.traffic_daily_salts is
  'One random salt per UTC day for the tracking snippet''s visitor keys (00250). Kept two days, then deleted by traffic_salt.';

alter table public.traffic_daily_salts enable row level security;
revoke all on table public.traffic_daily_salts from anon, authenticated;
grant all on table public.traffic_daily_salts to service_role;

-- The salt of p_day, made on first use; salts older than the day before
-- are deleted on the way.
create or replace function public.traffic_salt(p_day date)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_salt text;
begin
  delete from public.traffic_daily_salts where day < p_day - 1;

  insert into public.traffic_daily_salts (day, salt)
  values (p_day, replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  on conflict (day) do nothing;

  select salt into v_salt from public.traffic_daily_salts where day = p_day;
  return v_salt;
end;
$$;

revoke all on function public.traffic_salt(date) from public, anon, authenticated;
grant execute on function public.traffic_salt(date) to service_role;

alter table public.ai_traffic_logs
  add column if not exists visitor_key text;

comment on column public.ai_traffic_logs.visitor_key is
  'A one-way key for the visitor, from their IP address, the brand and the day''s salt (00250); groups a visit''s pageviews. The IP address itself is not stored.';

comment on column public.ai_traffic_logs.ip_address is
  'No longer written (00250): the IP address is not stored. Null on every row.';

update public.ai_traffic_logs
set ip_address = null
where ip_address is not null;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00251_chatgpt_shopping_visits.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00251: ChatGPT Shopping visits, from feed links tagged utm_medium=feed (#1283)
-- ============================================================================
-- A product URL in a merchant's feed tagged utm_source=chatgpt.com and
-- utm_medium=feed tells a visit from a ChatGPT Shopping product card apart
-- from one through a ChatGPT answer. Until now both were ChatGPT and nothing
-- read the medium. The AI source list (backend/src/lib/ai-sources.json,
-- version 3) gives ChatGPT a shopping surface: utm_medium = feed.
--
--   * ai_traffic_logs.source_surface: 'shopping' for a snippet visit from
--     ChatGPT whose landing URL's utm_medium is feed. The server decides it
--     from the URL it stores, so a cached older snippet's visits are marked
--     too. The visit stays source_platform = 'chatgpt.com', so ChatGPT's
--     totals don't change. The rows stored before are marked below, once,
--     from their URL.
--   * ga_ai_traffic_stats.medium and surface: GA4's session medium, which
--     the sync now reads, and the surface it marks, from the list as for the
--     snippet. One source can bring sessions of several mediums to one page
--     on one day, so the medium is part of a row's key. Rows synced before
--     have none: the sync replaces them as it re-reads their days (the last
--     few each day; all of them with backfillGaAiHistory.js).
--   * ai_traffic_merged (00176) also returns the visits by platform and
--     surface. Its platforms keep counting every visit, surfaces included.
--   * ga_platform_value (00177) also returns each platform's figures by
--     surface. Its platform rows keep counting every session, as before.
--
-- Deploy the server right after applying this: the running server's Google
-- Analytics sync upserts on the old key, which is gone, so its brands fail
-- to sync until then (the next run re-reads the last few days). The new
-- server writes source_surface, so it must not run before this.

-- ─── The snippet's visits ───────────────────────────────────────────────────

alter table public.ai_traffic_logs
  add column if not exists source_surface text
    constraint ai_traffic_logs_source_surface_check
      check (source_surface is null or source_surface in ('shopping'));

comment on column public.ai_traffic_logs.source_surface is
  'The part of the AI source the visit came through, from the AI source list (backend/src/lib/ai-sources.json): shopping for a ChatGPT Shopping product card (a ChatGPT visit whose landing URL has utm_medium=feed). Null for the source''s ordinary links. The visit still counts under source_platform (00251).';

-- Visits stored before: a ChatGPT visit whose landing URL's first
-- utm_medium parameter (its name in any case) is feed, in any case, as the
-- server reads a new visit's URL (landingMedium in aiSources.js).
update public.ai_traffic_logs l
set source_surface = 'shopping'
where l.source_platform = 'chatgpt.com'
  and l.source_surface is null
  and l.url ilike '%utm_medium%'
  and (
    select lower(substring(p.pair from '=(.*)$'))
    from regexp_split_to_table(substring(l.url from '\?([^#]*)'), '&') with ordinality as p (pair, n)
    where lower(split_part(p.pair, '=', 1)) = 'utm_medium'
    order by p.n
    limit 1
  ) = 'feed';

-- ─── Google Analytics' sessions ─────────────────────────────────────────────

alter table public.ga_ai_traffic_stats
  add column if not exists medium text;

alter table public.ga_ai_traffic_stats
  add column if not exists surface text
    constraint ga_ai_traffic_stats_surface_check
      check (surface is null or surface in ('shopping'));

comment on column public.ga_ai_traffic_stats.medium is
  'GA4''s session medium, as reported (feed, referral, (none), …). Part of the row''s key. Null on rows synced before the sync read it (00251), which a re-read of their day replaces.';

comment on column public.ga_ai_traffic_stats.surface is
  'The part of the platform the sessions came through, from the AI source list (backend/src/lib/ai-sources.json): shopping for ChatGPT Shopping (chatgpt.com with medium feed). Null otherwise. The sessions still count under platform (00251).';

-- The key adds the medium. A null medium is one key, not many, so the rows
-- from before stay one per (date, source, entry URL) until they're replaced.
alter table public.ga_ai_traffic_stats
  drop constraint if exists ga_ai_traffic_stats_brand_id_date_source_landing_page_query_key;

alter table public.ga_ai_traffic_stats
  drop constraint if exists ga_ai_traffic_stats_brand_date_source_medium_page_key;

alter table public.ga_ai_traffic_stats
  add constraint ga_ai_traffic_stats_brand_date_source_medium_page_key
    unique nulls not distinct (brand_id, date, source, medium, landing_page_query);

-- ─── The AI Traffic page's visits, with their surfaces ──────────────────────

create or replace function public.ai_traffic_merged(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz,
  p_to_inclusive boolean default true,
  p_analytics boolean default true
)
returns jsonb
language sql
stable
security invoker
set search_path to 'public'
as $$
  with bounds as (
    select
      -- The first whole UTC day inside the window.
      case
        when p_from is null then null
        when (p_from at time zone 'utc')::time = time '00:00' then (p_from at time zone 'utc')::date
        else (p_from at time zone 'utc')::date + 1
      end as first_day,
      coalesce((p_to at time zone 'utc')::date, (now() at time zone 'utc')::date) as last_day
  ),
  snippet as (
    select
      (l.created_at at time zone 'utc')::date as day,
      coalesce(nullif(l.source_platform, ''), 'unknown') as platform,
      l.source_surface as surface,
      public.normalize_page_path(l.url) as page
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
      and (p_to is null or l.created_at < p_to or (p_to_inclusive and l.created_at = p_to))
  ),
  -- Days the snippet was active, over the whole day, not just the window.
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l, bounds b
    where p_analytics
      and l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= coalesce((b.first_day::timestamp at time zone 'utc'), '-infinity'::timestamptz)
      and l.created_at < ((b.last_day + 1)::timestamp at time zone 'utc')
  ),
  analytics as (
    select
      g.date as day,
      coalesce(g.platform, g.source) as platform,
      g.surface,
      public.normalize_page_path(g.landing_page) as page,
      g.sessions as visits
    from public.ga_ai_traffic_stats g, bounds b
    where p_analytics
      and g.brand_id = p_brand_id
      and g.sessions > 0
      and g.date >= coalesce(b.first_day, '-infinity'::date)
      and g.date <= b.last_day
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  merged as (
    select day, platform, surface, page, 1::bigint as visits, 'snippet' as origin from snippet
    union all
    select day, platform, surface, page, visits::bigint, 'analytics' from analytics
  )
  select jsonb_build_object(
    'visits', (select coalesce(sum(visits), 0) from merged),
    'pageviews', (
      select count(*)
      from public.ai_traffic_logs l
      where l.brand_id = p_brand_id
        and l.created_at >= coalesce(p_from, '-infinity'::timestamptz)
        and (p_to is null or l.created_at < p_to or (p_to_inclusive and l.created_at = p_to))
    ),
    'analytics_days', (
      select coalesce(jsonb_agg(distinct day order by day), '[]'::jsonb) from analytics
    ),
    'platforms', (
      select coalesce(jsonb_agg(jsonb_build_object('platform', platform, 'visits', visits) order by visits desc, platform), '[]'::jsonb)
      from (select platform, sum(visits) as visits from merged group by platform) t
    ),
    -- Part of their platform's visits above, never added to them.
    'surfaces', (
      select coalesce(jsonb_agg(jsonb_build_object('platform', platform, 'surface', surface, 'visits', visits) order by visits desc, platform, surface), '[]'::jsonb)
      from (
        select platform, surface, sum(visits) as visits
        from merged
        where surface is not null
        group by platform, surface
      ) t
    ),
    'pages', (
      select coalesce(jsonb_agg(jsonb_build_object('page', page, 'visits', visits) order by visits desc, page), '[]'::jsonb)
      from (select page, sum(visits) as visits from merged group by page) t
    ),
    'days', (
      select coalesce(jsonb_agg(jsonb_build_object('day', day, 'platform', platform, 'visits', visits) order by day, platform), '[]'::jsonb)
      from (select day, platform, sum(visits) as visits from merged group by day, platform) t
    )
  );
$$;

revoke all on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean)
  from public, anon;
grant execute on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean)
  to authenticated, service_role;

comment on function public.ai_traffic_merged(uuid, timestamptz, timestamptz, boolean, boolean) is
  'AI Traffic (AT-004, spec §5.2): AI-referred visits for one brand in a window, from the tracking snippet on days it was active and from Google Analytics on other whole days, never summed. Returns visits, the snippet''s pageviews, the days Analytics filled, and visits by platform, by platform and surface (ChatGPT Shopping, 00251; part of the platform''s visits), page and day. Security invoker: RLS decides the brand.';

-- ─── Per AI platform, with its surfaces, for the Referrals by Platform table ─

-- A new column in the result: dropped and made again, with its grants.
drop function if exists public.ga_platform_value(uuid, date, date);

create function public.ga_platform_value(
  p_brand_id uuid,
  p_since date,
  p_until date
)
returns table (
  platform text,
  sessions bigint,
  engaged_sessions bigint,
  key_events bigint,
  key_event_sessions bigint,
  surfaces jsonb
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  with by_surface as (
    select
      coalesce(gat.platform, gat.source) as platform,
      gat.surface,
      coalesce(sum(gat.sessions), 0)::bigint as sessions,
      coalesce(sum(gat.engaged_sessions), 0)::bigint as engaged_sessions,
      coalesce(sum(gat.key_events), 0)::bigint as key_events,
      coalesce(sum(gat.key_event_sessions), 0)::bigint as key_event_sessions
    from public.ga_ai_traffic_stats gat
    where gat.brand_id = p_brand_id
      and gat.date >= coalesce(p_since, '-infinity'::date)
      and gat.date <= p_until
    group by 1, 2
  )
  select
    s.platform,
    sum(s.sessions)::bigint,
    sum(s.engaged_sessions)::bigint,
    sum(s.key_events)::bigint,
    sum(s.key_event_sessions)::bigint,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'surface', s.surface,
          'sessions', s.sessions,
          'engaged_sessions', s.engaged_sessions,
          'key_events', s.key_events,
          'key_event_sessions', s.key_event_sessions
        )
        order by s.surface
      ) filter (where s.surface is not null),
      '[]'::jsonb
    )
  from by_surface s
  group by s.platform;
$$;

revoke all on function public.ga_platform_value(uuid, date, date) from public, anon;
grant execute on function public.ga_platform_value(uuid, date, date) to authenticated, service_role;

comment on function public.ga_platform_value(uuid, date, date) is
  'AI Traffic (AT-005): Google Analytics'' sessions, engaged sessions, key events and sessions with a key event per AI platform, and the same per surface of the platform (ChatGPT Shopping, 00251; part of the platform''s figures), for one brand between two days (p_since null = from the start). Security invoker: RLS decides the brand.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00256_content_authors.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00256: the workspace's authors (Content Editor Quality, CE-037)
-- ============================================================================
-- Settings › Authors (Quality spec §9): the real people a page is by. A
-- page's author is its metadata, never its content: the editor shows it as
-- a byline outside the page, GetCito sets the CMS author field on publish,
-- and Person schema names it. "Real people only. Content Agent can't add,
-- edit or invent authors": the server has no path that writes these.
--
--   * content_authors: one row per person, in an organization: name, title,
--     a short bio, profile links (sameAs), a photo. user_id is the member
--     the author is, when they are one: only that member links or unlinks
--     themself, and each member is one author at most.
--   * Anyone in the workspace adds authors; whoever added one, the author
--     themself or an admin edits and deletes it. Its organization, who
--     added it and when stay as they were.
--   * content_author_defaults: one default author per brand, which every
--     new page of the brand gets; admins and managers set it, as the
--     workspace's other settings. With none, a page is by the organization
--     ("{Brand} Team").

-- Profile links feed Person schema's sameAs and Site trust, and members
-- write the table from their own sessions, so the table holds the rule the
-- action checks: each link https, at most 300 characters.
create or replace function public.content_author_links_ok(links text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(bool_and(l ~ '^https://\S+$' and char_length(l) <= 300), true)
  from unnest(links) as l
$$;

create table if not exists public.content_authors (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  user_id uuid references public.profiles(id) on delete set null,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  title text check (title is null or char_length(title) <= 120),
  bio text check (bio is null or char_length(bio) <= 400),
  photo_url text check (
    photo_url is null or (photo_url ~ '^https://' and char_length(photo_url) <= 2048)
  ),
  same_as text[] not null default '{}' check (
    cardinality(same_as) <= 10 and public.content_author_links_ok(same_as)
  ),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists content_authors_organization
  on public.content_authors (organization_id, name);

-- A member is one author of their organization at most.
create unique index if not exists content_authors_member
  on public.content_authors (organization_id, user_id)
  where user_id is not null;

create or replace trigger content_authors_updated_at
  before update on public.content_authors
  for each row execute function public.handle_updated_at();

-- What RLS can't say: an author's organization, who added it and when never
-- change, and user_id changes only as its member linking or unlinking
-- themself.
create or replace function public.guard_content_author_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;
  if new.organization_id is distinct from old.organization_id
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
  then
    raise exception 'content author column can''t change'
      using errcode = '42501';
  end if;
  if new.user_id is distinct from old.user_id
     and not (old.user_id is null and new.user_id = auth.uid())
     and not (old.user_id = auth.uid() and new.user_id is null)
  then
    raise exception 'only a member links or unlinks themself as an author'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace trigger content_authors_guard
  before update on public.content_authors
  for each row execute function public.guard_content_author_columns();

alter table public.content_authors enable row level security;

create policy "content_authors: member select"
  on public.content_authors
  for select
  using (organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid()));

-- Added by the member, as no one or as themself.
create policy "content_authors: member insert"
  on public.content_authors
  for insert
  with check (
    organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid())
    and created_by = auth.uid()
    and (user_id is null or user_id = auth.uid())
  );

-- Whoever added it, the author themself, or an admin of the organization.
create policy "content_authors: owner or admin update"
  on public.content_authors
  for update
  using (
    organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid())
    and (
      created_by = auth.uid()
      or user_id = auth.uid()
      or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
    )
  )
  with check (
    organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid())
  );

create policy "content_authors: owner or admin delete"
  on public.content_authors
  for delete
  using (
    organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid())
    and (
      created_by = auth.uid()
      or user_id = auth.uid()
      or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
    )
  );

-- Every policy needs auth.uid(); revoking anon keeps it so if one is loosened.
revoke all on table public.content_authors from anon;
grant select, insert, update, delete on public.content_authors to authenticated;

comment on table public.content_authors is
  'Content Editor Quality (CE-037): the workspace''s authors — real people a page is by (page metadata, never content). Anyone adds; whoever added it, the author themself or an admin edits. The server never writes them.';

create table if not exists public.content_author_defaults (
  brand_id uuid primary key references public.brands(id) on delete cascade,
  author_id uuid not null references public.content_authors(id) on delete cascade,
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);

create index if not exists content_author_defaults_author
  on public.content_author_defaults (author_id);

alter table public.content_author_defaults enable row level security;

create policy "content_author_defaults: member select"
  on public.content_author_defaults
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

-- Admins and managers of the brand's organization, with an author of it.
create policy "content_author_defaults: manager write"
  on public.content_author_defaults
  for all
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  )
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
    and author_id in (
      select a.id from public.content_authors a
      join public.brands b on b.organization_id = a.organization_id
      where b.id = content_author_defaults.brand_id
    )
    and updated_by = auth.uid()
  );

revoke all on table public.content_author_defaults from anon;
grant select, insert, update, delete on public.content_author_defaults to authenticated;

comment on table public.content_author_defaults is
  'Content Editor Quality (CE-037): the author every new page of a brand gets; none means the organization byline. Admins and managers set it.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00257_content_draft_author.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00257: a page's author (Content Editor Quality, CE-038)
-- ============================================================================
-- content_drafts.author_id: the real person the page is by (content_authors,
-- 00256). It is page metadata: the editor shows it in its Page info strip,
-- outside the page, and GetCito sends it to the CMS author field; it is
-- never in the page's text. (The draft's `author` column, 'user' or 'agent',
-- says who wrote the text: another thing.)
--
--   * A new draft gets its brand's default author (content_author_defaults),
--     the server's drafts too; none means the organization byline
--     ("{Brand} Team").
--   * The author must be one of the brand's organization's.

alter table public.content_drafts
  add column if not exists author_id uuid
    references public.content_authors(id) on delete set null;

create index if not exists content_drafts_author
  on public.content_drafts (author_id)
  where author_id is not null;

comment on column public.content_drafts.author_id is
  'Content Editor Quality (CE-038): the person the page is by (content_authors), page metadata — never the page''s text. A new draft gets its brand''s default; null is the organization byline.';

-- As the member who writes (RLS reads their organization's defaults and
-- authors); the server bypasses RLS and reads them all.
create or replace function public.content_draft_author()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and new.author_id is null then
    select d.author_id into new.author_id
    from public.content_author_defaults d
    where d.brand_id = new.brand_id;
  end if;
  if new.author_id is not null
     and (tg_op = 'INSERT' or new.author_id is distinct from old.author_id)
     and not exists (
       select 1
       from public.content_authors a
       join public.brands b on b.organization_id = a.organization_id
       where a.id = new.author_id and b.id = new.brand_id
     )
  then
    raise exception 'content draft author is not one of the brand''s organization'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists content_drafts_author on public.content_drafts;
create trigger content_drafts_author
  before insert or update of author_id on public.content_drafts
  for each row execute function public.content_draft_author();

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00258_content_link_checks.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00258: the pages a Content Editor draft links to, read once a day
-- (Content Editor Quality, Trust)
-- ============================================================================
-- Trust's "No broken links" and "Fresh sources (≤ 24 months)" (Quality spec
-- §2.2) read each link a saved draft has: does it answer, and how old is the
-- page it points to. The server reads a link at most once a day (an
-- 'unknown' answer again after a few hours), whoever's draft has it; this is
-- that read. It holds only what any visitor of the linked page sees, so it
-- is shared, and only the server touches it. Rows go after a week.
--
--   * url_hash: sha256 of the link as the check keys it (no hash, no
--     tracking parameters); url is that link.
--   * status: 'ok' (it answers, a page or a file), 'broken' (gone, or the
--     site is nowhere), 'unknown' (it wouldn't tell: slow, a bot wall, a
--     server or certificate error that may pass).
--   * page_date: the page's own newest date (its main JSON-LD entity, else
--     its article:* meta, else the first <time> in its article), or null.

create table if not exists public.content_link_checks (
  url_hash text primary key check (char_length(url_hash) = 64),
  url text not null check (char_length(url) <= 2048),
  status text not null check (status in ('ok', 'broken', 'unknown')),
  http_status integer,
  page_date timestamptz,
  checked_at timestamptz not null default now()
);

create index if not exists content_link_checks_checked_at
  on public.content_link_checks (checked_at);

-- Service-role only, no policy.
alter table public.content_link_checks enable row level security;
revoke all on table public.content_link_checks from anon, authenticated;
grant all on table public.content_link_checks to service_role;

comment on table public.content_link_checks is
  'Content Editor Quality (Trust): each linked page''s last read — answers or not, and its own date. Server only; read at most once a day, kept a week.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00259_site_trust.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00259: a brand's site trust (Content Editor Quality, CE-043)
-- ============================================================================
-- Site trust (Quality spec §8): five site-level checks Site Audit shows as
-- "Site trust {n}/5", and Trust gives 5 points on every page from:
--
--   * about: an About page;
--   * contact: a Contact page;
--   * editorial: an editorial policy (or "How we review") page;
--   * organizationSchema: Organization schema on the home page;
--   * authorPages: a page for each author in Settings › Authors.
--
-- The server reads them from the brand's page list (site_pages), its home
-- page and its authors, at most once a day or when someone asks again; this
-- is the last read. complete is false when the site didn't answer all of it
-- (slow, unreachable, a server error, a bot wall): such a read is read again
-- after a few minutes. scraped_at is when the home page last went through
-- Scrape.do, past a bot wall: at most once a day per brand, one credit.
-- Members read it; only the server writes it.

create table if not exists public.site_trust (
  brand_id uuid primary key references public.brands(id) on delete cascade,
  checks jsonb not null,
  score smallint not null check (score between 0 and 5),
  complete boolean not null default true,
  checked_at timestamptz not null default now(),
  scraped_at timestamptz
);

-- For a database that ran this file before scraped_at was added to it.
alter table public.site_trust add column if not exists scraped_at timestamptz;

alter table public.site_trust enable row level security;
revoke all on table public.site_trust from anon, authenticated;
grant select on table public.site_trust to authenticated;
grant all on table public.site_trust to service_role;

drop policy if exists "site_trust: member select" on public.site_trust;
create policy "site_trust: member select"
  on public.site_trust
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.site_trust is
  'Content Editor Quality (CE-043): a brand''s five site trust checks (About, Contact, editorial policy, Organization schema on the home page, author pages) and how many pass. Written by the server, read by members.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00260_content_draft_ready_log.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00260: Mark ready anyway, logged (Content Editor Quality, CE-041)
-- ============================================================================
-- Before you publish (Quality spec §7) warns when a page's Trust is under 60
-- and still lets the person mark it ready: "Mark ready anyway (logged)".
-- Each time, a row keeps the Trust the page had, the check the warning named
-- (its id, e.g. claimsSourced, and how many it counted) and who marked it.
--
-- A member adds a row as themselves, only for a draft of their brand that is
-- ready, and gives only the draft, the Trust and the reason: who and when
-- are the database's. Members read them; nothing changes or deletes them,
-- and they go with the draft.

create table if not exists public.content_draft_ready_log (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  trust smallint not null check (trust between 0 and 100),
  reason text check (reason is null or reason ~ '^[A-Za-z]{1,40}$'),
  reason_count integer check (reason_count is null or reason_count >= 0),
  created_by uuid default auth.uid() references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists content_draft_ready_log_draft_idx
  on public.content_draft_ready_log (draft_id, created_at desc);

alter table public.content_draft_ready_log enable row level security;
revoke all on table public.content_draft_ready_log from anon, authenticated;
grant select on table public.content_draft_ready_log to authenticated;
grant insert (draft_id, trust, reason, reason_count)
  on table public.content_draft_ready_log to authenticated;
grant all on table public.content_draft_ready_log to service_role;

drop policy if exists "content_draft_ready_log: member select" on public.content_draft_ready_log;
create policy "content_draft_ready_log: member select"
  on public.content_draft_ready_log
  for select
  using (public.content_draft_member(draft_id));

drop policy if exists "content_draft_ready_log: member insert" on public.content_draft_ready_log;
create policy "content_draft_ready_log: member insert"
  on public.content_draft_ready_log
  for insert
  with check (
    public.content_draft_member(draft_id)
    and created_by = auth.uid()
    and exists (
      select 1 from public.content_drafts d
      where d.id = draft_id and d.status = 'ready'
    )
  );

comment on table public.content_draft_ready_log is
  'Content Editor Quality (CE-041): each "Mark ready anyway" past the Trust < 60 warning — the Trust the page had, the check the warning named and its count, who and when. Added by members as themselves for a ready draft; never changed.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00261_brand_content_byline.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00261: Add byline to content, per brand (Content Editor Quality, CE-057)
-- ============================================================================
-- The author is page metadata: a CMS's own author field shows the byline,
-- and nothing of it goes into the content (Quality spec §9). For a CMS with
-- no author support (rare), a brand can opt in: its exports then put one
-- byline line under the H1. Off by default. Admins and managers change it,
-- as the rest of a brand (brands: admin/manager update).

alter table public.brands
  add column if not exists content_byline boolean not null default false;

comment on column public.brands.content_byline is
  'Content Editor Quality (CE-057): add one byline line under the H1 in exports, for a CMS with no author field. Off by default.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00262_content_draft_deliveries.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00262: Send to CMS, phase 1 (webhook) — #1331
-- ============================================================================
-- An admin or manager sends a Content Editor page to the brand's webhook as a
-- content package (its publishable HTML, title, slug, meta and page fields);
-- the workspace's own automation (Zapier, Make, n8n, its CMS) takes it from
-- there and may call back with how it went: the address it published at (and
-- the CMS's id for the post), or that it failed.
--
-- content_drafts gets the page's slug and meta, filled from the page and
-- editable in the Send dialog, and where it went live. A send is a row of
-- content_draft_deliveries: queued when reserved, then sent or failed, and
-- published once the callback names the live address. A table of its own,
-- not columns on content_drafts: a page is sent many times, and each send's
-- answer is kept (the draft gets only its slug, meta and live address).
-- A callback that says it failed marks the delivery failed.

alter table public.content_drafts
  add column if not exists slug text
    check (slug is null or (char_length(slug) between 1 and 200 and slug !~ '[/\s]')),
  add column if not exists meta_title text
    check (meta_title is null or char_length(meta_title) <= 300),
  add column if not exists meta_description text
    check (meta_description is null or char_length(meta_description) <= 500),
  add column if not exists published_url text
    check (
      published_url is null
      or (char_length(published_url) <= 2048 and published_url ~* '^https?://')
    ),
  add column if not exists published_at timestamptz;

comment on column public.content_drafts.slug is
  'The page''s URL slug for its CMS (Send to CMS, 00262): filled from the page, editable in the Send dialog.';
comment on column public.content_drafts.published_url is
  'Where the page went live: what the CMS called back with after a Send to CMS (00262).';

create table if not exists public.content_draft_deliveries (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  brand_id uuid not null references public.brands(id) on delete cascade,
  -- Kept when the draft goes (its title stays below), as the day's count does.
  draft_id uuid references public.content_drafts(id) on delete set null,
  sent_by uuid references public.profiles(id) on delete set null,
  -- A bulk send's deliveries share one, so the Library can follow them.
  batch_id uuid,
  status text not null default 'queued'
    check (status in ('queued', 'sent', 'failed', 'published')),
  title text not null check (char_length(title) between 1 and 300),
  slug text check (slug is null or char_length(slug) <= 200),
  -- What the webhook answered: its HTTP status and the start of its body.
  http_status smallint,
  response_excerpt text check (response_excerpt is null or char_length(response_excerpt) <= 2000),
  error text check (error is null or char_length(error) <= 500),
  published_url text check (
    published_url is null
    or (char_length(published_url) <= 2048 and published_url ~* '^https?://')
  ),
  -- The CMS's own id for the post, when the callback names it.
  external_id text check (external_id is null or char_length(external_id) between 1 and 200),
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  published_at timestamptz
);

create index if not exists content_draft_deliveries_org_created
  on public.content_draft_deliveries (organization_id, created_at desc);
create index if not exists content_draft_deliveries_draft_created
  on public.content_draft_deliveries (draft_id, created_at desc);
create index if not exists content_draft_deliveries_batch
  on public.content_draft_deliveries (batch_id) where batch_id is not null;
-- The next send closes a workspace's sends left queued (below): only those rows.
create index if not exists content_draft_deliveries_queued
  on public.content_draft_deliveries (organization_id) where status = 'queued';

alter table public.content_draft_deliveries enable row level security;
revoke all on table public.content_draft_deliveries from anon, authenticated;
grant select on table public.content_draft_deliveries to authenticated;
grant all on table public.content_draft_deliveries to service_role;

-- Members read their workspace's deliveries; the server writes them.
drop policy if exists "content_draft_deliveries: member select" on public.content_draft_deliveries;
create policy "content_draft_deliveries: member select"
  on public.content_draft_deliveries
  for select
  using (organization_id in (select p.organization_id from public.profiles p where p.id = auth.uid()));

comment on table public.content_draft_deliveries is
  'Send to CMS (#1331, 00262): each page sent to the brand''s webhook, as queued, sent, failed or published. Written by the server; read by the editor and the Library.';

-- Each page's last send, one row a page, for the Library's marks: a read of
-- the table itself stops at PostgREST's 1,000 rows, which a workspace that
-- re-sends often passes. Read through the member's policy: only their
-- workspace's sends answer.
create or replace function public.content_draft_last_deliveries(p_draft_ids uuid[])
returns setof public.content_draft_deliveries
language sql
stable
security invoker
set search_path = public
as $$
  select distinct on (d.draft_id) d.*
  from public.content_draft_deliveries d
  where d.draft_id = any (p_draft_ids[1:500])
  order by d.draft_id, d.created_at desc;
$$;

revoke execute on function public.content_draft_last_deliveries(uuid[]) from public, anon;
grant execute on function public.content_draft_last_deliveries(uuid[]) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- The day's cap: reserve_content_deliveries queues as many of the pages as the
-- workspace's last 24 hours leave room for (p_limit, 200), under a lock per
-- organization so sends at once can't pass it together (as 00243). It returns
-- the queued rows; pages past the cap get none.
-- p_items: [{ "draft_id", "title", "slug" }], in the order they go.
-- A row still queued after 30 minutes was left by a server that stopped
-- mid-batch: the next send closes it as interrupted (as 00249 closes runs),
-- so the Library tells it from one still going. It still counts for the day.
-- ----------------------------------------------------------------------------
create or replace function public.reserve_content_deliveries(
  p_organization_id uuid,
  p_brand_id uuid,
  p_sent_by uuid,
  p_batch_id uuid,
  p_items jsonb,
  p_limit integer
)
returns setof public.content_draft_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  used integer;
  room integer;
begin
  perform pg_advisory_xact_lock(hashtext('content_deliveries:' || p_organization_id::text));

  -- sent_at stays empty: it was never sent, and its time stays its own.
  update public.content_draft_deliveries
  set status = 'failed', error = 'Not sent: interrupted'
  where organization_id = p_organization_id
    and status = 'queued'
    and created_at < now() - interval '30 minutes';

  select count(*) into used
  from public.content_draft_deliveries
  where organization_id = p_organization_id
    and created_at > now() - interval '24 hours';

  room := greatest(0, p_limit - used);
  if room = 0 or jsonb_typeof(p_items) <> 'array' then
    return;
  end if;

  return query
  insert into public.content_draft_deliveries
    (organization_id, brand_id, draft_id, sent_by, batch_id, title, slug)
  select p_organization_id, p_brand_id, (item ->> 'draft_id')::uuid, p_sent_by, p_batch_id,
         left(item ->> 'title', 300), nullif(left(item ->> 'slug', 200), '')
  from jsonb_array_elements(p_items) with ordinality as items(item, position)
  order by position
  limit room
  returning *;
end;
$$;

revoke all on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer)
  from public, anon, authenticated;
grant execute on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer)
  to service_role;

-- ----------------------------------------------------------------------------
-- Where the page went live is the server's: the callback writes it, with the
-- service role. guard_content_draft_server_columns (00247) refuses a member's
-- write of it, as of the other columns the server keeps; slug and meta stay
-- the members' to edit.
-- ----------------------------------------------------------------------------
create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
    if new.action_id is not null then
      raise exception 'content draft action is set server-side'
        using errcode = '42501';
    end if;
    if new.agent_state is not null or new.agent_state_at is not null
       or new.agent_run is not null then
      raise exception 'content draft agent state is set server-side'
        using errcode = '42501';
    end if;
    if new.published_url is not null or new.published_at is not null then
      raise exception 'content draft live address is set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
     or new.action_id is distinct from old.action_id
     or new.agent_state is distinct from old.agent_state
     or new.agent_state_at is distinct from old.agent_state_at
     or new.agent_run is distinct from old.agent_run
     or new.published_url is distinct from old.published_url
     or new.published_at is distinct from old.published_at
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

-- ----------------------------------------------------------------------------
-- Webhooks: a page sent is an event a webhook subscribes to (00198's list).
-- ----------------------------------------------------------------------------
alter table public.webhook_configs
  drop constraint if exists webhook_configs_events_allowed;

alter table public.webhook_configs
  add constraint webhook_configs_events_allowed
  check (
    events <@ array[
      'opportunity.sent', 'daily_pulse.created', 'action_task.sent', 'content_draft.sent'
    ]::text[]
  );

comment on column public.webhook_configs.events is
  'Event types subscribed to by this webhook (opportunity.sent, daily_pulse.created, action_task.sent, content_draft.sent). webhook.test is always sent by the test action and is not stored here.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00263_content_draft_kept_sources.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00263: Quality phase 2, CE-046 — the sources a person keeps
-- ============================================================================
-- Trust reads what kind of source each of a page's links is: primary
-- (official, research, standards), secondary, weak (forums, social posts) or
-- a competitor's page. A weak source or a competitor's the person trusts all
-- the same is kept: it no longer lowers Trust or shows as a suggestion. Kept
-- per draft, by the link's address as the page has it, 50 at most.

alter table public.content_drafts
  add column if not exists kept_sources text[] not null default '{}'
    check (cardinality(kept_sources) <= 50);

comment on column public.content_drafts.kept_sources is
  'Quality CE-046 (00263): weak or competitors'' sources the person chose to keep on this page, by address. They don''t lower Trust.';

-- Keeps one source on a draft, once, up to the 50: a member's own change of
-- their draft, through their policy (security invoker). Returns the draft's
-- kept sources after, or nothing when the caller can't change the draft.
create or replace function public.content_draft_keep_source(p_draft_id uuid, p_url text)
returns text[]
language sql
volatile
security invoker
set search_path = public
as $$
  update public.content_drafts
  set kept_sources = case
    when p_url = any (kept_sources) or cardinality(kept_sources) >= 50 then kept_sources
    else array_append(kept_sources, p_url)
  end
  where id = p_draft_id
    and char_length(p_url) between 1 and 2048
  returning kept_sources;
$$;

revoke execute on function public.content_draft_keep_source(uuid, text) from public, anon;
grant execute on function public.content_draft_keep_source(uuid, text) to authenticated, service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00264_content_source_classes.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00264: Quality phase 2, CE-046 (part b) — AI reads of sources' kinds
-- ============================================================================
-- Trust reads what kind of source each of a page's links is by rules first
-- (00263's part a). A site the rules can't place is read by the model once,
-- as primary, secondary or weak (unknown when it doesn't know the site,
-- kept a day), and kept for every workspace for 90 days:
-- what kind of site a public website is isn't any workspace's own data, and
-- one read serves them all. Only the site's address goes to the model.
--
-- The reads draw on the workspace's AI budget as their own feature,
-- "quality", so the Billing meter shows them apart and their small holds
-- don't set the hold of the Content Agent's larger calls (holdCostUsd).

alter table public.prompt_improve_usage
  drop constraint if exists prompt_improve_usage_feature_check;
alter table public.prompt_improve_usage
  add constraint prompt_improve_usage_feature_check
    check (feature is null or feature in ('improve', 'content', 'action_center', 'quality'));

comment on column public.prompt_improve_usage.feature is
  'What the AI call was for: improve (the Improve tab), content (the Content Editor''s AI), action_center (the task writer) or quality (the Content Editor''s Quality checks, 00264). Null on rows from before 00242 whose prompt, draft or action was deleted.';

create table if not exists public.content_source_classes (
  -- A site as the citations name it: lower case, without "www.", and a
  -- public DNS name only (letters, digits and hyphens in each label, a dot
  -- at least, a letter top-level domain): no IP address, no single-label
  -- name, as the API and the editor take them (SITE_NAME).
  host text primary key
    check (
      char_length(host) between 1 and 253
      and host ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$'
      and host !~ '^www\.'
    ),
  -- unknown: the model doesn't know the site; Trust leaves it out, and the
  -- read is asked again after a day.
  kind text not null check (kind in ('primary', 'secondary', 'weak', 'unknown')),
  model text check (model is null or char_length(model) <= 100),
  classified_at timestamptz not null default now()
);

alter table public.content_source_classes enable row level security;
revoke all on table public.content_source_classes from anon, authenticated;
grant all on table public.content_source_classes to service_role;

comment on table public.content_source_classes is
  'Quality CE-046 (00264): the kind of source a site is (primary, secondary or weak; unknown when the model doesn''t know it), as the model read it for a site the rules can''t place. Kept 90 days (unknown, a day), shared by every workspace; server-only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00265_content_draft_inputs.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00265: Quality phase 2, CE-048 — Brief › Your input
-- ============================================================================
-- What only the person can give a page, kept beside its brief (a rebuild
-- writes the brief over; this stays): their first-hand experience, their
-- data (rows read from a CSV or Excel file in the browser, or pasted, and
-- GetCito data they chose to use) and expert quotes, each with the
-- person's name, title, the words as said and where they were said. The
-- Content Agent writes from them as given and adds nothing beyond them;
-- E-E-A-T and Trust count them once the page uses them.
--
-- One row a draft, read and written by the members of its workspace
-- (content_draft_member, 00215), as the draft itself is; a write names its
-- writer as updated_by, as content_rule_sets' do (00214). The sizes match
-- what the editor keeps (frontend/src/lib/content/draftInputs.ts).

create table if not exists public.content_draft_inputs (
  draft_id uuid primary key references public.content_drafts(id) on delete cascade,
  experience text check (experience is null or char_length(experience) <= 4000),
  -- [{ "name": "…", "rows": [["…"]] }]: the tables as read, 5 at most.
  data jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(data) = 'array'
      and jsonb_array_length(data) <= 5
      and octet_length(data::text) <= 65536
    ),
  -- [{ "promptId", "prompt", "answers", "mentioned", "asOf", "days" }]: GetCito data used, with the day it was used and the days it covers.
  getcito_data jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(getcito_data) = 'array'
      and jsonb_array_length(getcito_data) <= 10
      and octet_length(getcito_data::text) <= 16384
    ),
  -- [{ "name", "title", "text", "sourceUrl" }]: quotes from real people, word for word.
  quotes jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(quotes) = 'array'
      and jsonb_array_length(quotes) <= 10
      and octet_length(quotes::text) <= 16384
    ),
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);

create or replace trigger content_draft_inputs_updated_at
  before update on public.content_draft_inputs
  for each row execute function public.handle_updated_at();

alter table public.content_draft_inputs enable row level security;
revoke all on table public.content_draft_inputs from anon;
grant select, insert, update, delete on table public.content_draft_inputs to authenticated;
grant all on table public.content_draft_inputs to service_role;

drop policy if exists "content_draft_inputs: member select" on public.content_draft_inputs;
create policy "content_draft_inputs: member select"
  on public.content_draft_inputs for select
  using (public.content_draft_member(draft_id));

drop policy if exists "content_draft_inputs: member insert" on public.content_draft_inputs;
create policy "content_draft_inputs: member insert"
  on public.content_draft_inputs for insert
  with check (public.content_draft_member(draft_id) and updated_by = auth.uid());

drop policy if exists "content_draft_inputs: member update" on public.content_draft_inputs;
create policy "content_draft_inputs: member update"
  on public.content_draft_inputs for update
  using (public.content_draft_member(draft_id))
  with check (public.content_draft_member(draft_id) and updated_by = auth.uid());

drop policy if exists "content_draft_inputs: member delete" on public.content_draft_inputs;
create policy "content_draft_inputs: member delete"
  on public.content_draft_inputs for delete
  using (public.content_draft_member(draft_id));

comment on table public.content_draft_inputs is
  'Quality CE-048 (00265): Brief › Your input — a draft''s first-hand experience, data and expert quotes, as the person gave them. The Content Agent writes from them and adds nothing beyond them.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00266_content_quality_claims.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00266: Quality phase 2, CE-045 — the claims in a draft's own words
-- ============================================================================
-- Trust wants a source for every claim on a page. Phase 1 reads figures by
-- rule; phase 2 has the model read the person's own paragraphs for the
-- claims a rule can't see: research ("studies show"), superlatives ("the
-- fastest"), awards and certifications ("SOC 2"), product facts
-- ("waterproof"). The editor underlines one with no source in its block.
--
-- What the model read is kept per draft and paragraph, by a hash of the
-- paragraph's words: a paragraph not changed since isn't read again, and the
-- rows of paragraphs no longer on the page go at the next read. Each claim
-- is { "text", "kind" }: its words as the paragraph has them, and number,
-- stat, superlative or fact. `missed` marks a paragraph whose answer missed
-- the schema (cut short, or blocked by the provider's filter): kept as read
-- with no claims, so it isn't charged on every save, and read again after a
-- day. Server-only: the API reads and writes it, after its own check that
-- the caller is a member of the draft's workspace.

create table if not exists public.content_quality_claims (
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  paragraph_hash text not null check (paragraph_hash ~ '^[0-9a-f]{16}$'),
  claims jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(claims) = 'array'
      and jsonb_array_length(claims) <= 5
      and octet_length(claims::text) <= 4096
    ),
  model text check (model is null or char_length(model) <= 100),
  missed boolean not null default false,
  checked_at timestamptz not null default now(),
  primary key (draft_id, paragraph_hash)
);

alter table public.content_quality_claims enable row level security;
revoke all on table public.content_quality_claims from anon, authenticated;
grant all on table public.content_quality_claims to service_role;

comment on table public.content_quality_claims is
  'Quality CE-045 (00266): the claims the model read in a draft''s paragraph (number, stat, superlative or fact), by the paragraph''s hash; a changed paragraph is read again, a removed one''s row goes. Server-only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00267_shopping_overview_chatgpt_market.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Shopping: keep ChatGPT Shopping to one market in the Overview (#1278).
--
-- ChatGPT Shopping picks products differently by market (the US from OpenAI's
-- product index, Europe from Google Shopping), so the Shopping page has a
-- US / Europe switch that keeps ChatGPT Shopping's cards to the market's
-- regions. The card reads apply it as a PostgREST filter; the Overview's KPIs
-- and charts come from this function, whose `p_regions` narrows every
-- platform. `p_chatgpt_regions` narrows ChatGPT Shopping's results and cards
-- only and lets every other platform through. Null, the default, changes
-- nothing: a call without it reads exactly what it did before.
--
-- APPLY BEFORE DEPLOYING THE WEB. The new web passes `p_chatgpt_regions`, which
-- the old function doesn't have; the old web's calls match the new function,
-- since the parameter has a default.
--
-- A new parameter makes a new overload under create or replace, and PostgREST
-- would then have two candidates for one call. So the 6-argument version is
-- dropped first, and the new one gets the grants it had. The body is 00115's,
-- with one condition added to the results, cards and trend.

drop function if exists public.shopping_overview(
  uuid, timestamptz, timestamptz, text[], text[], timestamptz
);

create or replace function public.shopping_overview(
  p_brand_id uuid,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_platforms text[] default null,
  p_regions text[] default null,
  p_trend_from timestamptz default null,
  p_chatgpt_regions text[] default null
) returns jsonb
language plpgsql
stable
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  return (
    with results as materialized (
      select r.id, r.platform
      from public.prompt_results r
      where r.brand_id = p_brand_id
        and (p_from is null or r.created_at >= p_from)
        and (p_to is null or r.created_at <= p_to)
        and (p_platforms is null or r.platform = any (p_platforms))
        and (p_regions is null or r.region = any (p_regions))
        and (p_chatgpt_regions is null or r.platform <> 'chatgpt-shopping'
             or r.region = any (p_chatgpt_regions))
    ),
    by_platform as (
      select res.platform,
             count(*) as total_results,
             count(*) filter (where exists (
               select 1 from public.prompt_result_shopping_cards c
               where c.prompt_result_id = res.id
             )) as results_with_cards
      from results res
      group by res.platform
    ),
    cards as materialized (
      select c.matched_brand_role, c.merchant_domain
      from public.prompt_result_shopping_cards c
      where c.brand_id = p_brand_id
        and (p_from is null or c.created_at >= p_from)
        and (p_to is null or c.created_at <= p_to)
        and (p_platforms is null or c.platform = any (p_platforms))
        and (p_regions is null or c.region = any (p_regions))
        and (p_chatgpt_regions is null or c.platform <> 'chatgpt-shopping'
             or c.region = any (p_chatgpt_regions))
    ),
    top_merchant as (
      select merchant_domain, count(*) as card_count
      from cards
      where matched_brand_role = 'own' and merchant_domain is not null
      group by merchant_domain
      order by count(*) desc, merchant_domain
      limit 1
    ),
    trend as (
      select (c.created_at at time zone 'UTC')::date as day,
             count(*) filter (where c.matched_brand_role = 'own') as own_cards,
             count(*) as total_cards
      from public.prompt_result_shopping_cards c
      where c.brand_id = p_brand_id
        and p_trend_from is not null
        and c.created_at >= p_trend_from
        and (p_platforms is null or c.platform = any (p_platforms))
        and (p_regions is null or c.region = any (p_regions))
        and (p_chatgpt_regions is null or c.platform <> 'chatgpt-shopping'
             or c.region = any (p_chatgpt_regions))
      group by 1
    )
    select jsonb_build_object(
      'total_results',       coalesce((select sum(total_results) from by_platform), 0),
      'results_with_cards',  coalesce((select sum(results_with_cards) from by_platform), 0),
      'total_cards',         (select count(*) from cards),
      'own_cards',           (select count(*) from cards where matched_brand_role = 'own'),
      'top_merchant',        (select jsonb_build_object('domain', merchant_domain,
                                                        'card_count', card_count)
                              from top_merchant),
      'by_platform', coalesce(
        (select jsonb_agg(jsonb_build_object(
                  'platform',           platform,
                  'total_results',      total_results,
                  'results_with_cards', results_with_cards)
                order by platform)
         from by_platform),
        '[]'::jsonb),
      'trend', coalesce(
        (select jsonb_agg(jsonb_build_object(
                  'day',         day,
                  'own_cards',   own_cards,
                  'total_cards', total_cards)
                order by day)
         from trend),
        '[]'::jsonb)
    )
  );
end;
$$;

grant execute on function public.shopping_overview(
  uuid, timestamptz, timestamptz, text[], text[], timestamptz, text[]
) to public, anon, authenticated, service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00268_shopping_merchant_split.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Shopping: where AI sends shoppers, and resellers cheaper than the brand (#1277).
--
-- 00225 stores each card's destination (merchant_kind, marketplace,
-- listing_id). Two reads over the brand's own products (cards with
-- matched_brand_role = 'own') build on it, in the Overview tab's window and
-- filters (p_from, p_to, p_platforms, p_regions and ChatGPT Shopping's market,
-- p_chatgpt_regions, as in shopping_overview since 00267):
--
--   1. shopping_merchant_split: the cards per destination (your store,
--      Amazon, Walmart, eBay, other marketplaces, other resellers). Cards
--      with no merchant URL (merchant_kind null) are counted apart, never
--      spread over the segments, so the segments add up to the classified
--      cards.
--   2. shopping_own_product_offers: the lowest price per merchant, listing,
--      title and currency, with the link of the card that showed it. The web
--      app matches these offers to the brand's store and flags the cheaper
--      resellers (frontend/src/lib/shoppingResellerPriceAlert.ts).
--
-- Both are aggregated here, not read as rows: PostgREST caps rows at 1,000,
-- and the offers come back as one jsonb value for the same reason. On the
-- largest brands the own products are a few hundred cards a quarter, read
-- through the (brand_id, matched_brand_role) indexes.
--
-- Security definer behind the same membership check as
-- shopping_amazon_share_weekly (00225), its sibling over these columns: the
-- check runs once, a non-member gets no rows (or an empty list), and the
-- reads below use the indexes without the per-row RLS filter.
--
-- Apply after 00267 and before deploying the web: the web passes
-- p_chatgpt_regions to both, as it does to shopping_overview.

create or replace function public.shopping_merchant_split(
  p_brand_id uuid,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_platforms text[] default null,
  p_regions text[] default null,
  p_chatgpt_regions text[] default null
)
returns table (
  own_store_cards bigint,
  amazon_cards bigint,
  walmart_cards bigint,
  ebay_cards bigint,
  other_marketplace_cards bigint,
  reseller_cards bigint,
  unclassified_cards bigint
)
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1
    from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id
      and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  select
    count(*) filter (where c.merchant_kind = 'own'),
    count(*) filter (where c.merchant_kind = 'marketplace' and c.marketplace = 'amazon'),
    count(*) filter (where c.merchant_kind = 'marketplace' and c.marketplace = 'walmart'),
    count(*) filter (where c.merchant_kind = 'marketplace' and c.marketplace = 'ebay'),
    count(*) filter (where c.merchant_kind = 'marketplace'
                       and coalesce(c.marketplace, '') not in ('amazon', 'walmart', 'ebay')),
    count(*) filter (where c.merchant_kind = 'reseller'),
    count(*) filter (where c.merchant_kind is null)
  from public.prompt_result_shopping_cards c
  where c.brand_id = p_brand_id
    and c.matched_brand_role = 'own'
    and (p_from is null or c.created_at >= p_from)
    and (p_to is null or c.created_at <= p_to)
    and (p_platforms is null or c.platform = any (p_platforms))
    and (p_regions is null or c.region = any (p_regions))
    and (p_chatgpt_regions is null or c.platform <> 'chatgpt-shopping'
         or c.region = any (p_chatgpt_regions));
end;
$$;

revoke all on function public.shopping_merchant_split(uuid, timestamptz, timestamptz, text[], text[], text[]) from public, anon;
grant execute on function public.shopping_merchant_split(uuid, timestamptz, timestamptz, text[], text[], text[]) to authenticated, service_role;

-- One entry per merchant offer of the brand's own products: the classified
-- cards with a price, grouped by destination, listing, title (case and outer
-- spaces aside) and currency. Repeat sightings of the same offer collapse to
-- its lowest price, all the price rule needs, so the list stays short.
create or replace function public.shopping_own_product_offers(
  p_brand_id uuid,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_platforms text[] default null,
  p_regions text[] default null,
  p_chatgpt_regions text[] default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1
    from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id
      and pf.id = auth.uid()
  ) then
    return '[]'::jsonb;
  end if;

  return (
    with offers as (
      select
        c.merchant_kind,
        c.marketplace,
        c.merchant_domain,
        c.listing_id,
        min(c.product_title) as product_title,
        upper(btrim(c.price_currency)) as price_currency,
        min(c.price_amount) as price_amount,
        (array_agg(c.merchant_url order by c.price_amount, c.created_at desc))[1] as merchant_url
      from public.prompt_result_shopping_cards c
      where c.brand_id = p_brand_id
        and c.matched_brand_role = 'own'
        and c.merchant_kind is not null
        and c.merchant_url is not null
        and c.price_amount > 0
        and nullif(btrim(c.price_currency), '') is not null
        and (p_from is null or c.created_at >= p_from)
        and (p_to is null or c.created_at <= p_to)
        and (p_platforms is null or c.platform = any (p_platforms))
        and (p_regions is null or c.region = any (p_regions))
        and (p_chatgpt_regions is null or c.platform <> 'chatgpt-shopping'
             or c.region = any (p_chatgpt_regions))
      group by
        c.merchant_kind,
        c.marketplace,
        c.merchant_domain,
        c.listing_id,
        lower(btrim(c.product_title)),
        upper(btrim(c.price_currency))
    )
    -- Without both a store offer and another merchant's there is nothing to
    -- compare: return an empty list rather than every store offer.
    select coalesce(
      jsonb_agg(jsonb_build_object(
        'merchant_kind',   o.merchant_kind,
        'marketplace',     o.marketplace,
        'merchant_domain', o.merchant_domain,
        'merchant_url',    o.merchant_url,
        'listing_id',      o.listing_id,
        'product_title',   o.product_title,
        'price_amount',    o.price_amount,
        'price_currency',  o.price_currency)),
      '[]'::jsonb)
    from offers o
    where exists (select 1 from offers x where x.merchant_kind = 'own')
      and exists (select 1 from offers x where x.merchant_kind <> 'own')
  );
end;
$$;

revoke all on function public.shopping_own_product_offers(uuid, timestamptz, timestamptz, text[], text[], text[]) from public, anon;
grant execute on function public.shopping_own_product_offers(uuid, timestamptz, timestamptz, text[], text[], text[]) to authenticated, service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00269_brand_facts.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00269: Quality phase 2, CE-047 — a brand's facts, read from its own site
-- ============================================================================
-- Trust gives 10 points for a page consistent with the brand's facts (Quality
-- spec §10): its prices and plans, its trial, when it was founded, and the
-- claims it makes of itself (awards, certifications), read from the brand's
-- own pricing, About and product pages. The server reads them when someone
-- first asks and again each week; a person approves each one, and only the
-- approved ones are compared with a page.
--
--   * brand_facts: one row per fact, by what it is about (`slot`: "price of
--     the Pro plan, in USD, a month") and its value (`value_key`: "49.00").
--     `quote` is the page's own words, which hold the value: the server
--     keeps a fact only when its quote is on the page word for word, and
--     reads the value from it by rule. A new value in a slot is a new
--     pending fact: the person approves the change. An approved fact no
--     longer on the page is marked gone (`gone_at`) and left out of the
--     check; the server removes it after 30 days.
--   * brand_fact_pages: the pages read, one per kind, with a hash of their
--     text: an unchanged page isn't sent to the model again. No page text is
--     kept.
--
-- Members read the facts and change only their status (approve or reject),
-- as themselves; everything else is the server's. brand_fact_pages is
-- server-only.

create table if not exists public.brand_facts (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  kind text not null check (kind in ('price', 'trial', 'founded', 'claim')),
  slot text not null check (char_length(slot) between 1 and 300),
  value jsonb not null default '{}'::jsonb
    check (jsonb_typeof(value) = 'object' and octet_length(value::text) <= 1024),
  value_key text not null check (char_length(value_key) between 1 and 300),
  quote text not null check (char_length(quote) between 1 and 300),
  source_url text not null
    check (char_length(source_url) <= 2048 and source_url ~ '^https?://'),
  source_kind text not null check (source_kind in ('pricing', 'about', 'product')),
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected')),
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  gone_at timestamptz,
  unique (brand_id, slot, value_key),
  -- Each kind's value, as the server reads it from the fact's words.
  -- A key left out is a violation (a NULL check would pass), and a number
  -- out of range too, never a cast error.
  constraint brand_facts_kind_value_check check (
    coalesce(
      case kind
        when 'price' then
          jsonb_typeof(value -> 'amount') = 'number'
          and (value ->> 'amount')::numeric >= 0
          and coalesce(value ->> 'currency', '') ~ '^[A-Z]{3}$'
          and jsonb_typeof(value -> 'plan') = 'string'
        when 'trial' then
          jsonb_typeof(value -> 'days') = 'number'
          and (value ->> 'days')::numeric between 1 and 365
        when 'founded' then
          jsonb_typeof(value -> 'year') = 'number'
          and (value ->> 'year')::numeric between 1800 and 2100
        else true
      end,
      false
    )
  )
);

create index if not exists brand_facts_brand_status_idx
  on public.brand_facts (brand_id, status);

alter table public.brand_facts enable row level security;
revoke all on table public.brand_facts from anon, authenticated;
grant select on table public.brand_facts to authenticated;
-- A member changes a fact's status only: its value and words are the site's.
grant update (status, reviewed_by, reviewed_at) on table public.brand_facts to authenticated;
grant all on table public.brand_facts to service_role;

drop policy if exists "brand_facts: member select" on public.brand_facts;
create policy "brand_facts: member select"
  on public.brand_facts
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

drop policy if exists "brand_facts: member update" on public.brand_facts;
create policy "brand_facts: member update"
  on public.brand_facts
  for update
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  )
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
    and reviewed_by = auth.uid()
    and status in ('approved', 'rejected')
    and reviewed_at between now() - interval '1 minute' and now() + interval '1 minute'
  );

comment on table public.brand_facts is
  'Quality CE-047 (00269): a brand''s facts (prices, trial, founding year, claims) read from its own pricing, About and product pages, each kept with its words on the page; members approve or reject them, and only approved ones not gone from the site are compared with a page.';

create table if not exists public.brand_fact_pages (
  brand_id uuid not null references public.brands(id) on delete cascade,
  kind text not null check (kind in ('pricing', 'about', 'product')),
  url text check (url is null or char_length(url) <= 2048),
  status text not null check (status in ('ok', 'blocked', 'not_found', 'failed', 'missed')),
  text_hash text check (text_hash is null or text_hash ~ '^[0-9a-f]{16}$'),
  model text check (model is null or char_length(model) <= 100),
  checked_at timestamptz not null default now(),
  extracted_at timestamptz,
  primary key (brand_id, kind)
);

create index if not exists brand_fact_pages_checked_idx
  on public.brand_fact_pages (checked_at);

alter table public.brand_fact_pages enable row level security;
revoke all on table public.brand_fact_pages from anon, authenticated;
grant all on table public.brand_fact_pages to service_role;

comment on table public.brand_fact_pages is
  'Quality CE-047 (00269): the brand pages its facts were read from, one per kind, with a hash of their text (an unchanged page isn''t read by the model again) and when they were read. No page text is kept. Server-only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00270_content_quality_pages.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00270: Quality phase 2, CE-049 — a page's visual proof spots and proof asks
-- ============================================================================
-- Quality's dynamic suggestions (spec §4b) read the whole page, with its page
-- type and the brand's business type (B2B, B2C, e-commerce):
--
--   * visual proof spots: where one specific image the business can take
--     itself (a screenshot of its own tool's result, a photo of this product
--     in use) would prove what a paragraph says; three a page at most, one
--     an H2 section, none when no specific image fits;
--   * proof asks: claims the business makes about itself whose proof only it
--     has (an award, a certification, its own test, a rating, a ranking, its
--     own figure, a named customer), each with the kind of proof it needs;
--   * whether the page advises consumers on health, finance or law (a
--     qualified reviewer is asked for).
--
-- content_quality_pages keeps the last read of each draft, by a hash of its
-- headings, paragraphs and types: an unchanged page isn't read again. Each
-- item names its paragraph by the hash the claims read keeps it by (00266),
-- so an item whose paragraph changed drops out. `missed` marks a read whose
-- answer missed the schema: read again after a day. `day_reads` counts the
-- reads since `day_started_at` (a draft's page reads a day are capped).
-- Server-only.
--
-- content_draft_own_images: the images a member confirmed are their own,
-- not stock (E-E-A-T's visual proof): only the person can tell, so it is
-- their statement, kept with who made it. An image is named by its address;
-- a new address is confirmed again. 50 a draft at most.

create table if not exists public.content_quality_pages (
  draft_id uuid primary key references public.content_drafts(id) on delete cascade,
  page_hash text not null check (page_hash ~ '^[0-9a-f]{16}$'),
  site_type text not null check (site_type in ('b2b', 'ecommerce', 'b2c')),
  page_type text check (page_type is null or char_length(page_type) <= 50),
  -- [{ "passage", "block_hash", "image", "alt" }]
  spots jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(spots) = 'array'
      and jsonb_array_length(spots) <= 3
      and octet_length(spots::text) <= 8192
    ),
  -- [{ "claim", "block_hash", "kind" }]
  proofs jsonb not null default '[]'::jsonb
    check (
      jsonb_typeof(proofs) = 'array'
      and jsonb_array_length(proofs) <= 8
      and octet_length(proofs::text) <= 8192
    ),
  regulated text check (regulated is null or regulated in ('health', 'finance', 'legal')),
  model text check (model is null or char_length(model) <= 100),
  missed boolean not null default false,
  read_at timestamptz not null default now(),
  day_reads smallint not null default 0 check (day_reads >= 0),
  day_started_at timestamptz
);

alter table public.content_quality_pages enable row level security;
revoke all on table public.content_quality_pages from anon, authenticated;
grant all on table public.content_quality_pages to service_role;

comment on table public.content_quality_pages is
  'Quality CE-049 (00270): the last read of a draft''s page for visual proof spots and proof asks, by a hash of its headings, paragraphs and types; items name their paragraph by its hash (00266). Server-only.';

create table if not exists public.content_draft_own_images (
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  src text not null check (char_length(src) between 8 and 2048 and src ~ '^https?://'),
  confirmed_by uuid references public.profiles(id) on delete set null,
  confirmed_at timestamptz not null default now(),
  primary key (draft_id, src)
);

alter table public.content_draft_own_images enable row level security;
revoke all on table public.content_draft_own_images from anon, authenticated;
grant select, insert on table public.content_draft_own_images to authenticated;
grant all on table public.content_draft_own_images to service_role;

drop policy if exists "content_draft_own_images: member select" on public.content_draft_own_images;
create policy "content_draft_own_images: member select"
  on public.content_draft_own_images
  for select
  using (public.content_draft_member(draft_id));

-- A member confirms as themself, now.
drop policy if exists "content_draft_own_images: member insert" on public.content_draft_own_images;
create policy "content_draft_own_images: member insert"
  on public.content_draft_own_images
  for insert
  with check (
    public.content_draft_member(draft_id)
    and confirmed_by = auth.uid()
    and confirmed_at between now() - interval '1 minute' and now() + interval '1 minute'
  );

create or replace function public.content_draft_own_images_cap()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- One confirm at a time a draft, so the count holds.
  perform pg_advisory_xact_lock(hashtext('content_draft_own_images'), hashtext(new.draft_id::text));
  -- Confirmed already: the insert's ON CONFLICT leaves it as it is.
  if exists (
    select 1 from public.content_draft_own_images where draft_id = new.draft_id and src = new.src
  ) then
    return new;
  end if;
  if (select count(*) from public.content_draft_own_images where draft_id = new.draft_id) >= 50 then
    raise exception 'A draft keeps 50 confirmed images at most' using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists content_draft_own_images_cap on public.content_draft_own_images;
create trigger content_draft_own_images_cap
  before insert on public.content_draft_own_images
  for each row execute function public.content_draft_own_images_cap();

comment on table public.content_draft_own_images is
  'Quality CE-049 (00270): images a member confirmed are their own (E-E-A-T visual proof), by address, with who confirmed; 50 a draft at most. Members read and insert as themselves; no update or delete.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00271_content_draft_author_confirmed.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00271: Quality — the page's author confirmed by the person (E-E-A-T)
-- ============================================================================
-- E-E-A-T counts who stands behind a page: a real, named author (the
-- byline) with a profile (a bio and links). Many sites already show their
-- author through the CMS, so picking one of GetCito's authors isn't the
-- only way: the person can confirm, page by page,
--
--   * author_real:    the page's author is a real person, named on our site;
--   * author_profile: their profile there has a bio and links.
--
-- Each is the person's own statement, kept with who made it and when; a
-- trigger stamps both from the session, so no one confirms in another's
-- name, and unticking clears them.

alter table public.content_drafts
  add column if not exists author_real_at timestamptz,
  add column if not exists author_real_by uuid references public.profiles(id) on delete set null,
  add column if not exists author_profile_at timestamptz,
  add column if not exists author_profile_by uuid references public.profiles(id) on delete set null;

comment on column public.content_drafts.author_real_at is
  'Quality (00271): when a member confirmed the page''s author is a real person named on the site (E-E-A-T byline); null when not confirmed.';
comment on column public.content_drafts.author_profile_at is
  'Quality (00271): when a member confirmed the author''s profile on the site has a bio and links (E-E-A-T profile); null when not confirmed.';

-- Who and when come from the session, not the request: a confirmation is
-- stamped now, by the member making it; a change to who alone is undone,
-- clearing it too. Only a role that bypasses RLS changes who alone: the
-- profiles FK's on delete set null, run as the table's owner. On insert
-- OLD is null: a draft starts with only what the session stamps.
create or replace function public.content_drafts_author_confirmed()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.author_real_at is distinct from old.author_real_at then
    if new.author_real_at is null then
      -- Unticked: the profile's word goes with the author's.
      new.author_real_by := null;
      new.author_profile_at := null;
      new.author_profile_by := null;
      return new;
    end if;
    new.author_real_at := now();
    new.author_real_by := auth.uid();
  elsif new.author_real_by is distinct from old.author_real_by
    and (tg_op = 'INSERT'
         or not (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)) then
    new.author_real_by := old.author_real_by;
  end if;
  if new.author_profile_at is distinct from old.author_profile_at then
    if new.author_profile_at is null then
      new.author_profile_by := null;
    else
      new.author_profile_at := now();
      new.author_profile_by := auth.uid();
    end if;
  elsif new.author_profile_by is distinct from old.author_profile_by
    and (tg_op = 'INSERT'
         or not (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)) then
    new.author_profile_by := old.author_profile_by;
  end if;
  return new;
end;
$$;

drop trigger if exists content_drafts_author_confirmed on public.content_drafts;
create trigger content_drafts_author_confirmed
  before insert or update on public.content_drafts
  for each row execute function public.content_drafts_author_confirmed();

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00272_content_images_storage.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00272: Content images — upload an image instead of pasting its address
-- ============================================================================
-- Most people have the screenshot or photo on their computer, not at an
-- address. The Content Editor's image dialogs and an author's photo upload
-- it here: a public bucket (the page and the CMS show it by its address),
-- JPEG, PNG, WebP or GIF, 5 MB at most.
--
-- Each organization's images go under its own folder ({organization_id}/
-- {id}.{ext}). Members have no policy here: the app gives a one-time
-- upload address for a name it makes, and says who may upload and how
-- much (on the managed cloud, an organization with an active or trialing
-- subscription, a number a day; only the app knows a cloud from a
-- self-host). Nothing is overwritten or deleted from the app; anyone with
-- an image's address can see it, as any image on a published page.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'content-images',
  'content-images',
  true,
  5242880,
  array['image/jpeg', 'image/png', 'image/webp', 'image/gif']
)
-- Run again, it leaves the bucket as an admin may have set it.
on conflict (id) do nothing;

-- Each one-time upload address the app gives, on the managed cloud: the
-- day's cap counts them, not the files arrived (an address may be used
-- later). Only the service role reads and writes it.
create table if not exists public.content_image_uploads (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  path text not null,
  created_at timestamptz not null default now()
);

create index if not exists content_image_uploads_org_created_idx
  on public.content_image_uploads (organization_id, created_at);

alter table public.content_image_uploads enable row level security;

comment on table public.content_image_uploads is
  'Content images (00272): each one-time upload address given on the managed cloud, for the daily cap. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00273_content_draft_reviewer.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00273: Quality CE-049 — a qualified reviewer for regulated pages
-- ============================================================================
-- A consumer page that advises on health, finance or law (the page read's
-- `regulated`, 00270) asks for a qualified reviewer: "Reviewed by {name,
-- credential}", from Authors only (Quality spec §4b). Like the author
-- (00257), it is page metadata: the editor shows it outside the page,
-- never in the page's text.
--
--   * content_drafts.reviewer_id: one of the brand's organization's authors,
--     else null.

alter table public.content_drafts
  add column if not exists reviewer_id uuid
    references public.content_authors(id) on delete set null;

create index if not exists content_drafts_reviewer
  on public.content_drafts (reviewer_id)
  where reviewer_id is not null;

comment on column public.content_drafts.reviewer_id is
  'Quality CE-049 (00273): the qualified person who reviewed a regulated page (content_authors), page metadata — never the page''s text; null when none.';

create or replace function public.content_draft_reviewer()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.reviewer_id is not null
     and (tg_op = 'INSERT' or new.reviewer_id is distinct from old.reviewer_id)
     and not exists (
       select 1
       from public.content_authors a
       join public.brands b on b.organization_id = a.organization_id
       where a.id = new.reviewer_id and b.id = new.brand_id
     )
  then
    raise exception 'content draft reviewer is not one of the brand''s organization'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists content_drafts_reviewer on public.content_drafts;
create trigger content_drafts_reviewer
  before insert or update of reviewer_id on public.content_drafts
  for each row execute function public.content_draft_reviewer();

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00274_content_quality_page_checks.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00274: Quality phase 2, CE-050 — the page read's checks
-- ============================================================================
-- The page read (00270) also says, in the page's own words:
--
--   * answerFirst: whether the paragraph right after the H1 answers it;
--   * recommends: where the page puts the brand forward among options;
--   * disclosure: where it says the brand makes what it recommends;
--   * balance: a real limit of the brand's own product, or where another
--     option wins;
--   * how: how the page's content was made (who, how, why);
--   * cut: whether the model read less than the whole page (a check not
--     found may be in the rest).
--
-- Each found one names its paragraph by its hash, as the read's items do;
-- null when the page wasn't read for them (a read before this, a missed one).

alter table public.content_quality_pages
  add column if not exists checks jsonb
    check (
      checks is null
      or (jsonb_typeof(checks) = 'object' and octet_length(checks::text) <= 4096)
    );

comment on column public.content_quality_pages.checks is
  'Quality CE-050 (00274): { answerFirst: { block_hash, answers } | null, recommends | disclosure | balance | how: { quote, block_hash } | null, cut: boolean }; null when the page wasn''t read for them.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00275_content_quality_handoff.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00275: Quality phase 2, CE-051 — hand it off to the Content Agent
-- ============================================================================
-- Hand off has the Content Agent fix every fixable Quality suggestion in one
-- run, as suggestions the person reviews: a run of its own kind. A brand may
-- hand off its new and optimized pages on their own (Settings › Content,
-- off by default); each such draft gets its automatic run once.
--
--   * content_agent_runs.kind gains 'handoff'; origin says who started a
--     run: a person, or the editor on its own ('auto'), one a draft;
--   * brands.content_quality_handoff: the brand's setting;
--   * content_drafts.quality_handoff: the setting as it was when the draft
--     was made (a trigger copies it; a member can't change it), so turning
--     it on reaches new drafts only.

alter table public.content_agent_runs drop constraint if exists content_agent_runs_kind_check;
alter table public.content_agent_runs
  add constraint content_agent_runs_kind_check
  check (kind in ('fix', 'rewrite', 'write', 'brief', 'handoff'));

alter table public.content_agent_runs
  add column if not exists origin text not null default 'person'
  check (origin in ('person', 'auto'));

-- An automatic hand-off is once a draft: its row is the claim.
create unique index if not exists content_agent_runs_auto_handoff
  on public.content_agent_runs (draft_id)
  where kind = 'handoff' and origin = 'auto';

comment on column public.content_agent_runs.origin is
  'Content Agent run (00275): who started it — a person, or the editor on its own (auto: Quality''s hand-off, once a draft).';

alter table public.brands
  add column if not exists content_quality_handoff boolean not null default false;

comment on column public.brands.content_quality_handoff is
  'Quality CE-051 (00275): hand off quality fixes automatically — new and optimized pages get the Content Agent''s hand-off run, its changes left for review. Off by default.';

alter table public.content_drafts
  add column if not exists quality_handoff boolean not null default false;

comment on column public.content_drafts.quality_handoff is
  'Quality CE-051 (00275): the brand''s hand-off setting when the draft was made (a trigger copies it); its automatic hand-off runs once.';

-- As the member who makes the draft (RLS reads their brand); the server
-- bypasses RLS. A change by a member is undone: only the server sets it.
create or replace function public.content_draft_quality_handoff()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    select b.content_quality_handoff into new.quality_handoff
    from public.brands b
    where b.id = new.brand_id;
    new.quality_handoff := coalesce(new.quality_handoff, false);
  elsif new.quality_handoff is distinct from old.quality_handoff
    and not (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)
  then
    new.quality_handoff := old.quality_handoff;
  end if;
  return new;
end;
$$;

drop trigger if exists content_drafts_quality_handoff on public.content_drafts;
create trigger content_drafts_quality_handoff
  before insert or update of quality_handoff on public.content_drafts
  for each row execute function public.content_draft_quality_handoff();

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00276_organization_insert_columns.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00276: a new organization's plan and billing are set by the server
-- ============================================================================
-- An organization's plan, billing state and AI key columns belong to the
-- server: Stripe's webhook, the billing routes and the key settings write them
-- with the service role (00062). Onboarding creates the organization with the
-- person's own session, and sends only its name and slug; every other column
-- starts at its default.
--
-- 00062's guard compares the new row with the old one, so it ran on update
-- only. On insert there is no old row: the columns are held to their defaults
-- instead. A role that bypasses row-level security (the service role,
-- migrations) still sets them, as before.

create or replace function public.guard_organization_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.plan is distinct from 'free'
       or new.plan_overrides is not null
       or new.subscription_status is distinct from 'incomplete'
       or new.subscription_ends_at is not null
       or new.stripe_customer_id is not null
       or new.stripe_subscription_id is not null
       or new.anthropic_api_key_encrypted is not null
       or new.anthropic_api_key_last4 is not null
       or new.anthropic_api_key_set_at is not null
       or new.anthropic_api_key_set_by is not null
    then
      raise exception 'organization column is managed server-side and cannot be set from the client'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.plan is distinct from old.plan
     or new.plan_overrides is distinct from old.plan_overrides
     or new.subscription_status is distinct from old.subscription_status
     or new.subscription_ends_at is distinct from old.subscription_ends_at
     or new.stripe_customer_id is distinct from old.stripe_customer_id
     or new.stripe_subscription_id is distinct from old.stripe_subscription_id
     or new.anthropic_api_key_encrypted is distinct from old.anthropic_api_key_encrypted
     or new.anthropic_api_key_last4 is distinct from old.anthropic_api_key_last4
     or new.anthropic_api_key_set_at is distinct from old.anthropic_api_key_set_at
     or new.anthropic_api_key_set_by is distinct from old.anthropic_api_key_set_by
  then
    raise exception 'organization column is managed server-side and cannot be set from the client'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

drop trigger if exists organizations_guard_server_columns on public.organizations;

create trigger organizations_guard_server_columns
  before insert or update on public.organizations
  for each row
  execute function public.guard_organization_server_columns();

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00277_brand_openai_product_feed.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00277: a brand's word that it sends OpenAI a direct product feed (#1281)
-- ============================================================================
-- In the US, ChatGPT Shopping picks products from OpenAI's own product
-- index. There's no public API to check whether a catalog is in it, so the
-- Shopping page shows what we can know: the brand's own word that it sends a
-- direct feed (this column), else whether its own products appear in tracked
-- US ChatGPT Shopping answers. Off by default. Admins and managers change it,
-- as the rest of a brand (brands: admin/manager update).

alter table public.brands
  add column if not exists openai_product_feed boolean not null default false;

comment on column public.brands.openai_product_feed is
  'Shopping (#1281): the brand says it sends OpenAI a direct product feed, so its catalog is in OpenAI''s product index (ChatGPT Shopping, US). Off by default.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00278_catalog.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00278: the product catalog (#1263, part 1)
-- ============================================================================
-- One shape every catalog source writes into: a store connection, a product
-- feed URL, a CSV upload. Everything is a brand's:
--
--   * catalog_products: a product, keyed by (brand, source, external id). A
--     feed's item group is one product; an item with no group is its own.
--   * catalog_variants: what's sold: SKU, GTIN, MPN, a marketplace's item id
--     (ASIN), price, availability and the options that make it (color,
--     size, material, as `attributes`).
--   * catalog_images: a product's or a variant's images, in order.
--   * catalog_categories: a flat list per brand (a feed's product type, as
--     written), and catalog_product_categories, a product's (several).
--
-- Only the server writes (the service role), through one batch sync
-- (backend/src/lib/catalog/sync.js) that updates rows in place and marks a
-- product or variant gone from its source as removed (removed_at), never
-- deleting it. `content_hash` is the sync's: a row whose content didn't
-- change isn't written again. Members read their brands' rows.

create table if not exists public.catalog_products (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  source text not null check (source ~ '^[a-z][a-z0-9_]{1,39}$'),
  external_id text not null check (char_length(external_id) between 1 and 300),
  title text not null check (char_length(title) between 1 and 1000),
  description text check (description is null or char_length(description) <= 20000),
  product_brand text check (product_brand is null or char_length(product_brand) <= 300),
  url text check (url is null or (char_length(url) <= 2048 and url ~ '^https?://')),
  product_type text check (product_type is null or char_length(product_type) <= 750),
  content_hash text not null check (content_hash ~ '^[0-9a-f]{40}$'),
  removed_at timestamptz,
  first_seen_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (brand_id, source, external_id)
);

create index if not exists catalog_products_brand_live_idx
  on public.catalog_products (brand_id)
  where removed_at is null;

create table if not exists public.catalog_variants (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  product_id uuid not null references public.catalog_products(id) on delete cascade,
  source text not null check (source ~ '^[a-z][a-z0-9_]{1,39}$'),
  external_id text not null check (char_length(external_id) between 1 and 300),
  title text check (title is null or char_length(title) <= 1000),
  sku text check (sku is null or char_length(sku) <= 300),
  gtin text check (gtin is null or char_length(gtin) <= 50),
  mpn text check (mpn is null or char_length(mpn) <= 300),
  marketplace_item_id text check (marketplace_item_id is null or char_length(marketplace_item_id) <= 300),
  url text check (url is null or (char_length(url) <= 2048 and url ~ '^https?://')),
  price numeric(14, 2) check (price is null or price >= 0),
  sale_price numeric(14, 2) check (sale_price is null or sale_price >= 0),
  currency text check (currency is null or currency ~ '^[A-Z]{3}$'),
  availability text check (availability is null or char_length(availability) <= 50),
  condition text check (condition is null or char_length(condition) <= 50),
  attributes jsonb not null default '{}'::jsonb
    check (jsonb_typeof(attributes) = 'object' and octet_length(attributes::text) <= 4096),
  content_hash text not null check (content_hash ~ '^[0-9a-f]{40}$'),
  removed_at timestamptz,
  first_seen_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (brand_id, source, external_id)
);

create index if not exists catalog_variants_product_idx on public.catalog_variants (product_id);
create index if not exists catalog_variants_brand_gtin_idx
  on public.catalog_variants (brand_id, gtin)
  where gtin is not null;

create table if not exists public.catalog_images (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  product_id uuid not null references public.catalog_products(id) on delete cascade,
  variant_id uuid references public.catalog_variants(id) on delete cascade,
  url text not null check (char_length(url) <= 2048 and url ~ '^https?://'),
  position smallint not null default 0 check (position >= 0)
);

create index if not exists catalog_images_product_idx on public.catalog_images (product_id);
create index if not exists catalog_images_variant_idx on public.catalog_images (variant_id);

create table if not exists public.catalog_categories (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 750),
  created_at timestamptz not null default now(),
  unique (brand_id, name)
);

create table if not exists public.catalog_product_categories (
  brand_id uuid not null references public.brands(id) on delete cascade,
  product_id uuid not null references public.catalog_products(id) on delete cascade,
  category_id uuid not null references public.catalog_categories(id) on delete cascade,
  primary key (product_id, category_id)
);

create index if not exists catalog_product_categories_category_idx
  on public.catalog_product_categories (category_id);

-- Members read their brands' catalog; only the service role writes.
do $$
declare
  t text;
begin
  foreach t in array array[
    'catalog_products',
    'catalog_variants',
    'catalog_images',
    'catalog_categories',
    'catalog_product_categories'
  ]
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select on table public.%I to authenticated', t);
    execute format('grant all on table public.%I to service_role', t);
    execute format('drop policy if exists %I on public.%I', t || ': member select', t);
    execute format(
      'create policy %I on public.%I for select using (
         brand_id in (
           select b.id from public.brands b
           join public.profiles p on p.organization_id = b.organization_id
           where p.id = auth.uid()
         )
       )',
      t || ': member select',
      t
    );
  end loop;
end $$;

comment on table public.catalog_products is
  'Catalog (#1263, 00278): a brand''s products from a source (store, feed, CSV), keyed by (brand, source, external id); removed_at once gone from the source. Server writes, members read.';
comment on table public.catalog_variants is
  'Catalog (#1263, 00278): a product''s variants: SKU, GTIN, MPN, marketplace item id, price, availability and options (attributes). Server writes, members read.';
comment on table public.catalog_images is
  'Catalog (#1263, 00278): a product''s or variant''s images, in order. Server writes, members read.';
comment on table public.catalog_categories is
  'Catalog (#1263, 00278): a brand''s categories, a flat list (a feed''s product type as written). Server writes, members read.';
comment on table public.catalog_product_categories is
  'Catalog (#1263, 00278): the categories a product is in. Server writes, members read.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00279_catalog_sources.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00279: where a brand's catalog comes from (#1263, part 2)
-- ============================================================================
-- A brand's catalog sources: a product feed URL the server reads every day
-- (and on demand), or the CSV a person uploads. Each source's products are
-- kept in the catalog (00278) under its own `source` key,
-- `src_<the source's id without dashes>`, so two feeds of one brand never
-- mark each other's products removed.
--
--   * Members read their brands' sources; admins and managers add, change
--     and remove them (as the rest of a brand). A feed URL must be http(s);
--     the server fetches it only to public addresses.
--   * The last sync's outcome (`last_*`) is the server's to write.
--   * At most 10 sources a brand, one upload source each.
--   * Removing a source removes its products from the catalog: nothing of
--     a source outlives it.

create table if not exists public.catalog_sources (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  kind text not null check (kind in ('feed_url', 'upload')),
  format text not null default 'auto'
    check (format in ('auto', 'google_xml', 'csv', 'meta_csv')),
  url text check (url is null or (char_length(url) <= 2048 and url ~ '^https?://')),
  label text check (label is null or char_length(label) between 1 and 200),
  last_synced_at timestamptz,
  last_status text check (last_status is null or last_status in ('ok', 'failed', 'format_error')),
  last_error text check (last_error is null or char_length(last_error) <= 1000),
  last_counts jsonb check (
    last_counts is null
    or (jsonb_typeof(last_counts) = 'object' and octet_length(last_counts::text) <= 4096)
  ),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint catalog_sources_url_kind check ((kind = 'feed_url') = (url is not null)),
  unique (brand_id, url)
);

create unique index if not exists catalog_sources_one_upload
  on public.catalog_sources (brand_id)
  where kind = 'upload';
create index if not exists catalog_sources_feed_due_idx
  on public.catalog_sources (last_synced_at nulls first)
  where kind = 'feed_url';

alter table public.catalog_sources enable row level security;
revoke all on table public.catalog_sources from anon, authenticated;
grant select on table public.catalog_sources to authenticated;
grant insert (brand_id, kind, format, url, label, created_by) on table public.catalog_sources to authenticated;
grant update (format, label) on table public.catalog_sources to authenticated;
grant delete on table public.catalog_sources to authenticated;
grant all on table public.catalog_sources to service_role;

drop policy if exists "catalog_sources: member select" on public.catalog_sources;
create policy "catalog_sources: member select"
  on public.catalog_sources
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

drop policy if exists "catalog_sources: admin/manager insert" on public.catalog_sources;
create policy "catalog_sources: admin/manager insert"
  on public.catalog_sources
  for insert
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
    and created_by = auth.uid()
  );

drop policy if exists "catalog_sources: admin/manager update" on public.catalog_sources;
create policy "catalog_sources: admin/manager update"
  on public.catalog_sources
  for update
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

drop policy if exists "catalog_sources: admin/manager delete" on public.catalog_sources;
create policy "catalog_sources: admin/manager delete"
  on public.catalog_sources
  for delete
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

-- At most 10 sources a brand. Serialized per brand, so two inserts at once
-- can't both pass.
create or replace function public.catalog_sources_cap()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(hashtext('catalog_sources'), hashtext(new.brand_id::text));
  if (select count(*) from public.catalog_sources where brand_id = new.brand_id) >= 10 then
    raise exception 'A brand has 10 catalog sources at most' using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists catalog_sources_cap on public.catalog_sources;
create trigger catalog_sources_cap
  before insert on public.catalog_sources
  for each row execute function public.catalog_sources_cap();

-- A removed source takes its products with it. Members can't write the
-- catalog, so this runs as the table's owner; it touches only the removed
-- source's own rows (its brand and its source key).
create or replace function public.catalog_sources_forget()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.catalog_products
  where brand_id = old.brand_id
    and source = 'src_' || replace(old.id::text, '-', '');
  delete from public.catalog_variants
  where brand_id = old.brand_id
    and source = 'src_' || replace(old.id::text, '-', '');
  return old;
end;
$$;

revoke all on function public.catalog_sources_forget() from public, anon, authenticated;

drop trigger if exists catalog_sources_forget on public.catalog_sources;
create trigger catalog_sources_forget
  after delete on public.catalog_sources
  for each row execute function public.catalog_sources_forget();

comment on table public.catalog_sources is
  'Catalog (#1263, 00279): where a brand''s catalog comes from: a feed URL read daily, or an uploaded CSV. Its products are kept under source src_<id>. Members read; admins and managers add, change and remove; the server writes last_*. Removing one removes its products.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00280_content_draft_confirmations.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00280: Quality phase 3, CE-052 — what only the person can confirm
-- ============================================================================
-- What Quality can't verify on its own becomes a confirm step, never a pass
-- (Content Editor Quality spec §11): a customer's case (their name, logo or
-- results) goes out only with their permission, and only the person knows
-- they have it. Their statement is kept here, with who made it, by what it
-- is about: its kind, and its key (a customer case's, by its claim's words;
-- the page matches a case to it by those words). Category pages' intro
-- facts (CE-054) are confirmed here too.

create table if not exists public.content_draft_confirmations (
  draft_id uuid not null references public.content_drafts(id) on delete cascade,
  kind text not null check (kind in ('customer_case', 'intro_fact')),
  key text not null check (char_length(key) between 1 and 400),
  confirmed_by uuid references public.profiles(id) on delete set null,
  confirmed_at timestamptz not null default now(),
  primary key (draft_id, kind, key)
);

alter table public.content_draft_confirmations enable row level security;
revoke all on table public.content_draft_confirmations from anon, authenticated;
grant select, insert on table public.content_draft_confirmations to authenticated;
grant all on table public.content_draft_confirmations to service_role;

comment on table public.content_draft_confirmations is
  'Quality CE-052 (00280): what a member confirmed that only they can (a customer case may be published; a category intro''s facts are right), by kind and key, with who and when. Members read their drafts'' and confirm as themselves; no update or delete.';

drop policy if exists "content_draft_confirmations: member select" on public.content_draft_confirmations;
create policy "content_draft_confirmations: member select"
  on public.content_draft_confirmations
  for select
  using (public.content_draft_member(draft_id));

-- A member confirms as themself, now.
drop policy if exists "content_draft_confirmations: member insert" on public.content_draft_confirmations;
create policy "content_draft_confirmations: member insert"
  on public.content_draft_confirmations
  for insert
  with check (
    public.content_draft_member(draft_id)
    and confirmed_by = auth.uid()
    and confirmed_at between now() - interval '1 minute' and now() + interval '1 minute'
  );

create or replace function public.content_draft_confirmations_cap()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- One confirm at a time a draft, so the count holds.
  perform pg_advisory_xact_lock(hashtext('content_draft_confirmations'), hashtext(new.draft_id::text));
  -- Confirmed already: the insert's ON CONFLICT leaves it as it is.
  if exists (
    select 1 from public.content_draft_confirmations
    where draft_id = new.draft_id and kind = new.kind and key = new.key
  ) then
    return new;
  end if;
  if (select count(*) from public.content_draft_confirmations where draft_id = new.draft_id) >= 50 then
    raise exception 'A draft keeps 50 confirmations at most' using errcode = '23514';
  end if;
  return new;
end;
$$;

drop trigger if exists content_draft_confirmations_cap on public.content_draft_confirmations;
create trigger content_draft_confirmations_cap
  before insert on public.content_draft_confirmations
  for each row execute function public.content_draft_confirmations_cap();

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00281_catalog_variants_brand_live.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00281: Quality phase 3, CE-053 — a brand's live variants, by its brand
-- ============================================================================
-- The Content Editor finds a product page's product in the brand's catalog
-- (00278) by the page's URL: the product's own (catalog_products_brand_live_idx
-- serves that read), else a variant's, when a feed gives a variant its own
-- page. This index serves the variants' read the same way, so it reads the
-- brand's live variants only, not every brand's.

create index if not exists catalog_variants_brand_live_idx
  on public.catalog_variants (brand_id)
  where removed_at is null;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00282_catalog_store_connections.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00282: store connections for the catalog (#1263, part 3)
-- ============================================================================
-- A catalog source (00279) can now be a store or marketplace a connector
-- reads with the brand's own sign-in (WooCommerce, Etsy, …), next to a feed
-- URL and an upload.
--
--   * A source's kind is its connector's: any short slug. The server only
--     syncs kinds it has a connector for.
--   * Members still add only feed URLs and uploads themselves. A store is
--     connected through the API, which checks the sign-in with the store,
--     makes the source and keeps its credentials, so a store source never
--     exists without them.
--   * `account` names the store's account to the person: a shop's domain,
--     a seller id. A store's `url` is optional; a feed's is required, and an
--     upload has none.
--   * A brand connects each store account once.
--   * Members remove feed URLs and uploads themselves. A store is removed
--     through the API, which revokes its sign-in at the store first.
--   * `auth_failed`: the store refused the saved sign-in.
--   * The daily run reads every kind but uploads.
--
-- Credentials live in `catalog_source_credentials`, one row per source,
-- encrypted by the API with a key only it holds (AES-256-GCM, bound to the
-- source's id). Only the service role reads or writes them: members can't
-- even see that a row exists. They go with their source.

alter table public.catalog_sources drop constraint if exists catalog_sources_kind_check;
alter table public.catalog_sources
  add constraint catalog_sources_kind_check check (kind ~ '^[a-z][a-z0-9_]{1,39}$');

alter table public.catalog_sources drop constraint if exists catalog_sources_url_kind;
alter table public.catalog_sources
  add constraint catalog_sources_url_kind check (
    (kind <> 'feed_url' or url is not null) and (kind <> 'upload' or url is null)
  );

alter table public.catalog_sources
  add column if not exists account text
    check (account is null or char_length(account) between 1 and 200);

alter table public.catalog_sources drop constraint if exists catalog_sources_last_status_check;
alter table public.catalog_sources
  add constraint catalog_sources_last_status_check check (
    last_status is null or last_status in ('ok', 'failed', 'format_error', 'auth_failed')
  );

-- Members add feed URLs and uploads; stores come through the API.
drop policy if exists "catalog_sources: admin/manager insert" on public.catalog_sources;
create policy "catalog_sources: admin/manager insert"
  on public.catalog_sources
  for insert
  with check (
    kind in ('feed_url', 'upload')
    and brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
    and created_by = auth.uid()
  );

-- Members remove feed URLs and uploads; stores go through the API.
drop policy if exists "catalog_sources: admin/manager delete" on public.catalog_sources;
create policy "catalog_sources: admin/manager delete"
  on public.catalog_sources
  for delete
  using (
    kind in ('feed_url', 'upload')
    and brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

create unique index if not exists catalog_sources_one_account
  on public.catalog_sources (brand_id, kind, account)
  where account is not null;

drop index if exists public.catalog_sources_feed_due_idx;
create index if not exists catalog_sources_due_idx
  on public.catalog_sources (last_synced_at nulls first)
  where kind <> 'upload';

create table if not exists public.catalog_source_credentials (
  source_id uuid primary key references public.catalog_sources(id) on delete cascade,
  secret text not null check (char_length(secret) between 1 and 16384),
  set_at timestamptz not null default now(),
  set_by uuid references public.profiles(id) on delete set null
);

alter table public.catalog_source_credentials enable row level security;
revoke all on table public.catalog_source_credentials from public, anon, authenticated;
grant all on table public.catalog_source_credentials to service_role;

comment on table public.catalog_source_credentials is
  'Catalog (#1263, 00282): a store source''s sign-in, encrypted by the API (AES-256-GCM, bound to the source id). Service role only; removed with its source.';
comment on column public.catalog_sources.account is
  'The store''s account as the person knows it (a shop domain, a seller id), set by the API when the store is connected.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00283_brand_cms_connections.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00283: a brand's CMS connection for Send to CMS (#1331, phase 2)
-- ============================================================================
-- Phase 1 sends pages to the brand's webhook. Phase 2 sends them to the CMS
-- itself, Webflow first: a brand connects its Webflow site with a site token,
-- picks the collection its pages go to and which of the collection's fields
-- takes what.
--
--   * One connection a brand and CMS. A Webflow site token is one site's, so
--     the connection is the brand's, not the workspace's.
--   * The token never touches this table: Composio keeps it (an API-key
--     connected account, as Search Console's OAuth tokens are kept, 00045).
--     We keep the connected account's id and its Composio user.
--   * `field_map`: which of the collection's fields takes each part of a page
--     ({ body, metaTitle, metaDescription, jsonLd } → a field's slug). The
--     item's name and slug always go to Webflow's own `name` and `slug`.
--   * `auth_failed`: Webflow refused the saved token; the person connects again.
--   * Members read their brands' connections (the Send dialog and Settings
--     show them); only the server writes them, for admins and managers.

create table if not exists public.brand_cms_connections (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  provider text not null check (provider in ('webflow')),
  composio_account_id text not null check (char_length(composio_account_id) between 1 and 200),
  composio_entity_id text not null check (char_length(composio_entity_id) between 1 and 200),
  status text not null default 'connected' check (status in ('connected', 'auth_failed')),
  site_id text check (site_id is null or char_length(site_id) between 1 and 100),
  site_name text check (site_name is null or char_length(site_name) <= 300),
  collection_id text check (collection_id is null or char_length(collection_id) between 1 and 100),
  collection_name text check (collection_name is null or char_length(collection_name) <= 300),
  field_map jsonb not null default '{}'::jsonb check (
    jsonb_typeof(field_map) = 'object' and octet_length(field_map::text) <= 2048
  ),
  connected_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- A collection is picked on its site.
  constraint brand_cms_connections_collection_site check (collection_id is null or site_id is not null),
  unique (brand_id, provider)
);

alter table public.brand_cms_connections enable row level security;
revoke all on table public.brand_cms_connections from anon, authenticated;
grant select on table public.brand_cms_connections to authenticated;
grant all on table public.brand_cms_connections to service_role;

drop policy if exists "brand_cms_connections: member select" on public.brand_cms_connections;
create policy "brand_cms_connections: member select"
  on public.brand_cms_connections
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.brand_cms_connections is
  'Send to CMS, phase 2 (#1331, 00283): a brand''s CMS connection (Webflow first): its Composio connected account (the token stays at Composio), the site and collection pages go to, and field_map (body, metaTitle, metaDescription, jsonLd → the collection''s field slugs). Members read; the server writes for admins and managers.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00284_content_delivery_targets.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00284: where a page was sent (Send to CMS #1331, phase 2)
-- ============================================================================
-- Phase 1 sent every page to the brand's webhook (00262). A page now goes to
-- the webhook or to the brand's Webflow collection (00283), so a delivery
-- says which:
--
--   * `target`: 'webhook' (every delivery so far) or 'webflow'.
--   * `target_collection`: the Webflow collection the item was written to.
--     The item's id is the delivery's external_id, as a CMS's own id is for
--     the webhook. A page sent again updates its item while the brand still
--     sends to that collection, and makes a new one after it changes.
--
-- reserve_content_deliveries takes the target, 'webhook' when it's left out:
-- the API before this change calls it with six arguments and still works,
-- so the migration goes first. For Webflow it refuses (delivery_in_progress)
-- pages a send still has queued: two sends of one page at once would both
-- make an item, the second refused on its slug.
--
-- Adding the columns checks content_draft_deliveries' rows once (the check
-- constraints), under its lock: a few hundred rows at most so far.

alter table public.content_draft_deliveries
  add column if not exists target text not null default 'webhook'
    check (target in ('webhook', 'webflow')),
  add column if not exists target_collection text
    check (target_collection is null or char_length(target_collection) between 1 and 100);

comment on column public.content_draft_deliveries.target is
  'Where the page was sent (00284): the brand''s webhook, or its Webflow collection (00283).';
comment on column public.content_draft_deliveries.target_collection is
  'The Webflow collection the page''s item was written to (00284); the item''s id is external_id.';

drop function if exists public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer);

-- ----------------------------------------------------------------------------
-- As 00262, with the target each queued row goes to, and no second Webflow
-- send of a page while one is queued.
-- ----------------------------------------------------------------------------
create or replace function public.reserve_content_deliveries(
  p_organization_id uuid,
  p_brand_id uuid,
  p_sent_by uuid,
  p_batch_id uuid,
  p_items jsonb,
  p_limit integer,
  p_target text default 'webhook'
)
returns setof public.content_draft_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  used integer;
  room integer;
begin
  perform pg_advisory_xact_lock(hashtext('content_deliveries:' || p_organization_id::text));

  -- sent_at stays empty: it was never sent, and its time stays its own.
  update public.content_draft_deliveries
  set status = 'failed', error = 'Not sent: interrupted'
  where organization_id = p_organization_id
    and status = 'queued'
    and created_at < now() - interval '30 minutes';

  select count(*) into used
  from public.content_draft_deliveries
  where organization_id = p_organization_id
    and created_at > now() - interval '24 hours';

  room := greatest(0, p_limit - used);
  if room = 0 or jsonb_typeof(p_items) <> 'array' then
    return;
  end if;

  -- Under the lock, so two sends of one page can't both pass.
  if p_target = 'webflow' and exists (
    select 1
    from public.content_draft_deliveries d
    join jsonb_array_elements(p_items) as items(item)
      on d.draft_id = (item ->> 'draft_id')::uuid
    where d.organization_id = p_organization_id
      and d.target = 'webflow'
      and d.status = 'queued'
  ) then
    raise exception 'delivery_in_progress' using errcode = 'P0001';
  end if;

  return query
  insert into public.content_draft_deliveries
    (organization_id, brand_id, draft_id, sent_by, batch_id, title, slug, target)
  select p_organization_id, p_brand_id, (item ->> 'draft_id')::uuid, p_sent_by, p_batch_id,
         left(item ->> 'title', 300), nullif(left(item ->> 'slug', 200), ''),
         coalesce(p_target, 'webhook')
  from jsonb_array_elements(p_items) with ordinality as items(item, position)
  order by position
  limit room
  returning *;
end;
$$;

revoke all on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  from public, anon, authenticated;
grant execute on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00285_content_page_rewrite_reach.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00285: what a page rewrite was asked for and came to (Length's reach)
-- ============================================================================
-- In the live editor test of 2026-10-25, a page kept 78% of its Length in
-- passages AI answers quote and tables, and the editor kept recommending
-- Rewrite page: three rewrites came to 5,468, 6,843 and 7,335 characters for
-- a Length of 4,000. A rewrite that missed isn't offered again for the same
-- Length, so a page rewrite (kind 'page', 00247) now says:
--
--   * `length_target`: the Length it was written to; null with Length off
--     (the page kept its own length, which says nothing about a Length).
--   * `kept_chars`: the characters it kept word for word (quoted passages,
--     tables…): a passage unlocked since lets a rewrite go shorter.
--   * `after_chars`: the characters it came to, counted once here, so the
--     editor reads a number, not the rewritten page.
--
-- All three are written by the API (contentWriter.js) and are null on other
-- suggestions and on page rewrites made before this. Adding nullable columns
-- with no default rewrites nothing.

alter table public.content_draft_suggestions
  add column if not exists length_target integer
    check (length_target is null or length_target > 0),
  add column if not exists kept_chars integer
    check (kept_chars is null or kept_chars >= 0),
  add column if not exists after_chars integer
    check (after_chars is null or after_chars >= 0);

comment on column public.content_draft_suggestions.length_target is
  'A page rewrite''s Length target (00285); null with Length off and on other suggestions.';
comment on column public.content_draft_suggestions.kept_chars is
  'The characters a page rewrite kept word for word (00285).';
comment on column public.content_draft_suggestions.after_chars is
  'The characters a page rewrite came to (00285).';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00286_ai_traffic_conversions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00286: conversions from AI visits, as the AI Traffic snippet sees them (CE-017)
-- ============================================================================
-- The snippet counts AI-referred landings (ai_traffic_logs). With conversions
-- on, it also follows a visitor who came from an AI assistant through the
-- site to a goal (a signup, a demo form, an order…), so the Content Editor
-- can show what a page earns from AI visits, and the journeys that got there.
--
--   * Off by default, per brand (`conversions_enabled`). A brand that leaves
--     it off sends nothing new: the snippet keeps nothing in the browser, as
--     it always has.
--   * `conversions_consent`: 'wait' (default) keeps the visitor's id only once
--     the site says the visitor agreed (its consent banner, or Google Consent
--     Mode); 'always' keeps it at once, for sites whose own banner covers it.
--     The snippet reads it from its install tag; the server keeps it for the
--     Settings page.
--   * `ai_traffic_events`: a journey's pageviews and its conversions. One
--     visitor id per browser, random and first-party: never the IP address,
--     never a name or an email. Each row carries the first AI visit it is
--     credited to (first touch, within 30 days), so a journey reads without
--     joining the landing logs.
--   * `url` is the page without its query string or fragment: a thank-you
--     page's ?email=… never gets in, nor a path segment holding an email
--     (stored as "[email]").
--   * `order_ref`: a hash of the brand and an order's own id at the shop
--     (Shopify's pixel, a site's call), once per visitor, so an order sent
--     twice counts once; only ever compared, so the id itself isn't kept.
--     Per visitor, not per brand: the tracking code is public, and an order
--     id sent first by anyone else must not shut the real one out.
--   * The server stores at most a few hundred pageviews per visitor id in
--     the window and a few conversions a day, so a journey's reads stay
--     bounded (routes/traffic.js).
--   * `page_key` and `first_key`: the pages' keys, made once on insert, for
--     the journeys' reads.
--   * Members read their brands' events; only the server writes them.

alter table public.brands
  add column if not exists conversions_enabled boolean not null default false,
  add column if not exists conversions_consent text not null default 'wait'
    check (conversions_consent in ('wait', 'always'));

comment on column public.brands.conversions_enabled is
  'CE-017 (00286): the AI Traffic snippet follows AI visitors to conversions (ai_traffic_events). Off by default.';
comment on column public.brands.conversions_consent is
  'CE-017 (00286): ''wait'' keeps the snippet''s visitor id only after the site''s consent, ''always'' at once.';

create table if not exists public.ai_traffic_events (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  visitor_id text not null check (visitor_id ~ '^[A-Za-z0-9_-]{16,64}$'),
  kind text not null check (kind in ('page', 'conversion')),
  url text not null check (char_length(url) between 1 and 2048),
  goal text check (goal in ('signup', 'demo', 'order', 'booking', 'newsletter', 'custom')),
  -- The form's or the call's own name ("pricing-demo"), never what was typed in it.
  label text check (label is null or char_length(label) between 1 and 80),
  origin text check (origin in ('call', 'form', 'shopify')),
  value numeric(14, 2) check (value is null or value >= 0),
  currency text check (currency is null or currency ~ '^[A-Z]{3}$'),
  units integer check (units is null or units between 0 and 100000),
  order_ref text check (order_ref is null or char_length(order_ref) between 1 and 128),
  first_source text not null check (char_length(first_source) between 1 and 64),
  first_url text not null check (char_length(first_url) between 1 and 2048),
  first_at timestamptz not null,
  occurred_at timestamptz not null default now(),
  -- The pages' keys as journeys read them (lower(normalize_page_path), as in
  -- 00209 / 00210): made once when the row is stored, so a journey's reads
  -- (00287, 00288) compare keys rather than work each address out again.
  page_key text generated always as (lower(public.normalize_page_path(url))) stored,
  first_key text generated always as (lower(public.normalize_page_path(first_url))) stored,
  -- A conversion says what it was and where it came from; a pageview neither.
  constraint ai_traffic_events_kind check (
    (kind = 'conversion' and goal is not null and origin is not null)
    or (kind = 'page' and goal is null and origin is null and order_ref is null)
  )
);

-- A database that ran this file before the keys were added gets them, and
-- loses the brand-time index nothing reads.
alter table public.ai_traffic_events
  add column if not exists page_key text
    generated always as (lower(public.normalize_page_path(url))) stored,
  add column if not exists first_key text
    generated always as (lower(public.normalize_page_path(first_url))) stored;
drop index if exists public.ai_traffic_events_brand_time;

-- An order counts once however often its visitor's browser sends it.
create unique index if not exists ai_traffic_events_order
  on public.ai_traffic_events (brand_id, visitor_id, order_ref)
  where order_ref is not null;

create index if not exists ai_traffic_events_journey
  on public.ai_traffic_events (brand_id, visitor_id, occurred_at);

alter table public.ai_traffic_events enable row level security;
revoke all on table public.ai_traffic_events from anon, authenticated;
grant select on table public.ai_traffic_events to authenticated;
grant all on table public.ai_traffic_events to service_role;

drop policy if exists "ai_traffic_events: member select" on public.ai_traffic_events;
create policy "ai_traffic_events: member select"
  on public.ai_traffic_events
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.ai_traffic_events is
  'CE-017 (00286): journeys of visitors who came from an AI assistant, as the AI Traffic snippet sends them with conversions on: pageviews and conversions (goal, value, units; an order once by the hash of its id, order_ref), each credited to the first AI visit (first_source, first_url, first_at). A random first-party visitor id; no IP, name or email. Members read; the server writes.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00287_content_page_conversions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00287: conversions from AI journeys through a page, for the editor's Live page tab
-- ============================================================================
-- With conversions on (00286), the AI Traffic snippet follows a visitor who
-- came from an AI assistant to a goal. The Live page tab (CE-016) shows what
-- the page a draft optimizes took part in (Content Editor spec v2 §7, CE-017).
--
-- content_page_conversions(brand, page, days) returns one jsonb over the last
-- N whole UTC days, ending yesterday, as content_page_results (00210):
--   * enabled: whether the brand has conversions on;
--   * page: the page's key, for the tab to find it in the journeys;
--   * goals: per goal, the conversions and their units, of journeys through
--     the page: a conversion whose journey (its visitor id: the snippet
--     makes a new one for each journey) landed on the page, went through it
--     before, or converted on it;
--   * revenue: the value of their orders and bookings per currency (a value
--     without one isn't summed);
--   * sources: per AI source the journey started from (first touch), its
--     conversions;
--   * journeys: the five most frequent (the latest first among as many), each
--     its source, its pages in order (the landing page, the pages after
--     without repeats in a row, the page it converted on, as
--     lower(normalize_page_path) keys), its goal and how many.
-- The journey's first AI visit isn't its key: the server keeps a browser's
-- clock from dating it after the event, so first_at may differ within one.
-- Conversions are read through their own partial index: most events are
-- pageviews. Pages are compared by the keys stored with each event
-- (page_key, first_key, 00286). The reads are bounded whatever a sender
-- stored: a visitor id's pageviews are read once for the page, from a day
-- before its first AI visit; a journey's steps are the latest 100 pageviews
-- before its conversion; and the journeys are the latest 2,000
-- conversions' (the counts take all).
-- A page is one lower(normalize_page_path) key, as in 00209 / 00210.
--
-- Security definer with an organization check, as content_page_results, and
-- planned for each call's own values (plan_cache_mode).

create index if not exists ai_traffic_events_conversions
  on public.ai_traffic_events (brand_id, occurred_at desc)
  where kind = 'conversion';

create or replace function public.content_page_conversions(
  p_brand_id uuid,
  p_page text,
  p_days integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_key text := lower(public.normalize_page_path(p_page));
  -- The last whole day.
  v_last_day date := (now() at time zone 'utc')::date - 1;
  v_from timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days is null or p_days < 1 or p_days > 366 or p_page is null then
    raise exception 'content_page_conversions: a page and 1 to 366 days are needed'
      using errcode = '22023';
  end if;

  v_from := (v_last_day - p_days + 1)::timestamp at time zone 'utc';
  v_until := (v_last_day + 1)::timestamp at time zone 'utc';

  with conversions as (
    select c.*
    from public.ai_traffic_events c
    where c.brand_id = p_brand_id
      and c.kind = 'conversion'
      and c.occurred_at >= v_from
      and c.occurred_at < v_until
  ),
  -- When each visitor id first saw the page in its journey: read once per
  -- visitor id however many conversions it has, from a day before its first
  -- AI visit (first_at is clamped per event, within the server's clock
  -- allowance) to its last conversion, by the stored keys.
  seen as (
    select v.visitor_id, (
      select min(e.occurred_at)
      from public.ai_traffic_events e
      where e.brand_id = p_brand_id
        and e.visitor_id = v.visitor_id
        and e.kind = 'page'
        and e.page_key = v_key
        and e.occurred_at >= v.since
        and e.occurred_at <= v.last_at
    ) as at
    from (
      select visitor_id, min(first_at) - interval '1 day' as since, max(occurred_at) as last_at
      from conversions
      group by visitor_id
    ) v
  ),
  -- A conversion whose journey landed on the page, went through it, or converted on it.
  through as (
    select c.*
    from conversions c
    left join seen s on s.visitor_id = c.visitor_id
    where c.first_key = v_key
      or c.page_key = v_key
      or (s.at is not null and s.at <= c.occurred_at and s.at >= c.first_at - interval '1 day')
  ),
  -- The paths of the latest 2,000 (the counts above take all): the landing
  -- page, the latest 100 pageviews before the conversion, the page it
  -- converted on.
  paths as (
    select t.first_source, t.goal, t.occurred_at, (
      select array_agg(s.page order by s.ord <> 0, s.at, s.ord)
      from (
        select steps.page, steps.at, steps.ord,
          lag(steps.page) over (order by steps.ord <> 0, steps.at, steps.ord) as before
        from (
          select t.first_key as page, t.first_at as at, 0 as ord
          union all
          select p.page_key, p.occurred_at, 1
          from (
            select e.page_key, e.occurred_at
            from public.ai_traffic_events e
            where e.brand_id = p_brand_id
              and e.visitor_id = t.visitor_id
              and e.kind = 'page'
              and e.occurred_at >= t.first_at - interval '1 day'
              and e.occurred_at <= t.occurred_at
            order by e.occurred_at desc
            limit 100
          ) p
          union all
          select t.page_key, t.occurred_at, 2
        ) steps
      ) s
      where s.before is distinct from s.page
    ) as pages
    from (select * from through order by occurred_at desc limit 2000) t
  )
  select jsonb_build_object(
    'page', v_key,
    'enabled', coalesce((select b.conversions_enabled from public.brands b where b.id = p_brand_id), false),
    'goals', coalesce((
      select jsonb_agg(jsonb_build_object('goal', g.goal, 'count', g.n, 'units', g.units)
        order by g.n desc, g.goal)
      from (
        select goal, count(*)::bigint as n, coalesce(sum(units), 0)::bigint as units
        from through group by goal
      ) g
    ), '[]'::jsonb),
    'revenue', coalesce((
      select jsonb_agg(jsonb_build_object('currency', r.currency, 'value', r.value)
        order by r.value desc, r.currency)
      from (
        select currency, sum(value)::numeric as value
        from through
        where goal in ('order', 'booking') and value is not null and currency is not null
        group by currency
      ) r
    ), '[]'::jsonb),
    'sources', coalesce((
      select jsonb_agg(jsonb_build_object('platform', s.first_source, 'conversions', s.n)
        order by s.n desc, s.first_source)
      from (select first_source, count(*)::bigint as n from through group by first_source) s
    ), '[]'::jsonb),
    'journeys', coalesce((
      select jsonb_agg(jsonb_build_object('source', j.first_source, 'pages', to_jsonb(j.pages),
          'goal', j.goal, 'count', j.n)
        order by j.n desc, j.latest desc, j.first_source, j.goal)
      from (
        select first_source, pages, goal, count(*)::bigint as n, max(occurred_at) as latest
        from paths
        group by first_source, pages, goal
        order by count(*) desc, max(occurred_at) desc, first_source, goal
        limit 5
      ) j
    ), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.content_page_conversions(uuid, text, integer) from public, anon;
grant execute on function public.content_page_conversions(uuid, text, integer)
  to authenticated, service_role;

comment on function public.content_page_conversions(uuid, text, integer) is
  'Content Editor (CE-017, 00287): conversions of AI journeys through one page over the last N whole UTC days (ending yesterday), from the AI Traffic snippet (ai_traffic_events, 00286): per goal with units, value per currency, per first AI source, and the five most frequent journeys (source, pages, goal). Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00288_brand_ai_conversions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00288: the brand's conversions from AI journeys, for the Content plan's strip
-- ============================================================================
-- The Content plan's AI results strip (spec v2 §4 point 8, CE-014) says what
-- AI visits brought in: "48 signups · 20 demo forms · 10 orders", and the top
-- journey. With conversions on (00286), the AI Traffic snippet's journeys
-- give it the goals (CE-017), beside Google Analytics' key events.
--
-- brand_ai_conversions(brand, days) returns one jsonb over the last 7, 30 or
-- 90 whole UTC days, ending yesterday, as content_plan_insights (00226):
--   * enabled: whether the brand has conversions on;
--   * goals: per goal, its conversions, the most first;
--   * journey: the most frequent journey to a conversion among the period's
--     latest 2,000 (the latest first among as many), its source, pages and
--     goal, as content_page_conversions (00287) builds them (the latest 100
--     pageviews before the conversion), and how many; null without one. The
--     bounds keep a big brand's 90 days, or a visitor id with a long
--     history, from holding the Plan page up: the goals still count every
--     conversion.
--
-- Security definer with an organization check, as content_plan_insights.

create or replace function public.brand_ai_conversions(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_from timestamptz;
  v_until timestamptz;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_from := (v_last - p_days + 1)::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';

  with conversions as (
    select c.*
    from public.ai_traffic_events c
    where c.brand_id = p_brand_id
      and c.kind = 'conversion'
      and c.occurred_at >= v_from
      and c.occurred_at < v_until
  ),
  -- The latest 2,000's paths (the goals take all): the landing page, the
  -- latest 100 pageviews before the conversion, from a day before its first
  -- AI visit (first_at is clamped per event, within the server's clock
  -- allowance), the page it converted on; by the keys stored with each
  -- event (00286).
  paths as (
    select t.first_source, t.goal, t.occurred_at, (
      select array_agg(s.page order by s.ord <> 0, s.at, s.ord)
      from (
        select steps.page, steps.at, steps.ord,
          lag(steps.page) over (order by steps.ord <> 0, steps.at, steps.ord) as before
        from (
          select t.first_key as page, t.first_at as at, 0 as ord
          union all
          select p.page_key, p.occurred_at, 1
          from (
            select e.page_key, e.occurred_at
            from public.ai_traffic_events e
            where e.brand_id = p_brand_id
              and e.visitor_id = t.visitor_id
              and e.kind = 'page'
              and e.occurred_at >= t.first_at - interval '1 day'
              and e.occurred_at <= t.occurred_at
            order by e.occurred_at desc
            limit 100
          ) p
          union all
          select t.page_key, t.occurred_at, 2
        ) steps
      ) s
      where s.before is distinct from s.page
    ) as pages
    from (select * from conversions order by occurred_at desc limit 2000) t
  )
  select jsonb_build_object(
    'enabled', coalesce((select b.conversions_enabled from public.brands b where b.id = p_brand_id), false),
    'goals', coalesce((
      select jsonb_agg(jsonb_build_object('goal', g.goal, 'count', g.n) order by g.n desc, g.goal)
      from (select goal, count(*)::bigint as n from conversions group by goal) g
    ), '[]'::jsonb),
    'journey', (
      select jsonb_build_object('source', j.first_source, 'pages', to_jsonb(j.pages),
        'goal', j.goal, 'count', j.n)
      from (
        select first_source, pages, goal, count(*)::bigint as n
        from paths
        group by first_source, pages, goal
        order by count(*) desc, max(occurred_at) desc, first_source, goal
        limit 1
      ) j
    )
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.brand_ai_conversions(uuid, integer) from public, anon;
grant execute on function public.brand_ai_conversions(uuid, integer)
  to authenticated, service_role;

comment on function public.brand_ai_conversions(uuid, integer) is
  'Content plan (CE-017, 00288): the brand''s conversions from AI journeys over the last 7, 30 or 90 whole UTC days (ending yesterday), from the AI Traffic snippet (ai_traffic_events, 00286): per goal, and the most frequent journey (source, pages, goal, count). Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00289_content_draft_restored_at.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00289: when a draft's page was last restored from History
-- ============================================================================
-- The editor opens the agent's card closed when its latest batch is from
-- before the page was last restored: that batch was for the page before
-- (#1522's follow-up, #1536). The "restore" version can't say when: it is
-- kept only when the page differs from the draft's latest version (00215,
-- content_draft_keep_version), so a restore right after Mark ready, or after
-- an Undo all, leaves none.
--
-- content_drafts.restored_at is set by content_draft_restore (00215) each
-- time it changes the page; a restore of the page the draft already is
-- leaves it as it was, and says so ('restored': false), so the editor sets
-- nothing aside for it. Null for a draft never restored, and for one
-- restored before this: no backfill, as an update to content_drafts moves
-- its updated_at (the Library's order, an open editor's save base), and
-- #1522 hasn't shipped. It is the server's to write:
-- guard_content_draft_server_columns (00262) refuses a member's.

alter table public.content_drafts
  add column if not exists restored_at timestamptz;

comment on column public.content_drafts.restored_at is
  'When content_draft_restore last changed the page to a History version (00289): the agent''s batch from before it was for the page before. Null when never restored.';

-- As 00215's, with restored_at set when the page changes, and whether it did.
create or replace function public.content_draft_restore(p_version_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path to 'public'
as $$
declare
  v_version public.content_draft_versions%rowtype;
  v_draft public.content_drafts%rowtype;
  v_changed boolean;
begin
  select * into v_version
  from public.content_draft_versions v
  where v.id = p_version_id and v.created_at >= now() - interval '90 days';
  if v_version.id is null or not public.content_draft_member(v_version.draft_id) then
    return null;
  end if;

  select * into v_draft from public.content_drafts d where d.id = v_version.draft_id;
  -- Already this page: nothing to keep or change.
  v_changed := v_draft.title is distinct from v_version.title
    or v_draft.body_html is distinct from v_version.body_html;
  if v_changed then
    perform public.content_draft_keep_version(v_version.draft_id, 'restore');

    update public.content_drafts d
    set title = v_version.title, body_html = v_version.body_html, restored_at = now()
    where d.id = v_version.draft_id
    returning * into v_draft;
  end if;

  return jsonb_build_object(
    'title', v_draft.title,
    'bodyHtml', v_draft.body_html,
    'updatedAt', v_draft.updated_at,
    'restored', v_changed
  );
end;
$$;

revoke all on function public.content_draft_restore(uuid) from public, anon;
grant execute on function public.content_draft_restore(uuid) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- When the page was restored is the server's: as 00262's, with restored_at.
-- ----------------------------------------------------------------------------
create or replace function public.guard_content_draft_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- A role that bypasses RLS is server-side (service role, migrations).
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.score_before is not null or new.score_after is not null then
      raise exception 'content draft scores are set server-side'
        using errcode = '42501';
    end if;
    if new.action_id is not null then
      raise exception 'content draft action is set server-side'
        using errcode = '42501';
    end if;
    if new.agent_state is not null or new.agent_state_at is not null
       or new.agent_run is not null then
      raise exception 'content draft agent state is set server-side'
        using errcode = '42501';
    end if;
    if new.published_url is not null or new.published_at is not null then
      raise exception 'content draft live address is set server-side'
        using errcode = '42501';
    end if;
    if new.restored_at is not null then
      raise exception 'content draft restore time is set server-side'
        using errcode = '42501';
    end if;
  elsif new.brand_id is distinct from old.brand_id
     or new.author is distinct from old.author
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at
     or new.score_before is distinct from old.score_before
     or new.score_after is distinct from old.score_after
     or new.action_id is distinct from old.action_id
     or new.agent_state is distinct from old.agent_state
     or new.agent_state_at is distinct from old.agent_state_at
     or new.agent_run is distinct from old.agent_run
     or new.published_url is distinct from old.published_url
     or new.published_at is distinct from old.published_at
     or new.restored_at is distinct from old.restored_at
  then
    raise exception 'content draft column is managed server-side'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00290_mentions_perception_live_narrower.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00290: the Perception tab's filtered views, read faster (Mentions & Sentiment, MS-09)
-- ============================================================================
-- 00241 computes the default view ahead; a filtered one (a platform, a
-- country, a topic or a search) still reads mentions_perception_live. On
-- production (2026-10-26, the GetCito brand, read-only):
--   * ChatGPT only took 6.3 s at 30 days, and failed at 90 days (8.7 s twice,
--     past the 8 s statement timeout: "Couldn't load");
--   * a search failed at 30 days the same way;
--   * the morning report's 'mentions_perception_live' probe took 10.9 s at
--     30 days and 8.9 s at 90.
-- The default view opened in 1.1–1.2 s from its snapshot. The target is 3 s
-- for every view.
--
-- The same output for every window and filter, with less read:
--   1. The window before is read only for what the tab shows of it: each
--      entity's mentions and co-mentions (mentions_entities_daily, small)
--      and the previous answers of the brand's 15 terms shown. 00237 summed
--      every shown entity's every term over both windows for those 15
--      numbers.
--      * The rollups (whole days, no topic or search) now read the shown
--        entities' terms for the window and only the brand's for the window
--        before: about 6 entity-windows of rows instead of 10.
--      * A topic or a search (and a window under two days) still reads both
--        windows' answers, which the mentions and co-mentions need, but
--        unnests only the brand's from the window before.
--      A platform or a country is checked inside the key (after the day), so
--      a filtered view reads as many index entries as the default one.
--   2. mentions_terms_daily's key carries the count (include answers), so
--      the terms' sums come from the index alone. It replaces 00231's
--      mentions_terms_daily_key: the same key, still unique, nulls not
--      distinct.
--   3. Autovacuum runs on both rollups about daily, as 00236 does for the
--      Insights rollups: each refresh deletes and rewrites a range of days,
--      and an index-only scan still goes to the table for a page that isn't
--      all-visible yet. mentions_entities_daily has no covering index; it
--      gets the dead rows cleared and its statistics kept current.
--
-- On a large mentions_terms_daily, build the index by hand first, which
-- doesn't hold back the refreshes, with no statement timeout; this migration
-- then finds it in place:
--   set statement_timeout = 0;
--   create unique index concurrently if not exists mentions_terms_daily_key_cover
--     on public.mentions_terms_daily (brand_id, entity, day, platform, region, term)
--     include (answers) nulls not distinct;
--   -- indisvalid must be true before the old key goes:
--   select indisvalid from pg_index
--     where indexrelid = 'public.mentions_terms_daily_key_cover'::regclass;
--   drop index concurrently if exists public.mentions_terms_daily_key;
-- A build that stopped part way leaves an invalid index under that name;
-- drop it and build again. This migration refuses to drop the old key while
-- the new one is invalid.

create unique index if not exists mentions_terms_daily_key_cover
  on public.mentions_terms_daily (brand_id, entity, day, platform, region, term)
  include (answers)
  nulls not distinct;

do $$
begin
  if exists (
    select 1 from pg_index
    where indexrelid = 'public.mentions_terms_daily_key_cover'::regclass
      and not indisvalid
  ) then
    raise exception 'mentions_terms_daily_key_cover is invalid (a concurrent build stopped part way): drop it and build it again';
  end if;
end;
$$;

-- The Perception reads and the refreshes don't queue behind the drop for
-- long: it gives up after 3 s instead (run it again).
set lock_timeout = '3s';

drop index if exists public.mentions_terms_daily_key;

reset lock_timeout;

alter table public.mentions_terms_daily set (
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

alter table public.mentions_entities_daily set (
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_vacuum_insert_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.02
);

-- 00241's read, the window before narrowed to the brand's terms shown.
create or replace function public.mentions_perception_live(
  p_brand_id  uuid,
  p_date_from timestamptz,
  p_date_to   timestamptz default null,
  p_platform  text default null,
  p_region    text default null,
  p_topic_id  uuid default null,
  p_search    text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
set work_mem to '64MB'
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_to         timestamptz := coalesce(p_date_to, now());
  v_from       timestamptz := least(p_date_from, coalesce(p_date_to, now()));
  v_days       integer;
  v_day_to     date;
  v_start      timestamptz;
  v_end        timestamptz;
  v_prev_start timestamptz;
  v_search     text := nullif(btrim(lower(coalesce(p_search, ''))), '');
  v_rollup     boolean;
  v_start_day  date;
  v_end_day    date;
  v_prev_day   date;
  v_result     jsonb;
begin
  v_days := greatest(1, ceil(extract(epoch from v_to - v_from) / 86400.0 - 1.0 / 24)::integer);
  if v_days < 2 then
    v_start := v_from;
    v_end   := v_to + interval '1 microsecond';
  else
    v_day_to := (v_to at time zone 'utc')::date;
    v_start  := (v_day_to - (v_days - 1))::timestamp at time zone 'utc';
    v_end    := (v_day_to + 1)::timestamp at time zone 'utc';
  end if;
  v_prev_start := v_start - (v_end - v_start);
  -- Whole UTC days with no topic or search read the daily rollups (00231);
  -- a window under two days, or a filter on the prompts, reads the answers'
  -- terms as before. The branch not taken is pruned (plan_cache_mode).
  v_rollup    := v_days >= 2 and p_topic_id is null and v_search is null;
  v_start_day := (v_start at time zone 'utc')::date;
  v_end_day   := (v_end at time zone 'utc')::date;
  v_prev_day  := (v_prev_start at time zone 'utc')::date;

  with
  prompts_in as (
    select p.id
    from public.prompts p
    join public.prompt_sets ps on ps.id = p.prompt_set_id
    where ps.brand_id = p_brand_id
      and (p_topic_id is null or p.topic_id = p_topic_id)
      and (v_search is null or position(v_search in lower(p.text)) > 0)
  ),
  rows_in as (
    select t.result_id, t.entity, t.terms, (t.created_at >= v_start) as cur
    from public.mentions_answer_terms t
    join prompts_in pi on pi.id = t.prompt_id
    where not v_rollup
      and t.brand_id = p_brand_id
      and t.created_at >= v_prev_start
      and t.created_at < v_end
      and (p_platform is null or t.platform = p_platform)
      and (p_region is null or t.region = p_region)
  ),
  entity_counts as (
    select entity,
           count(*) filter (where cur)     as mentions,
           count(*) filter (where not cur) as prev_mentions
    from rows_in
    group by entity
    union all
    select d.entity,
           coalesce(sum(d.answers) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.answers) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
  ),
  shown as (
    select 'brand'::text as entity, 0 as rank
    union all
    select * from (
      select ec.entity, row_number() over (order by ec.mentions desc, ec.entity)::int
      from entity_counts ec
      join public.competitors co on co.id::text = ec.entity and co.brand_id = p_brand_id
      where ec.mentions > 0
      order by ec.mentions desc, ec.entity
      limit 4
    ) top_competitors
  ),
  -- The shown entities' terms in the window. The window before is read
  -- only for the brand's terms shown (brand_prev).
  term_counts_all as (
    select r.entity, term, count(*) as answers
    from rows_in r
    join shown s on s.entity = r.entity
    cross join lateral unnest(r.terms) as term
    where r.cur
    group by r.entity, term
    union all
    select d.entity, d.term, sum(d.answers)
    from public.mentions_terms_daily d
    join shown s on s.entity = d.entity
    where v_rollup
      and d.brand_id = p_brand_id
      and d.day >= v_start_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity, d.term
  ),
  -- Each entity's 60 most frequent terms are the candidates.
  candidates as (
    select entity, term, answers
    from (
      select t.*, row_number() over (partition by t.entity order by t.answers desc, t.term) as rn
      from term_counts_all t
      where t.answers > 0
    ) ranked
    where rn <= 60
  ),
  -- A word that nearly always comes in one phrase is that phrase: "fresh" and
  -- "roast" give way to "fresh roast" when it has 80% of their answers.
  term_counts as (
    select c.*
    from candidates c
    where position(' ' in c.term) > 0
       or not exists (
         select 1 from candidates p
         where p.entity = c.entity
           and position(' ' in p.term) > 0
           and (p.term like c.term || ' %' or p.term like '% ' || c.term)
           and p.answers >= 0.8 * c.answers)
  ),
  brand_terms as (
    select term, answers
    from term_counts
    where entity = 'brand' and answers > 0
    order by answers desc, term
    limit 15
  ),
  -- Those terms' answers in the window before, for their trend.
  brand_prev as (
    select term, count(*) as prev_answers
    from rows_in r
    cross join lateral unnest(r.terms) as term
    where not r.cur
      and r.entity = 'brand'
      and term in (select bt.term from brand_terms bt)
    group by term
    union all
    select d.term, sum(d.answers)
    from public.mentions_terms_daily d
    where v_rollup
      and d.brand_id = p_brand_id
      and d.entity = 'brand'
      and d.day >= v_prev_day
      and d.day < v_start_day
      and d.term in (select bt.term from brand_terms bt)
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.term
  ),
  -- The terms that tell the brands apart most: the widest spread between the
  -- highest and lowest share of mentions, then the highest shares.
  attributes as (
    select u.term
    from (select distinct term from term_counts) u
    cross join shown s
    left join term_counts_all tc on tc.entity = s.entity and tc.term = u.term
    left join entity_counts ec on ec.entity = s.entity
    group by u.term
    order by
      max(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0))
        - min(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      sum(coalesce(tc.answers, 0)::numeric / nullif(ec.mentions, 0)) desc nulls last,
      u.term
    limit 8
  ),
  -- A competitor's rows in answers that name the brand too, in one pass.
  co as (
    select x.entity,
           count(*) filter (where x.cur)     as co_mentions,
           count(*) filter (where not x.cur) as prev_co_mentions
    from (
      select r.entity, r.cur,
             bool_or(r.entity = 'brand') over (partition by r.result_id) as with_brand
      from rows_in r
    ) x
    where x.entity <> 'brand' and x.with_brand
    group by x.entity
    union all
    select d.entity,
           coalesce(sum(d.with_brand) filter (where d.day >= v_start_day), 0),
           coalesce(sum(d.with_brand) filter (where d.day < v_start_day), 0)
    from public.mentions_entities_daily d
    where v_rollup
      and d.entity <> 'brand'
      and d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day < v_end_day
      and (p_platform is null or d.platform = p_platform)
      and (p_region is null or d.region = p_region)
    group by d.entity
    having sum(d.with_brand) > 0
  )
  select jsonb_build_object(
    'window', jsonb_build_object('from', v_start, 'to', v_end, 'days', v_days),
    'entities', coalesce((
      select jsonb_agg(jsonb_build_object(
               'entity', s.entity,
               'name', case when s.entity = 'brand' then b.name else co.name end,
               'is_brand', s.entity = 'brand',
               'mentions', coalesce(ec.mentions, 0),
               'prev_mentions', coalesce(ec.prev_mentions, 0))
             order by s.rank)
      from shown s
      left join entity_counts ec on ec.entity = s.entity
      left join public.brands b on s.entity = 'brand' and b.id = p_brand_id
      left join public.competitors co on co.id::text = s.entity and co.brand_id = p_brand_id
    ), '[]'::jsonb),
    'brand_terms', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', bt.term, 'answers', bt.answers,
               'prev_answers', coalesce(bp.prev_answers, 0))
             order by bt.answers desc, bt.term)
      from brand_terms bt
      left join brand_prev bp on bp.term = bt.term
    ), '[]'::jsonb),
    'attributes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'term', a.term,
               'values', (
                 select jsonb_agg(jsonb_build_object(
                          'entity', s.entity, 'answers', coalesce(tc.answers, 0))
                        order by s.rank)
                 from shown s
                 left join term_counts_all tc on tc.entity = s.entity and tc.term = a.term)))
      from attributes a
    ), '[]'::jsonb),
    'co_mentions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'competitor_id', c.entity,
               'name', comp.name,
               'co_mentions', c.co_mentions,
               'prev_co_mentions', c.prev_co_mentions)
             order by c.co_mentions desc, comp.name)
      from co c
      join public.competitors comp on comp.id::text = c.entity and comp.brand_id = p_brand_id
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

revoke all on function public.mentions_perception_live(uuid, timestamptz, timestamptz, text, text, uuid, text)
  from public, anon, authenticated;
grant execute on function public.mentions_perception_live(uuid, timestamptz, timestamptz, text, text, uuid, text)
  to service_role;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00291_content_plan_pages_conversions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00291: content_plan_pages with each page's conversions from AI journeys
-- ============================================================================
-- The Content Plan's Priority Score weighs a page's value by its AI visits
-- (#1356). With conversions on (CE-017, 00286), it weighs the conversions
-- the page took part in too, as the editor's Live page tab counts them
-- (00287): a conversion whose AI journey landed on the page, went through
-- it, or converted on it, in the window, of the latest 2,000.
--
-- Each page of the list gets 'conversions': that count, or null for a brand
-- with conversions off (unknown, never zero). Everything else is 00238's,
-- with the same signature, so its grants carry over (create or replace); its
-- comment is brought up to date below. The conversions are read only with
-- conversions on: through 00287's partial index, then, as 00287 reads them,
-- when each visitor id first saw each listed page, once per visitor and page
-- on the journey index (00286), so a sender's many pageviews can't multiply
-- the rows.

create or replace function public.content_plan_pages(
  p_brand_id uuid,
  p_days integer default 30
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public'
-- A cached generic plan can't see the brand's size (00207).
set plan_cache_mode to 'force_custom_plan'
as $$
declare
  v_last date := (now() at time zone 'utc')::date - 1;
  v_cur_day date;
  v_prev_day date;
  v_cur timestamptz;
  v_until timestamptz;
  v_conversions_on boolean;
  v_result jsonb;
begin
  if not exists (
    select 1 from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id and pf.id = auth.uid()
  ) and auth.role() is distinct from 'service_role' then
    return null;
  end if;
  if p_days not in (7, 30, 90) then
    raise exception 'p_days must be 7, 30 or 90';
  end if;

  v_cur_day := v_last - p_days + 1;
  v_prev_day := v_cur_day - p_days;
  v_cur := v_cur_day::timestamp at time zone 'utc';
  v_until := (v_last + 1)::timestamp at time zone 'utc';
  v_conversions_on := coalesce(
    (select b.conversions_enabled from public.brands b where b.id = p_brand_id), false);

  with own_domains as (
    select lower(regexp_replace(bd.domain, '^www\.', '')) as domain
    from public.brand_domains bd
    where bd.brand_id = p_brand_id
  ),
  own_urls as materialized (
    select cu.id, cu.url, cu.title, lower(public.normalize_page_path(cu.url)) as page_key
    from public.citation_urls cu
    where cu.domain in (select domain from own_domains)
  ),
  url_counts as materialized (
    select d.url_id, d.platform, d.day >= v_cur_day as is_cur, sum(d.citations)::bigint as n
    from public.citation_url_daily d
    where d.brand_id = p_brand_id
      and d.day >= v_prev_day
      and d.day <= v_last
      and d.url_id in (select id from own_urls)
      and d.platform is distinct from 'chatgpt-shopping'
    group by d.url_id, d.platform, d.day >= v_cur_day
  ),
  url_totals as (
    select
      u.page_key,
      u.url,
      u.title,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    group by u.page_key, u.url, u.title
  ),
  pages as materialized (
    select
      t.page_key,
      -- The address cited most often stands for the page.
      (array_agg(t.url order by t.cur + t.prev desc, t.url))[1] as page,
      max(t.title) as title,
      sum(t.cur)::bigint as cur,
      sum(t.prev)::bigint as prev
    from url_totals t
    group by t.page_key
    order by sum(t.cur + t.prev) desc, t.page_key
    limit 100
  ),
  answers as (
    select
      r.platform,
      coalesce(sum(r.answers) filter (where r.day >= v_cur_day), 0)::bigint as cur,
      coalesce(sum(r.answers) filter (where r.day < v_cur_day), 0)::bigint as prev
    from public.citation_result_daily r
    where r.brand_id = p_brand_id
      and r.day >= v_prev_day
      and r.day <= v_last
      and r.platform is distinct from 'chatgpt-shopping'
    group by r.platform
  ),
  per_platform as (
    select
      u.page_key,
      c.platform,
      coalesce(sum(c.n) filter (where c.is_cur), 0) as cur,
      coalesce(sum(c.n) filter (where not c.is_cur), 0) as prev
    from url_counts c
    join own_urls u on u.id = c.url_id
    where u.page_key in (select p.page_key from pages p)
      and c.platform is not null
    group by u.page_key, c.platform
  ),
  down as (
    -- A platform tracked in both windows, citing the page at a lower rate.
    select
      pp.page_key,
      array_agg(
        pp.platform
        order by pp.prev::numeric / a.prev - pp.cur::numeric / a.cur desc, pp.platform
      ) as platforms
    from per_platform pp
    join answers a on a.platform = pp.platform
    where a.prev > 0
      and a.cur > 0
      and pp.prev::numeric / a.prev > pp.cur::numeric / a.cur
    group by pp.page_key
  ),
  snippet_days as (
    select distinct (l.created_at at time zone 'utc')::date as day
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page_key, 1::bigint as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.visit_of is null
      and l.created_at >= v_cur
      and l.created_at < v_until
    union all
    select lower(public.normalize_page_path(g.landing_page)), g.sessions::bigint
    from public.ga_ai_traffic_stats g
    where g.brand_id = p_brand_id
      and g.sessions > 0
      -- A session without a landing page would read as the home page.
      and g.landing_page <> ''
      and g.date >= v_cur_day
      and g.date <= v_last
      and not exists (select 1 from snippet_days s where s.day = g.date)
  ),
  page_visits as (
    select v.page_key, sum(v.n) as visits
    from visits v
    where v.page_key in (select p.page_key from pages p)
    group by v.page_key
  ),
  -- Conversions from AI journeys in the window, with conversions on (00286):
  -- the latest 2,000, as 00287 and 00288 bound their journeys, through 00287's
  -- partial index (brand_id, occurred_at desc), so the read stops there. The
  -- score counts 20 in full; past 2,000, a page's count is of the latest.
  conversions as materialized (
    select c.id, c.visitor_id, c.first_key, c.page_key, c.first_at, c.occurred_at
    from public.ai_traffic_events c
    where v_conversions_on
      and c.brand_id = p_brand_id
      and c.kind = 'conversion'
      and c.occurred_at >= v_cur
      and c.occurred_at < v_until
    order by c.occurred_at desc
    limit 2000
  ),
  -- When each visitor id first saw each listed page, from a day before its
  -- first AI visit to its last conversion: 00287's `seen`, for every listed
  -- page at once (the journey index), one row per visitor and page.
  seen as (
    select e.visitor_id, e.page_key, min(e.occurred_at) as at
    from (
      select visitor_id, min(first_at) - interval '1 day' as since, max(occurred_at) as last_at
      from conversions
      group by visitor_id
    ) v
    join public.ai_traffic_events e
      on e.brand_id = p_brand_id
     and e.visitor_id = v.visitor_id
     and e.kind = 'page'
     and e.occurred_at >= v.since
     and e.occurred_at <= v.last_at
    where e.page_key in (select p.page_key from pages p)
    group by e.visitor_id, e.page_key
  ),
  -- A conversion counts for each page its journey landed on, went through
  -- or converted on: the Live page tab's count (00287), once per page.
  touched as (
    select c.id, c.first_key as page_key from conversions c
    union
    select c.id, c.page_key from conversions c
    union
    select c.id, s.page_key
    from conversions c
    join seen s
      on s.visitor_id = c.visitor_id
     and s.at <= c.occurred_at
     and s.at >= c.first_at - interval '1 day'
  ),
  page_conversions as (
    select t.page_key, count(*)::bigint as n
    from touched t
    where t.page_key in (select p.page_key from pages p)
    group by t.page_key
  )
  select jsonb_build_object(
    'days', p_days,
    -- The earlier window's first day, and the brand's first tracked day: a
    -- window before it is only partly tracked, or not at all.
    'prevFrom', v_prev_day,
    'trackedSince', (
      select min(r.day) from public.citation_result_daily r where r.brand_id = p_brand_id
    ),
    'answers', (
      select jsonb_build_object(
        'cur', coalesce(sum(a.cur), 0),
        'prev', coalesce(sum(a.prev), 0)
      )
      from answers a
    ),
    'pages', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'page', p.page,
          'title', p.title,
          'citations', jsonb_build_object('cur', p.cur, 'prev', p.prev),
          'platformsDown', coalesce(to_jsonb(d.platforms[1:3]), '[]'::jsonb),
          'aiVisits', coalesce(pv.visits, 0),
          -- Null with conversions off: unknown, never zero.
          'conversions', case when v_conversions_on then coalesce(pc.n, 0) end
        )
        order by p.cur + p.prev desc, p.page
      )
      from pages p
      left join down d on d.page_key = p.page_key
      left join page_visits pv on pv.page_key = p.page_key
      left join page_conversions pc on pc.page_key = p.page_key
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$$;

comment on function public.content_plan_pages(uuid, integer) is
  'Content Editor (CE-014): the brand''s 100 most cited pages over the last N (7, 30 or 90) whole UTC days to yesterday and the N before, from the daily rollups: citations, the brand''s answers in each window, platforms citing at a lower rate, AI visits and, with conversions on (00291), the conversions from AI journeys that landed on, went through or converted on each page, of the latest 2,000 (null with conversions off); with the earlier window''s first day and the brand''s first tracked day. Security definer with an organization check.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00293_action_task_reviews.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00293: tasks waiting for review (AC-010)
-- ============================================================================
-- Every task an agent writes says the exact page, the change, when it is
-- done and how that is checked (AC-010; the fields live in
-- action_tasks.details). A task the AI task writer gives without one of
-- them doesn't reach the people doing the work: it waits here, for an
-- admin or a manager of the brand's organization to fill what it misses.
--
--   * action_task_reviews: one row per task waiting, with the task as it was
--     written (title and details) and the fields it misses ('url', 'change',
--     'doneWhen', 'check'). Not a task yet, so nothing that reads
--     action_tasks (the lists, counts, exports, the runner) sees it.
--   * approve_action_task_review: the reviewed task, its four fields filled,
--     goes onto the action's task list, after its last task, and the review
--     row goes, in one transaction. The trail says a task was added. It is
--     the reviewer's task now (source 'reviewed'): Regenerate tasks keeps
--     it, as it keeps a task someone added. Not on an action that is
--     deleted or closed.
--   * Admins and managers read and dismiss (delete) the rows; the server
--     writes them (service role). Edits go into the task on approval.

create table if not exists public.action_task_reviews (
  id uuid primary key default gen_random_uuid(),
  action_id uuid not null references public.actions(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 200),
  details jsonb not null default '{}'::jsonb,
  missing text[] not null default '{}'
    check (missing <@ array['url', 'change', 'doneWhen', 'check']::text[]),
  source text not null default 'ai' check (source in ('ai', 'agent')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists action_task_reviews_action_idx
  on public.action_task_reviews (action_id);

-- Read and dismissed by admins and managers (the policies below); written by the server.
alter table public.action_task_reviews enable row level security;
revoke all on table public.action_task_reviews from anon, authenticated;
grant select, delete on table public.action_task_reviews to authenticated;
grant all on table public.action_task_reviews to service_role;

drop policy if exists "action_task_reviews: manager select" on public.action_task_reviews;
create policy "action_task_reviews: manager select"
  on public.action_task_reviews
  for select
  using (
    action_id in (
      select a.id from public.actions a
      join public.brands b on b.id = a.brand_id
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  );

drop policy if exists "action_task_reviews: manager delete" on public.action_task_reviews;
create policy "action_task_reviews: manager delete"
  on public.action_task_reviews
  for delete
  using (
    action_id in (
      select a.id from public.actions a
      join public.brands b on b.id = a.brand_id
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid() and p.role in ('admin', 'manager')
    )
  );

comment on table public.action_task_reviews is
  'Action Center (AC-010): tasks an agent wrote without the exact page, the change, Done when or how it is checked (missing), waiting for an admin or a manager. Not tasks yet: approve_action_task_review puts one on its action''s list. The server writes them.';

-- The reviewed task onto its action's list, its four fields filled, and the
-- review row gone. Null when the row isn't there (approved or dismissed
-- meanwhile, or another organization's); an error when the caller isn't an
-- admin or a manager, the action is deleted or closed, or a field is still
-- missing.
create or replace function public.approve_action_task_review(
  p_review_id uuid,
  p_title text,
  p_details jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_review public.action_task_reviews%rowtype;
  v_title text := btrim(coalesce(p_title, ''));
  v_task_id uuid;
begin
  -- The caller's role first, before any row is read or locked.
  if not exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role in ('admin', 'manager')
  ) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  -- Only a row of the caller's own organization: another's reads as not there.
  select r.* into v_review
  from public.action_task_reviews r
  join public.actions a on a.id = r.action_id
  join public.brands b on b.id = a.brand_id
  join public.profiles p on p.organization_id = b.organization_id
  where r.id = p_review_id
    and p.id = auth.uid()
  for update of r;
  if not found then
    return null;
  end if;

  if exists (
    select 1 from public.actions a
    where a.id = v_review.action_id
      and (a.deleted_at is not null or a.status in ('completed', 'dismissed'))
  ) then
    raise exception 'action closed' using errcode = '55000';
  end if;

  if char_length(v_title) not between 1 and 200
    or jsonb_typeof(p_details) is distinct from 'object'
    or nullif(btrim(coalesce(p_details->>'url', '')), '') is null
    or nullif(btrim(coalesce(p_details->'change'->>'after', '')), '') is null
    or nullif(btrim(coalesce(p_details->>'doneWhen', '')), '') is null
    or coalesce(p_details->>'check', '') not in ('auto', 'rerun', 'manual')
  then
    raise exception 'incomplete task' using errcode = '22023';
  end if;

  insert into public.action_tasks (action_id, position, title, status, mode, permission, details)
  select
    v_review.action_id,
    coalesce(max(t.position), 0) + 1,
    v_title,
    'todo',
    'human',
    'read',
    -- The reviewer's task now: Regenerate keeps it (task-writer keepsTask).
    p_details || jsonb_build_object('source', 'reviewed')
  from public.action_tasks t
  where t.action_id = v_review.action_id
  returning id into v_task_id;

  delete from public.action_task_reviews where id = v_review.id;

  insert into public.action_events (action_id, event, data, actor_id)
  values (v_review.action_id, 'task_added', jsonb_build_object('title', v_title), auth.uid());

  update public.actions set updated_at = now() where id = v_review.action_id;

  return v_task_id;
end;
$$;

revoke all on function public.approve_action_task_review(uuid, text, jsonb) from public, anon;
grant execute on function public.approve_action_task_review(uuid, text, jsonb) to authenticated;

comment on function public.approve_action_task_review(uuid, text, jsonb) is
  'Action Center (AC-010): a task waiting for review (action_task_reviews) onto its action''s task list, after its last task, with the exact page, the change, Done when and how it is checked filled, as the reviewer''s (source reviewed); the review row goes and the trail says a task was added. Admins and managers of the brand''s organization only, on an action neither deleted nor closed. Null when the row is gone or another organization''s.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00294_cms_wordpress.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00294: WordPress for Send to CMS (#1331, phase 2)
-- ============================================================================
-- After Webflow (00283, 00284), a brand connects its WordPress site: the
-- site's address, a user and an Application Password (WordPress 5.6+, made
-- under Users › Profile). Pages go to it through the REST API as draft posts.
--
--   * brand_cms_connections takes provider 'wordpress'. Composio's ids are
--     Webflow's only (Composio keeps its token); a WordPress connection has
--     the site's address (`site_url`), its name (`site_name`) and the user
--     it signs in as (`account`).
--   * brand_cms_credentials: the connection's sign-in (the user and the
--     Application Password), encrypted by the API as a store's is
--     (catalog_source_credentials, 00282): AES-256-GCM under
--     CONNECTOR_CREDENTIALS_KEY, bound to the connection's id. Service role
--     only; removed with its connection.
--   * content_draft_deliveries.target takes 'wordpress'. `target_collection`
--     keeps the site's address the post was written to, as it keeps
--     Webflow's collection: a page sent again updates its post on that site
--     only (two sites in folders of one domain number their posts each from
--     1), so it takes an address's length now.
--   * reserve_content_deliveries: as 00284, a page already queued for the
--     same CMS (Webflow or WordPress) isn't sent there again meanwhile.

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_check,
  add constraint brand_cms_connections_provider_check
    check (provider in ('webflow', 'wordpress')),
  alter column composio_account_id drop not null,
  alter column composio_entity_id drop not null,
  add column if not exists site_url text
    check (site_url is null or (char_length(site_url) <= 2048 and site_url ~* '^https://')),
  add column if not exists account text
    check (account is null or char_length(account) between 1 and 200);

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_fields,
  add constraint brand_cms_connections_provider_fields check (
    case provider
      when 'webflow' then composio_account_id is not null and composio_entity_id is not null
      when 'wordpress' then site_url is not null and account is not null
      else false
    end
  );

comment on column public.brand_cms_connections.site_url is
  'WordPress (00294): the site''s address, its REST API at /wp-json/.';
comment on column public.brand_cms_connections.account is
  'WordPress (00294): the user the connection signs in as, with an Application Password (kept in brand_cms_credentials).';

create table if not exists public.brand_cms_credentials (
  connection_id uuid primary key references public.brand_cms_connections(id) on delete cascade,
  secret text not null check (char_length(secret) between 1 and 16384),
  set_at timestamptz not null default now(),
  set_by uuid references public.profiles(id) on delete set null
);

alter table public.brand_cms_credentials enable row level security;
revoke all on table public.brand_cms_credentials from public, anon, authenticated;
grant all on table public.brand_cms_credentials to service_role;

comment on table public.brand_cms_credentials is
  'Send to CMS (#1331, 00294): a CMS connection''s sign-in (WordPress: the user and the Application Password), encrypted by the API (AES-256-GCM, bound to the connection id). Service role only; removed with its connection.';

alter table public.content_draft_deliveries
  drop constraint if exists content_draft_deliveries_target_check,
  add constraint content_draft_deliveries_target_check
    check (target in ('webhook', 'webflow', 'wordpress')),
  drop constraint if exists content_draft_deliveries_target_collection_check,
  add constraint content_draft_deliveries_target_collection_check
    check (target_collection is null or char_length(target_collection) between 1 and 2048);

comment on column public.content_draft_deliveries.target is
  'Where the page was sent (00284, 00294): the brand''s webhook, its Webflow collection or its WordPress site (00283).';
comment on column public.content_draft_deliveries.target_collection is
  'The Webflow collection (00284), or the WordPress site''s address (00294), the page''s item or post was written to; its id is external_id.';

-- ----------------------------------------------------------------------------
-- As 00284, with no second send of a page to the same CMS while one is queued.
-- ----------------------------------------------------------------------------
create or replace function public.reserve_content_deliveries(
  p_organization_id uuid,
  p_brand_id uuid,
  p_sent_by uuid,
  p_batch_id uuid,
  p_items jsonb,
  p_limit integer,
  p_target text default 'webhook'
)
returns setof public.content_draft_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  used integer;
  room integer;
begin
  perform pg_advisory_xact_lock(hashtext('content_deliveries:' || p_organization_id::text));

  -- sent_at stays empty: it was never sent, and its time stays its own.
  update public.content_draft_deliveries
  set status = 'failed', error = 'Not sent: interrupted'
  where organization_id = p_organization_id
    and status = 'queued'
    and created_at < now() - interval '30 minutes';

  select count(*) into used
  from public.content_draft_deliveries
  where organization_id = p_organization_id
    and created_at > now() - interval '24 hours';

  room := greatest(0, p_limit - used);
  if room = 0 or jsonb_typeof(p_items) <> 'array' then
    return;
  end if;

  -- Under the lock, so two sends of one page can't both pass: both would
  -- make an item (Webflow refuses the second on its slug) or a post.
  if p_target in ('webflow', 'wordpress') and exists (
    select 1
    from public.content_draft_deliveries d
    join jsonb_array_elements(p_items) as items(item)
      on d.draft_id = (item ->> 'draft_id')::uuid
    where d.organization_id = p_organization_id
      and d.target = p_target
      and d.status = 'queued'
  ) then
    raise exception 'delivery_in_progress' using errcode = 'P0001';
  end if;

  return query
  insert into public.content_draft_deliveries
    (organization_id, brand_id, draft_id, sent_by, batch_id, title, slug, target)
  select p_organization_id, p_brand_id, (item ->> 'draft_id')::uuid, p_sent_by, p_batch_id,
         left(item ->> 'title', 300), nullif(left(item ->> 'slug', 200), ''),
         coalesce(p_target, 'webhook')
  from jsonb_array_elements(p_items) with ordinality as items(item, position)
  order by position
  limit room
  returning *;
end;
$$;

revoke all on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  from public, anon, authenticated;
grant execute on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00295_cms_framer.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00295: Framer for Send to CMS (#1331, phase 2)
-- ============================================================================
-- After Webflow (00283, 00284) and WordPress (00294), a brand connects its
-- Framer project: the project's address (or its id) and an API key made in
-- the project (Site Settings › General). The API reaches it through Framer's
-- Server API, and pages go to one of the project's CMS collections.
--
--   * brand_cms_connections takes provider 'framer'. A Framer connection
--     keeps the project's id (`site_id`, the one Framer connects to), its
--     name (`site_name`), its published address (`site_url`, empty while the
--     project isn't published) and the user the key acts as (`account`).
--     The collection and `field_map` are picked as Webflow's are, the map
--     naming field ids: { title, body, metaTitle, metaDescription, jsonLd }.
--   * The API key is kept in brand_cms_credentials, sealed as WordPress's
--     sign-in is (00294); the table itself doesn't change.
--   * content_draft_deliveries.target takes 'framer'. `target_collection`
--     keeps the collection the item was written to, as it keeps Webflow's.
--   * reserve_content_deliveries: as 00294, a page already queued for the
--     same CMS (Webflow, WordPress or Framer) isn't sent there again meanwhile.

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_check,
  add constraint brand_cms_connections_provider_check
    check (provider in ('webflow', 'wordpress', 'framer'));

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_fields,
  add constraint brand_cms_connections_provider_fields check (
    case provider
      when 'webflow' then composio_account_id is not null and composio_entity_id is not null
      when 'wordpress' then site_url is not null and account is not null
      when 'framer' then site_id is not null
      else false
    end
  );

comment on column public.brand_cms_connections.site_id is
  'Webflow: the site pages go to (00283). Framer (00295): the project''s id, as Framer connects to it.';
comment on column public.brand_cms_connections.site_name is
  'The site''s name (Webflow, WordPress), or the Framer project''s (00295).';
comment on column public.brand_cms_connections.site_url is
  'WordPress (00294): the site''s address, its REST API at /wp-json/. Framer (00295): the project''s published address, null while it isn''t published.';
comment on column public.brand_cms_connections.account is
  'WordPress (00294): the user the connection signs in as, with an Application Password. Framer (00295): the user the API key acts as. Both kept in brand_cms_credentials.';
comment on column public.brand_cms_connections.field_map is
  'Which of the collection''s fields takes each part of a page: Webflow (00283) { body, metaTitle, metaDescription, jsonLd } → field slugs; Framer (00295) { title, body, metaTitle, metaDescription, jsonLd } → field ids.';

comment on table public.brand_cms_credentials is
  'Send to CMS (#1331, 00294, 00295): a CMS connection''s sign-in (WordPress: the user and the Application Password; Framer: the project''s API key), encrypted by the API (AES-256-GCM, bound to the connection id). Service role only; removed with its connection.';

alter table public.content_draft_deliveries
  drop constraint if exists content_draft_deliveries_target_check,
  add constraint content_draft_deliveries_target_check
    check (target in ('webhook', 'webflow', 'wordpress', 'framer'));

comment on column public.content_draft_deliveries.target is
  'Where the page was sent (00284, 00294, 00295): the brand''s webhook, its Webflow collection, its WordPress site or its Framer collection (00283).';
comment on column public.content_draft_deliveries.target_collection is
  'The Webflow or Framer collection (00284, 00295), or the WordPress site''s address (00294), the page''s item or post was written to; its id is external_id.';

-- ----------------------------------------------------------------------------
-- As 00294, with Framer among the CMSs a page isn't sent to twice at once.
-- ----------------------------------------------------------------------------
create or replace function public.reserve_content_deliveries(
  p_organization_id uuid,
  p_brand_id uuid,
  p_sent_by uuid,
  p_batch_id uuid,
  p_items jsonb,
  p_limit integer,
  p_target text default 'webhook'
)
returns setof public.content_draft_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  used integer;
  room integer;
begin
  perform pg_advisory_xact_lock(hashtext('content_deliveries:' || p_organization_id::text));

  -- sent_at stays empty: it was never sent, and its time stays its own.
  update public.content_draft_deliveries
  set status = 'failed', error = 'Not sent: interrupted'
  where organization_id = p_organization_id
    and status = 'queued'
    and created_at < now() - interval '30 minutes';

  select count(*) into used
  from public.content_draft_deliveries
  where organization_id = p_organization_id
    and created_at > now() - interval '24 hours';

  room := greatest(0, p_limit - used);
  if room = 0 or jsonb_typeof(p_items) <> 'array' then
    return;
  end if;

  -- Under the lock, so two sends of one page can't both pass: both would
  -- make an item (Webflow refuses the second on its slug) or a post.
  if p_target in ('webflow', 'wordpress', 'framer') and exists (
    select 1
    from public.content_draft_deliveries d
    join jsonb_array_elements(p_items) as items(item)
      on d.draft_id = (item ->> 'draft_id')::uuid
    where d.organization_id = p_organization_id
      and d.target = p_target
      and d.status = 'queued'
  ) then
    raise exception 'delivery_in_progress' using errcode = 'P0001';
  end if;

  return query
  insert into public.content_draft_deliveries
    (organization_id, brand_id, draft_id, sent_by, batch_id, title, slug, target)
  select p_organization_id, p_brand_id, (item ->> 'draft_id')::uuid, p_sent_by, p_batch_id,
         left(item ->> 'title', 300), nullif(left(item ->> 'slug', 200), ''),
         coalesce(p_target, 'webhook')
  from jsonb_array_elements(p_items) with ordinality as items(item, position)
  order by position
  limit room
  returning *;
end;
$$;

revoke all on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  from public, anon, authenticated;
grant execute on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00296_catalog_item_issues.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00296: item issues from Google Merchant Center (#1270)
-- ============================================================================
-- The Merchant Center connector reads a brand's Merchant Center account into
-- its catalog (00278), and with each product the problems Merchant Center
-- reports for it: a missing GTIN, a price that doesn't match the landing
-- page, an image too small. Those decide whether the product can show in
-- Google's shopping results, AI Overviews and AI Mode among them, so we keep
-- them to tell the brand what to fix ("Feed fields complete", the readiness
-- cards, later).
--
--   * One row per issue per item (an offer, the catalog's variant), as
--     Merchant Center lists it: its code, severity (not_impacted, demoted,
--     disapproved), the attribute it concerns, the destination it affects
--     (reporting context) and its description. An item with no issues has
--     no rows.
--   * A sync replaces its source's rows; they go with their source.
--   * Members read their brands' rows; the server writes them.
--
-- A Merchant Center source has no credentials row (00282): it reads through
-- the workspace's Google sign-in, which Composio keeps
-- (integration_connections, 00045).

create table if not exists public.catalog_item_issues (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  source_id uuid not null references public.catalog_sources(id) on delete cascade,
  -- The item's id in the catalog (catalog_variants.external_id): Merchant Center's offer id.
  external_id text not null check (char_length(external_id) between 1 and 200),
  code text not null check (char_length(code) between 1 and 200),
  severity text not null check (severity in ('not_impacted', 'demoted', 'disapproved')),
  attribute text check (attribute is null or char_length(attribute) <= 200),
  reporting_context text check (reporting_context is null or char_length(reporting_context) <= 100),
  description text check (description is null or char_length(description) <= 1000),
  detail text check (detail is null or char_length(detail) <= 2000),
  documentation text check (documentation is null or char_length(documentation) <= 2048),
  resolution text check (resolution is null or char_length(resolution) <= 100),
  countries text[] not null default '{}' check (cardinality(countries) <= 300),
  created_at timestamptz not null default now()
);

create index if not exists catalog_item_issues_source_idx
  on public.catalog_item_issues (source_id);
create index if not exists catalog_item_issues_brand_item_idx
  on public.catalog_item_issues (brand_id, external_id);

alter table public.catalog_item_issues enable row level security;
revoke all on table public.catalog_item_issues from anon, authenticated;
grant select on table public.catalog_item_issues to authenticated;
grant all on table public.catalog_item_issues to service_role;

drop policy if exists "catalog_item_issues: member select" on public.catalog_item_issues;
create policy "catalog_item_issues: member select"
  on public.catalog_item_issues
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.catalog_item_issues is
  'Catalog (#1270, 00296): the issues Google Merchant Center reports per item (offer) of a Merchant Center source: code, severity, attribute, destination (reporting context), description. Replaced by each sync, removed with the source. Server writes, members read.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00350_catalog_category_pages.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00350: each catalog category's page on the brand's site (shopping path, 1)
-- ============================================================================
-- A brand's catalog names its categories (00278, from the products'
-- product_type: "Shoes > Hiking Boots"), but not where each one lives on the
-- site. The shopping path links a buying guide or a comparison to that page
-- (/collections/hiking-boots), so the API matches each category to one of
-- the brand's own pages that reads as a category (site_pages, 00104), every
-- time it's asked: nothing here keeps those matches.
--
--   * `catalog_category_pages` keeps what a person decided instead: the
--     page for a category (`url`), or that it has none (`url` null). A
--     category with no row is matched automatically. Keyed by the
--     category's name, as the catalog keeps it, so a decision outlives a
--     sync that writes the category again.
--   * Members read their brands' rows; the API writes them, for admins
--     and managers, after checking the page is on the brand's domains.
--   * `catalog_category_counts`: each category's live products and how
--     many of them have a variant in stock, for the Settings table and the
--     shopping path. In stock as the editor's feed match reads a variant
--     (frontend/src/lib/content/feedMatch.ts, feedStock): in_stock, instock,
--     available or limited_availability, whatever its case, spaces or
--     hyphens. The service role calls it.

create table if not exists public.catalog_category_pages (
  brand_id uuid not null references public.brands(id) on delete cascade,
  category text not null check (char_length(category) between 1 and 750),
  url text check (url is null or (char_length(url) <= 2048 and url ~* '^https?://')),
  set_by uuid references public.profiles(id) on delete set null,
  set_at timestamptz not null default now(),
  primary key (brand_id, category)
);

alter table public.catalog_category_pages enable row level security;
revoke all on table public.catalog_category_pages from anon, authenticated;
grant select on table public.catalog_category_pages to authenticated;
grant all on table public.catalog_category_pages to service_role;

drop policy if exists "catalog_category_pages: member select" on public.catalog_category_pages;
create policy "catalog_category_pages: member select"
  on public.catalog_category_pages
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.catalog_category_pages is
  'Shopping path (00350): the page a person set for a catalog category (url), or that it has none (url null). Categories with no row are matched to the brand''s site pages by the API on each read. Server writes, members read.';

create or replace function public.catalog_category_counts(p_brand_id uuid)
returns table (category text, products integer, in_stock integer)
language sql
stable
set search_path = public
as $$
  select c.name,
         count(distinct p.id)::integer,
         count(distinct p.id) filter (where exists (
           select 1 from public.catalog_variants v
           where v.product_id = p.id
             and v.removed_at is null
             and lower(regexp_replace(v.availability, '[\s-]+', '_', 'g'))
               in ('in_stock', 'instock', 'available', 'limited_availability')
         ))::integer
  from public.catalog_categories c
  join public.catalog_product_categories pc on pc.category_id = c.id
  join public.catalog_products p on p.id = pc.product_id and p.removed_at is null
  where c.brand_id = p_brand_id
  group by c.name
$$;

revoke all on function public.catalog_category_counts(uuid) from public, anon, authenticated;
grant execute on function public.catalog_category_counts(uuid) to service_role;

comment on function public.catalog_category_counts(uuid) is
  'Shopping path (00350): each catalog category of a brand with its live products and how many have a variant in stock (in_stock, instock, available or limited_availability, as feedMatch.ts reads it). Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00351_content_draft_shopping_path.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00351: a draft's shopping path (shopping path, part 2)
-- ============================================================================
-- On an online shop, a buying guide, a best-of list or a comparison should
-- send its readers, and the AI answers that quote it, to the right category
-- page and to products that are in stock and that Google Merchant Center
-- accepts. The API picks them from the brand's catalog (00278, 00296, 00350)
-- for the draft's topic; the Brief tab shows them, the person swaps, removes,
-- locks or adds, and the Content Agent writes with them.
--
--   * content_drafts.shopping_path: the path as jsonb — {version, builtAt,
--     pageType, categories: [{name, url, title}], products: [{id, title,
--     url, price, salePrice, currency, availability, image, issues, score}],
--     leftOut: [{id, title, reason}], locked, removed, added}. Null until
--     built, and for a page or a brand it doesn't fit. A member changes it
--     like the brief, so it isn't a server column.

alter table public.content_drafts
  add column if not exists shopping_path jsonb
    check (
      shopping_path is null
      or (jsonb_typeof(shopping_path) = 'object' and octet_length(shopping_path::text) <= 65536)
    );

comment on column public.content_drafts.shopping_path is
  'The draft''s shopping path (shopping path, part 2): the category pages and catalog products the page links, the products left out and why, and the person''s locks, removals and additions. Null until built.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00352_content_shopping_checks.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00352: whether a page's shopping links still sell (shopping path, part 7)
-- ============================================================================
-- A buying guide, a best-of list or a comparison sends its readers, and the
-- AI answers that quote it, to the category pages and the products of its
-- shopping path (00351). A product sells out, Google Merchant Center refuses
-- it, or it leaves the catalog, and the page goes on linking it. After each
-- catalog sync the API reads every page with a shopping path again: the live
-- page where it is published (content_drafts.published_url, or an optimized
-- page's own address), else the draft, and keeps here what its links do with
-- the path. The Content Library shows it in its Shopping path column.
--
--   * One row per draft with a shopping path; it goes with the draft, and
--     the next check removes a row whose draft lost its path or was archived.
--   * `bad`: the linked products that no longer sell, [{id, title, state}]
--     with state sold_out, refused or gone, and `needs_attention` whether
--     there are any.
--   * Members read their brands' rows; the server writes them.

create table if not exists public.content_shopping_checks (
  draft_id uuid primary key references public.content_drafts(id) on delete cascade,
  brand_id uuid not null references public.brands(id) on delete cascade,
  -- Where the links were read: the live page, or the draft when it isn't
  -- published or its page couldn't be read.
  read_from text not null check (read_from in ('page', 'draft')),
  page_url text check (
    page_url is null or (char_length(page_url) <= 2048 and page_url ~* '^https?://')
  ),
  -- The path's category pages and products, and how many of them the page links.
  categories smallint not null default 0 check (categories between 0 and 5),
  categories_linked smallint not null default 0,
  products smallint not null default 0 check (products between 0 and 40),
  products_linked smallint not null default 0,
  bad jsonb not null default '[]'::jsonb check (
    jsonb_typeof(bad) = 'array' and jsonb_array_length(bad) <= 40
  ),
  needs_attention boolean generated always as (
    jsonb_typeof(bad) = 'array' and jsonb_array_length(bad) > 0
  ) stored,
  checked_at timestamptz not null default now(),
  constraint content_shopping_checks_linked_check check (
    categories_linked between 0 and categories and products_linked between 0 and products
  )
);

create index if not exists content_shopping_checks_brand_idx
  on public.content_shopping_checks (brand_id, needs_attention);

alter table public.content_shopping_checks enable row level security;
revoke all on table public.content_shopping_checks from anon, authenticated;
grant select on table public.content_shopping_checks to authenticated;
grant all on table public.content_shopping_checks to service_role;

drop policy if exists "content_shopping_checks: member select" on public.content_shopping_checks;
create policy "content_shopping_checks: member select"
  on public.content_shopping_checks
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.content_shopping_checks is
  'Shopping path, part 7 (00352): what a page''s links do with its shopping path (00351) as the last catalog sync left the catalog: how many of its category pages and products it links, and the linked products that no longer sell (sold out, refused by Merchant Center, gone). Read from the live page when published, else the draft. Server writes, members read.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00360_shopping_card_catalog_match.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00360: the catalog product behind an AI shopping card (product visibility, part 2)
-- ============================================================================
-- Product Visibility's Shelf, Products and Categories (ECOM-005…008) count a
-- brand's products on the AI "shelf": which catalog product (00278) each
-- product card in an AI answer (prompt_result_shopping_cards) shows. A card
-- the brand's own (matched_brand_role 'own') is matched to the brand's
-- catalog when it's written, and again after the catalog changes:
--
--   * by the marketplace listing it links (an ASIN, an eBay item id) to a
--     variant's marketplace_item_id;
--   * by a GTIN the card carries, to a variant's;
--   * by its link, to a product's or a variant's page;
--   * else by its title, close enough to one product's and to no other.
--
--   * catalog_product_id: the product, null for none (a rival's card, or a
--     product the catalog doesn't have); catalog_match: how it was found,
--     read only with a product. A product deleted from the catalog leaves
--     its cards' catalog_match behind until the next sweep clears it.
--   * set_shopping_card_matches: the API writes a brand's matches in bulk
--     after a catalog sync. Members read the cards as before (RLS); only
--     the server writes these.

alter table public.prompt_result_shopping_cards
  add column if not exists catalog_product_id uuid
    references public.catalog_products(id) on delete set null,
  add column if not exists catalog_match text
    check (catalog_match is null or catalog_match in ('listing', 'gtin', 'url', 'title'));

create index if not exists prompt_result_shopping_cards_catalog_product_idx
  on public.prompt_result_shopping_cards (brand_id, catalog_product_id)
  where catalog_product_id is not null;

-- A catalog product's cards by the product alone: what `on delete set null`
-- looks up when a product is deleted, which the index above can't serve.
create index if not exists prompt_result_shopping_cards_catalog_product_id_idx
  on public.prompt_result_shopping_cards (catalog_product_id)
  where catalog_product_id is not null;

comment on column public.prompt_result_shopping_cards.catalog_product_id is
  'Product visibility (00360): the brand''s catalog product this card shows, matched by its listing, GTIN, link or title; null for none.';
comment on column public.prompt_result_shopping_cards.catalog_match is
  'How catalog_product_id was found: listing, gtin, url or title (00360).';

-- A brand's cards' matches, in bulk: [{"id", "product_id", "match"}], a null
-- product_id clearing one. Only the brand's own cards change, and only those
-- whose match changed; returns how many did.
create or replace function public.set_shopping_card_matches(p_brand_id uuid, p_matches jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with m as (
    select
      (e->>'id')::uuid as id,
      nullif(e->>'product_id', '')::uuid as product_id,
      nullif(e->>'match', '') as match
    from jsonb_array_elements(coalesce(p_matches, '[]'::jsonb)) as e
  ),
  changed as (
    update public.prompt_result_shopping_cards c
    set catalog_product_id = m.product_id,
        catalog_match = case when m.product_id is null then null else m.match end
    from m
    where c.id = m.id
      and c.brand_id = p_brand_id
      and (
        c.catalog_product_id is distinct from m.product_id
        or c.catalog_match is distinct from (case when m.product_id is null then null else m.match end)
      )
    returning 1
  )
  select count(*)::integer from changed;
$$;

revoke all on function public.set_shopping_card_matches(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.set_shopping_card_matches(uuid, jsonb) to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00361_catalog_product_ai_stats.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00361: AI visits and orders per catalog product (product visibility, part 4)
-- ============================================================================
-- Product Visibility's Products table (ECOM-007) shows, for each product in
-- the brand's catalog (00278), the AI-referred visits its page got and the
-- orders those visits led to, beside where it stands on the AI shelf. No
-- source carries an order's line items yet (Shopify order sync, #1267), so an
-- order is credited to the product whose page the AI visitor landed on first:
-- ai_traffic_events.first_url (CE-017, 00286).
--
--   * ai_visits: AI-referred page views on the product's page (the tracking
--     snippet, ai_traffic_logs: a visit's first view, from an AI source);
--   * orders, revenue: order conversions whose AI visit started on it, the
--     revenue in its main currency;
--   * a product's page is its link, else its first variant's, matched as
--     page paths are everywhere (normalize_page_path, lowercased);
--   * only the products with an AI visit or an order: a big catalog's other
--     products would only add zero rows, past PostgREST's 1000-row page;
--   * p_product_id: that one product's row (its page), none for all.
--
-- Members of the brand's organization only, as the Shopping reads.

create or replace function public.catalog_product_ai_stats(
  p_brand_id uuid,
  p_from timestamptz,
  p_to timestamptz default null,
  p_product_id uuid default null
)
returns table (
  product_id uuid,
  ai_visits bigint,
  orders bigint,
  revenue numeric,
  currency text
)
language plpgsql
stable
security definer
set search_path to 'public'
as $$
begin
  if auth.role() is distinct from 'service_role' and not exists (
    select 1
    from public.brands b
    join public.profiles pf on pf.organization_id = b.organization_id
    where b.id = p_brand_id
      and pf.id = auth.uid()
  ) then
    return;
  end if;

  return query
  with pages as (
    select
      p.id as product_id,
      lower(public.normalize_page_path(coalesce(p.url, (
        select v.url
        from public.catalog_variants v
        where v.product_id = p.id and v.removed_at is null and v.url is not null
        order by v.external_id
        limit 1
      )))) as page
    from public.catalog_products p
    where p.brand_id = p_brand_id
      and p.removed_at is null
      and (p_product_id is null or p.id = p_product_id)
  ),
  keyed as (
    select pages.product_id, pages.page
    from pages
    where pages.page is not null and pages.page <> '/'
  ),
  visits as (
    select lower(public.normalize_page_path(l.url)) as page, count(*) as n
    from public.ai_traffic_logs l
    where l.brand_id = p_brand_id
      and l.created_at >= p_from
      and (p_to is null or l.created_at < p_to)
      and l.visit_of is null
      and l.source_platform is not null
    group by 1
  ),
  sales as (
    select e.first_key as page, e.currency, count(*) as n, coalesce(sum(e.value), 0) as value
    from public.ai_traffic_events e
    where e.brand_id = p_brand_id
      and e.kind = 'conversion'
      and e.goal = 'order'
      and e.occurred_at >= p_from
      and (p_to is null or e.occurred_at < p_to)
    group by 1, 2
  ),
  -- A page's orders in its main currency: the one most of them are in.
  main_sales as (
    select distinct on (s.page) s.page, s.currency, s.value
    from sales s
    order by s.page, s.n desc, s.currency
  ),
  all_sales as (
    select s.page, sum(s.n) as n
    from sales s
    group by 1
  )
  select
    k.product_id,
    coalesce(v.n, 0)::bigint,
    coalesce(a.n, 0)::bigint,
    m.value,
    m.currency
  from keyed k
  left join visits v on v.page = k.page
  left join all_sales a on a.page = k.page
  left join main_sales m on m.page = k.page
  where v.n is not null or a.n is not null;
end;
$$;

revoke all on function public.catalog_product_ai_stats(uuid, timestamptz, timestamptz, uuid) from public, anon;
grant execute on function public.catalog_product_ai_stats(uuid, timestamptz, timestamptz, uuid)
  to authenticated, service_role;

comment on function public.catalog_product_ai_stats(uuid, timestamptz, timestamptz, uuid) is
  'Product visibility, part 4 (00361): per live catalog product of a brand with an AI visit or an order (or the one p_product_id names), the AI-referred visits to its page and the orders whose AI visit started there (first_url), with their revenue in the main currency. A product''s page is its link, else its first variant''s. Security definer with an organization check.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00362_prompt_suggestions_catalog_source.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00362: the catalog as a prompt-suggestion source (product visibility, part 14)
-- ============================================================================
-- Shopping questions drawn from the brand's catalog categories and their price
-- bands (ECOM-003) carry source 'catalog', with the category behind them in
-- source_data. Without it in the check the suggestion insert fails outright,
-- so this lands with the generator that writes those rows.

alter table public.prompt_suggestions drop constraint prompt_suggestions_source_check;
alter table public.prompt_suggestions add constraint prompt_suggestions_source_check
  check (source = any (array['llm', 'heuristic', 'gsc', 'ga', 'catalog']));

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00363_prompt_table_views.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00363: Tracked Prompts column views (PROMPT-015a)
-- ============================================================================
-- The Tracked Prompts table's columns, as a person set them: which are shown
-- and in what order. One row per person and brand, and one row per brand
-- (user_id null) for the view an admin or manager shared with everyone on it.
-- A person without a row of their own sees the brand's; without that,
-- today's default. `columns` is `{ "order": [ids], "hidden": [ids] }`; ids
-- the web doesn't know are ignored when read.

create table if not exists public.prompt_table_views (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  -- Null: the brand's shared view.
  user_id uuid references auth.users(id) on delete cascade,
  columns jsonb not null check (jsonb_typeof(columns) = 'object' and pg_column_size(columns) <= 8192),
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  unique nulls not distinct (brand_id, user_id)
);

alter table public.prompt_table_views enable row level security;
revoke all on table public.prompt_table_views from anon, authenticated;
grant select, insert, update, delete on table public.prompt_table_views to authenticated;
grant all on table public.prompt_table_views to service_role;

-- Members of the brand's organization read their own view and the brand's.
drop policy if exists "prompt_table_views: member select" on public.prompt_table_views;
create policy "prompt_table_views: member select" on public.prompt_table_views
  for select using (
    (user_id is null or user_id = auth.uid())
    and brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

-- A member writes their own view; an admin or manager writes the brand's.
drop policy if exists "prompt_table_views: write" on public.prompt_table_views;
create policy "prompt_table_views: write" on public.prompt_table_views
  for all using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
        and (
          prompt_table_views.user_id = auth.uid()
          or (prompt_table_views.user_id is null and p.role in ('admin', 'manager'))
        )
    )
  )
  with check (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
        and (
          prompt_table_views.user_id = auth.uid()
          or (prompt_table_views.user_id is null and p.role in ('admin', 'manager'))
        )
    )
  );

comment on table public.prompt_table_views is
  'Tracked Prompts columns (PROMPT-015a, 00363): a person''s shown and ordered columns per brand, and the brand''s shared view (user_id null) set by an admin or manager.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00364_cloro_countries.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00364: the countries each tracking engine answers from (PROMPT-015e)
-- ============================================================================
-- The AI engines' provider (Cloro) supports a different set of countries per
-- engine, and asking an engine in a country it doesn't support fails. Its
-- GET /v1/countries?model= is the only source of truth, so the API reads it
-- daily, before the tracking runs, and keeps it here:
--
--   * the location picker offers only countries some engine answers from;
--   * the tracking run skips an engine in a country it doesn't support.
--
-- A model whose read fails keeps its last list. An empty table (no provider
-- key, or before the first read) restricts nothing.

create table if not exists public.cloro_countries (
  model text not null check (char_length(model) between 1 and 40),
  country text not null check (country ~ '^[A-Z]{2}$'),
  refreshed_at timestamptz not null default now(),
  primary key (model, country)
);

alter table public.cloro_countries enable row level security;
revoke all on table public.cloro_countries from anon, authenticated;
grant select on table public.cloro_countries to authenticated;
grant all on table public.cloro_countries to service_role;

-- Not a customer's data: every signed-in member may read it; the API writes.
drop policy if exists "cloro_countries: read" on public.cloro_countries;
create policy "cloro_countries: read" on public.cloro_countries
  for select to authenticated using (true);

comment on table public.cloro_countries is
  'Countries each tracking engine answers from (PROMPT-015e, 00364), read daily from the provider''s GET /v1/countries?model=. Empty restricts nothing.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00365_action_outcome_mixed.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00365: an action's result can read "mixed" (learning A4)
-- ============================================================================
-- The validation sweep (backend/src/lib/action-center/validate.js) compares an
-- action's metrics before it was raised and after it closed. One metric up
-- and another down used to read as "improved", which taught that anything
-- moving up was the work paying off. It now reads "mixed", as does a Site
-- Audit fix whose pages, audited again, only partly pass. The action's main
-- metric decides when it was measured; see deriveOutcome.

alter table public.actions
  drop constraint if exists actions_outcome_check;

alter table public.actions
  add constraint actions_outcome_check
  check (outcome in (
    'pending_measurement',
    'improved',
    'mixed',
    'no_meaningful_change',
    'declined',
    'not_measurable'
  ));

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00366_action_dismiss_reason.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00366: why an action was dismissed (learning A5)
-- ============================================================================
-- Dismissing an Action Center action asked nothing, so a dismissal taught
-- nothing: the same definition could open again 14 days later for the same
-- reason it was turned down. The person now says why, as a content
-- opportunity's dismissal does (CONTENT-006): the reason is kept while the
-- action stays dismissed, and cleared when it's set to another status.
-- Nothing reads it to rank or rest actions yet (phase B).

alter table public.actions
  add column if not exists dismiss_reason text;

alter table public.actions
  drop constraint if exists actions_dismiss_reason_check;

alter table public.actions
  add constraint actions_dismiss_reason_check
  check (
    dismiss_reason is null
    or dismiss_reason in ('not_relevant', 'already_done', 'wrong_data', 'not_now')
  );

comment on column public.actions.dismiss_reason is
  'Why the action was dismissed (00366, learning A5): not_relevant, already_done, wrong_data or not_now; null when no reason was given or the action is not dismissed.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00367_content_suggestion_decisions.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00367: how a brand decides the Content Agent's suggestions, by rule
-- (learning B6)
-- ============================================================================
-- Each suggestion the agent leaves on a draft (00217) names the rules it
-- fixes (rule_keys), and keeps whether a person accepted or rejected it. Read
-- one at a time, nothing learned from them. This sums a brand's decisions
-- since a day by rule: the agent keeps its changes small for a rule people
-- there mostly reject (contentSuggestionStats.js). One brand's own
-- decisions only, read by the API (service role).
--
-- Only its small changes count, a passage's words replaced or blocks
-- inserted: a whole page rewritten to the rules (kind 'page', 00247) names
-- every rule it was asked for, and one rejected would count against each.
-- `drafts` is how many drafts a rule's suggestions were rejected on, so one
-- Reject all on one draft isn't read as a habit, even beside an Accept on
-- another.

-- A database with an earlier shape of it (a dev database, before review)
-- takes this one in its place: create or replace can't change its rows.
drop function if exists public.content_suggestion_decisions(uuid, timestamptz);

create or replace function public.content_suggestion_decisions(
  p_brand_id uuid,
  p_since timestamptz
)
returns table (rule_key text, accepted integer, rejected integer, drafts integer)
language sql
stable
security invoker
set search_path to 'public'
as $$
  select k.rule_key,
         count(*) filter (where s.status = 'accepted')::integer as accepted,
         count(*) filter (where s.status = 'rejected')::integer as rejected,
         count(distinct s.draft_id) filter (where s.status = 'rejected')::integer as drafts
    from public.content_draft_suggestions s
    join public.content_drafts d on d.id = s.draft_id
    cross join lateral unnest(s.rule_keys) as k(rule_key)
   where d.brand_id = p_brand_id
     and s.kind in ('replace', 'insert')
     and s.status in ('accepted', 'rejected')
     and s.decided_at >= p_since
   group by k.rule_key;
$$;

revoke all on function public.content_suggestion_decisions(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.content_suggestion_decisions(uuid, timestamptz) to service_role;

comment on function public.content_suggestion_decisions(uuid, timestamptz) is
  'A brand''s accepted and rejected Content Agent suggestions since a day, by rule key, and the drafts they were rejected on; small changes only, not page rewrites (00367, learning B6). Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00368_action_scorecard.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00368: what worked at a brand, by kind of action (learning B3)
-- ============================================================================
-- Each completed action keeps its result (server action-center/validate.js,
-- read a week, two weeks and a month after it closed) and a dismissed one
-- why it was turned down (00366). Read one at a time, a brand can't see
-- which kinds of work pay off for it. This sums the brand's actions raised
-- since a day by kind: how many were completed, what their results read,
-- the median change in each one's main metric, and how many were dismissed
-- and why. One brand's own actions only, never another's: the History tab
-- reads it with the member's session (RLS keeps it to their organization),
-- the API with the service role.

create or replace function public.action_scorecard(
  p_brand_id uuid,
  p_since timestamptz default null
)
returns table (
  kind text,
  completed integer,
  improved integer,
  mixed integer,
  no_change integer,
  declined integer,
  not_measurable integer,
  pending integer,
  final integer,
  median_change numeric,
  dismissed integer,
  dismiss_reasons jsonb
)
language sql
stable
security invoker
set search_path to 'public'
as $$
  with closed as (
    select a.kind,
           a.status,
           a.outcome,
           a.dismiss_reason,
           a.validation->>'final' = 'true' as is_final,
           -- The relative change in its main metric (learning A4), when the
           -- metric was read before and after and had a before to scale by.
           (select (m->>'after')::numeric / nullif((m->>'before')::numeric, 0) - 1
              from jsonb_array_elements(
                     case when jsonb_typeof(a.validation->'metrics') = 'array'
                          then a.validation->'metrics' else '[]'::jsonb end
                   ) as m
             where m->>'metric' = a.validation->>'primary'
               and jsonb_typeof(m->'before') = 'number'
               and jsonb_typeof(m->'after') = 'number'
             limit 1) as change
      from public.actions a
     where a.brand_id = p_brand_id
       and a.deleted_at is null
       and a.status in ('completed', 'dismissed')
       and (p_since is null or a.created_at >= p_since)
  )
  select c.kind,
         count(*) filter (where c.status = 'completed')::integer,
         count(*) filter (where c.status = 'completed' and c.outcome = 'improved')::integer,
         count(*) filter (where c.status = 'completed' and c.outcome = 'mixed')::integer,
         count(*) filter (where c.status = 'completed' and c.outcome = 'no_meaningful_change')::integer,
         count(*) filter (where c.status = 'completed' and c.outcome = 'declined')::integer,
         count(*) filter (where c.status = 'completed' and c.outcome = 'not_measurable')::integer,
         count(*) filter (
           where c.status = 'completed'
             and (c.outcome is null or c.outcome = 'pending_measurement')
         )::integer,
         count(*) filter (where c.status = 'completed' and c.is_final)::integer,
         -- The median, so one small page that went from 1 to 20 doesn't
         -- read as the kind's typical result. Over the results with a
         -- verdict only.
         round(
           (percentile_cont(0.5) within group (order by c.change) filter (
             where c.status = 'completed'
               and c.outcome in ('improved', 'mixed', 'no_meaningful_change', 'declined')
           ))::numeric,
           4
         ),
         count(*) filter (where c.status = 'dismissed')::integer,
         coalesce(
           (select jsonb_object_agg(r.reason, r.n)
              from (select coalesce(d.dismiss_reason, 'none') as reason, count(*) as n
                      from closed d
                     where d.kind = c.kind and d.status = 'dismissed'
                     group by 1) as r),
           '{}'::jsonb
         )
    from closed c
   group by c.kind;
$$;

revoke all on function public.action_scorecard(uuid, timestamptz) from public, anon;
grant execute on function public.action_scorecard(uuid, timestamptz) to authenticated, service_role;

comment on function public.action_scorecard(uuid, timestamptz) is
  'A brand''s actions raised since a day, by kind: completed, results, median change in the main metric, dismissed and why (00368, learning B3). RLS applies to the caller.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00369_cited_page_features.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00369: what the pages AI answers cite have (learning C1)
-- ============================================================================
-- The Action Center's "Analyze competitor content" task was a step for a
-- person: nothing read the competitor pages AI engines cite instead of the
-- brand. The task now reads them (server action-center/competitorPages.js):
-- the public pages cited in the brand's own tracked answers for the action's
-- prompts, and the brand's own page cited there, fetched free (safe-fetch,
-- never a paid scraper) and run through Site Audit's own rule checks
-- (structure, FAQ, schema, statistics, dates, length). Only what the checks
-- found is kept here, never the page's text, and nothing is summarised by AI.
--
-- One row per brand and page: read again after two weeks, and a day's reads
-- counted against the brand's daily cap. The server writes and reads it
-- (service role); members see what it found on the task.

create table if not exists public.cited_page_features (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  -- The page as Site Audit keys it: host and path, lower case.
  page_key text not null,
  url text not null,
  domain text not null,
  -- The brand's own page, cited for the same prompts.
  own boolean not null default false,
  -- { words, checks: { "<check key>": "pass" | "warn" | "fail" | "na" } }, or
  -- { unreadable: true[, disallowed: true] } for a page that couldn't be read
  -- (it blocks readers, a wall, robots.txt): kept so it counts against the
  -- day's reads and isn't tried again while fresh.
  features jsonb not null default '{}'::jsonb,
  read_at timestamptz not null default now(),
  unique (brand_id, page_key)
);

create index if not exists cited_page_features_brand_read_idx
  on public.cited_page_features (brand_id, read_at desc);

-- The server's alone: no member reads it directly.
alter table public.cited_page_features enable row level security;
revoke all on table public.cited_page_features from anon, authenticated;
grant all on table public.cited_page_features to service_role;

comment on table public.cited_page_features is
  'Learning C1 (00369): Site Audit rule checks of the pages cited in a brand''s tracked answers for an action''s prompts (competitors'' and its own), read free (safe-fetch). Features only, never page text. Server only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00370_prompt_demand.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00370: real demand for a tracked prompt (PROMPT-014)
-- ============================================================================
-- A prompt's AI search volume is an estimate (PROMPT-013). Its Demand card
-- shows the signs that people really ask it, each with its source and date:
--
--   * Search Console: impressions and clicks over 28 days for the brand's
--     queries that match the prompt (gsc_query_stats, read every night).
--   * Google Trends: the 12 months of its keyword, rising, steady or falling.
--   * People Also Ask: the questions Google lists for its keyword.
--   * YouTube: the videos for its keyword, and their views.
--
-- The last three are DataForSEO's queued (Standard) tasks, read about once a
-- week: the keyword is the prompt's volume analysis's own (prompt_volumes),
-- where it is measured, so a prompt never analysed has none of them. A task
-- is set one night and read when it's done, that night or the next (`tasks`).
-- A sweep claims a prompt before it sets its tasks (prompt_demand_claim), so
-- two sweeps at once never pay for the same prompt twice.
--
-- The level (high, medium, low) weighs the signals there are; `signals` is
-- how many of the four were read. The Action Center's priority reads it.
--
--   * Members read their brands' rows; the server's nightly sweep writes
--     them (service role). The app reads them through the server
--     (GET /api/prompts/:id/demand).
--   * prompt_demand_gsc_queries: a brand's Search Console queries over a
--     window, with their clicks and impressions, for the sweep to match to
--     its prompts. Service role only.
--   * prompt_demand_claim: claims the prompts a sweep is about to set tasks
--     for. Service role only.
--   * prompt_demand_brand_updates: when each brand's rows were last written,
--     so a night starts with the brands waiting longest. Service role only.

create table if not exists public.prompt_demand (
  prompt_id     uuid primary key references public.prompts(id) on delete cascade,
  brand_id      uuid not null references public.brands(id) on delete cascade,
  -- What the paid signals were read for: the volume analysis's top keyword,
  -- its DataForSEO location and language.
  keyword       text,
  location_code integer,
  language_code text,
  -- Each { ..., at }: what was read and when. Null: never read, or the
  -- source isn't there (no Search Console property, no keyword).
  gsc           jsonb,
  trends        jsonb,
  paa           jsonb,
  youtube       jsonb,
  -- The DataForSEO tasks set and not read yet: { posted_at, trends, paa, youtube } (task ids).
  tasks         jsonb,
  -- When the paid signals were last set to be read: about once a week.
  posted_at     timestamptz,
  -- When a sweep last claimed the prompt to set its tasks
  -- (prompt_demand_claim). A claim older than the sweep's window is one
  -- that died, and may be taken again.
  claimed_at    timestamptz,
  level         text
    constraint prompt_demand_level_check check (level in ('high', 'medium', 'low')),
  signals       smallint not null default 0
    constraint prompt_demand_signals_check check (signals between 0 and 4),
  updated_at    timestamptz not null default now()
);

create index if not exists prompt_demand_brand_idx on public.prompt_demand (brand_id);
-- The tasks waiting to be read: few at a time, looked up every night.
create index if not exists prompt_demand_tasks_idx
  on public.prompt_demand (prompt_id) where tasks is not null;

-- Read by the brand's members (the policy below); written by the server.
alter table public.prompt_demand enable row level security;
revoke all on table public.prompt_demand from anon, authenticated;
grant select on table public.prompt_demand to authenticated;
grant all on table public.prompt_demand to service_role;

drop policy if exists "prompt_demand: member select" on public.prompt_demand;
create policy "prompt_demand: member select"
  on public.prompt_demand
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

comment on table public.prompt_demand is
  'Real demand for a tracked prompt (PROMPT-014): Search Console impressions and clicks (nightly), Google Trends, People Also Ask and YouTube (DataForSEO, about weekly), and the level they come to. Written by the server''s nightly sweep; members read.';

-- A brand's Search Console queries over a window, the most seen first, with
-- their clicks and impressions: the sweep matches each one to a prompt.
-- jsonb, so PostgREST's row cap doesn't cut the list at 1,000.
create or replace function public.prompt_demand_gsc_queries(
  p_brand_id uuid, p_from date, p_to date, p_limit integer default 5000
) returns jsonb
language sql
stable
set search_path = public
as $$
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) from (
    select g.query,
           sum(g.clicks)::bigint as clicks,
           sum(g.impressions)::bigint as impressions
    from public.gsc_query_stats g
    where g.brand_id = p_brand_id and g.date between p_from and p_to
    group by g.query
    order by sum(g.impressions) desc, g.query
    limit greatest(least(coalesce(p_limit, 5000), 20000), 1)
  ) x
$$;

revoke all on function public.prompt_demand_gsc_queries(uuid, date, date, integer) from public, anon, authenticated;
grant execute on function public.prompt_demand_gsc_queries(uuid, date, date, integer) to service_role;

comment on function public.prompt_demand_gsc_queries(uuid, date, date, integer) is
  'PROMPT-014 (00370): a brand''s Search Console queries between two days with their clicks and impressions, the most seen first, at most p_limit (default 5,000). The demand sweep matches them to prompts. Service role only.';

-- Claims the prompts a sweep is about to set DataForSEO tasks for, before
-- it sets them: a prompt is claimed when no task of its is waiting and no
-- other sweep claimed it in the last p_stale_minutes. Makes the row of a
-- prompt that has none yet; a prompt deleted since is left out. Returns
-- the prompt ids claimed (jsonb, past PostgREST's row cap): only those are
-- set. Two sweeps at once: the row's lock makes the second wait, and then
-- find the claim.
create or replace function public.prompt_demand_claim(
  p_rows jsonb, p_stale_minutes integer default 120
) returns jsonb
language sql
volatile
set search_path = public
as $$
  with asked as (
    select distinct on (r.prompt_id) r.prompt_id, r.brand_id
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(prompt_id uuid, brand_id uuid)
    join public.prompts p on p.id = r.prompt_id
    where r.brand_id is not null
    order by r.prompt_id
  ), claimed as (
    insert into public.prompt_demand as d (prompt_id, brand_id, claimed_at)
    select a.prompt_id, a.brand_id, now() from asked a
    on conflict (prompt_id) do update
      set claimed_at = excluded.claimed_at
      where d.tasks is null
        and (
          d.claimed_at is null
          or d.claimed_at < now() - make_interval(mins => greatest(coalesce(p_stale_minutes, 120), 1))
        )
    returning d.prompt_id
  )
  select coalesce(jsonb_agg(c.prompt_id), '[]'::jsonb) from claimed c
$$;

revoke all on function public.prompt_demand_claim(jsonb, integer) from public, anon, authenticated;
grant execute on function public.prompt_demand_claim(jsonb, integer) to service_role;

comment on function public.prompt_demand_claim(jsonb, integer) is
  'PROMPT-014 (00370): claims [{prompt_id, brand_id}] for a sweep about to set their DataForSEO tasks: those with no task waiting and no claim in the last p_stale_minutes (default 120). Returns the prompt ids claimed. Service role only.';

-- When each brand's demand rows were last written, { brand_id: timestamptz }:
-- a night takes the brands never written first, then the ones waiting
-- longest, so a sweep that runs out of time leaves different brands each
-- night.
create or replace function public.prompt_demand_brand_updates()
returns jsonb
language sql
stable
set search_path = public
as $$
  select coalesce(jsonb_object_agg(x.brand_id, x.updated_at), '{}'::jsonb) from (
    select d.brand_id, max(d.updated_at) as updated_at
    from public.prompt_demand d
    group by d.brand_id
  ) x
$$;

revoke all on function public.prompt_demand_brand_updates() from public, anon, authenticated;
grant execute on function public.prompt_demand_brand_updates() to service_role;

comment on function public.prompt_demand_brand_updates() is
  'PROMPT-014 (00370): when each brand''s prompt_demand rows were last written, as { brand_id: updated_at }, for the nightly sweep''s brand order. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00371_catalog_suggestion_categories.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00371: catalog categories for shopping suggestions, counted in the database
-- ============================================================================
-- Shopping prompt suggestions (ECOM-003, 00362) offer the model a brand's
-- biggest catalog categories, each with its price band. The server read the
-- whole live catalog for that, a page at a time (every product, category
-- link and variant), to keep 8 categories, and cut the categories at an
-- arbitrary 1,000. `catalog_suggestion_categories` counts here instead and
-- returns only the categories offered:
--
--   * a category's live products (removed_at null), p_min_products at least;
--   * a product's price: its lowest live variant's, on sale or not, above
--     zero, in that variant's currency;
--   * when every priced product of the category shares one currency: the
--     lowest and the highest price, and the price three quarters of them
--     sell at or under (price_p75; the server rounds it to one a shopper
--     would name);
--   * the most products first, then by name, p_limit of them.
--
-- Products and variants are read by brand, live only, so their brand
-- indexes (00278, 00281) serve the read, not every brand's rows.
--
-- The service role calls it, as 00350's catalog_category_counts.

create or replace function public.catalog_suggestion_categories(
  p_brand_id uuid,
  p_limit integer default 8,
  p_min_products integer default 2
)
returns table (
  category text,
  products integer,
  price_low numeric,
  price_high numeric,
  price_p75 numeric,
  currency text
)
language sql
stable
set search_path = public
as $$
  with live as (
    select pc.category_id, pc.product_id
    from public.catalog_product_categories pc
    join public.catalog_products p
      on p.id = pc.product_id and p.brand_id = p_brand_id and p.removed_at is null
    where pc.brand_id = p_brand_id
  ),
  priced as (
    select distinct on (v.product_id)
           v.product_id,
           coalesce(v.sale_price, v.price) as amount,
           v.currency
    from public.catalog_variants v
    where v.brand_id = p_brand_id
      and v.removed_at is null
      and v.product_id in (select l.product_id from live l)
      and coalesce(v.sale_price, v.price) > 0
    order by v.product_id, coalesce(v.sale_price, v.price), v.id
  ),
  counted as (
    select c.name as name,
           count(*)::integer as product_count,
           count(distinct coalesce(pr.currency, '')) filter (where pr.product_id is not null)
             as currencies,
           max(pr.currency) as one_currency,
           min(pr.amount) as low,
           max(pr.amount) as high,
           percentile_disc(0.75) within group (order by pr.amount) as p75
    from public.catalog_categories c
    join live l on l.category_id = c.id
    left join priced pr on pr.product_id = l.product_id
    where c.brand_id = p_brand_id
    group by c.id, c.name
    having count(*) >= p_min_products
  )
  select k.name,
         k.product_count,
         case when k.currencies = 1 and k.one_currency is not null then k.low end,
         case when k.currencies = 1 and k.one_currency is not null then k.high end,
         case when k.currencies = 1 and k.one_currency is not null then k.p75 end,
         case when k.currencies = 1 then k.one_currency end
  from counted k
  order by k.product_count desc, k.name
  limit greatest(p_limit, 0)
$$;

revoke all on function public.catalog_suggestion_categories(uuid, integer, integer)
  from public, anon, authenticated;
grant execute on function public.catalog_suggestion_categories(uuid, integer, integer)
  to service_role;

comment on function public.catalog_suggestion_categories(uuid, integer, integer) is
  'Shopping prompt suggestions (ECOM-003, 00371): a brand''s catalog categories with the most live products (p_min_products at least, p_limit of them), each with the lowest, highest and 75th-percentile price of its products (a product''s lowest live variant price, sale price first) when they share one currency. Service role only.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00372_cms_wix.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00372: Wix for Send to CMS (#1331, phase 2)
-- ============================================================================
-- After Webflow (00283, 00284), WordPress (00294) and Framer (00295), a brand
-- connects its Wix site: the site's id and an API key its owner made in Wix's
-- API Keys Manager, with the Wix Blog permissions. Pages go to the site's
-- Blog through Wix's REST API as draft posts.
--
--   * brand_cms_connections takes provider 'wix'. A Wix connection keeps the
--     site's id (`site_id`), its name (`site_name`) and the member who owns
--     the posts it writes (`account`: a Wix member id; Wix's Blog needs an
--     owner for a post).
--   * The API key is kept in brand_cms_credentials, sealed as WordPress's
--     sign-in is (00294); the table itself doesn't change.
--   * content_draft_deliveries.target takes 'wix'. `target_collection` keeps
--     the site's id the post was written to, as it keeps WordPress's site.
--   * reserve_content_deliveries: as 00295, a page already queued for the
--     same CMS (Webflow, WordPress, Framer or Wix) isn't sent there again
--     meanwhile.

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_check,
  add constraint brand_cms_connections_provider_check
    check (provider in ('webflow', 'wordpress', 'framer', 'wix'));

alter table public.brand_cms_connections
  drop constraint if exists brand_cms_connections_provider_fields,
  add constraint brand_cms_connections_provider_fields check (
    case provider
      when 'webflow' then composio_account_id is not null and composio_entity_id is not null
      when 'wordpress' then site_url is not null and account is not null
      when 'framer' then site_id is not null
      when 'wix' then site_id is not null and account is not null
      else false
    end
  );

comment on column public.brand_cms_connections.site_id is
  'Webflow: the site pages go to (00283). Framer (00295): the project''s id, as Framer connects to it. Wix (00372): the site''s id.';
comment on column public.brand_cms_connections.site_name is
  'The site''s name (Webflow, WordPress, Wix (00372): its display name, when the API key may read it), or the Framer project''s (00295).';
comment on column public.brand_cms_connections.account is
  'WordPress (00294): the user the connection signs in as, with an Application Password. Framer (00295): the user the API key acts as. Both kept in brand_cms_credentials. Wix (00372): the member who owns the posts it writes.';

comment on table public.brand_cms_credentials is
  'Send to CMS (#1331, 00294, 00295, 00372): a CMS connection''s sign-in (WordPress: the user and the Application Password; Framer: the project''s API key; Wix: the site owner''s API key), encrypted by the API (AES-256-GCM, bound to the connection id). Service role only; removed with its connection.';

alter table public.content_draft_deliveries
  drop constraint if exists content_draft_deliveries_target_check,
  add constraint content_draft_deliveries_target_check
    check (target in ('webhook', 'webflow', 'wordpress', 'framer', 'wix'));

comment on column public.content_draft_deliveries.target is
  'Where the page was sent (00284, 00294, 00295, 00372): the brand''s webhook, its Webflow collection, its WordPress site, its Framer collection or its Wix site''s Blog (00283).';
comment on column public.content_draft_deliveries.target_collection is
  'The Webflow or Framer collection (00284, 00295), the WordPress site''s address (00294) or the Wix site''s id (00372) the page''s item or post was written to; its id is external_id.';

-- ----------------------------------------------------------------------------
-- As 00295, with Wix among the CMSs a page isn't sent to twice at once.
-- ----------------------------------------------------------------------------
create or replace function public.reserve_content_deliveries(
  p_organization_id uuid,
  p_brand_id uuid,
  p_sent_by uuid,
  p_batch_id uuid,
  p_items jsonb,
  p_limit integer,
  p_target text default 'webhook'
)
returns setof public.content_draft_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  used integer;
  room integer;
begin
  perform pg_advisory_xact_lock(hashtext('content_deliveries:' || p_organization_id::text));

  -- sent_at stays empty: it was never sent, and its time stays its own.
  update public.content_draft_deliveries
  set status = 'failed', error = 'Not sent: interrupted'
  where organization_id = p_organization_id
    and status = 'queued'
    and created_at < now() - interval '30 minutes';

  select count(*) into used
  from public.content_draft_deliveries
  where organization_id = p_organization_id
    and created_at > now() - interval '24 hours';

  room := greatest(0, p_limit - used);
  if room = 0 or jsonb_typeof(p_items) <> 'array' then
    return;
  end if;

  -- Under the lock, so two sends of one page can't both pass: both would
  -- make an item (Webflow refuses the second on its slug) or a post.
  if p_target in ('webflow', 'wordpress', 'framer', 'wix') and exists (
    select 1
    from public.content_draft_deliveries d
    join jsonb_array_elements(p_items) as items(item)
      on d.draft_id = (item ->> 'draft_id')::uuid
    where d.organization_id = p_organization_id
      and d.target = p_target
      and d.status = 'queued'
  ) then
    raise exception 'delivery_in_progress' using errcode = 'P0001';
  end if;

  return query
  insert into public.content_draft_deliveries
    (organization_id, brand_id, draft_id, sent_by, batch_id, title, slug, target)
  select p_organization_id, p_brand_id, (item ->> 'draft_id')::uuid, p_sent_by, p_batch_id,
         left(item ->> 'title', 300), nullif(left(item ->> 'slug', 200), ''),
         coalesce(p_target, 'webhook')
  from jsonb_array_elements(p_items) with ordinality as items(item, position)
  order by position
  limit room
  returning *;
end;
$$;

revoke all on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  from public, anon, authenticated;
grant execute on function public.reserve_content_deliveries(uuid, uuid, uuid, uuid, jsonb, integer, text)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00373_basket_positive_sentiment.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00373: a basket's positive sentiment (learning D1)
-- ============================================================================
-- An action sent from Mentions (MS-08) is measured on its answers' prompts
-- (opportunity_basket_metrics, 00116), but the basket read mentions,
-- visibility and citations only: an action sent to turn negative answers
-- around was judged by how often the brand was named, not by how it was
-- spoken of. The basket now reads its prompts' answers naming the brand
-- (the rollup's mention_answers, 00130) and the positive ones among them;
-- the server turns them into the positive share (basketMetrics.js). That is
-- the base Insights' Positive Sentiment card divides by since 00191: an
-- answer that only cites the brand is always neutral, so counting it (the
-- rollup's mentioning_answers, naming OR citing) would pull the share down.
-- Null while a day of the window isn't rewritten with them yet. Otherwise
-- as 00116.

create or replace function public.opportunity_basket_metrics(
  p_brand_id uuid,
  p_prompt_ids uuid[],
  p_page_keys text[],
  p_page_domains text[],
  p_page_paths text[],
  p_from date,
  p_to date
)
returns jsonb
language sql
stable
set search_path = public
as $$
  with cells as (
    select count(*) as cells,
           count(*) filter (where has_mention or has_citation) as visible,
           coalesce(sum(answer_count) filter (where has_mention), 0) as mention_answers,
           -- Sentiment (00373): the answers naming the brand (the rollup's
           -- column, not the alias above; never the ones only citing it), and
           -- the positive ones among them, as Insights' Positive Sentiment
           -- card counts them (00191).
           coalesce(sum(d.mention_answers), 0) as named_answers,
           coalesce(sum(d.positive_count), 0) as positive_answers,
           count(*) filter (where d.mention_answers is null or d.positive_count is null) as unfilled
    from insights_prompt_daily d
    where brand_id = p_brand_id
      and day between p_from and p_to
      and prompt_id = any(p_prompt_ids)
  ),
  comp as (
    select d.competitor_id, count(*) as visible
    from insights_competitor_prompt_daily d
    join competitors c on c.id::text = d.competitor_id and c.brand_id = p_brand_id
    where d.brand_id = p_brand_id
      and d.day between p_from and p_to
      and d.prompt_id = any(p_prompt_ids)
    group by d.competitor_id
  ),
  urls as (
    select id
    from citation_urls
    where domain = any(p_page_domains)
      and rtrim(
            regexp_replace(split_part(split_part(lower(url), '#', 1), '?', 1), '^https?://(www\.)?', ''),
            '/'
          ) = any(p_page_keys)
  )
  select jsonb_build_object(
    'cells', (select cells from cells),
    'visible', (select visible from cells),
    'mention_answers', (select mention_answers from cells),
    -- Null while a day of the window isn't rewritten with them yet (00130):
    -- a partial count would read as a change.
    'named_answers', (select case when unfilled = 0 then named_answers end from cells),
    'positive_answers', (select case when unfilled = 0 then positive_answers end from cells),
    'competitor_visible_total', (select coalesce(sum(visible), 0) from comp),
    'top_competitor_visible', (select coalesce(max(visible), 0) from comp),
    'page_citations', (
      select count(*)
      from prompt_result_citations
      where brand_id = p_brand_id
        and created_at >= p_from
        and created_at < p_to + 1
        and url_id in (select id from urls)
    ),
    'ga_connected', exists (
      select 1 from ga_ai_traffic_stats
      where brand_id = p_brand_id and date between p_from and p_to
    ),
    'page_ai_sessions', (
      select coalesce(sum(sessions), 0)
      from ga_ai_traffic_stats
      where brand_id = p_brand_id
        and date between p_from and p_to
        and coalesce(nullif(rtrim(split_part(landing_page, '?', 1), '/'), ''), '/') = any(p_page_paths)
    )
  );
$$;

revoke all on function public.opportunity_basket_metrics(uuid, uuid[], text[], text[], text[], date, date)
  from public, anon, authenticated;
grant execute on function public.opportunity_basket_metrics(uuid, uuid[], text[], text[], text[], date, date)
  to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00374_menu_access.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00374: menu access — which left-menu sections each role and person sees
-- ============================================================================
-- Admins pick which sections of the left menu each role sees, and can let
-- chosen managers do it too (Settings › Menu access). People pick what they
-- work on or lead, which narrows their own menu (the "What do you work on?"
-- step and Settings › Account). Hide only: a hidden section is off the menu,
-- its pages still open from a link, and roles and data access don't change.
-- Nobody takes a section off an admin's menu (only their own work areas
-- narrow it), and Action Center is on everyone's menu (the app applies both).
--
-- Sections are named by their route under /dashboard ('content', 'audit',
-- 'insights'…), so a section added later is on everyone's menu until someone
-- hides it.
--
--   * organization_menu_roles: per organization and role (not admin), the
--     sections that role doesn't see. No row = the role sees every section.
--     Members of the organization read it (their menu needs their role's
--     row); the server writes it (service role), for an admin or a manager
--     who can change menus.
--   * profiles.menu_shown / menu_hidden: a person's exception to their role:
--     a section shown that the role hides, or hidden that it shows.
--     profiles.can_manage_menus: a manager an admin let change menus. All
--     three are set by the server (the guard below), like role, and belong
--     to the organization and role they were given for: moving organization
--     (removed, then invited elsewhere) clears all three, and a new role
--     clears can_manage_menus (the reset below).
--   * profiles.work_areas: what the person works on or leads, theirs to set.
--     work_areas_asked_at: when they answered (or skipped) the step, so it
--     is asked once.

create table if not exists public.organization_menu_roles (
  organization_id uuid not null references public.organizations(id) on delete cascade,
  role public.user_role not null check (role <> 'admin'),
  hidden_sections text[] not null default '{}',
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (organization_id, role)
);

-- Read by members of the organization (the policy below); written by the server.
alter table public.organization_menu_roles enable row level security;
revoke all on table public.organization_menu_roles from anon, authenticated;
grant select on table public.organization_menu_roles to authenticated;
grant all on table public.organization_menu_roles to service_role;

drop policy if exists "organization_menu_roles: member select" on public.organization_menu_roles;
create policy "organization_menu_roles: member select"
  on public.organization_menu_roles
  for select
  using (
    organization_id in (
      select p.organization_id from public.profiles p where p.id = auth.uid()
    )
  );

drop trigger if exists trg_organization_menu_roles_updated_at on public.organization_menu_roles;
create trigger trg_organization_menu_roles_updated_at
  before update on public.organization_menu_roles
  for each row execute function public.handle_updated_at();

comment on table public.organization_menu_roles is
  'Menu access: the left-menu sections (routes under /dashboard) a role of the organization doesn''t see. Hide only: the pages still open. No row = every section. Never for admins; the server writes it.';

alter table public.profiles
  add column if not exists work_areas text[] not null default '{}'
    check (
      work_areas <@ array[
        'leaders', 'aeo', 'content', 'brand', 'growth',
        'product', 'bizdev', 'developers', 'analytics'
      ]::text[]
    ),
  add column if not exists work_areas_asked_at timestamptz,
  add column if not exists menu_shown text[] not null default '{}',
  add column if not exists menu_hidden text[] not null default '{}',
  add column if not exists can_manage_menus boolean not null default false;

comment on column public.profiles.work_areas is
  'Menu access: what the person works on or leads; narrows their left menu to those areas'' sections. Empty = every section.';
comment on column public.profiles.work_areas_asked_at is
  'Menu access: when the person answered or skipped "What do you work on?"; null = not asked yet.';
comment on column public.profiles.menu_shown is
  'Menu access: sections shown for this person although their role hides them. Set by the server.';
comment on column public.profiles.menu_hidden is
  'Menu access: sections hidden for this person although their role shows them. Set by the server.';
comment on column public.profiles.can_manage_menus is
  'Menu access: a manager an admin let change menus (the role table and every non-admin''s exceptions). Set by the server.';

-- 00228's guard, plus the menu columns: a person's own update can't give
-- them a menu exception or the right to change menus.
create or replace function public.guard_profile_server_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user) then
    return new;
  end if;
  if new.role is distinct from old.role then
    raise exception 'profile role is managed server-side' using errcode = '42501';
  end if;
  if new.organization_id is distinct from old.organization_id
     and (
       old.organization_id is not null
       or new.organization_id is null
       or public.organization_has_other_members(new.organization_id, new.id)
     )
  then
    raise exception 'profile organization is managed server-side' using errcode = '42501';
  end if;
  if new.menu_shown is distinct from old.menu_shown
     or new.menu_hidden is distinct from old.menu_hidden
     or new.can_manage_menus is distinct from old.can_manage_menus
  then
    raise exception 'profile menu access is managed server-side' using errcode = '42501';
  end if;
  return new;
end;
$$;

-- A removed member keeps their profile (organization_id goes null) and an
-- invitation moves it to the next organization, so a menu manager of one
-- organization would arrive in another still able to change its menus.
-- Whoever makes the change, a new organization clears the menu columns and
-- a new role clears the right to change menus (an admin gives it again);
-- a value the same update sets stays, only one carried over goes. Fires
-- after the guard (triggers run in name order), so the guard checks what
-- the person asked for, not this reset.
create or replace function public.reset_profile_menu_access()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (new.organization_id is distinct from old.organization_id
      or new.role is distinct from old.role)
     and new.can_manage_menus is not distinct from old.can_manage_menus
  then
    new.can_manage_menus := false;
  end if;
  if new.organization_id is distinct from old.organization_id then
    if new.menu_shown is not distinct from old.menu_shown then
      new.menu_shown := '{}';
    end if;
    if new.menu_hidden is not distinct from old.menu_hidden then
      new.menu_hidden := '{}';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_reset_menu_access on public.profiles;
create trigger profiles_reset_menu_access
  before update of organization_id, role on public.profiles
  for each row execute function public.reset_profile_menu_access();

-- Everyone here before menu access counts as asked: "What do you work on?"
-- is for new sign-ups and people joining from an invite, once. Existing
-- people pick their work areas in Settings › Account if they want to.
update public.profiles set work_areas_asked_at = now() where work_areas_asked_at is null;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00375_task_review_approve_api.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00375: approving a task waiting for review over the API and MCP (AC-010)
-- ============================================================================
-- approve_action_task_review (00293) takes the reviewer from auth.uid(), so
-- it only works for a signed-in admin or manager. The MCP tools authenticate
-- with an API key and reach the database as the service role, where
-- auth.uid() is null.
--
-- Restated with p_user_id: the person the service role approves for, the API
-- key's owner. It counts only for the service role; a signed-in caller is
-- always auth.uid(), whatever it passes. Either way the person must be an
-- admin or manager of the review's organization, and the trail says they
-- added the task, as from the dashboard. Nothing else changes.
--
-- The 3-argument function is dropped rather than overloaded: a call with
-- three arguments would match both, and the dashboard's call keeps working
-- through p_user_id's default.

drop function if exists public.approve_action_task_review(uuid, text, jsonb);

create or replace function public.approve_action_task_review(
  p_review_id uuid,
  p_title text,
  p_details jsonb,
  p_user_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_review public.action_task_reviews%rowtype;
  v_title text := btrim(coalesce(p_title, ''));
  v_task_id uuid;
  -- Who approves: the API key's owner for the service role, else the caller.
  v_person uuid := case when auth.role() = 'service_role' then p_user_id else auth.uid() end;
begin
  -- The person's role first, before any row is read or locked.
  if not exists (
    select 1 from public.profiles p
    where p.id = v_person and p.role in ('admin', 'manager')
  ) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  -- Only a row of the person's own organization: another's reads as not there.
  select r.* into v_review
  from public.action_task_reviews r
  join public.actions a on a.id = r.action_id
  join public.brands b on b.id = a.brand_id
  join public.profiles p on p.organization_id = b.organization_id
  where r.id = p_review_id
    and p.id = v_person
  for update of r;
  if not found then
    return null;
  end if;

  if exists (
    select 1 from public.actions a
    where a.id = v_review.action_id
      and (a.deleted_at is not null or a.status in ('completed', 'dismissed'))
  ) then
    raise exception 'action closed' using errcode = '55000';
  end if;

  if char_length(v_title) not between 1 and 200
    or jsonb_typeof(p_details) is distinct from 'object'
    or nullif(btrim(coalesce(p_details->>'url', '')), '') is null
    or nullif(btrim(coalesce(p_details->'change'->>'after', '')), '') is null
    or nullif(btrim(coalesce(p_details->>'doneWhen', '')), '') is null
    or coalesce(p_details->>'check', '') not in ('auto', 'rerun', 'manual')
  then
    raise exception 'incomplete task' using errcode = '22023';
  end if;

  insert into public.action_tasks (action_id, position, title, status, mode, permission, details)
  select
    v_review.action_id,
    coalesce(max(t.position), 0) + 1,
    v_title,
    'todo',
    'human',
    'read',
    -- The reviewer's task now: Regenerate keeps it (task-writer keepsTask).
    p_details || jsonb_build_object('source', 'reviewed')
  from public.action_tasks t
  where t.action_id = v_review.action_id
  returning id into v_task_id;

  delete from public.action_task_reviews where id = v_review.id;

  insert into public.action_events (action_id, event, data, actor_id)
  values (v_review.action_id, 'task_added', jsonb_build_object('title', v_title), v_person);

  update public.actions set updated_at = now() where id = v_review.action_id;

  return v_task_id;
end;
$$;

revoke all on function public.approve_action_task_review(uuid, text, jsonb, uuid)
  from public, anon;
grant execute on function public.approve_action_task_review(uuid, text, jsonb, uuid)
  to authenticated, service_role;

comment on function public.approve_action_task_review(uuid, text, jsonb, uuid) is
  'Action Center (AC-010): a task waiting for review (action_task_reviews) onto its action''s task list, after its last task, with the exact page, the change, Done when and how it is checked filled, as the reviewer''s (source reviewed); the review row goes and the trail says a task was added. Admins and managers of the brand''s organization only, on an action neither deleted nor closed; p_user_id is the person the service role approves for (00375), a signed-in caller is always auth.uid(). Null when the row is gone or another organization''s.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00376_competitor_page_timeline.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00376: a competitor's pages over time (learning C3)
-- ============================================================================
-- A competitor rising in AI answers had no "why" beside it. This keeps two
-- kinds of dated events for each competitor page the brand's own tracked
-- answers cite (server action-center/competitorTimeline.js):
--
--   first_cited  the first day the brand's answers cited the page, read from
--                prompt_result_citations (no page read; the first night goes
--                back 90 days, so it is the first since then);
--   changed      a weekly re-read found the page's words changed by more than
--                a date or a price moving (the Action Center's page checks'
--                rule, taskChecks.js), with the Site Audit checks it gained
--                and lost.
--
-- The page is read free (safe-fetch), within the brand's daily page reads,
-- as the pages "Analyze competitor content" reads (00369). What is kept of a
-- read is what Site Audit's checks found and a sketch of its words (hashes
-- of its 4-word runs, not the text), so the next read can tell it changed.
-- Members read the events; the server writes them.

alter table public.cited_page_features
  add column if not exists sketch jsonb;

comment on column public.cited_page_features.sketch is
  'Learning C3 (00376): the read page''s word sketch (taskChecks.js sketch(): hashes of its 4-word runs, never its text), compared with the next read to tell whether the page changed.';

create table if not exists public.competitor_page_events (
  id uuid primary key default gen_random_uuid(),
  brand_id uuid not null references public.brands(id) on delete cascade,
  competitor_id uuid not null references public.competitors(id) on delete cascade,
  -- The page as Site Audit keys it: host and path, lower case.
  page_key text not null,
  url text not null,
  domain text not null,
  kind text not null check (kind in ('first_cited', 'changed')),
  at timestamptz not null,
  -- first_cited: { answers }; changed: { similarity, gained: [{ key, label }], lost: [{ key, label }] }.
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- A page is first cited once.
create unique index if not exists competitor_page_events_first_cited_uidx
  on public.competitor_page_events (brand_id, page_key)
  where kind = 'first_cited';

-- The Competitors page reads one competitor's events, newest first.
create index if not exists competitor_page_events_competitor_idx
  on public.competitor_page_events (brand_id, competitor_id, at desc);

alter table public.competitor_page_events enable row level security;

create policy competitor_page_events_member_select on public.competitor_page_events
  for select
  using (
    brand_id in (
      select b.id from public.brands b
      join public.profiles p on p.organization_id = b.organization_id
      where p.id = auth.uid()
    )
  );

revoke all on table public.competitor_page_events from anon, authenticated;
grant select on table public.competitor_page_events to authenticated;
grant all on table public.competitor_page_events to service_role;

comment on table public.competitor_page_events is
  'Learning C3 (00376): when a competitor page was first cited in the brand''s tracked answers, and when a weekly re-read found it changed (and which Site Audit checks it gained or lost). Server writes; members read.';

-- When each competitor's citations were last read for first_cited events: a
-- competitor never read is read back 90 days once, the rest from their last
-- read, so a night doesn't read a brand's whole history again.
create table if not exists public.competitor_timeline_scans (
  competitor_id uuid primary key references public.competitors(id) on delete cascade,
  brand_id uuid not null references public.brands(id) on delete cascade,
  scanned_at timestamptz not null
);

alter table public.competitor_timeline_scans enable row level security;
revoke all on table public.competitor_timeline_scans from anon, authenticated;
grant all on table public.competitor_timeline_scans to service_role;

comment on table public.competitor_timeline_scans is
  'Learning C3 (00376): when each competitor''s cited pages were last read for first_cited events. Server only.';

-- ----------------------------------------------------------------------------
-- The competitor pages the brand's answers cited since p_since: each cited
-- URL on a competitor's domain (its subdomains too), its competitor, the
-- first time it was cited and in how many answers. Read in the database so a
-- brand's citations never travel; the server only.
-- ----------------------------------------------------------------------------
create or replace function public.competitor_cited_urls(p_brand_id uuid, p_since timestamptz)
returns table (
  url text,
  domain text,
  competitor_id uuid,
  first_at timestamptz,
  answers bigint
)
language sql
stable
security definer
set search_path = public
as $$
  with rivals as (
    select c.id,
      -- As citation_urls.domain is kept: host without www., lower case.
      regexp_replace(
        regexp_replace(lower(trim(c.domain)), '^[a-z]+://', ''),
        '^www\.|[/:?#].*$', '', 'g'
      ) as host
    from public.competitors c
    where c.brand_id = p_brand_id and trim(c.domain) <> ''
  )
  select u.url, u.domain, r.id, min(prc.created_at), count(distinct prc.prompt_result_id)
  from public.prompt_result_citations prc
  join public.citation_urls u on u.id = prc.url_id
  join rivals r on r.host <> '' and (u.domain = r.host or u.domain like '%.' || r.host)
  where prc.brand_id = p_brand_id
    and prc.created_at >= p_since
  group by u.url, u.domain, r.id
$$;

revoke all on function public.competitor_cited_urls(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.competitor_cited_urls(uuid, timestamptz) to service_role;

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00377_gsc_shopping_appearance.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00377: does Google show the brand's products in its shopping results?
-- ============================================================================
-- Product Visibility's Readiness asked for a Google Merchant Center feed,
-- which this deployment may not be able to connect. Search Console says it
-- too, from the brand's own property: the pages Google shows as merchant
-- listings (the free shopping listings, fed by Merchant Center or by the
-- page's product schema) and as product snippets (a product's price,
-- rating and stock under its result).
--
-- The Search Analytics API can't give search appearance as a column beside
-- the page, so the sync (backend/src/lib/gscSync.js) asks in two steps: the
-- property's appearance types over the last 28 days, then each shopping one's
-- pages by day, filtered to it. gsc_shopping_page_stats keeps those rows; the
-- sync (service role) upserts on (brand_id, page, appearance, date), and
-- members read them. Rows older than 90 days are pruned, as queries' are.
--
-- brands.gsc_shopping_property is the property whose shopping rows the brand
-- has (another one's are dropped first), and gsc_shopping_synced_at when they
-- were last read: before the first read, Readiness says it doesn't know yet
-- rather than that no product shows.

create table if not exists public.gsc_shopping_page_stats (
    id uuid primary key default gen_random_uuid(),
    brand_id uuid not null references public.brands(id) on delete cascade,
    page text not null,
    -- merchant_listings | product_snippets
    appearance text not null check (appearance in ('merchant_listings', 'product_snippets')),
    date date not null,
    clicks integer not null default 0,
    impressions integer not null default 0,
    ctr double precision not null default 0,
    position double precision not null default 0,
    created_at timestamptz not null default now(),
    unique (brand_id, page, appearance, date)
);

create index if not exists gsc_shopping_page_stats_brand_date_idx
    on public.gsc_shopping_page_stats (brand_id, date desc);

-- The sync's table-wide retention prune (date < 90 days ago).
create index if not exists gsc_shopping_page_stats_date_idx
    on public.gsc_shopping_page_stats (date);

alter table public.gsc_shopping_page_stats enable row level security;

create policy "gsc_shopping_page_stats: member select" on public.gsc_shopping_page_stats
    for select using (
        brand_id in (
            select b.id
            from public.brands b
            join public.profiles p on p.organization_id = b.organization_id
            where p.id = auth.uid()
        )
    );

revoke all on table public.gsc_shopping_page_stats from anon, authenticated;
grant select on public.gsc_shopping_page_stats to authenticated;

comment on table public.gsc_shopping_page_stats is
  'Product Visibility Readiness (00377): the brand''s Search Console pages Google showed as merchant listings or product snippets, by day. Synced from the brand''s own property (gscSync.js); members read.';

alter table public.brands
    add column if not exists gsc_shopping_property text,
    add column if not exists gsc_shopping_synced_at timestamptz;

comment on column public.brands.gsc_shopping_property is
  '00377: the Search Console property gsc_shopping_page_stats''s rows for the brand come from; when it names another, they are dropped first (gscSync.js).';
comment on column public.brands.gsc_shopping_synced_at is
  '00377: when the brand''s shopping appearance rows were last read; null before the first read, when Readiness doesn''t know yet.';

notify pgrst, 'reload schema';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00378_cloro_pending_tasks_legacy.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00378: which pending Cloro tasks went to ChatGPT's legacy interface
-- ============================================================================
-- A prompt's ChatGPT task asks for its query fan-out one day a week through
-- Cloro's legacy desktop interface (CLORO_CHATGPT_FANOUT), which Cloro calls
-- best-effort and temporary. When Cloro takes such a task and then fails it,
-- the webhook sends it again without legacy, so the day keeps its answer
-- (backend/src/routes/cloroCallback.js). The callback only has this row to
-- go on, so the row says whether the task was a legacy one. Every other task,
-- and every row from before this file, is not.

alter table public.cloro_pending_tasks
  add column if not exists legacy boolean not null default false;

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00379_brand_site_type_source.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00379: where a brand's site type came from (action plan by business type,
--        Step 0)
-- ============================================================================
-- Setup now detects the kind of site from the brand's home page
-- (backend/src/lib/siteTypeDetect.js) instead of leaving it empty, where
-- the app guessed B2B for most brands, shops included.
--
--   * brands.site_type_source: 'auto' when a detection set the type (the
--     home page, Shopping mode, a catalog), 'manual' when a person chose it
--     (Brand settings, the Content Editor). Setup's detection only fills an
--     empty type; a catalog never writes over a manual one. Null while no
--     type is set.
--   * brands.site_type_detected_at: when a detection last set the type. A
--     change of site_type that doesn't set it too is a person's, and the
--     trigger below marks it manual: so every place a person picks a type
--     wins without knowing about detection.
--   * A catalog source added to a brand (a feed, an upload, a store) makes
--     it an online shop, unless a person chose its type.

alter table public.brands
  add column if not exists site_type_source text
    check (site_type_source in ('auto', 'manual')),
  add column if not exists site_type_detected_at timestamptz;

comment on column public.brands.site_type_source is
  'Step 0 (action plan by business type): auto = detected (home page, Shopping mode, a catalog); manual = a person chose it. Detection only fills an empty type; a catalog never overwrites manual. Null while site_type is null.';
comment on column public.brands.site_type_detected_at is
  'Step 0: when a detection last set site_type. A site_type change without it is a person''s (marked manual).';

-- A type set before today was a person's choice.
update public.brands
   set site_type_source = 'manual'
 where site_type is not null
   and site_type_source is null;

-- A brand in Shopping mode, or with a catalog, already sells online.
update public.brands b
   set site_type = 'ecommerce',
       site_type_source = 'auto',
       site_type_detected_at = now()
 where b.site_type is null
   and (
     b.shopping_mode_enabled
     or exists (select 1 from public.catalog_sources s where s.brand_id = b.id)
   );

create or replace function public.mark_brand_site_type_source()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.site_type is null then
    -- No type: nothing chosen or detected; the app guesses again.
    new.site_type_source := null;
  elsif tg_op = 'INSERT' then
    new.site_type_source :=
      case when new.site_type_detected_at is null then 'manual' else 'auto' end;
  elsif new.site_type is distinct from old.site_type then
    -- A detection stamps site_type_detected_at with the type; a person doesn't.
    new.site_type_source :=
      case
        when new.site_type_detected_at is distinct from old.site_type_detected_at then 'auto'
        else 'manual'
      end;
  end if;
  return new;
end;
$$;

drop trigger if exists brands_site_type_source on public.brands;
create trigger brands_site_type_source
  before insert or update of site_type, site_type_source, site_type_detected_at
  on public.brands
  for each row execute function public.mark_brand_site_type_source();

-- A catalog source makes the brand a shop, unless a person chose its type.
-- As the person who adds it: admins and managers may add a source (00279)
-- and update the brand alike; the server adds stores as the service role.
create or replace function public.catalog_source_marks_ecommerce()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.brands
     set site_type = 'ecommerce',
         site_type_detected_at = now()
   where id = new.brand_id
     and site_type_source is distinct from 'manual'
     and site_type is distinct from 'ecommerce';
  return new;
end;
$$;

drop trigger if exists catalog_sources_mark_ecommerce on public.catalog_sources;
create trigger catalog_sources_mark_ecommerce
  after insert on public.catalog_sources
  for each row execute function public.catalog_source_marks_ecommerce();

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00380_demo_brand.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00380: a demo brand per organization (demo-core)
-- ============================================================================
-- People who sign up without a card, and workspaces whose trial ended or whose
-- plan was cancelled, can explore a demo brand: Brewline Coffee, a fictional
-- brand on a `.example` domain, filled with sample data in the real tables.
-- It is an ordinary brand row in the person's own organization, so every page
-- reads it through the same queries and policies as any brand. The server
-- writes its data (backend/src/lib/demo/) and rebuilds it when DEMO_VERSION
-- moves on or the data grows old, keeping the brand's id so links to it hold.
--
-- What it must never do is cost anything or count against the plan:
--   * the nightly sweeps and the jobs skip `is_demo` brands (server code);
--   * the plan's prompt-location quota and the brand count leave them out
--     (org_prompt_location_usage, prompt_usage_summary below; the web's
--     maxBrands check);
--   * the health report's fan-out share leaves out their answers, which share
--     their searches every run by construction and would hide a real drop.
--
-- Policies: members read the demo brand like any other. Only the server
-- (service role) writes it: people can't insert a demo brand, mark a brand as
-- one, change it or delete it. Hiding it (demo_hidden_at) goes through the
-- server too (PATCH /api/demo), for admins and managers.

alter table public.brands
  add column if not exists is_demo boolean not null default false,
  add column if not exists demo_version integer,
  add column if not exists demo_built_at timestamptz,
  add column if not exists demo_hidden_at timestamptz;

-- The demo columns mean nothing on a real brand.
alter table public.brands
  drop constraint if exists brands_demo_columns_check;
alter table public.brands
  add constraint brands_demo_columns_check
  check (is_demo or (demo_version is null and demo_built_at is null and demo_hidden_at is null));

-- One demo brand per organization. Two first visits at once both try to
-- create it; the second insert fails here and reads the first one's row.
create unique index if not exists brands_one_demo_per_org
  on public.brands (organization_id)
  where is_demo;

comment on column public.brands.is_demo is
  'Demo brand (00380): sample data written by the server (lib/demo), one per organization. Never tracked, audited or synced, never counted against the plan; people read it and can''t change it.';
comment on column public.brands.demo_version is
  'Demo brand (00380): the DEMO_VERSION its data was built with; null while a build is under way or after one failed. A lower version is rebuilt on the next visit.';
comment on column public.brands.demo_built_at is
  'Demo brand (00380): when its data was last built, its dates counted back from then; with a null demo_version, when the build under way started. Data older than a few days is rebuilt on the next visit.';
comment on column public.brands.demo_hidden_at is
  'Demo brand (00380): when the organization hid it (after a purchase, or from the brand switcher); null = shown. Hidden, never deleted: it can be shown again.';

-- ─── Policies ──────────────────────────────────────────────────────────────
-- Same as before, plus `not is_demo`: a person can't insert a demo brand, turn
-- a brand into one or back, change one or delete one. The server's writes use
-- the service role and aren't bound by these.

drop policy if exists "brands: admin/manager insert" on public.brands;
create policy "brands: admin/manager insert" on public.brands
  for insert
  with check (
    not is_demo
    and organization_id in (
      select profiles.organization_id
      from public.profiles
      where profiles.id = auth.uid()
        and profiles.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

drop policy if exists "brands: admin/manager update" on public.brands;
create policy "brands: admin/manager update" on public.brands
  for update
  using (
    not is_demo
    and organization_id in (
      select profiles.organization_id
      from public.profiles
      where profiles.id = auth.uid()
        and profiles.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  )
  with check (
    not is_demo
    and organization_id in (
      select profiles.organization_id
      from public.profiles
      where profiles.id = auth.uid()
        and profiles.role = any (array['admin'::public.user_role, 'manager'::public.user_role])
    )
  );

drop policy if exists "brands: admin delete" on public.brands;
create policy "brands: admin delete" on public.brands
  for delete
  using (
    not is_demo
    and organization_id in (
      select profiles.organization_id
      from public.profiles
      where profiles.id = auth.uid()
        and profiles.role = 'admin'::public.user_role
    )
  );

-- ─── The plan's prompt-location quota (00128) without the demo brand ───────
-- savePromptSet, the prompt dialogs and import_prompts all count through this.
create or replace function public.org_prompt_location_usage(p_organization_id uuid)
returns table (brand_id uuid, locations bigint)
language sql
stable
set search_path to 'public'
as $$
  select b.id, sum(greatest(coalesce(array_length(p.regions, 1), 0), 1))::bigint
  from public.prompts p
  join public.prompt_sets ps on ps.id = p.prompt_set_id
  join public.brands b on b.id = ps.brand_id
  where b.organization_id = p_organization_id
    and not b.is_demo
    and p.is_active
  group by b.id;
$$;

revoke all on function public.org_prompt_location_usage(uuid) from public;
grant execute on function public.org_prompt_location_usage(uuid) to authenticated, service_role;

comment on function public.org_prompt_location_usage(uuid) is
  'Active prompt locations per brand for one org (#691, 00128) — the plan-quota unit, one per region entry per active prompt, minimum one; paused prompts and the demo brand (00380) don''t count. Security invoker: RLS scopes it to the caller''s org.';

-- ─── The usage cards' account totals (00139) without the demo brand ────────
-- The demo brand's own counts stay (its Prompts page shows them); the
-- account's prompts, brands and locations, which the plan limits, leave it out.
create or replace function public.prompt_usage_summary(p_brand_id uuid)
returns table (
  brand_active integer,
  brand_paused integer,
  account_active integer,
  account_brands integer,
  account_locations integer
)
language sql
stable
set search_path = public
as $$
  select
    coalesce(bc.active_prompts, 0),
    coalesce(bc.paused_prompts, 0),
    coalesce(acct.active_prompts, 0)::integer,
    (
      select count(*)
      from public.brands b2
      where b2.organization_id = b.organization_id
        and not b2.is_demo
    )::integer,
    coalesce(acct.active_locations, 0)::integer
  from public.brands b
  left join public.prompt_usage_counters bc on bc.brand_id = b.id
  left join lateral (
    select sum(c.active_prompts) as active_prompts, sum(c.active_locations) as active_locations
    from public.prompt_usage_counters c
    join public.brands cb on cb.id = c.brand_id
    where c.organization_id = b.organization_id
      and not cb.is_demo
  ) acct on true
  where b.id = p_brand_id;
$$;

revoke all on function public.prompt_usage_summary(uuid) from public, anon;
grant execute on function public.prompt_usage_summary(uuid) to authenticated, service_role;

comment on function public.prompt_usage_summary(uuid) is
  'One brand''s active/paused prompts and its account''s active prompts, brands and active prompt locations, from prompt_usage_counters only (PROMPT-012); the account totals leave out the demo brand (00380). Security invoker.';

-- ─── The health report's fan-out share (00140) without demo answers ────────
create or replace function public.fanout_coverage_by_platform(
  p_since timestamptz,
  p_until timestamptz
)
returns table (platform text, answers bigint, answers_with_fanout bigint)
language sql
stable
security definer
set search_path = public
as $$
  select
    r.platform,
    count(*)::bigint,
    count(*) filter (
      where case
        when jsonb_typeof(r.search_queries) = 'array' then jsonb_array_length(r.search_queries)
        else 0
      end > 0
    )::bigint
  from public.prompt_results r
  join public.brands b on b.id = r.brand_id
  where r.created_at >= p_since
    and r.created_at < p_until
    and not b.is_demo
  group by r.platform;
$$;

revoke all on function public.fanout_coverage_by_platform(timestamptz, timestamptz)
  from public, anon, authenticated;
grant execute on function public.fanout_coverage_by_platform(timestamptz, timestamptz)
  to service_role;

comment on function public.fanout_coverage_by_platform(timestamptz, timestamptz) is
  'Answers and answers with observed query fan-out per platform in [p_since, p_until), across all brands but demo ones (00140, 00380). Read by the daily health report.';

-- ─────────────────────────────────────────────────────────────────────────
-- migrations/00381_demo_brand_writes.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- 00381: people can't write the demo brand's data (demo-guard)
-- ============================================================================
-- The demo brand (00380) is sample data the server writes (backend/src/lib/
-- demo) with the service role. People explore it, but nothing of theirs may
-- change it: the API refuses its writes (402 demo_brand, backend/src/
-- middleware/demoBrand.js) and so does the web app's lock, but members can
-- also write a brand's rows straight through Supabase, under RLS. This
-- refuses those writes in the database.
--
-- refuse_demo_brand_writes() is a BEFORE INSERT/UPDATE/DELETE row trigger:
--   * a role that bypasses RLS (the service role the server and the demo
--     generator use, migrations, the table owner behind a cascade) passes,
--     as in the other server-column guards (00204, 00228). Not, though, a
--     SECURITY DEFINER function a person calls (approve_action_task_review,
--     content_draft_restore, override_mention_sentiment, seed_kpi_presets):
--     it runs as its owner, who bypasses RLS, but the write is the person's.
--     So the session's own role decides (the one PostgREST sets per request:
--     authenticated or anon is a person), unless the write comes from inside
--     another trigger (a cascade, or a trigger of the server's);
--   * otherwise, a row of a demo brand is refused with SQLSTATE 42501 and
--     the message 'demo_brand' (an update is checked on its old and new row,
--     so a row can't be moved into or out of the demo brand either).
-- With no arguments, the row's brand is its own brand_id. A table without a
-- brand_id names the way to it: (column, table) pairs, each table's row found
-- by its id, the last one's brand_id being the brand, e.g. prompt_notes:
-- prompt_id → prompts, prompt_set_id → prompt_sets.
--
-- It is attached to every table people can write under RLS (an insert,
-- update, delete or all policy for a role other than service_role) that
-- belongs to a brand. backend/src/lib/demo/writeGuard.test.js reads the
-- migrations and fails on such a table without it: a new one attaches it in
-- its own migration.
--
-- It reads the brand (and a parent row) as the person, under RLS: a row of a
-- brand they can't see is refused by RLS itself. The brands themselves are
-- guarded by their own policies (00380).

create or replace function public.refuse_demo_brand_writes()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_keys text[] := '{}';
  v_key text;
  v_column text;
  i integer;
begin
  -- A role that bypasses RLS is server-side (service role, migrations), unless
  -- it is the owner of a SECURITY DEFINER function a person called directly.
  if (select rolbypassrls from pg_catalog.pg_roles where rolname = current_user)
    and (
      pg_catalog.pg_trigger_depth() > 1
      or coalesce(pg_catalog.current_setting('role', true), 'none')
        not in ('authenticated', 'anon')
    )
  then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_nargs = 0 then
    if tg_op <> 'INSERT' then
      v_keys := v_keys || old.brand_id::text;
    end if;
    if tg_op <> 'DELETE' then
      v_keys := v_keys || new.brand_id::text;
    end if;
  else
    if tg_op <> 'INSERT' then
      execute format('select ($1).%I::text', tg_argv[0]) into v_key using old;
      v_keys := v_keys || v_key;
    end if;
    if tg_op <> 'DELETE' then
      execute format('select ($1).%I::text', tg_argv[0]) into v_key using new;
      v_keys := v_keys || v_key;
    end if;
    -- From each table on the way to the next one's id, the last one's brand_id.
    i := 1;
    while i < tg_nargs loop
      v_column := case when i + 1 < tg_nargs then tg_argv[i + 1] else 'brand_id' end;
      execute format(
        'select coalesce(array_agg(distinct t.%I::text), ''{}'') '
          || 'from public.%I t where t.id = any ($1::uuid[])',
        v_column,
        tg_argv[i]
      ) into v_keys using v_keys;
      i := i + 2;
    end loop;
  end if;

  if exists (
    select 1 from public.brands b
    where b.id = any (v_keys::uuid[])
      and b.is_demo
  ) then
    raise exception 'demo_brand'
      using errcode = '42501',
            detail = 'The demo brand holds sample data and can''t be changed.',
            hint = 'Choose a plan to do this for your own brand.';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

comment on function public.refuse_demo_brand_writes() is
  'Demo brand (00381): refuses a write to a demo brand''s row (42501, ''demo_brand'') unless the role bypasses RLS (the server, which writes the demo''s sample data) and isn''t a person''s SECURITY DEFINER call. No arguments: the row''s brand_id; else (column, table) pairs leading to the brand.';

